# Potential causes remain hypotheses unless the evidence establishes them.
eda_policy_rows = []
for eda_issue in eda_prior_checks:
    if eda_issue["status"] != "needs_review":
        continue
    eda_name = eda_issue["check_name"]
    eda_cause = "The original source or transformation may contain optional, unavailable, or inconsistent information."
    eda_handling = "Retain source values, document field requirements, and investigate the originating record before correction."
    if "historical_input" in eda_name:
        eda_cause = "The historical input was not included in the checked local locations; its acquisition history remains unresolved."
        eda_handling = "Recover the publisher input or document the lineage gap; retain checksums and transformation records."
    elif "description" in eda_name:
        eda_cause = "The publisher data or an earlier preparation stage may lack instructional text."
        eda_handling = "Retain name-only exercises, monitor coverage by label, and assess their model performance separately later."
    elif "planning_input" in eda_name:
        eda_cause = "The current fictional-profile schemas do not include all planned constraint groups."
        eda_handling = "Add explicit input collection or missing-information handling when the Step 13 rules define the requirements."
    elif "negative_measurements" in eda_name or "finite_core" in eda_name:
        eda_cause = "Nutrient availability, source conventions, or extraction choices may explain the values."
        eda_handling = "Preserve the raw values; screen only the analysis view and trace the original nutrient record before changing a value."
    elif "name" in eda_name:
        eda_cause = "Naming variants, activity variations, repeated occurrences, or inconsistent labels may explain the overlap."
        eda_handling = "Retain the records and their source links; review identity and labels separately, using linked groups for partitioning."
    elif "unknown" in eda_name:
        eda_cause = "The field explicitly records uncertainty; the reason for that uncertainty is not established."
        eda_handling = "Preserve unknown separately from missing and reported none; request information only where a planning rule needs it."
    elif "empty_json" in eda_name:
        eda_cause = "Earlier conversion may have omitted unavailable source values, leaving an empty object."
        eda_handling = "Trace the linked source row and withhold unsupported retrieval content until its payload has been reviewed."
    eda_policy_rows.append({"source_id": eda_issue["source_id"], "finding": eda_name,
                            "affected_count": eda_issue["affected_count"], "affected_unit": eda_issue["affected_unit"],
                            "observed_evidence": eda_issue["details"], "possible_cause": eda_cause,
                            "cause_status": "not independently established", "current_handling": "Source values and the recorded finding are retained.",
                            "proposed_production_handling": eda_handling})
