    ax.barh(eda_positions + .18, [row["distinct_split_groups"] for row in eda_label_groups], height=.35, label="Linked groups within label", color="#2563EB")
    ax.set_yticks(eda_positions, [row["body_part"] for row in eda_label_groups])
    ax.set(xlabel="Count within source label", title="Record counts and linked-group support")
    ax.legend(frameon=False)
