def p134_source_decision_proposal(record):
    identity = record["candidate_rule_id"]
    kind = record["source_rule_type"]
    if identity == "NBA_A12_SLEEP":
        return "review_only", "retain_outside_target_reference", "Retain the exception without applying it to the 13-17 project target."
    if identity == "NBA_G9_12_MAX_MONTHS":
        return "review_only", "review_published_maximum_range", "No universal cutoff or minimum participation value has been selected."
    if identity == "AAP_WEEKLY_SPORT_REST":
        return "review_only", "review_broad_rest_recommendation", "Full-report scope review remains pending; two is not a ceiling on rest."
    if record["record_kind"] == "general_guidance":
        return "advisory", "contextual_guidance_only", "Retain context and related records without duplicate scoring or numeric extraction."
    if kind == "maximum":
        severity = "advisory" if record["metric_or_topic"] == "organized_basketball_months_per_year" else "required"
        return severity, "<=", "Proposed comparison only, subject to adopted applicability, window, and qualifications."
    if kind == "minimum":
        return "required", ">=", "Proposed comparison only, subject to adopted scope and schedule completeness."
    return "advisory", "describe_recommendation", "Recommendation position does not automatically make a plan fail a required check."


