# Step 14-6 — Save and verify our selected food-reference snapshot
# Field/operation eligibility belongs to this reference; Step 24 activates application lookup.
import csv
import hashlib
import io
import json
import os
import re
from pathlib import Path, PureWindowsPath

if not globals().get("step14_report", {}).get("reference_prepared") or not callable(globals().get("fd145_require")):
    raise RuntimeError("Complete Step 14-5 successfully before saving its selected food reference.")
step14_report.update(status="saving_food_reference", reference_saved=False,
                     data_preparation_complete=False, reference_snapshot_ready_for_step24=False,
                     application_lookup_enabled=False, step24_integration_pending=True)


def fd146_relative(name):
    fd145_require(isinstance(name, str) and bool(name), "A reference output name is empty or invalid.")
    normalized = name.replace("\\", "/")
    path = Path(normalized)
    fd145_require(not path.is_absolute() and not PureWindowsPath(name).drive
                  and all(part not in {"", ".", ".."} for part in normalized.split("/")),
                  "Expected a safe bundle-relative reference output name: " + name)
    return normalized


def fd146_csv_bytes(table):
    fd145_require(isinstance(table, dict) and isinstance(table.get("columns"), list)
                  and isinstance(table.get("rows"), list), "A selected-reference table lacks columns or rows.")
    columns, rows = table["columns"], table["rows"]
    fd145_require(bool(columns) and all(isinstance(field, str) and field for field in columns)
                  and len(columns) == len(set(columns)), "A selected-reference table has invalid column names.")
    fd145_require(all(isinstance(row, dict) and set(row) == set(columns) for row in rows),
                  "Selected-reference row fields disagree with the declared columns.")
    buffer = io.StringIO(newline="")
    writer = csv.DictWriter(buffer, fieldnames=columns, extrasaction="raise", lineterminator="\n")
    writer.writeheader()
    writer.writerows(rows)
    return buffer.getvalue().encode("utf-8")


def fd146_json_bytes(value):
    return (json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n").encode("utf-8")


