def fd146_verify_inputs():
    for reference, expected in fd146_inputs.items():
        fd145_require(isinstance(expected, str) and re.fullmatch(r"[0-9a-f]{64}", expected),
                      "A reference input has an invalid SHA-256: " + str(reference))
