def fd146_register(name, content, metadata):
    relative = fd146_relative(name)
    fd145_require(isinstance(content, bytes), "A selected-reference artifact has invalid serialized bytes: " + relative)
    fd145_require(relative.casefold() not in fd146_portable_names,
                  "Two reference outputs share a portable filename: " + relative)
    fd145_require(relative.casefold() != "step14_food_reference_summary.json",
                  "A selected-reference artifact would replace the reference producer.")
    fd146_portable_names.add(relative.casefold())
    fd146_payload_names[relative] = content
    fd146_artifacts[relative] = {"bytes": len(content), "sha256": hashlib.sha256(content).hexdigest(), **metadata}


