# Step 15-1 — Verify and load our saved exercise inputs.
# This cell reads existing files. It does not change reviews or create splits.
import hashlib
import io
import json
from pathlib import Path

import pandas as pd
from IPython.display import display

step15_report = {"status": "incomplete", "splits_created": False}
step15_inputs = None


def load_step15_inputs():
    cwd = Path.cwd().resolve()
    root = next((p for p in (cwd, *cwd.parents)
                 if (p / "notebooks/champion_athletic_map.ipynb").is_file()
                 and (p / "results/step10_exercise_preparation.json").is_file()), None)
    if root is None:
        raise RuntimeError("Open this cell from our project folder or its notebooks folder.")
    hashes, checks = {}, []

    def require(condition, message):
        if not bool(condition):
            raise RuntimeError(message + " Stop here and reconcile the saved inputs.")

    def read_bytes(relative, expected=None):
        path = (root / relative).resolve()
        require(path.is_relative_to(root), f"Path outside our project: {relative}")
        require(path.is_file(), f"Missing input: {relative}")
        content = path.read_bytes()
        observed = hashlib.sha256(content).hexdigest()
        if expected is not None:
            require(observed == expected, f"Checksum mismatch: {relative}")
        hashes[relative] = observed
        return content

    def read_table(relative, spec):
        content = read_bytes(relative, spec["sha256"])
        table = pd.read_csv(io.BytesIO(content), dtype=str, keep_default_na=False,
                            encoding="utf-8-sig")
        require(len(table) == spec["rows"], f"Row-count mismatch: {relative}")
        require(list(table.columns) == spec["columns"], f"Schema mismatch: {relative}")
        checks.append({"file": relative, "rows": len(table), "status": "pass"})
        return table

    # These producer identities match the uploaded files and GitHub at d34072a.
    producer_hashes = {
        "results/step10_exercise_preparation.json":
            "e5a86eb8224e579bac479c88844dddbb491c40bde11c61ba6ee00a804c689fa2",
        "results/step11_eda_summary.json":
            "3c69a8ca870ecd3355055c6a76db894f260f63d9b05fcaf7ea1b5c5713fe5584",
    }
    producers = {p: json.loads(read_bytes(p, digest).decode("utf-8-sig"))
                 for p, digest in producer_hashes.items()}
    prep = producers["results/step10_exercise_preparation.json"]
    eda = producers["results/step11_eda_summary.json"]
    require(prep["status"] == "prepared_with_reviews", "Unexpected Step 10 status")
    require(eda["status"] == "completed_with_reviews", "Unexpected Step 11 status")
    contract = prep["feature_contract"]
    require(contract["input_fields"] == ["exercise_name_prepared", "description_prepared"]
            and contract["model_text_field"] == "classifier_text"
            and contract["target_field"] == "body_part_prepared"
            and contract["split_group_field"] == "split_group_id"
            and contract["final_splits_created"] is False,
            "Unexpected Step 10 feature contract")
    require(eda["methods"]["feature_contract"] == contract, "EDA feature contract differs")

    tables = {name: read_table(spec["relative_path"], spec)
              for name, spec in prep["artifacts"].items()}
    source_spec = prep["parent_source"]
    source = read_table(source_spec["relative_path"], source_spec)
    # Verify that Step 11 used these exact exercise inputs and producer record.
    for relative, digest in list(hashes.items()):
        if relative != "results/step11_eda_summary.json":
            require(eda["input_hashes"].get(relative) == digest,
                    f"Step 11 input identity differs: {relative}")
    exercise_eda = {}
    for relative, spec in eda["artifacts"].items():
        if Path(relative).name.startswith("exercise_"):
            if spec["kind"] == "table":
                exercise_eda[relative] = read_table(relative, spec)
            else:
                read_bytes(relative, spec["sha256"])

    catalog, membership = tables["catalog"], tables["group_membership"]
    ids = catalog["catalog_id"]
    require(ids.is_unique and ids.str.strip().ne("").all(), "Invalid catalog identifiers")
    for field in ["exercise_name_prepared", "body_part_prepared", "split_group_id"]:
        require(catalog[field].str.strip().ne("").all(), f"Missing values in {field}")
    positions = pd.to_numeric(catalog["source_cleaned_record_position"], errors="raise")
    require(sorted(positions.tolist()) == list(range(1, len(source) + 1)),
            "Source positions do not cover the parent dataset exactly once")
    expected_ids = positions.map(lambda p: f"exercise_clean:{int(p):06d}")
    require(ids.equals(expected_ids), "Catalog IDs differ from their source positions")
    original = source.iloc[positions.astype(int).to_numpy() - 1].reset_index(drop=True)
    require(catalog[list(source.columns)].reset_index(drop=True).equals(original),
            "Original exercise source values changed")
    require(catalog["source_sha256"].eq(source_spec["sha256"]).all()
            and catalog["source_file"].eq(source_spec["relative_path"]).all()
            and catalog["preparation_version"].eq(prep["recipe_version"]).all(),
            "Catalog source identity or preparation version differs")
    expected_text = catalog.apply(lambda r: "\n\n".join(
        v for v in (r["exercise_name_prepared"], r["description_prepared"]) if v), axis=1)
    require(catalog["classifier_text"].equals(expected_text), "Classifier text contract differs")
    expected_availability = catalog["description_prepared"].map(
        lambda v: "name_and_description" if v else "name_only")
    require(catalog["text_availability"].equals(expected_availability),
            "Text-availability flags differ")

    components = membership.loc[membership["relation_type"].eq("split_component")]
    require(components["catalog_id"].is_unique and set(components["catalog_id"]) == set(ids),
            "Expected one split-component membership per catalog record")
    saved_groups = components.set_index("catalog_id")["group_id"].sort_index()
    catalog_groups = catalog.set_index("catalog_id")["split_group_id"].sort_index()
    require(saved_groups.equals(catalog_groups.rename("group_id")),
            "Membership groups differ from the catalog")
    for name in ["group_membership", "review_queue"]:
        require(set(tables[name]["catalog_id"]).issubset(set(ids)),
                f"Unknown catalog IDs in {name}")
    group_count = catalog["split_group_id"].nunique()
    require(len(catalog) == prep["preparation_metrics"]["catalog_records"]
            == eda["exercise_metrics"]["catalog_records"]
            and group_count == prep["grouping_metrics"]["split_metrics"]["total_groups"]
            == eda["exercise_metrics"]["split_groups"], "Producer counts differ")
    require(catalog["body_part_prepared"].value_counts().to_dict()
            == prep["preparation_metrics"]["label_counts"]
            == eda["exercise_metrics"]["class_counts"], "Producer class counts differ")
    # No earlier Step 15 output is replaced by this inspection.
    existing = [p.relative_to(root).as_posix() for folder in ["data/processed", "results"]
                for p in (root / folder).glob("exercise_*.csv")
                if p.name in {"exercise_groups.csv", "exercise_split_manifest.csv",
                              "exercise_benchmark_review_decisions.csv", "exercise_class_eligibility.csv",
                              "exercise_split_candidates.csv", "exercise_split_summary.csv",
                              "exercise_split_checks.csv"}]
    existing += [p for p in ["artifacts/splits/exercise_split_config.json",
                            "results/step15_exercise_split_summary.json"] if (root / p).exists()]
    require(all(hashlib.sha256((root / p).read_bytes()).hexdigest() == digest
                for p, digest in hashes.items()), "An input changed during this check")
    support = catalog.groupby("body_part_prepared").agg(
        records=("catalog_id", "size"), groups=("split_group_id", "nunique"))
    support["meets_10_group_threshold_before_review"] = support["groups"].ge(10)
    print("Step 15-1 — Saved exercise inputs verified")
    print(f"Project: {root}")
    print(f"Records: {len(catalog):,} | Groups: {group_count:,} | Source classes: {len(support)}")
    print("Text availability:", catalog["text_availability"].value_counts().to_dict())
    print("Review status:", tables["review_queue"]["review_status"].value_counts().to_dict())
    print(f"Carryover rows: {len(tables['review_carryover']):,} | Verified files: {len(hashes)}")
    display(pd.DataFrame(checks).head(6))
    display(support)
    print("Existing Step 15 outputs:", existing or "none")
    print("Input checks passed. Group review, benchmark eligibility, and splits remain pending.")
    return {"root": root, **tables, "source": source, "preparation": prep, "eda": eda,
            "exercise_eda": exercise_eda, "input_hashes": hashes,
            "input_checks": pd.DataFrame(checks), "class_support_before_review": support,
            "existing_step15_outputs": existing}


step15_inputs = load_step15_inputs()
step15_report.update(status="inputs_verified", splits_created=False)


