# Step 15-2 — Inspect existing groups and collect benchmark-review evidence.
# We verify the saved mapping; source labels, review records, and splits stay unchanged.
import hashlib
import io
import json
import re
import unicodedata
from collections import defaultdict

import pandas as pd
from IPython.display import display

if not isinstance(globals().get("step15_inputs"), dict):
    raise RuntimeError("Run Step 15-1 successfully before this cell.")
step15_group_review = None
step15_report.update(status="group_checks_incomplete", splits_created=False,
                     benchmark_review_complete=False)


def inspect_step15_groups(inputs):
    root = inputs["root"]
    snapshot = {p: (root / p).read_bytes() for p in inputs["input_hashes"]}
    if any(hashlib.sha256(content).hexdigest() != inputs["input_hashes"][p]
           for p, content in snapshot.items()):
        raise RuntimeError("An input changed after Step 15-1. Stop and reconcile it.")

    def table(relative):
        return pd.read_csv(io.BytesIO(snapshot[relative]), dtype=str,
                           keep_default_na=False, encoding="utf-8-sig")

    catalog = table("data/processed/exercise_catalog.csv").sort_values("catalog_id")
    membership = table("results/exercise_group_membership.csv")
    queue = table("results/exercise_review_queue.csv")
    prep = json.loads(snapshot["results/step10_exercise_preparation.json"])
    records = catalog.set_index("catalog_id").to_dict("index")
    assignments = catalog.set_index("catalog_id")["split_group_id"].to_dict()

    def require(condition, message):
        if not bool(condition):
            raise RuntimeError(message + " Stop before benchmark allocation.")

    def strict(value):
        return unicodedata.normalize("NFKC", re.sub(r"\s+", " ", value).strip()).casefold()

    def broad(value):
        return " ".join(re.findall(r"[a-z0-9]+", value.lower()))

    def canonical(value):
        return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))

    def digest(value):
        return hashlib.sha256(canonical(value).encode("utf-8")).hexdigest()

    def identifier(relation, comparison_digest):
        payload = {"recipe_version": prep["recipe_version"],
                   "source_sha256": prep["parent_source"]["sha256"],
                   "relation_type": relation, "comparison_digest": comparison_digest}
        return "exgroup:" + digest(payload)

    content_fields = ["exercise_name_prepared", "description_prepared",
                      "exercise_type_prepared", "equipment_prepared", "difficulty_level_prepared"]
    # Content metadata below is used only to audit Step 10 comparisons.
    key_functions = {
        "broad_name": lambda r: broad(r["exercise_name_prepared"]),
        "shared_description": lambda r: strict(r["description_prepared"]),
        "strict_classifier_input": lambda r: strict(r["classifier_text"]),
        "broad_classifier_input": lambda r: broad(r["classifier_text"]),
        "strict_content_without_label": lambda r: tuple(strict(r[f]) for f in content_fields),
        "broad_content_without_label": lambda r: tuple(broad(r[f]) for f in content_fields),
    }
    split_relations = {"broad_name", "shared_description", "strict_classifier_input"}
    null_descriptions = {"", "nan", "null", "none", "n/a"}
    require(not membership.duplicated(["relation_type", "group_id", "catalog_id"]).any(),
            "Duplicate saved relationship memberships")
    recorded = {(rel, gid): rows for (rel, gid), rows in
                membership.groupby(["relation_type", "group_id"], sort=True)}
    checked, relation_rows, comparison_rows = set(), [], []
    neighbors = {rid: set() for rid in records}
    link_types = defaultdict(set)

    def check_saved(relation, key, members, role):
        labels = sorted({records[rid]["body_part_prepared"] for rid in members})
        comparison_digest = digest(key)
        gid = identifier(relation, comparison_digest)
        entry = recorded.get((relation, gid))
        require(entry is not None, f"Missing saved relationship: {relation}, {gid}")
        require(set(entry["catalog_id"]) == set(members)
                and len(entry) == len(members), f"Relationship members differ: {gid}")
        for field, expected in {"member_count": str(len(members)),
                                "labels_json": canonical(labels),
                                "comparison_digest": comparison_digest,
                                "link_role": role}.items():
            require(entry[field].eq(expected).all(), f"Saved {field} differs: {gid}")
        checked.add((relation, gid))
        return gid, labels

    for relation, key_for in key_functions.items():
        buckets = defaultdict(list)
        for rid, row in records.items():
            key = key_for(row)
            if relation == "shared_description" and key in null_descriptions:
                continue
            if key != "":
                buckets[key].append(rid)
        repeated = [sorted(members) for members in buckets.values() if len(members) > 1]
        mixed, crossed = 0, 0
        for key, members in buckets.items():
            if len(members) < 2:
                continue
            members = sorted(members)
            role = "split_link" if relation in split_relations else "review_only"
            gid, labels = check_saved(relation, key, members, role)
            group_ids = sorted({assignments[rid] for rid in members})
            mixed += int(len(labels) > 1)
            crossed += int(len(group_ids) > 1)
            if role == "split_link":
                require(len(group_ids) == 1, f"A split relationship crosses groups: {gid}")
                link_types[group_ids[0]].add(relation)
                for rid in members[1:]:
                    neighbors[members[0]].add(rid)
                    neighbors[rid].add(members[0])
            comparison_rows.append({"relation_type": relation, "relation_group_id": gid,
                "catalog_ids_json": canonical(members), "records": len(members),
                "source_labels_json": canonical(labels), "mixed_labels": len(labels) > 1,
                "saved_split_groups": len(group_ids), "link_role": role,
                "same_full_description": len({records[r]["description_prepared"] for r in members}) == 1})
        metrics = {"repeated_groups": len(repeated),
                   "records_in_repeated_groups": sum(map(len, repeated)),
                   "additional_records": sum(len(m) - 1 for m in repeated),
                   "different_label_groups": mixed,
                   "largest_group": max(map(len, repeated), default=0)}
        require(metrics == prep["grouping_metrics"]["relation_metrics"][relation],
                f"Relationship metrics differ from Step 10: {relation}")
        relation_rows.append({"relationship": relation, "repeated_groups": len(repeated),
                             "records": metrics["records_in_repeated_groups"],
                             "mixed_label_groups": mixed, "crosses_saved_groups": crossed})

    group_rows = []
    for gid, rows in catalog.groupby("split_group_id", sort=True):
        members = sorted(rows["catalog_id"])
        expected_gid, labels = check_saved("split_component", members, members, "split_link")
        require(gid == expected_gid, f"Saved split-group identity differs: {gid}")
        # A chain of supported links is sufficient; every pair need not link directly.
        seen, pending = set(), [members[0]]
        while pending:
            rid = pending.pop()
            if rid not in seen:
                seen.add(rid)
                pending.extend(neighbors[rid] - seen)
        require(seen == set(members), f"Unsupported connection within split group: {gid}")
        require(rows["split_group_size"].eq(str(len(members))).all()
                and rows["split_group_label_count"].eq(str(len(labels))).all(),
                f"Catalog group counters differ: {gid}")
        group_rows.append({"split_group_id": gid, "records": len(members),
                           "source_labels_json": canonical(labels), "mixed_labels": len(labels) > 1,
                           "link_types_json": canonical(sorted(link_types[gid])),
                           "link_type_count": len(link_types[gid])})
    require(checked == set(recorded), "Unexpected relationships in the saved membership table")
    groups = pd.DataFrame(group_rows)
    require(groups["mixed_labels"].sum() == prep["grouping_metrics"]["split_metrics"]["different_label_groups"],
            "Mixed-label group count differs from Step 10")
    comparisons = pd.DataFrame(comparison_rows)
    review_records = catalog.loc[catalog["split_group_size"].astype(int).gt(1)].copy()
    queue_refs = queue.groupby("catalog_id")["issue_type"].agg(lambda s: canonical(sorted(set(s))))
    review_records["pending_review_issue_types_json"] = review_records["catalog_id"].map(queue_refs).fillna("[]")
    review_records["benchmark_review_status"] = "not_decided"

    def conflicting_records(relation):
        findings = comparisons.loc[comparisons["relation_type"].eq(relation) & comparisons["mixed_labels"]]
        links = [{"relation_group_id": row.relation_group_id, "catalog_id": rid}
                 for row in findings.itertuples() for rid in json.loads(row.catalog_ids_json)]
        columns = ["relation_group_id", "catalog_id", "exercise_name_prepared", "body_part_prepared",
                   "description_prepared", "classifier_text", "split_group_id", "label_review_status"]
        return (pd.DataFrame(links, columns=["relation_group_id", "catalog_id"])
                .merge(catalog, on="catalog_id", validate="many_to_one")[columns])

    strict_conflicts = conflicting_records("strict_classifier_input")
    broad_conflicts = conflicting_records("broad_classifier_input")
    name_conflicts = conflicting_records("broad_name")
    other_name_conflicts = name_conflicts.loc[
        ~name_conflicts["catalog_id"].isin(broad_conflicts["catalog_id"])].reset_index(drop=True)
    require(all(hashlib.sha256((root / p).read_bytes()).hexdigest() == digest_value
                for p, digest_value in inputs["input_hashes"].items()), "An input changed during this check")
    print("Step 15-2 — Existing exercise-group checks passed")
    print(f"Saved split groups: {len(groups):,} | Multi-record groups: {groups['records'].gt(1).sum():,}")
    print(f"Mixed-label split groups: {groups['mixed_labels'].sum():,} | "
          f"Groups using multiple link types: {groups['link_type_count'].gt(1).sum():,}")
    print("Relationship counts overlap; do not add them as separate record totals.")
    with pd.option_context("display.max_columns", None):
        display(pd.DataFrame(relation_rows))
    print(f"Conflicting strict-input groups: {strict_conflicts['relation_group_id'].nunique()}")
    print(f"Conflicting broader-input groups: {broad_conflicts['relation_group_id'].nunique()} "
          f"({len(broad_conflicts)} records)")
    display_columns = ["catalog_id", "exercise_name_prepared", "body_part_prepared"]
    print("Broader-input conflicts — source labels, not benchmark decisions:")
    with pd.option_context("display.max_rows", 30, "display.max_columns", None,
                           "display.max_colwidth", 90):
        display(broad_conflicts[display_columns])
        print("Additional name-group conflicts with nonidentical input text:")
        display(other_name_conflicts[display_columns])
    print(f"Full in-memory group review packet: {len(review_records)} records.")
    print("Labels and review history are unchanged. Benchmark decisions and splits remain pending.")
    return {"status": "group_checks_passed_review_pending", "groups": groups,
            "relationship_summary": pd.DataFrame(relation_rows), "comparisons": comparisons,
            "review_records": review_records, "strict_input_conflicts": strict_conflicts,
            "broad_input_conflicts": broad_conflicts, "other_name_conflicts": other_name_conflicts,
            "input_hashes": dict(inputs["input_hashes"])}


step15_group_review = inspect_step15_groups(step15_inputs)
step15_report.update(status="group_checks_passed_review_pending", splits_created=False,
                     benchmark_review_complete=False)


