# Step 16-1 — Inspect saved profile sources and reference checkpoints.
# We preserve the source records and prepare no accepted profiles or final test cases here.
import hashlib
import io
import json
from pathlib import Path

import pandas as pd
from IPython.display import display

step16_inputs = None
step16_report = {"status": "incomplete", "profiles_created": False,
                 "accepted_profiles": 0, "final_profiles_frozen": False}


def load_step16_inputs():
    cwd = Path.cwd().resolve()
    root = next((p for p in (cwd, *cwd.parents)
                 if (p / "notebooks/champion_athletic_map.ipynb").is_file()
                 and (p / "data/source_manifest.csv").is_file()), None)
    if root is None:
        raise RuntimeError("Open this cell from our project folder or its notebooks folder.")
    hashes = {}

    def require(condition, message):
        if not bool(condition):
            raise RuntimeError(message + " Stop and reconcile the saved version before continuing.")

    def read_bytes(relative, expected=None):
        path = (root / relative).resolve()
        require(path.is_relative_to(root) and path.is_file(), f"Missing or invalid input: {relative}")
        content = path.read_bytes()
        observed = hashlib.sha256(content).hexdigest()
        require(expected is None or observed == expected, f"Checksum mismatch: {relative}")
        hashes[relative] = observed
        return content

    def read_csv(relative, expected, spec=None):
        frame = pd.read_csv(io.BytesIO(read_bytes(relative, expected)), dtype=str,
                            keep_default_na=False, encoding="utf-8-sig")
        if spec is not None:
            require(len(frame) == spec["rows"] and list(frame.columns) == spec["columns"],
                    f"Saved table dimensions differ: {relative}")
        return frame

    eda_path = "results/step11_eda_summary.json"
    eda = json.loads(read_bytes(eda_path, "3c69a8ca870ecd3355055c6a76db894f260f63d9b05fcaf7ea1b5c5713fe5584"))
    require(eda["status"] == "completed_with_reviews", "Unexpected saved EDA status")
    registry = read_csv("data/source_manifest.csv", eda["input_hashes"]["data/source_manifest.csv"])
    inventory = read_csv("results/data_inventory.csv", eda["input_hashes"]["results/data_inventory.csv"])
    require(registry["source_id"].is_unique, "Duplicate source-register identifiers")
    specifications = {
        "derived_athlete_profile": {"rows": 30, "columns": ["athlete_id", "age", "sport", "position",
            "experience_level", "goal", "injury_status", "available_days", "equipment", "notes"]},
        "aditi_synthetic_athletes": {"rows": 60, "columns": ["athlete_id", "age", "sport", "position",
            "experience_level", "primary_goal", "available_days_per_week", "equipment", "injury_status",
            "scenario_type", "scenario_note", "is_synthetic", "athlete_request"]},
    }
    sources, source_rows, audit_rows, age_rows = {}, {}, [], []
    for source_id, spec in specifications.items():
        registered = registry.loc[registry["source_id"].eq(source_id)]
        inspected = inventory.loc[inventory["source_id"].eq(source_id)]
        require(len(registered) == len(inspected) == 1, f"Expected one registered/inspected profile source: {source_id}")
        row, prior = registered.iloc[0].to_dict(), inspected.iloc[0].to_dict()
        relative = row["relative_path"]
        require(row["file_status"] == "present" and prior["load_status"] == "loaded"
                and prior["relative_path"] == relative
                and row["sha256"] == prior["observed_sha256"] == eda["input_hashes"][relative],
                f"Source identity differs between producer records: {source_id}")
        frame = read_csv(relative, row["sha256"], spec)
        require(int(row["reported_records"]) == int(prior["actual_rows"]) == len(frame)
                and int(prior["columns"]) == len(frame.columns), f"Recorded profile dimensions differ: {source_id}")
        require(frame["athlete_id"].is_unique and frame["athlete_id"].str.strip().ne("").all(),
                f"Invalid athlete identifiers: {source_id}")
        ages = pd.to_numeric(frame["age"], errors="raise")
        require(ages.between(13, 17).all() and ages.mod(1).eq(0).all()
                and frame["sport"].str.strip().str.casefold().eq("basketball").all(),
                f"Unexpected age or sport values: {source_id}")
        unknown = frame["injury_status"].str.strip().str.casefold().eq("unknown")
        require(int(unknown.sum()) == eda["supporting_metrics"]["profiles"][source_id]["unknown_injury_statuses"],
                f"Unknown-status count differs from EDA: {source_id}")
        available_requests = int(frame["athlete_request"].str.strip().ne("").sum()) if "athlete_request" in frame else 0
        audit_rows.append({"source_id": source_id, "records": len(frame), "columns": len(frame.columns),
            "unknown_injury_statuses": int(unknown.sum()), "request_column_present": "athlete_request" in frame,
            "nonempty_requests": available_requests, "exact_duplicate_non_id_rows": int(frame.drop(columns="athlete_id").duplicated().sum())})
        for age in range(13, 18):
            age_rows.append({"source_id": source_id, "age": age, "records": int(ages.eq(age).sum())})
        sources[source_id], source_rows[source_id] = frame, row

    coverage_path = "results/eda/profile_planning_input_coverage.csv"
    coverage_spec = eda["artifacts"][coverage_path]
    coverage = read_csv(coverage_path, coverage_spec["sha256"], coverage_spec)
    for row in coverage.to_dict("records"):
        require(row["source_id"] in sources and int(row["total_records"]) == len(sources[row["source_id"]]),
                "Saved profile coverage does not match the selected sources")
    missing_groups = {source_id: coverage.loc[coverage["source_id"].eq(source_id)
        & coverage["schema_presence"].eq("absent"), "planning_field_group"].tolist() for source_id in sources}
    require(all(set(groups) == {"school_grade", "session_minutes", "existing_commitments", "sleep_information",
                               "annual_participation"} for groups in missing_groups.values()),
            "The saved planning-field gaps differ from the reviewed checkpoint")
    generator_path = "notebooks/03_Generate_Athlete_Profiles.ipynb"
    generator = json.loads(read_bytes(generator_path, "9978c2d7a455e8f4d094fd031470b45e3ad3449749d06338ad7ac04c986af50a"))
    generator_text = "\n".join("".join(cell.get("source", [])) for cell in generator["cells"])
    require("No real athlete or NBA records are used." in generator_text
            and "SEED = 42" in generator_text and "random.Random(SEED)" in generator_text
            and sources["aditi_synthetic_athletes"]["is_synthetic"].str.casefold().eq("true").all(),
            "Synthetic-source generation evidence differs")
    raw = registry.loc[registry["source_id"].eq("raw_athlete_profile")]
    require(len(raw) == 1, "Original-profile lineage entry is missing")
    provenance = {"derived_athlete_profile": "original_creation_evidence_unresolved",
                  "aditi_synthetic_athletes": "synthetic_flag_and_saved_generator; generator_not_rerun"}

    # Inspect the selected reference checkpoint, without downloads or old preparation execution.
    reference_specs = {
        "basketball": ("results/basketball_catalog_review/source_linked_schema_f42c98af0179a37d/step12_source_linked_schema_summary.json",
                       "f42c98af0179a37d4302aaa01388da280720bf73b3aae1fa17b24004a87fce36"),
        "rules": ("results/planning_rule_review/decision_tests_cd2f27a8c1f8876c/step13_decision_test_summary.json",
                  "cd2f27a8c1f8876c1ae57c0bd79257ada2f2ad80cbe3ccb3ed1d6c3a09a6dc2f"),
        "food": ("data/processed/usda_sr_legacy_2018_04/reference_ee67cf780262d24b/step14_food_reference_summary.json",
                 "ee67cf780262d24bf02bcc7230104e65bcbfe6508b44f3c36eb03100d85295af"),
    }
    references = {kind: json.loads(read_bytes(relative, expected))
                  for kind, (relative, expected) in reference_specs.items()}

    def bundle_artifact(kind, name):
        relative = (Path(reference_specs[kind][0]).parent / name).as_posix()
        spec = references[kind]["artifacts"][name]
        return read_csv(relative, spec["sha256"], spec)

    basketball = bundle_artifact("basketball", "basketball_candidate_schema_REVIEW_ONLY.csv")
    rules = bundle_artifact("rules", "planning_rule_decisions_PENDING.csv")
    foods = bundle_artifact("food", "usda_foods.csv")
    portions = bundle_artifact("food", "usda_food_portions.csv")
    planner_eligible = int(basketball["planner_eligible"].str.casefold().eq("yes").sum())
    adopted = int(rules["adoption_status"].eq("adopted").sum())
    enabled = int(rules["enabled_for_planner"].str.casefold().eq("yes").sum())
    require(planner_eligible == references["basketball"]["metrics"]["planner_eligible"]
            and adopted == references["rules"]["metrics"]["rules_adopted"]
            and enabled == references["rules"]["metrics"]["rules_enabled"], "Reference readiness counters differ")
    require(len(foods) == references["food"]["metrics"]["selected_foods"]
            and len(portions) == references["food"]["metrics"]["eligible_household_portions"],
            "Food-reference counts differ")
    readiness = pd.DataFrame([
        {"measure": "Basketball catalog candidates", "value": len(basketball)},
        {"measure": "Planner-eligible basketball drills", "value": planner_eligible},
        {"measure": "Planning-rule candidates", "value": len(rules)},
        {"measure": "Adopted planning rules", "value": adopted},
        {"measure": "Enabled planning rules", "value": enabled},
        {"measure": "Frozen food-reference foods", "value": len(foods)},
        {"measure": "Supported food portions", "value": len(portions)},
        {"measure": "Application food lookup enabled", "value": references["food"]["application_lookup_enabled"]},
    ])
    source_index = pd.DataFrame([{"source_record_key": source_id + ":" + rid,
        "source_id": source_id, "source_record_id": rid, "allowed_reuse": "development_candidate_only",
        "acceptance_status": "not_reviewed"} for source_id, frame in sources.items() for rid in frame["athlete_id"]])
    require(source_index["source_record_key"].is_unique, "Source-record keys must be unique")
    existing_paths = ["data/evaluation/athlete_profiles_development.jsonl", "data/evaluation/athlete_profiles_test.jsonl",
        "data/evaluation/profile_split_manifest.csv", "data/evaluation/profile_expected_behaviors.jsonl",
        "data/evaluation/profile_feasibility_records.jsonl", "results/profile_source_lineage.csv",
        "results/profile_review_decisions.csv", "results/profile_quality_checks.csv", "results/eda/profile_coverage.csv",
        "artifacts/evaluation/profile_dataset_config.json", "results/step16_profile_preparation_summary.json"]
    existing = [p for p in existing_paths if (root / p).exists()]
    require(all(hashlib.sha256((root / p).read_bytes()).hexdigest() == expected for p, expected in hashes.items()),
            "An input changed during inspection")
    print("Step 16-1 — Saved profile inputs and selected reference checkpoints verified")
    print(f"Project: {root} | Source records: {len(source_index)} | Verified input files: {len(hashes)}")
    with pd.option_context("display.max_columns", None, "display.max_rows", 12):
        display(pd.DataFrame(audit_rows))
        display(pd.DataFrame(age_rows).pivot(index="age", columns="source_id", values="records"))
        display(readiness)
    print("Saved EDA planning-field gaps in both schemas:", missing_groups["derived_athlete_profile"])
    print("Dated availability, participant counts, space details, and family IDs also require preparation.")
    print("Earlier 30: original creation evidence remains unresolved; recorded raw-source status:", raw.iloc[0]["file_status"])
    print("Later 60: synthetic flags and saved generator inspected; no generation code was executed.")
    print("Legacy scenario_type and scenario_note contain evaluation guidance; keep them outside model-visible inputs.")
    print("Existing scenarios require category and family review; limited equipment alone does not establish a conflict.")
    print("Existing Step 16 paths:", existing or "none")
    print("Drafting can proceed. Final feasibility approval and rule-dependent expectations remain gated by reference readiness and team review.")
    print("No source values changed. No profiles accepted, no families assigned, and no final test cases created.")
    return {"root": root, "sources": sources, "source_register_rows": source_rows,
        "source_index": source_index, "source_audit": pd.DataFrame(audit_rows), "coverage": coverage,
        "missing_planning_groups": missing_groups, "provenance": provenance,
        "generation_notebook_path": generator_path, "references": references, "reference_readiness": readiness,
        "reference_producer_paths": {k: v[0] for k, v in reference_specs.items()},
        "reference_tables": {"basketball": basketball, "rules": rules, "foods": foods, "portions": portions},
        "input_hashes": hashes, "existing_step16_paths": existing,
        "legacy_private_fields": ["scenario_type", "scenario_note"], "all_existing_sources_development_only": True}


step16_inputs = load_step16_inputs()
step16_report.update(status="inputs_verified_drafting_allowed", profiles_created=False,
                     accepted_profiles=0, final_profiles_frozen=False)


