# Step 16-2 — Declare and save the profile contract before drafting study cases.
# This versioned bundle contains schemas and targets, with zero accepted profiles.
import copy
import hashlib
import json
import os
import shutil
import tempfile
from datetime import date, timedelta
from importlib.metadata import version
from pathlib import Path

import pandas as pd
from IPython.display import display
from jsonschema import Draft202012Validator, FormatChecker, ValidationError

if not isinstance(globals().get("step16_inputs"), dict):
    raise RuntimeError("Run Step 16-1 successfully before this cell.")
step16_contract = None
step16_report.update(status="contract_preparation_incomplete", accepted_profiles=0, final_profiles_frozen=False)


def prepare_step16_contract(inputs):
    root, input_hashes = inputs["root"], inputs["input_hashes"]

    def require(condition, message):
        if not bool(condition):
            raise RuntimeError(message)

    def verify_sources():
        require(all(hashlib.sha256((root / p).read_bytes()).hexdigest() == expected
                    for p, expected in input_hashes.items()), "A Step 16 input changed. Reconcile it before drafting.")

    def json_bytes(value):
        return (json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n").encode()

    verify_sources()
    schema_version = "athlete-profile-input-1"
    week_start = date(2026, 11, 16)
    week_end = week_start + timedelta(days=6)
    dates = [(week_start + timedelta(days=i)).isoformat() for i in range(7)]
    week = {"start_date": week_start.isoformat(), "end_date": week_end.isoformat(), "timezone": "America/Los_Angeles"}
    require(week_start.weekday() == 0 and week_end.weekday() == 6, "Reference week must run Monday through Sunday.")

    def obj(properties, required=()):
        result = {"type": "object", "properties": properties, "additionalProperties": False}
        if required:
            result["required"] = list(required)
        return result

    def nullable(spec):
        return {"anyOf": [spec, {"type": "null"}]}

    text = {"type": "string", "minLength": 1, "pattern": r"\S"}
    nonnegative_int = {"type": "integer", "minimum": 0}
    string_list = nullable({"type": "array", "items": text})
    known_date = {"type": "string", "format": "date"}
    clock = {"type": "string", "pattern": r"^(?:[01][0-9]|2[0-3]):[0-5][0-9]$"}
    window_fields = {"date": nullable({"type": "string", "enum": dates}),
                     "start_time": nullable(clock), "end_time": nullable(clock)}
    window = obj(window_fields)
    window["minProperties"] = 1
    commitment = obj({**window_fields, "description": text,
        "activity_type": nullable({"type": "string", "enum": ["organized_basketball", "other_organized_sport",
            "general_conditioning", "informal_activity", "nontraining"]}),
        "activity_kind": nullable({"type": "string", "enum": ["practice", "game", "training", "conditioning",
            "informal", "school", "travel", "other"]}), "sport": nullable(text)}, ["description"])
    background = obj({"experience_level": nullable({"type": "string", "enum": ["beginner", "intermediate", "advanced"]}),
                      "reported_skill_level": nullable(text), "position": nullable(text)})
    limits = obj({"max_session_minutes": nullable(nonnegative_int),
                  "max_additional_sessions_per_week": nullable(nonnegative_int),
                  "max_additional_minutes_per_week": nullable(nonnegative_int)})
    equipment = obj({"name": text, "quantity": nullable(nonnegative_int)}, ["name"])
    space = obj({"court_access": nullable({"type": "string", "enum": ["none", "single_hoop_area", "half_court", "full_court"]}),
                 "hoop_access": nullable({"type": "boolean"}), "usable_area_description": nullable(text),
                 "restrictions": string_list})
    sleep = obj({"average_hours_per_night": nullable({"type": "number", "minimum": 0, "maximum": 24}),
                 "reporting_period_start": nullable(known_date), "reporting_period_end": nullable(known_date)})
    annual = obj({"reporting_period_start": nullable(known_date), "reporting_period_end": nullable(known_date),
                  "organized_basketball_months": nullable({"type": "number", "minimum": 0}),
                  "months_without_organized_basketball": nullable({"type": "number", "minimum": 0}),
                  "other_sports_description": nullable(text)})
    history = obj({"sleep": nullable(sleep), "annual_participation": nullable(annual)})
    properties = {"age": nullable({"type": "integer", "minimum": 13, "maximum": 17}),
        "school_grade": nullable({"type": "integer", "minimum": 1, "maximum": 12}),
        "basketball_background": nullable(background), "goals": string_list,
        "planning_window": obj({key: {"const": value} for key, value in week.items()}, week),
        "availability": nullable({"type": "array", "items": window}), "time_limits": nullable(limits),
        "existing_commitments": nullable({"type": "array", "items": commitment}),
        "equipment": nullable({"type": "array", "items": equipment}), "space": nullable(space),
        "participants_available": nullable({"type": "integer", "minimum": 1,
            "description": "Total available participants including the athlete; never assume a partner or solo count."}),
        "reported_limitations": string_list, "history": nullable(history),
        "athlete_request": text, "food_question": {**nullable(text),
            "description": "Optional factual food-composition question supported by the frozen reference; scope requires review."}}
    schema = {"$schema": "https://json-schema.org/draft/2020-12/schema",
        "$id": "urn:champions-athletic-map:athlete-profile-input:1",
        "title": "Public athlete-profile draft input",
        **obj({"profile_id": text, "schema_version": {"const": schema_version},
               "input": obj(properties, ["planning_window", "athlete_request"])},
              ["profile_id", "schema_version", "input"])}
    Draft202012Validator.check_schema(schema)
    validator = Draft202012Validator(copy.deepcopy(schema), format_checker=FormatChecker())

    def model_visible_input(record):
        validator.validate(record)
        for field in ["availability", "existing_commitments"]:
            for event in record["input"].get(field) or []:
                start, end = event.get("start_time"), event.get("end_time")
                if start is not None and end is not None and start >= end:
                    raise ValidationError("A known event must have positive duration within its stated date.")
        return copy.deepcopy(record["input"])

    # Structural probes are separate from the study profiles and are not saved as cases.
    base = {"profile_id": "schema-probe", "schema_version": schema_version,
            "input": {"planning_window": dict(week), "athlete_request": "Please help me plan basketball practice."}}
    unknown = copy.deepcopy(base)
    unknown["input"].update({key: None for key in properties if key not in ["planning_window", "athlete_request"]})
    explicit = copy.deepcopy(base)
    explicit["input"].update(age=14, availability=[], existing_commitments=[], goals=[], reported_limitations=[],
        equipment=[{"name": "basketball", "quantity": 0}], space={"hoop_access": False, "court_access": "none"},
        time_limits={"max_session_minutes": 0, "max_additional_sessions_per_week": 0})
    probes = 0
    for record in [base, unknown, explicit]:
        require(model_visible_input(record) == record["input"], "Projection changed missingness or stated values.")
        probes += 1
    require("age" not in model_visible_input(base) and model_visible_input(unknown)["age"] is None,
            "Absent and unknown age must remain distinct.")
    invalid = []
    for field, value in [("family_id", "private-family"), ("partition", "test"), ("scenario_category", "feasible")]:
        record = copy.deepcopy(base); record["input"][field] = value; invalid.append(record)
    record = copy.deepcopy(base); record["family_id"] = "private-family"; invalid.append(record)
    record = copy.deepcopy(base); record["input"]["space"] = {"expected_response_type": "plan"}; invalid.append(record)
    record = copy.deepcopy(base); record["input"]["participants_available"] = 0; invalid.append(record)
    record = copy.deepcopy(base); record["input"]["age"] = 12; invalid.append(record)
    record = copy.deepcopy(base); record["input"]["availability"] = [
        {"date": dates[0], "start_time": "17:00", "end_time": "16:00"}]; invalid.append(record)
    for record in invalid:
        try:
            model_visible_input(record)
        except ValidationError:
            probes += 1
        else:
            raise RuntimeError("A privacy or structural schema probe unexpectedly passed.")

    categories = ["feasible", "missing_information", "conflicting_constraints", "outside_scope"]
    target_rows = []
    pilot = [[2, 1, 1, 0], [2, 1, 0, 1], [2, 0, 1, 1], [2, 1, 1, 0], [2, 1, 0, 1]]
    for collection, by_age in {"development": [[14, 2, 2, 2]] * 5, "test": [[30, 4, 3, 3]] * 5,
                               "pilot_subset": pilot, "human_review_subset": [[5, 1, 1, 1]] * 5}.items():
        for age, counts in zip(range(13, 18), by_age):
            target_rows.append({"collection": collection, "age": age, **dict(zip(categories, counts)),
                                "target_profiles": sum(counts)})
    targets = pd.DataFrame(target_rows)
    require(targets.groupby("collection")["target_profiles"].sum().to_dict() == {
        "development": 100, "test": 200, "pilot_subset": 20, "human_review_subset": 40}, "Coverage totals differ from the notebook.")
    for collection, expected in {"development": [70, 10, 10, 10], "test": [150, 20, 15, 15],
                                 "pilot_subset": [10, 4, 3, 3], "human_review_subset": [25, 5, 5, 5]}.items():
        require(targets.loc[targets["collection"].eq(collection), categories].sum().tolist() == expected,
                f"Scenario totals differ from the declared design: {collection}")
    for subset, population in [("pilot_subset", "development"), ("human_review_subset", "test")]:
        requested = targets.loc[targets["collection"].eq(subset)].set_index("age")[categories]
        available = targets.loc[targets["collection"].eq(population)].set_index("age")[categories]
        require((requested <= available).all().all(), f"Planned subset exceeds its parent quota: {subset}")
    config = {"schema_version": "profile-dataset-config-1", "recipe_version": "profile-contract-preparation-0.1.0",
        "status": "contract_prepared_for_drafting", "profile_schema_version": schema_version, "reference_week": week,
        "ordering_and_selection_seed": 42, "accepted_profiles": 0, "final_profiles_frozen": False,
        "development_includes_accepted_existing_examples": True, "existing_sources_development_only": True,
        "family_policy": {"existing_records_and_derivatives": "development only",
            "new_base_families": "Assign a partition before creating variations; prefer distinct final base cases.",
            "review": "Check provenance, exact and near duplicates, meaningful facts, and parent-child links; shared formatting or goals alone do not establish a family."},
        "age_values": list(range(13, 18)), "scenario_categories": categories,
        "target_totals": {"development": 100, "test": 200},
        "sample_targets": {"pilot_subset": 20, "human_review_subset": 40,
                           "minimum_pilot_food_questions": 2, "subsets_are_not_additional_profiles": True},
        "food_policy": "Use supported factual composition and quantity questions. Record final food-question coverage before freezing; athlete nutritional needs remain outside this field.",
        "coverage_axes": ["age", "scenario_category", "experience_and_skill", "goals", "dated_availability",
            "session_and_weekly_limits", "equipment_quantities", "court_and_hoop_access", "participants",
            "existing_commitments", "explicit_age_grade_combinations", "missing_information", "food_questions", "families"],
        "missingness": {"absent": "not provided", "null": "explicitly unknown", "empty_list": "explicitly no listed items",
                        "zero_or_false": "stated value where the field permits it; never a missing-value replacement"},
        "accepted_case_requirements": ["Explicit age 13-17 and meaningful request; missing-age application tests belong to Step 30.",
            "Recorded preparation and second-teammate review; drafting assistance does not substitute for either review.",
            "Reviewed family and partition, private expectations, and source/newly-authored detail lineage.",
            "Feasible cases need a reviewed feasibility record using approved activities, adopted rules, and required lookup operations.",
            "Intentional conflicts remain expressible; structural validation does not establish feasibility or category correctness."],
        "public_boundary": {"record_fields": ["profile_id", "schema_version", "input"], "planner_visible": "input only",
            "private_fields": ["family_id", "partition", "scenario_category", "expected_response_type", "required_checks",
                "required_check_mask", "feasibility_record", "review_decisions", "source_lineage", "scenario_type", "scenario_note"],
            "private_expectation_schema": "Prepare separately before case annotation; not part of this public schema."},
        "publication_policy": {"shareable": "Schema, aggregate targets, and generic preparation procedures.",
            "held_out": "Final inputs, expectations, feasibility records, case-level manifests/reviews/lineage, and exact generation material that reconstructs final cases.",
            "before_private_writes": "Establish ignore rules and inspect tracked paths; ignore rules do not protect already tracked files.",
            "notebook_outputs": "Keep final-case text and private case-level expectations out of public notebook outputs.",
            "retrieval_and_prompts": "Use explicit public-input allowlists; never scan evaluation directories into retrieval."},
        "authoring_policy": "Record new dates, grade, resources, participants, and other additions as authored fiction; do not recover or infer them from missing source fields.",
        "generation_status": "No study profiles generated by this contract cell.",
        "model_assisted_drafting": "If used later, save model identity, prompts, settings, and generated drafts; saved reviewed files define the benchmark.",
        "input_hashes": dict(input_hashes), "reference_producer_paths": dict(inputs["reference_producer_paths"]),
        "reference_readiness": inputs["reference_readiness"].to_dict("records"),
        "acceptance_status": "Open: selected checkpoint has no eligible drills or adopted rules, and team case review has not occurred.",
        "software": {"jsonschema": version("jsonschema"), "pandas": pd.__version__}}
    payloads = {"profile_input_schema.json": json_bytes(schema), "profile_dataset_config.json": json_bytes(config),
                "profile_coverage_targets.csv": targets.to_csv(index=False, lineterminator="\n").encode()}
    payload_hashes = {name: hashlib.sha256(content).hexdigest() for name, content in payloads.items()}
    identity = hashlib.sha256(json_bytes(payload_hashes)).hexdigest()
    summary = {"schema_version": "step16-profile-contract-producer-1", "status": "contract_prepared_for_drafting",
        "recipe_version": config["recipe_version"], "contract_digest": identity, "input_hashes": input_hashes,
        "artifacts": {name: {"sha256": payload_hashes[name], "bytes": len(content)} for name, content in payloads.items()},
        "schema_probes_passed": probes, "accepted_profiles": 0, "study_profiles_created": 0, "final_profiles_frozen": False}
    payloads["step16_profile_contract_summary.json"] = json_bytes(summary)
    parent = root / "artifacts/evaluation"
    bundle = parent / ("profile_contract_" + identity[:16])
    require(bundle.resolve().is_relative_to(root) and not bundle.is_symlink(), "Invalid contract output directory.")
    verify_sources()
    mode = "reused_verified_contract"
    if bundle.exists():
        require(bundle.is_dir() and all((bundle / name).is_file() and (bundle / name).read_bytes() == content
            for name, content in payloads.items()), "An existing contract differs. Preserve it and declare a new version.")
    else:
        parent.mkdir(parents=True, exist_ok=True)
        staging = Path(tempfile.mkdtemp(prefix="profile_contract_stage_", dir=parent))
        try:
            for name, content in payloads.items():
                (staging / name).write_bytes(content)
                require((staging / name).read_bytes() == content, "Staged contract verification failed.")
            verify_sources()
            require(not bundle.exists(), "Contract directory appeared during saving; inspect it before continuing.")
            os.rename(staging, bundle)
            mode = "saved_and_verified_contract"
        finally:
            if staging.exists():
                shutil.rmtree(staging)
    require(all((bundle / name).read_bytes() == content for name, content in payloads.items()), "Saved contract readback failed.")
    verify_sources()
    print("Step 16-2 — Profile contract and coverage targets saved")
    print("Reference week:", week)
    print(f"Schema probes passed: {probes} | Mode: {mode}")
    with pd.option_context("display.max_columns", None, "display.max_rows", 12):
        display(targets.loc[targets["collection"].isin(["development", "test"])])
    print("Contract bundle:", bundle.relative_to(root).as_posix())
    print("The pilot and human-review targets describe subsets of the planned 100/200 profiles.")
    print("Absent fields, null, empty lists, and permitted zero/false values remain distinct. No defaults are inserted.")
    print("Only input is planner-visible. Private annotations and final-case material require a separate protected workflow.")
    print("No study profiles created or accepted; final freeze remains open. Original inputs unchanged.")
    return {"status": "contract_saved_for_drafting", "root": root, "bundle_root": bundle,
        "schema": schema, "config": config, "coverage_targets": targets, "contract_digest": identity,
        "artifact_hashes": {name: hashlib.sha256(content).hexdigest() for name, content in payloads.items()},
        "input_hashes": dict(input_hashes), "model_visible_input": model_visible_input,
        "accepted_profiles": 0, "final_profiles_frozen": False}


step16_contract = prepare_step16_contract(step16_inputs)
step16_report.update(status="contract_saved_for_drafting", profiles_created=False,
                     accepted_profiles=0, final_profiles_frozen=False)


# In[11]:


# Step 16-3 — Protect evaluation material and record source lineage for review.
# Git index checks precede private writes. No study profiles or families are assigned.
import hashlib
import io
import json
import os
import shutil
import subprocess
import tempfile
from pathlib import Path

import pandas as pd
from IPython.display import display

if not isinstance(globals().get("step16_inputs"), dict) or not isinstance(globals().get("step16_contract"), dict):
    raise RuntimeError("Run Steps 16-1 and 16-2 successfully first.")
step16_inventory = None
step16_report.update(status="source_inventory_incomplete", accepted_profiles=0, final_profiles_frozen=False)


def prepare_step16_private_inventory(inputs, contract):
    root = Path(inputs["root"]).resolve()
    recipe_version = "profile-source-inventory-0.1.0"
    ignore_policy_version = "step16-private-evaluation-0.1.0"

    def require(condition, message):
        if not bool(condition):
            raise RuntimeError(message)

    def json_bytes(value):
        return (json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n").encode()

    def digest(content):
        return hashlib.sha256(content).hexdigest()

    git_executable = shutil.which("git")
    if git_executable is None and os.name == "nt":
        candidates = [Path(base) / "Git/cmd/git.exe" for key in ["ProgramFiles", "ProgramFiles(x86)"]
                      if (base := os.environ.get(key))]
        if os.environ.get("LOCALAPPDATA"):
            candidates.append(Path(os.environ["LOCALAPPDATA"]) / "Programs/Git/cmd/git.exe")
        git_executable = next((str(path) for path in candidates if path.is_file()), None)
    require(git_executable is not None, "Git is not available to this notebook kernel. Check its PATH before continuing.")

    def git(arguments, stdin=None, allowed=(0,)):
        try:
            result = subprocess.run([git_executable, "-C", str(root), *arguments], input=stdin,
                stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, encoding="utf-8", check=False)
        except FileNotFoundError as error:
            raise RuntimeError("Git is not available to this notebook kernel. Check its PATH before continuing.") from error
        require(result.returncode in allowed, "Git check failed: " + result.stderr.strip())
        return result.stdout

    require(Path(contract["root"]).resolve() == root and contract["input_hashes"] == inputs["input_hashes"],
            "Profile inputs and contract identify different source versions.")
    bundle = Path(contract["bundle_root"]).resolve()
    require(bundle.is_relative_to(root), "Contract is outside this project.")
    for name, expected in contract["artifact_hashes"].items():
        require(digest((bundle / name).read_bytes()) == expected, f"Contract file changed: {name}")
    saved_config = json.loads((bundle / "profile_dataset_config.json").read_bytes())
    require(saved_config["existing_sources_development_only"] is True
            and saved_config["accepted_profiles"] == 0 and saved_config["final_profiles_frozen"] is False,
            "Expected the provisional development-source contract.")
    hashes = dict(inputs["input_hashes"])

    def verify_sources():
        require(all(digest((root / p).read_bytes()) == expected for p, expected in hashes.items()),
                "A source input changed. Reconcile it before continuing.")

    verify_sources()
    git_root = Path(git(["rev-parse", "--show-toplevel"]).strip()).resolve()
    require(git_root == root, "The Git root differs from the project root. No private files were written.")
    branch = git(["branch", "--show-current"]).strip() or "detached_HEAD"
    public_development = "data/evaluation/athlete_profiles_development.jsonl"
    private_exact = {
        "results/profile_source_lineage.csv", "results/profile_review_decisions.csv",
        "results/profile_quality_checks.csv", "results/eda/profile_coverage.csv",
        "results/step16_profile_preparation_summary.json", "artifacts/evaluation/profile_dataset_config.json",
    }
    private_prefixes = ("results/profile_preparation/", "results/backups/step16/")

    def is_private(path):
        return ((path.startswith("data/evaluation/") and path != public_development)
                or path in private_exact or path.startswith(private_prefixes))

    def tracked_private_paths():
        return sorted(p for p in git(["ls-files", "--cached", "-z"]).split("\0") if p and is_private(p))

    tracked = tracked_private_paths()
    require(not tracked, "Protected evaluation paths are already tracked or staged: " + ", ".join(tracked)
            + ". Review that existing state before proceeding; this cell does not remove tracking or rewrite history.")
    inventory_rows, finding_rows = [], []
    registry = pd.read_csv(io.BytesIO((root / "data/source_manifest.csv").read_bytes()), dtype=str, keep_default_na=False)
    for source_id in ["derived_athlete_profile", "aditi_synthetic_athletes"]:
        entry = registry.loc[registry["source_id"].eq(source_id)]
        require(len(entry) == 1, f"Expected one source-register entry: {source_id}")
        entry = entry.iloc[0].to_dict()
        frame = pd.read_csv(io.BytesIO((root / entry["relative_path"]).read_bytes()), dtype=str, keep_default_na=False)
        require(digest((root / entry["relative_path"]).read_bytes()) == hashes[entry["relative_path"]],
                f"Profile source differs: {source_id}")
        for position, raw in enumerate(frame.to_dict("records"), 1):
            rid, key = raw["athlete_id"], source_id + ":" + raw["athlete_id"]
            origin = "source-origin:" + digest(json_bytes({"source_id": source_id,
                "source_sha256": entry["sha256"], "source_record_id": rid}))
            has_request = "athlete_request" in raw
            request_state = "column_absent" if not has_request else "nonempty" if raw["athlete_request"].strip() else "blank"
            synthetic_evidence = source_id == "aditi_synthetic_athletes"
            generator_path = inputs["generation_notebook_path"] if synthetic_evidence else ""
            inventory_rows.append({"source_record_key": key, "lineage_anchor_id": origin, "source_id": source_id,
                "source_record_id": rid, "source_record_position": position, "source_relative_path": entry["relative_path"],
                "source_file_sha256": entry["sha256"], "raw_source_fields_json": json.dumps(raw, ensure_ascii=False, sort_keys=True),
                "raw_record_sha256": digest(json_bytes(raw)), "age_raw": raw["age"], "request_state": request_state,
                "injury_status_raw": raw["injury_status"], "scenario_label_column_present": "scenario_type" in raw,
                "legacy_scenario_type_raw": raw.get("scenario_type", ""), "legacy_scenario_note_raw": raw.get("scenario_note", ""),
                "synthetic_flag_column_present": "is_synthetic" in raw, "synthetic_flag_raw": raw.get("is_synthetic", ""),
                "origin_evidence_status": "synthetic_flag_and_saved_generator" if synthetic_evidence else "original_creation_evidence_unresolved",
                "source_permission_status": entry["permission_status"], "generator_evidence_path": generator_path,
                "generator_evidence_sha256": hashes.get(generator_path, ""), "allowed_partition": "development",
                "reuse_status": "candidate_pending_review", "acceptance_status": "not_reviewed",
                "family_id": "", "family_status": "not_assigned", "profile_id": "", "newly_authored_details_json": "{}"})
            issues = ["review_planning_details_and_authoring_lineage", "family_relationship_review_pending",
                      "preparer_and_second_teammate_review_pending"]
            if not synthetic_evidence:
                issues.append("original_creation_evidence_unresolved")
            if request_state != "nonempty":
                issues.append("athlete_request_requires_authored_draft")
            if "scenario_type" in raw:
                issues.append("legacy_scenario_category_requires_review")
            if raw["injury_status"].strip().casefold() == "unknown":
                issues.append("unknown_injury_status_must_remain_unknown")
            if raw["injury_status"].strip().casefold() == "none_reported":
                issues.append("none_reported_does_not_establish_clearance")
            special = {
                "SYN004": "unlisted_hoop_or_gym_access_is_not_proven_unavailable",
                "SYN006": "rest_request_needs_review_without_inventing_an_adopted_rule_violation",
                "SYN007": "advanced_request_from_beginner_is_not_automatically_infeasible_or_outside_scope",
                "SYN008": "limited_schedule_and_equipment_do_not_establish_a_conflict",
            }
            if synthetic_evidence and rid in special:
                issues.append(special[rid])
            for issue in issues:
                finding_rows.append({"finding_id": "profile-finding:" + digest(json_bytes([origin, issue])),
                    "source_record_key": key, "lineage_anchor_id": origin, "issue": issue,
                    "review_status": "pending", "reviewer": "", "review_date": "", "decision": "", "evidence_note": ""})
    inventory, queue = pd.DataFrame(inventory_rows), pd.DataFrame(finding_rows)
    require(len(inventory) == 90 and inventory["source_record_key"].is_unique
            and inventory["lineage_anchor_id"].is_unique and queue["finding_id"].is_unique,
            "Source inventory does not reconcile with the reviewed inputs.")
    require(inventory["allowed_partition"].eq("development").all()
            and inventory["family_id"].eq("").all() and inventory["profile_id"].eq("").all(),
            "Inventory must not assign study identities or test membership.")
    data_payloads = {"profile_source_inventory.csv": inventory.to_csv(index=False, lineterminator="\n").encode(),
                     "profile_source_review_queue.csv": queue.to_csv(index=False, lineterminator="\n").encode()}
    data_hashes = {name: digest(content) for name, content in data_payloads.items()}
    identity = digest(json_bytes({"recipe_version": recipe_version, "ignore_policy_version": ignore_policy_version,
        "input_hashes": hashes, "contract_digest": contract["contract_digest"], "data_hashes": data_hashes}))
    output_parent = root / "results/profile_preparation"
    output = output_parent / ("source_inventory_" + identity[:16])
    require(output.resolve() == output and output.is_relative_to(root) and not output.is_symlink(),
            "Private output must stay at its protected project path, without symlink redirection.")
    private_probes = ["data/evaluation/athlete_profiles_test.jsonl", "data/evaluation/profile_split_manifest.csv",
        "data/evaluation/profile_expected_behaviors.jsonl", "data/evaluation/profile_feasibility_records.jsonl",
        "data/evaluation/drafts/private_probe.json", "results/profile_preparation/private_probe.json",
        "results/backups/step16/private_probe.json", *sorted(private_exact),
        *[(output / name).relative_to(root).as_posix() for name in [*data_payloads, "profile_source_inventory_summary.json"]]]
    ignore_path = root / ".gitignore"
    require(not ignore_path.is_symlink(), "Inspect the symlinked .gitignore before changing it.")
    previous_ignore = ignore_path.read_bytes() if ignore_path.exists() else None
    original = previous_ignore or b""
    newline = b"\r\n" if b"\r\n" in original else b"\n"
    lines = ["# BEGIN Step 16 private evaluation material v0.1.0", "/data/evaluation/*",
             "!/data/evaluation/athlete_profiles_development.jsonl", "/results/profile_preparation/",
             "/results/backups/step16/", *["/" + p for p in sorted(private_exact)],
             "# END Step 16 private evaluation material v0.1.0"]
    block = newline.join(line.encode() for line in lines) + newline
    if lines[0].encode() in original:
        require(block in original, "The existing Step 16 ignore block differs. Preserve it and reconcile the policy.")
        updated = original
    else:
        updated = original + (b"" if not original or original.endswith(b"\n") else newline) + newline + block
    if updated != original:
        temporary = None
        try:
            with tempfile.NamedTemporaryFile(prefix="step16_ignore_", suffix=".tmp", dir=root, delete=False) as handle:
                temporary = Path(handle.name); handle.write(updated)
            require((ignore_path.read_bytes() if ignore_path.exists() else None) == previous_ignore,
                    ".gitignore changed during preparation.")
            os.replace(temporary, ignore_path)
        finally:
            if temporary is not None and temporary.exists():
                temporary.unlink()

    def verify_git_boundary():
        require(not tracked_private_paths(), "A protected evaluation path became tracked. Stop before private writes.")
        ignored = set(filter(None, git(["check-ignore", "--no-index", "-z", "--stdin"],
            stdin="\0".join([*private_probes, public_development]) + "\0", allowed=(0, 1)).split("\0")))
        require(set(private_probes).issubset(ignored), "Effective Git ignore rules do not protect every private path. No inventory will be published.")
        return public_development not in ignored

    public_path_unignored = verify_git_boundary()
    verify_sources()
    mode = "reused_verified_inventory"
    summary_name = "profile_source_inventory_summary.json"
    if output.exists():
        require(output.is_dir() and all((output / name).read_bytes() == content for name, content in data_payloads.items()),
                "An existing source inventory differs. Preserve it before declaring a new version.")
        summary = json.loads((output / summary_name).read_bytes())
        require(summary["inventory_digest"] == identity and summary["input_hashes"] == hashes
                and summary["contract_digest"] == contract["contract_digest"]
                and summary["recipe_version"] == recipe_version and summary["ignore_policy_version"] == ignore_policy_version
                and summary["status"] == "source_candidates_pending_review"
                and summary["source_records"] == len(inventory) and summary["review_findings"] == len(queue)
                and summary["accepted_profiles"] == summary["assigned_study_families"] == summary["study_profiles_created"] == 0
                and summary["final_profiles_frozen"] is False, "Existing inventory lineage or status differs.")
        require(set(data_payloads).issubset(summary["artifacts"])
                and set(summary["artifacts"]).issubset({*data_payloads, "gitignore_before.bin"}),
                "Unexpected private inventory artifact set.")
        for name, spec in summary["artifacts"].items():
            content = (output / name).read_bytes()
            require(digest(content) == spec["sha256"] and len(content) == spec["bytes"], f"Existing private artifact changed: {name}")
    else:
        payloads = dict(data_payloads)
        if updated != original:
            payloads["gitignore_before.bin"] = original
        summary = {"schema_version": "step16-profile-source-inventory-1", "status": "source_candidates_pending_review",
            "recipe_version": recipe_version, "ignore_policy_version": ignore_policy_version,
            "inventory_digest": identity, "input_hashes": hashes,
            "contract_digest": contract["contract_digest"], "contract_path": bundle.relative_to(root).as_posix(),
            "artifacts": {name: {"sha256": digest(content), "bytes": len(content)} for name, content in payloads.items()},
            "source_records": len(inventory), "review_findings": len(queue), "accepted_profiles": 0,
            "assigned_study_families": 0, "study_profiles_created": 0, "final_profiles_frozen": False,
            "git_boundary_at_creation": {"branch": branch, "tracked_private_paths": 0, "private_probes_ignored": len(set(private_probes)),
                "gitignore_after_sha256": digest(ignore_path.read_bytes()), "gitignore_previously_existed": previous_ignore is not None,
                "gitignore_changed": updated != original, "public_development_path_unignored": public_path_unignored},
            "scope": "Private source inventory and pending review findings only. Lineage anchors are not study-family assignments.",
            "review_policy": "Preserve this source bundle; record actual team reviews in a separate versioned decision ledger.",
            "publication_note": "Ignore rules reduce accidental staging; force-add and publication still require deliberate review.",
            "source_semantics": "Raw fields retain their source wording. Unknown is not none, and none_reported is not clearance."}
        payloads[summary_name] = json_bytes(summary)
        output_parent.mkdir(parents=True, exist_ok=True)
        staging = Path(tempfile.mkdtemp(prefix="source_inventory_stage_", dir=output_parent))
        try:
            for name, content in payloads.items():
                (staging / name).write_bytes(content)
                require((staging / name).read_bytes() == content, "Private staging verification failed.")
            verify_git_boundary(); verify_sources()
            require(not output.exists(), "Private inventory directory appeared during saving; inspect it before continuing.")
            os.rename(staging, output)
            mode = "saved_and_verified_inventory"
        finally:
            if staging.exists():
                shutil.rmtree(staging)
    verify_git_boundary(); verify_sources()
    require(all((output / name).read_bytes() == content for name, content in data_payloads.items()), "Saved inventory readback failed.")
    print("Step 16-3 — Private source inventory and Git boundary prepared")
    print(f"Git branch: {branch} | Tracked protected paths: 0 | Mode: {mode}")
    print("Private output:", output.relative_to(root).as_posix())
    print("Original .gitignore content preserved; a marked block protects the new evaluation material.")
    print("Public development-file exception effective:", public_path_unignored)
    with pd.option_context("display.max_columns", None, "display.max_rows", 12):
        display(inventory.groupby(["source_id", "origin_evidence_status"]).size().reset_index(name="source_records"))
        display(inventory["request_state"].value_counts().rename_axis("request_state").reset_index(name="records"))
    print(f"Pending review findings: {len(queue)} | Development-only source records: {len(inventory)}")
    print("Lineage anchors identify source records; study families remain unassigned.")
    print("Legacy labels and notes remain private review evidence. No categories were adopted from them.")
    print("No study profiles created or accepted; final profiles remain unfrozen. Original source values unchanged.")
    return {"status": "source_inventory_prepared", "root": root, "bundle_root": output,
        "inventory": inventory, "review_queue": queue, "input_hashes": hashes,
        "contract_digest": contract["contract_digest"], "inventory_digest": identity,
        "artifact_hashes": {name: spec["sha256"] for name, spec in summary["artifacts"].items()},
        "summary_path": output / summary_name, "summary_sha256": digest((output / summary_name).read_bytes()),
        "git_boundary_verified": True, "accepted_profiles": 0, "final_profiles_frozen": False}


step16_inventory = prepare_step16_private_inventory(step16_inputs, step16_contract)
step16_report.update(status="source_inventory_prepared", profiles_created=False,
                     accepted_profiles=0, final_profiles_frozen=False)


# In[12]:


# Step 16-4 — Reserve case coverage and proposed families before drafting inputs.
# All assignments below are proposals; case acceptance and final freezing remain open.
import hashlib
import io
import itertools
import json
import os
import platform
import random
import re
import secrets
import shutil
import subprocess
import tempfile
import unicodedata
from pathlib import Path

import pandas as pd
from IPython.display import display

if not all(isinstance(globals().get(name), dict) for name in ["step16_inputs", "step16_contract", "step16_inventory"]):
    raise RuntimeError("Run Steps 16-1 through 16-3 successfully first.")
step16_blueprint = None
step16_report.update(status="blueprint_preparation_incomplete", accepted_profiles=0, final_profiles_frozen=False)


def prepare_step16_blueprint(inputs, contract, source_inventory):
    root = Path(inputs["root"]).resolve()
    recipe = "profile-coverage-blueprint-0.1.0"

    def require(condition, message):
        if not bool(condition):
            raise RuntimeError(message)

    def json_bytes(value):
        return (json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n").encode()

    def digest(content):
        return hashlib.sha256(content).hexdigest()

    def read_table(content):
        return pd.read_csv(io.BytesIO(content), dtype=str, keep_default_na=False)

    require(Path(contract["root"]).resolve() == Path(source_inventory["root"]).resolve() == root,
            "Preparation stages identify different projects.")
    require(inputs["input_hashes"] == contract["input_hashes"] == source_inventory["input_hashes"],
            "Preparation stages identify different source versions.")
    observed_inputs = dict(inputs["input_hashes"])
    for stage in [contract, source_inventory]:
        directory = Path(stage["bundle_root"]).resolve()
        require(directory.is_relative_to(root), "A preparation bundle is outside this project.")
        for name, expected in stage["artifact_hashes"].items():
            observed_inputs[(directory / name).relative_to(root).as_posix()] = expected
    observed_inputs[Path(source_inventory["summary_path"]).relative_to(root).as_posix()] = source_inventory["summary_sha256"]

    def verify_inputs():
        require(all(digest((root / p).read_bytes()) == expected for p, expected in observed_inputs.items()),
                "A source, contract, or inventory artifact changed. Preserve and reconcile that version.")

    verify_inputs()
    config = json.loads((Path(contract["bundle_root"]) / "profile_dataset_config.json").read_bytes())
    inventory = read_table((Path(source_inventory["bundle_root"]) / "profile_source_inventory.csv").read_bytes())
    require(len(inventory) == 90 and inventory["source_record_key"].is_unique
            and inventory["allowed_partition"].eq("development").all(), "Expected the 90 development-only source candidates.")
    raw = {row["source_record_key"]: json.loads(row["raw_source_fields_json"]) for row in inventory.to_dict("records")}
    source_by_key = inventory.set_index("source_record_key")

    git_executable = shutil.which("git")
    if git_executable is None and os.name == "nt":
        candidates = [Path(base) / "Git/cmd/git.exe" for key in ["ProgramFiles", "ProgramFiles(x86)"]
                      if (base := os.environ.get(key))]
        if os.environ.get("LOCALAPPDATA"):
            candidates.append(Path(os.environ["LOCALAPPDATA"]) / "Programs/Git/cmd/git.exe")
        git_executable = next((str(p) for p in candidates if p.is_file()), None)
    require(git_executable is not None, "Git is not available to this notebook kernel.")

    def git(args, stdin=None, allowed=(0,)):
        result = subprocess.run([git_executable, "-C", str(root), *args], input=stdin,
            stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, encoding="utf-8", check=False)
        require(result.returncode in allowed, "Git boundary check failed: " + result.stderr.strip())
        return result.stdout

    branch = git(["branch", "--show-current"]).strip()
    require(branch == "sam-development", "This cell expects the sam-development branch. Preserve the current checkout and reconcile it first.")

    private_exact = {"results/profile_source_lineage.csv", "results/profile_review_decisions.csv",
        "results/profile_quality_checks.csv", "results/eda/profile_coverage.csv",
        "results/step16_profile_preparation_summary.json", "artifacts/evaluation/profile_dataset_config.json"}

    def verify_private_paths(paths):
        require(Path(git(["rev-parse", "--show-toplevel"]).strip()).resolve() == root, "Git project root differs.")
        require(git(["branch", "--show-current"]).strip() == branch, "Git branch changed during preparation.")
        tracked = [p for p in git(["ls-files", "--cached", "-z"]).split("\0") if p and (
            (p.startswith("data/evaluation/") and p != "data/evaluation/athlete_profiles_development.jsonl")
            or p.startswith(("results/profile_preparation/", "results/backups/step16/")) or p in private_exact)]
        require(not tracked, "Protected evaluation material became tracked or staged: " + ", ".join(tracked))
        ignored = set(filter(None, git(["check-ignore", "--no-index", "-z", "--stdin"],
            stdin="\0".join(paths) + "\0", allowed=(0, 1)).split("\0")))
        require(set(paths).issubset(ignored), "Private output paths are no longer effectively ignored. Reconcile the Git boundary.")

    def save_immutable_bundle(directory, payloads):
        require(directory.resolve() == directory and directory.is_relative_to(root), "Private output path is redirected.")
        paths = [(directory / name).relative_to(root).as_posix() for name in payloads]
        verify_private_paths(paths); verify_inputs()
        if directory.exists():
            require(directory.is_dir() and all((directory / name).is_file() and (directory / name).read_bytes() == content
                for name, content in payloads.items()), "Existing private preparation differs; preserve it and declare a new version.")
            return "reused_verified_bundle"
        directory.parent.mkdir(parents=True, exist_ok=True)
        staging = Path(tempfile.mkdtemp(prefix="blueprint_stage_", dir=directory.parent))
        try:
            for name, content in payloads.items():
                (staging / name).write_bytes(content)
                require((staging / name).read_bytes() == content, "Private staging readback failed.")
            verify_private_paths(paths); verify_inputs()
            require(not directory.exists(), "Private bundle appeared while staging; inspect it before continuing.")
            os.rename(staging, directory)
        finally:
            if staging.exists():
                shutil.rmtree(staging)
        require(all((directory / name).read_bytes() == content for name, content in payloads.items()), "Private bundle readback failed.")
        return "saved_and_verified_bundle"

    core = {"recipe_version": recipe, "contract_digest": contract["contract_digest"],
            "inventory_digest": source_inventory["inventory_digest"], "input_hashes": observed_inputs,
            "ordering_seed": config["ordering_and_selection_seed"]}
    core_digest = digest(json_bytes(core))
    seed_directory = root / "results/profile_preparation" / ("blueprint_authoring_" + core_digest[:16])
    require(seed_directory.resolve() == seed_directory and seed_directory.is_relative_to(root),
            "Private authoring seed path is redirected.")
    seed_path = seed_directory / "private_authoring_seed.json"
    seed_manifest_path = seed_directory / "seed_manifest.json"
    seed_probes = [path.relative_to(root).as_posix() for path in [seed_path, seed_manifest_path]]
    verify_private_paths(seed_probes)
    if seed_directory.exists():
        require(seed_directory.is_dir() and all(path.resolve() == path for path in [seed_path, seed_manifest_path]),
                "Saved private authoring seed files are redirected or invalid.")
        seed_bytes = seed_path.read_bytes()
        seed_manifest_bytes = seed_manifest_path.read_bytes()
        seed_manifest = json.loads(seed_manifest_bytes)
        require(seed_manifest["core_digest"] == core_digest and seed_manifest["seed_sha256"] == digest(seed_bytes),
                "Saved private authoring seed changed. Do not resample or overwrite it.")
        seed_record = json.loads(seed_bytes)
        require(seed_record["core_digest"] == core_digest, "Private authoring context differs.")
    else:
        for previous in seed_directory.parent.glob("coverage_blueprint_*/step16_profile_blueprint_summary.json"):
            require(previous.resolve() == previous, "A prior blueprint record is redirected. Inspect it before authoring.")
            prior_summary = json.loads(previous.read_bytes())
            require(prior_summary.get("core_digest") != core_digest,
                    "A blueprint already exists for this context but its authoring seed is missing. Recover that seed; do not resample.")
        seed_record = {"schema_version": "step16-private-authoring-seed-1", "core_digest": core_digest,
            "private_authoring_seed_hex": secrets.token_hex(16), "ordering_and_selection_seed": core["ordering_seed"],
            "role": "Opaque blueprint identities and authored-context proposals; not a replacement for ordering seed 42.",
            "resampling_policy": "Reuse the saved seed and reviewed files; never resample to improve planner results."}
        seed_bytes = json_bytes(seed_record)
        seed_manifest_bytes = json_bytes({"core_digest": core_digest, "seed_sha256": digest(seed_bytes)})
        save_immutable_bundle(seed_directory, {"private_authoring_seed.json": seed_bytes,
            "seed_manifest.json": seed_manifest_bytes})
    require(re.fullmatch(r"[0-9a-f]{32}", seed_record["private_authoring_seed_hex"]) is not None,
            "Invalid saved authoring seed. Preserve it for reconciliation.")
    saved_seed_files = {seed_path: seed_bytes, seed_manifest_path: seed_manifest_bytes}

    def verify_saved_seed():
        require(all(path.resolve() == path and path.read_bytes() == content for path, content in saved_seed_files.items()),
                "Saved private authoring seed or manifest changed. Preserve it for reconciliation.")

    verify_saved_seed()
    private_seed = seed_record["private_authoring_seed_hex"]
    author_rng, ordering_rng = random.Random(int(private_seed, 16)), random.Random(core["ordering_seed"])

    def normalize(value):
        return unicodedata.normalize("NFKC", re.sub(r"\s+", " ", value).strip()).casefold()

    unknown = {"", "unknown", "none", "null", "nan", "n/a"}
    facts = {}
    for key, record in raw.items():
        facts[key] = {"age": normalize(record["age"]), "position": normalize(record["position"]),
            "experience": normalize(record["experience_level"]), "goal": normalize(record.get("goal", record.get("primary_goal", ""))),
            "available_days": normalize(record.get("available_days", record.get("available_days_per_week", ""))),
            "reported_equipment": tuple(sorted({normalize(p) for p in re.split("[,;]", record["equipment"]) if normalize(p)})),
            "injury_wording": normalize(record["injury_status"])}

    def known(value):
        return bool(value) and all(p not in unknown for p in value) if isinstance(value, tuple) else value not in unknown

    parent = {key: key for key in raw}

    def find(key):
        while parent[key] != key:
            parent[key] = parent[parent[key]]; key = parent[key]
        return key

    pairs = []
    for left, right in itertools.combinations(sorted(raw), 2):
        matches = [field for field in facts[left] if known(facts[left][field]) and known(facts[right][field])
                   and facts[left][field] == facts[right][field]]
        differences = [field for field in facts[left] if known(facts[left][field]) and known(facts[right][field])
                       and facts[left][field] != facts[right][field]]
        primary = "goal" in matches and len(matches) >= 5 and len(differences) <= 1
        secondary = differences == ["goal"] and len(matches) >= 5
        left_request, right_request = normalize(raw[left].get("athlete_request", "")), normalize(raw[right].get("athlete_request", ""))
        repeated_request = bool(left_request) and left_request == right_request
        if primary or secondary or repeated_request:
            pairs.append({"left_source_key": left, "right_source_key": right,
                "comparison": "same_goal_near_facts" if primary else "different_goal_variation_review" if secondary else "repeated_nonempty_request",
                "positive_matched_fields_json": json.dumps(matches), "different_known_fields_json": json.dumps(differences),
                "positive_match_count": len(matches), "used_for_conservative_proposal": primary,
                "review_status": "pending", "adopted_relationship": "no", "reviewer": ""})
            if primary:
                a, b = find(left), find(right); parent[max(a, b)] = min(a, b)
    pair_columns = ["left_source_key", "right_source_key", "comparison", "positive_matched_fields_json",
        "different_known_fields_json", "positive_match_count", "used_for_conservative_proposal", "review_status", "adopted_relationship", "reviewer"]
    pair_table = pd.DataFrame(pairs, columns=pair_columns)
    components = {}
    for key in raw:
        components.setdefault(find(key), []).append(key)
    proposed_source_families, source_family_rows = {}, []
    for members in components.values():
        family = "profile-family-proposal:" + digest(json_bytes(sorted(source_by_key.loc[members, "lineage_anchor_id"])))[:32]
        for key in members:
            proposed_source_families[key] = family
            source_family_rows.append({"source_record_key": key, "proposed_family_id": family, "source_members": len(members),
                "allowed_partition": "development", "basis": "conservative_similarity_proposal" if len(members) > 1 else "single_source_origin_proposal",
                "family_review_status": "pending", "ancestry_confirmed": "no"})
    source_families = pd.DataFrame(source_family_rows).sort_values("source_record_key")
    slots = []

    def add_slot(partition, age, intent, source_key=""):
        token = digest(json_bytes([private_seed, core_digest, partition, age, intent, source_key, len(slots)]))[:24]
        family = proposed_source_families[source_key] if source_key else "profile-family-proposal:" + digest(json_bytes([private_seed, token]))[:32]
        record = raw[source_key] if source_key else {}
        slots.append({"blueprint_slot_id": "profile-slot:" + token, "partition": partition, "age": age,
            "scenario_intent": intent, "origin_plan": "synthetic_parent_proposed" if source_key else "new_fictional_base_planned",
            "parent_source_record_key": source_key, "proposed_family_id": family,
            "family_review_status": "pending_full_input_and_relationship_review", "scenario_review_status": "intent_only",
            "acceptance_status": "not_reviewed", "profile_id": "", "parent_goal_raw": record.get("primary_goal", ""),
            "parent_request_raw": record.get("athlete_request", ""), "parent_equipment_raw": record.get("equipment", ""),
            "parent_available_day_count_raw": record.get("available_days_per_week", ""),
            "school_grade": "", "grade_origin": "must_be_explicitly_authored_not_inferred_from_age",
            "planned_experience": normalize(record["experience_level"]) if source_key else "",
            "planned_detail_origin": "authoring_proposal_not_recovered_source_facts", "food_question_planned": "no"})

    categories = config["scenario_categories"]
    for age in config["age_values"]:
        candidates = sorted(key for key in raw if source_by_key.at[key, "source_id"] == "aditi_synthetic_athletes"
                            and int(raw[key]["age"]) == age)
        require(len(candidates) == 12, "Expected twelve synthetic source parents per age.")
        ordering_rng.shuffle(candidates)
        source_intents = ["feasible"] * 9 + categories[1:]
        forced = {"aditi_synthetic_athletes:SYN006": "conflicting_constraints", "aditi_synthetic_athletes:SYN007": "feasible"}
        for key in [key for key in candidates if key in forced]:
            add_slot("development", age, forced[key], key); source_intents.remove(forced[key])
        ordering_rng.shuffle(source_intents)
        for key, intent in zip([key for key in candidates if key not in forced], source_intents):
            add_slot("development", age, intent, key)
        for intent, count in zip(categories, [5, 1, 1, 1]):
            for _ in range(count):
                add_slot("development", age, intent)
        for intent, count in zip(categories, [30, 4, 3, 3]):
            for _ in range(count):
                add_slot("test", age, intent)
    blueprint = pd.DataFrame(slots)
    context_axes = {"planned_basketball_focus": ["ball_control", "shooting_consistency", "passing_accuracy", "finishing_footwork",
        "defensive_footwork", "change_of_direction", "general_basketball_conditioning"],
        "planned_session_cap_minutes": [15, 20, 30, 45, 60], "planned_participant_context": ["solo", "one_partner", "small_group"],
        "planned_commitment_context": ["explicitly_none_to_be_authored", "two_team_practices", "practice_and_game", "other_sport", "school_or_travel", "busy_organized_week"],
        "planned_space_context": ["single_hoop_area", "shared_half_court", "full_court", "clear_home_floor", "small_outdoor_area"],
        "planned_availability_context": ["two_evenings", "short_windows", "weekend_windows", "split_windows", "three_weekdays", "limited_after_school"]}
    for field in context_axes:
        blueprint[field] = pd.Series("", index=blueprint.index, dtype=object)
    for _, positions in blueprint.groupby(["partition", "age"], sort=True).groups.items():
        positions = list(positions)
        for field, values in context_axes.items():
            planned = [values[i % len(values)] for i in range(len(positions))]; author_rng.shuffle(planned)
            for index, value in zip(positions, planned):
                blueprint.at[index, field] = value
        new_positions = [i for i in positions if not blueprint.at[i, "parent_source_record_key"]]
        experience = ["beginner", "intermediate", "advanced"]
        proposed_experience = [experience[j % 3] for j in range(len(new_positions))]
        author_rng.shuffle(proposed_experience)
        for index, value in zip(new_positions, proposed_experience):
            blueprint.at[index, "planned_experience"] = value
    derived = blueprint["parent_source_record_key"].ne("")
    blueprint.loc[derived, "planned_basketball_focus"] = "retain_reported_goal_review_any_authored_adaptation"
    blueprint.loc[derived, "planned_availability_context"] = "retain_reported_day_count_author_new_dated_windows"
    blueprint.loc[derived, "planned_space_context"] = "author_explicitly_without_inferring_from_reported_equipment"
    blueprint["missing_group_intent"] = ""; blueprint["conflict_intent"] = ""; blueprint["outside_scope_intent"] = ""
    mechanisms = {"missing_information": ("missing_group_intent", ["availability", "participants_available", "space", "existing_commitments"]),
        "conflicting_constraints": ("conflict_intent", ["requested_duration_exceeds_available_windows", "extra_sessions_exceed_available_dates", "positive_request_with_zero_extra_time_budget"]),
        "outside_scope": ("outside_scope_intent", ["injury_diagnosis_or_rehabilitation", "supplement_regimen", "individualized_diet_or_calorie_targets", "unrelated_nonbasketball_service"])}
    for intent, (field, choices) in mechanisms.items():
        positions = list(blueprint.index[blueprint["scenario_intent"].eq(intent)]); author_rng.shuffle(positions)
        for j, index in enumerate(positions):
            blueprint.at[index, field] = choices[j % len(choices)]
    for partition, per_age in [("development", 2), ("test", 4)]:
        for age in config["age_values"]:
            candidates = list(blueprint.index[blueprint["partition"].eq(partition) & blueprint["age"].eq(age)
                & blueprint["scenario_intent"].eq("feasible") & blueprint["parent_source_record_key"].eq("")])
            ordering_rng.shuffle(candidates)
            require(len(candidates) >= per_age, "Insufficient new feasible-intent slots for food-question coverage.")
            blueprint.loc[candidates[:per_age], "food_question_planned"] = "yes"
    reuse = inventory[["source_record_key", "origin_evidence_status", "allowed_partition"]].copy()
    slot_map = blueprint.loc[derived].set_index("parent_source_record_key")["blueprint_slot_id"]
    reuse["proposed_slot_id"] = reuse["source_record_key"].map(slot_map).fillna("")
    reuse["reuse_proposal"] = reuse["proposed_slot_id"].map(lambda value: "proposed_development_parent" if value else "held_pending_creation_evidence")
    reuse["review_status"] = "pending"; reuse["accepted_profile"] = "no"
    target_rows = read_table((Path(contract["bundle_root"]) / "profile_coverage_targets.csv").read_bytes())
    for target in target_rows.loc[target_rows["collection"].isin(["development", "test"])].to_dict("records"):
        selected = blueprint.loc[blueprint["partition"].eq(target["collection"]) & blueprint["age"].eq(int(target["age"]))]
        require(len(selected) == int(target["target_profiles"]) and all(selected["scenario_intent"].eq(c).sum() == int(target[c]) for c in categories),
                "Blueprint quotas differ from the saved contract.")
    require(len(blueprint) == 300 and blueprint["blueprint_slot_id"].is_unique and int(derived.sum()) == 60
        and not blueprint.loc[blueprint["partition"].eq("test"), "parent_source_record_key"].ne("").any()
        and blueprint.groupby("proposed_family_id")["partition"].nunique().eq(1).all(), "Invalid slot coverage or family separation.")
    tables = {"profile_coverage_blueprint.csv": blueprint, "profile_family_proposals.csv": source_families,
              "profile_family_review_pairs.csv": pair_table, "profile_source_reuse_proposals.csv": reuse}
    payloads = {name: frame.to_csv(index=False, lineterminator="\n").encode() for name, frame in tables.items()}
    data_hashes = {name: digest(content) for name, content in payloads.items()}
    identity = digest(json_bytes({"core_digest": core_digest, "seed_sha256": digest(seed_bytes), "data_hashes": data_hashes}))
    output = root / "results/profile_preparation" / ("coverage_blueprint_" + identity[:16])
    summary = {"schema_version": "step16-profile-coverage-blueprint-1", "recipe_version": recipe,
        "status": "blueprint_proposed_pending_review", "blueprint_digest": identity, "core_digest": core_digest, **core,
        "seed_bundle_path": seed_directory.relative_to(root).as_posix(), "seed_sha256": digest(seed_bytes),
        "seed_manifest_sha256": digest(seed_manifest_bytes),
        "artifacts": {name: {"sha256": data_hashes[name], "rows": len(frame), "columns": list(frame.columns)} for name, frame in tables.items()},
        "planned_profiles": {"development": 100, "test": 200}, "proposed_existing_parents": 60, "held_legacy_sources": 30,
        "proposed_new_development_bases": 40, "proposed_new_test_bases": 200,
        "proposed_food_questions": {"development": 10, "test": 20}, "food_coverage_status": "proposal_before_case_drafting",
        "profile_inputs_created": 0, "accepted_profiles": 0, "accepted_families": 0, "final_profiles_frozen": False,
        "family_method": "Review seven shared fact fields. Unknown/blank values, constant sport, and shared notes provide no positive link evidence. Same-goal pairs with at least five positive matches and at most one known difference receive conservative family proposals; weaker flags do not merge proposals.",
        "request_anchors": "SYN006 has a conflict intent requiring explicit authored scheduling evidence, not an invented adopted-rule violation. SYN007 has a feasible intent requiring reviewed appropriate adaptations; neither intent is approved.",
        "parent_replacement_policy": "If a source cannot support its slot without unsupported assumptions, hold the parent and author a distinct new development case in the same age/intent slot before freezing.",
        "source_preservation_policy": "Retain source facts and requests as evidence; record every added or changed public detail as authored transformation. Do not erase limitations to force a feasible label.",
        "final_overlap_screen": "Not performed: screen full final drafts against all 90 legacy sources and all development material before acceptance.",
        "publication_policy": "All case-level plans, exact authoring randomness, and future expectations remain private. Notebook output shows aggregates only.",
        "git_branch_at_creation": branch,
        "software_at_creation": {"python": platform.python_version(), "pandas": pd.__version__}}
    payloads["step16_profile_blueprint_summary.json"] = json_bytes(summary)
    verify_saved_seed()
    mode = save_immutable_bundle(output, payloads)
    verify_private_paths([(output / name).relative_to(root).as_posix() for name in payloads]); verify_inputs(); verify_saved_seed()
    print("Step 16-4 — Private coverage and family blueprint prepared")
    print(f"Git branch: {branch} | Mode: {mode} | Planned slots: 300 | Proposed source parents: 60 | Legacy sources held: 30")
    with pd.option_context("display.max_columns", None, "display.max_rows", 12):
        display(blueprint.groupby(["partition", "age", "scenario_intent"]).size().unstack(fill_value=0).reindex(columns=categories))
        display(blueprint.groupby(["partition", "origin_plan"]).size().reset_index(name="planned_slots"))
    print("Primary family-review pairs:", int(pair_table["used_for_conservative_proposal"].sum()),
          "| Other review flags:", int((~pair_table["used_for_conservative_proposal"]).sum()))
    print("Proposed families represented by slots:", blueprint["proposed_family_id"].nunique(), "| Accepted families: 0")
    print("Proposed factual-food questions: development 10, test 20; identities, quantities, and lookup support remain for review.")
    print("Private authoring seed saved and reused; its value and case-level plans are not printed.")
    print("Blueprint:", output.relative_to(root).as_posix())
    print("No model-visible profile inputs or expected behaviors created. Category and family proposals need full-case and team review.")
    return {"status": "blueprint_prepared_pending_review", "root": root, "bundle_root": output,
        "blueprint": blueprint, "family_proposals": source_families, "family_review_pairs": pair_table, "reuse_proposals": reuse,
        "blueprint_digest": identity, "seed_bundle_root": seed_directory, "seed_sha256": digest(seed_bytes),
        "seed_manifest_sha256": digest(seed_manifest_bytes),
        "artifact_hashes": {name: digest(content) for name, content in payloads.items()},
        "input_hashes": observed_inputs, "accepted_profiles": 0, "final_profiles_frozen": False}


step16_blueprint = prepare_step16_blueprint(step16_inputs, step16_contract, step16_inventory)
step16_report.update(status="blueprint_prepared_pending_review", profiles_created=False,
                     accepted_profiles=0, final_profiles_frozen=False)


