# Step 16-5 — Prepare seven development drafts before expanding the collection.
# These are unaccepted drafts, separate from pilot selection and final testing.
import copy
import __future__
import ast
import hashlib
import io
import json
import linecache
import os
import re
import shutil
import subprocess
import tempfile
import types
from datetime import date, timedelta
from pathlib import Path

import pandas as pd
from IPython.display import display
from jsonschema import Draft202012Validator, FormatChecker

if not all(isinstance(globals().get(name), dict) for name in
           ["step16_inputs", "step16_contract", "step16_inventory", "step16_blueprint"]):
    raise RuntimeError("Run Steps 16-1 through 16-4 successfully first.")
step16_development_preflight = None
step16_report.update(status="development_preflight_incomplete", accepted_profiles=0, final_profiles_frozen=False)


def prepare_step16_development_preflight(inputs, contract, inventory_receipt, blueprint_receipt):
    root = Path(inputs["root"]).resolve()
    recipe = "development-preflight-drafts-0.1.0"

    def require(condition, message):
        if not bool(condition):
            raise RuntimeError(message)

    def packed(value):
        return (json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n").encode()

    def sha(content):
        return hashlib.sha256(content).hexdigest()

    def relative(path):
        path = Path(path)
        require(path == path.resolve() and path.is_relative_to(root), "A saved path is redirected or outside this project.")
        return path.relative_to(root).as_posix()

    pinned = dict(inputs["input_hashes"])
    require(inputs["input_hashes"] == contract["input_hashes"] == inventory_receipt["input_hashes"],
            "The source versions differ between preparation stages.")
    for stage in [contract, inventory_receipt]:
        require(Path(stage["root"]).resolve() == root, "Preparation stages identify different projects.")
        for name, expected in stage["artifact_hashes"].items():
            pinned[relative(Path(stage["bundle_root"]) / name)] = expected
    pinned[relative(inventory_receipt["summary_path"])] = inventory_receipt["summary_sha256"]
    require(blueprint_receipt["input_hashes"] == pinned and Path(blueprint_receipt["root"]).resolve() == root,
            "The blueprint does not identify these saved inputs.")
    blueprint_inputs = dict(pinned)
    bundle = Path(blueprint_receipt["bundle_root"])
    for name, expected in blueprint_receipt["artifact_hashes"].items():
        pinned[relative(bundle / name)] = expected
    seed_directory = Path(blueprint_receipt["seed_bundle_root"])
    pinned[relative(seed_directory / "private_authoring_seed.json")] = blueprint_receipt["seed_sha256"]
    pinned[relative(seed_directory / "seed_manifest.json")] = blueprint_receipt["seed_manifest_sha256"]

    def verified_bytes():
        result = {}
        for path, expected in pinned.items():
            relative(root / path)
            require((root / path).is_file(), "A required saved preparation input is absent: " + path)
            content = (root / path).read_bytes()
            require(sha(content) == expected, "A saved preparation input changed: " + path)
            result[path] = content
        return result

    saved = verified_bytes()
    def saved_json(path):
        return json.loads(saved[relative(path)])
    def saved_table(path):
        return pd.read_csv(io.BytesIO(saved[relative(path)]), dtype=str, keep_default_na=False)

    summary = saved_json(bundle / "step16_profile_blueprint_summary.json")
    config = saved_json(Path(contract["bundle_root"]) / "profile_dataset_config.json")
    schema = saved_json(Path(contract["bundle_root"]) / "profile_input_schema.json")
    blueprint = saved_table(bundle / "profile_coverage_blueprint.csv")
    inventory = saved_table(Path(inventory_receipt["bundle_root"]) / "profile_source_inventory.csv")
    core = {key: summary[key] for key in ["recipe_version", "contract_digest", "inventory_digest", "input_hashes", "ordering_seed"]}
    require(core["input_hashes"] == blueprint_inputs and core["contract_digest"] == contract["contract_digest"]
        and core["inventory_digest"] == inventory_receipt["inventory_digest"] and core["ordering_seed"] == 42
        and sha(packed(core)) == summary["core_digest"], "Blueprint context differs from its saved producer.")
    data_hashes = {name: spec["sha256"] for name, spec in summary["artifacts"].items()}
    require(len(data_hashes) == 4 and all(data_hashes[name] == blueprint_receipt["artifact_hashes"].get(name) for name in data_hashes)
        and sha(packed({"core_digest": summary["core_digest"], "seed_sha256": summary["seed_sha256"], "data_hashes": data_hashes}))
        == summary["blueprint_digest"] == blueprint_receipt["blueprint_digest"], "Blueprint identity check failed.")
    seed = saved_json(seed_directory / "private_authoring_seed.json")
    seed_manifest = saved_json(seed_directory / "seed_manifest.json")
    require(seed["core_digest"] == seed_manifest["core_digest"] == summary["core_digest"]
        and seed_manifest["seed_sha256"] == summary["seed_sha256"] == blueprint_receipt["seed_sha256"]
        and summary["seed_manifest_sha256"] == blueprint_receipt["seed_manifest_sha256"]
        and re.fullmatch(r"[0-9a-f]{32}", seed["private_authoring_seed_hex"]) is not None,
        "Private seed lineage differs; do not regenerate it here.")
    require(summary["accepted_profiles"] == summary["accepted_families"] == summary["profile_inputs_created"] == 0
        and summary["final_profiles_frozen"] is False and len(blueprint) == 300
        and blueprint["blueprint_slot_id"].is_unique and blueprint["acceptance_status"].eq("not_reviewed").all()
        and blueprint.groupby("proposed_family_id")["partition"].nunique().eq(1).all(), "Blueprint status or family separation differs.")
    targets = saved_table(Path(contract["bundle_root"]) / "profile_coverage_targets.csv")
    for target in targets.loc[targets["collection"].isin(["development", "test"])].to_dict("records"):
        group = blueprint.loc[blueprint["partition"].eq(target["collection"]) & blueprint["age"].eq(target["age"])]
        require(len(group) == int(target["target_profiles"]) and all(
            int(group["scenario_intent"].eq(category).sum()) == int(target[category]) for category in config["scenario_categories"]),
            "Blueprint coverage differs from the contract.")
    source_slots = blueprint["parent_source_record_key"].ne("")
    require(int(source_slots.sum()) == 60 and blueprint.loc[source_slots, "partition"].eq("development").all(),
            "Existing source parents must remain development-only.")

    # Select a bounded development batch; no final inputs are drafted or printed.
    selected = []
    roles = [("new13", 13, "feasible", True), ("new14", 14, "missing_information", False),
             ("new15", 15, "conflicting_constraints", False), ("new16", 16, "outside_scope", False),
             ("new17", 17, "feasible", True)]
    for role, age, intent, food in roles:
        matches = blueprint.loc[blueprint["partition"].eq("development") & blueprint["age"].eq(str(age))
            & blueprint["scenario_intent"].eq(intent) & ~source_slots & blueprint["food_question_planned"].eq("yes" if food else "no")]
        require(not matches.empty, "A requested preflight slot is absent: " + role)
        selected.append((role, matches.sort_values("blueprint_slot_id").iloc[0].to_dict()))
    for source_id in ["SYN006", "SYN007"]:
        matches = blueprint.loc[blueprint["partition"].eq("development")
            & blueprint["parent_source_record_key"].eq("aditi_synthetic_athletes:" + source_id)]
        require(len(matches) == 1, "The preserved-request source slot is absent.")
        selected.append((source_id, matches.iloc[0].to_dict()))

    food_parent = Path(inputs["reference_producer_paths"]["food"]).parent
    food_producer = saved_json(root / inputs["reference_producer_paths"]["food"])
    nutrient_spec = food_producer["artifacts"]["usda_food_nutrients.csv"]
    nutrient_path = (food_parent / "usda_food_nutrients.csv").as_posix()
    pinned[nutrient_path] = nutrient_spec["sha256"]
    saved = verified_bytes()
    nutrients = saved_table(root / nutrient_path)
    foods = saved_table(root / food_parent / "usda_foods.csv")
    require(len(nutrients) == nutrient_spec["rows"] and list(nutrients.columns) == nutrient_spec["columns"],
            "The saved nutrient table differs from the frozen reference.")
    food_specs = {"new13": ("Strawberries, raw", "1003", "grams of protein", 100),
                  "new17": ("Bananas, raw", "1008", "kilocalories of energy", 150)}
    food_support = []
    for role, (description, nutrient, wording, grams) in food_specs.items():
        match = foods.loc[foods["description"].eq(description)]
        require(len(match) == 1, "Exact food identity is unavailable: " + description)
        fdc = match.iloc[0]["fdc_id"]
        fact = nutrients.loc[nutrients["fdc_id"].eq(fdc) & nutrients["nutrient_id"].eq(nutrient)]
        require(len(fact) == 1 and fact.iloc[0]["numeric_status"] == "available"
            and fact.iloc[0]["reference_mass_g"] == "100" and fact.iloc[0]["reference_basis"] == "edible_food",
            "A requested food fact is unavailable on the declared 100 g basis.")
        food_support.append({"role": role, "fdc_id": fdc, "description": description, "nutrient_id": nutrient,
            "quantity_g": grams, "support": "available_per_100g_field; positive_gram_scaling", "application_lookup_enabled": False})

    first_day = date.fromisoformat(config["reference_week"]["start_date"])
    dates = [(first_day + timedelta(days=i)).isoformat() for i in range(7)]
    grades = {"new13": 8, "new14": 9, "new15": 10, "new16": 10, "new17": 12, "SYN006": 7, "SYN007": 8}
    focuses = {"ball_control": "Improve ball control", "shooting_consistency": "Improve shooting consistency",
        "passing_accuracy": "Improve passing accuracy", "finishing_footwork": "Improve finishing footwork",
        "defensive_footwork": "Improve defensive footwork", "change_of_direction": "Improve changes of direction",
        "general_basketball_conditioning": "Improve general basketball conditioning"}
    day_options = {"two_evenings": [0, 3], "short_windows": [1, 5], "weekend_windows": [5, 6],
        "split_windows": [0, 2, 5], "three_weekdays": [0, 2, 4], "limited_after_school": [1, 3]}
    source_days = {2: [1, 5], 3: [0, 2, 4], 4: [0, 2, 4, 6], 5: [0, 1, 2, 4, 6]}
    outside_requests = {"injury_diagnosis_or_rehabilitation": "My knee hurts during basketball. Diagnose the cause and give me a rehabilitation program.",
        "supplement_regimen": "Tell me which supplements to take for basketball performance and give me daily doses.",
        "individualized_diet_or_calorie_targets": "Give me a personalized daily calorie target and exact meal portions for changing my body weight.",
        "unrelated_nonbasketball_service": "Write a cover letter for my weekend retail job application."}
    records, reviews, lineage, changes, checks = [], [], [], [], []
    validator = Draft202012Validator(schema, format_checker=FormatChecker())

    def leaves(value, pointer=""):
        if isinstance(value, dict) and value:
            for key, item in value.items():
                yield from leaves(item, pointer + "/" + key.replace("~", "~0").replace("/", "~1"))
        elif isinstance(value, list) and value:
            for index, item in enumerate(value):
                yield from leaves(item, pointer + "/" + str(index))
        else:
            yield pointer, value

    for role, slot in selected:
        source_key = slot["parent_source_record_key"]
        source_row = inventory.loc[inventory["source_record_key"].eq(source_key)]
        parent = json.loads(source_row.iloc[0]["raw_source_fields_json"]) if source_key else {}
        original_fields = {}
        cap = int(slot["planned_session_cap_minutes"])
        days = source_days[int(parent["available_days_per_week"])] if parent else day_options[slot["planned_availability_context"]]
        duration = min(cap, 20) if slot["planned_availability_context"] == "short_windows" else cap
        windows = [{"date": dates[d], "start_time": "17:30", "end_time": f"{(1050 + duration) // 60:02d}:{(1050 + duration) % 60:02d}"} for d in days]
        participants = {"solo": 1, "one_partner": 2, "small_group": 4}[slot["planned_participant_context"]]
        equipment = [{"name": name.strip()} for name in parent.get("equipment", "Basketball; Cones").split(";")]
        area = slot["planned_space_context"] if not parent else "clear_home_floor" if role == "SYN007" else "single_hoop_area"
        court = {"single_hoop_area": "single_hoop_area", "shared_half_court": "half_court", "full_court": "full_court",
                 "clear_home_floor": "none", "small_outdoor_area": "none"}[area]
        if not parent and slot["planned_basketball_focus"] in ["shooting_consistency", "finishing_footwork"] and court == "none":
            changes.append({"role": role, "field": "space", "proposal": area,
                "draft": "single_hoop_area", "reason": "Authored hoop access for the requested shooting/finishing focus; not recovered source data."})
            court = "single_hoop_area"
        hoop = court != "none"
        if not parent:
            equipment = [{"name": "Basketball", "quantity": 1}, {"name": "Cones", "quantity": 4}]
            if hoop:
                equipment.append({"name": "Hoop", "quantity": 1})
        data = {"age": int(parent.get("age", slot["age"])), "school_grade": grades[role],
            "basketball_background": {"experience_level": parent.get("experience_level", slot["planned_experience"]).casefold()},
            "goals": [parent["primary_goal"] if parent else focuses[slot["planned_basketball_focus"]]],
            "planning_window": copy.deepcopy(config["reference_week"]), "availability": windows,
            "time_limits": {"max_session_minutes": cap, "max_additional_sessions_per_week": len(days),
                            "max_additional_minutes_per_week": len(days) * duration},
            "existing_commitments": [], "equipment": equipment,
            "space": {"court_access": court, "hoop_access": hoop,
                "usable_area_description": {"single_hoop_area": "Paved area with a hoop and clear space around it.",
                    "half_court": "Shared half court available during the listed windows.",
                    "full_court": "Full basketball court available during the listed windows.",
                    "none": "Clear level floor space for ball control; no court or hoop."}[court], "restrictions": []},
            "participants_available": participants, "reported_limitations": []}
        context = slot["planned_commitment_context"]
        commitment_days = {"explicitly_none_to_be_authored": [], "two_team_practices": [0, 3],
            "practice_and_game": [1, 5], "other_sport": [2], "school_or_travel": [4], "busy_organized_week": [0, 2, 5]}[context]
        for d in commitment_days:
            kind = "travel" if context == "school_or_travel" else "game" if d == 5 else "practice"
            data["existing_commitments"].append({"date": dates[d], "start_time": "15:30", "end_time": "16:30",
                "description": "School travel" if kind == "travel" else "Soccer practice" if context == "other_sport" else "Basketball " + kind,
                "activity_type": "nontraining" if kind == "travel" else "other_organized_sport" if context == "other_sport" else "organized_basketball",
                "activity_kind": kind, "sport": None if kind == "travel" else "Soccer" if context == "other_sport" else "Basketball"})
        request = "Please plan two extra basketball sessions this week to work on " + data["goals"][0].removeprefix("Improve ").lower() + ". Use only the availability and resources I have listed."
        omitted = []
        if parent:
            data["basketball_background"]["position"] = parent["position"]
            injury = parent["injury_status"]
            data["reported_limitations"] = ["Injury status is unknown." if injury == "unknown" else "No injury was reported." if injury == "none_reported" else injury]
            request = parent["athlete_request"]
            original_fields = {"/input/age": "age", "/input/basketball_background/experience_level": "experience_level",
                "/input/basketball_background/position": "position", "/input/goals/0": "primary_goal",
                "/input/reported_limitations/0": "injury_status", "/input/athlete_request": "athlete_request"}
            original_fields.update({f"/input/equipment/{i}/name": "equipment" for i in range(len(equipment))})
            checks.append({"profile_role": role, "check": "source_request_and_available_day_count_preserved",
                "pass": request == parent["athlete_request"] and len({w["date"] for w in windows}) == int(parent["available_days_per_week"])})
            if role == "SYN006":
                changes.append({"role": role, "field": "conflict_mechanism", "proposal": slot["conflict_intent"],
                    "draft": "verbatim_everyday_request_vs_five_available_dates", "reason": "Direct scheduling concern; no adopted rest rule assumed."})
        elif slot["scenario_intent"] == "missing_information":
            missing = slot["missing_group_intent"]
            if missing == "availability":
                data.pop("availability"); omitted.append("availability")
                request = "Plan two extra basketball sessions around the times I am available this week."
            elif missing == "participants_available":
                data[missing] = None
                data["goals"] = ["Improve passing accuracy"]
                request = "Plan a passing rotation for everyone who will attend, with equal turns for each person."
            elif missing == "space":
                data["space"] = {"court_access": None, "hoop_access": None, "usable_area_description": None}
                data["equipment"] = [item for item in data["equipment"] if item["name"] != "Hoop"]
                data["goals"] = ["Improve shooting consistency"]
                request = "I want shooting practice at a basket this week, but I haven't confirmed whether I can access a court or hoop."
            elif missing == "existing_commitments":
                data[missing] = None
                request = "Show my complete weekly basketball schedule, including all existing practices and games and two extra sessions."
            else:
                raise RuntimeError("Unknown missing-information proposal.")
            changes.append({"role": role, "field": "missing_group_and_request", "proposal": slot["missing_group_intent"],
                "draft": missing, "reason": "Authored request targets the deliberately unprovided information; essentiality remains for review."})
        elif slot["scenario_intent"] == "conflicting_constraints":
            mechanism = slot["conflict_intent"]
            if mechanism == "requested_duration_exceeds_available_windows":
                for event in data["availability"]:
                    event["end_time"] = "17:50"
                data["time_limits"] = {"max_session_minutes": 60, "max_additional_sessions_per_week": 2, "max_additional_minutes_per_week": 90}
                request = "Schedule one uninterrupted 45-minute basketball session inside one of my listed availability windows."
            elif mechanism == "extra_sessions_exceed_available_dates":
                data["availability"] = [{"date": dates[d], "start_time": "17:30", "end_time": "18:00"} for d in [1, 5]]
                data["time_limits"] = {"max_session_minutes": 30, "max_additional_sessions_per_week": 4, "max_additional_minutes_per_week": 120}
                request = "Schedule a 30-minute basketball session on each of four different days, using only my listed availability."
            elif mechanism == "positive_request_with_zero_extra_time_budget":
                for event in data["availability"]:
                    event["end_time"] = "17:50"
                data["time_limits"] = {"max_session_minutes": 30, "max_additional_sessions_per_week": 2, "max_additional_minutes_per_week": 0}
                request = "Add a 20-minute basketball session this week without changing my stated weekly extra-training time limit."
            else:
                raise RuntimeError("Unknown conflict proposal.")
            changes.append({"role": role, "field": "availability_and_limits", "proposal": "context proposals",
                "draft": mechanism, "reason": "New fictional hard constraints authored to express the declared conflict intent."})
        elif slot["scenario_intent"] == "outside_scope":
            mechanism = slot["outside_scope_intent"]
            request = outside_requests[mechanism]
            if mechanism == "injury_diagnosis_or_rehabilitation":
                data["reported_limitations"] = ["Knee pain during basketball."]
        data["athlete_request"] = request
        if role in food_specs:
            description, _, wording, grams = food_specs[role]
            data["food_question"] = f'For the food "{description}", how many {wording} are recorded for {grams} g?'
        record = {"profile_id": "athlete:" + sha(packed([recipe, slot["blueprint_slot_id"]]))[:24],
            "schema_version": config["profile_schema_version"], "input": data}
        validator.validate(record)
        for field in ["availability", "existing_commitments"]:
            for event in data.get(field) or []:
                require(event["date"] in dates and event["start_time"] < event["end_time"], "Invalid drafted schedule.")
        records.append(record)
        for pointer, value in leaves(record):
            origin = ("copied_source" if parent[original_fields[pointer]] == value else "normalized_source") if pointer in original_fields else "authored_fiction"
            source_field = original_fields.get(pointer, "")
            if parent and pointer.startswith("/input/availability/"):
                origin, source_field = "authored_subject_to_source_day_count", "available_days_per_week"
            if pointer.startswith("/input/planning_window/") or pointer == "/schema_version":
                origin = "saved_contract_constant"
            elif pointer == "/profile_id":
                origin = "derived_opaque_identifier"
            if not parent and slot["scenario_intent"] == "missing_information" and value is None:
                origin = "intentional_unknown_authored"
            lineage.append({"profile_id": record["profile_id"], "pointer": pointer, "value_json": json.dumps(value, ensure_ascii=False),
                "origin": origin, "parent_source_record_key": source_key, "source_field": source_field,
                "source_value_json": json.dumps(parent.get(source_field), ensure_ascii=False) if source_field else ""})
        for field in [*omitted, "history"]:
            lineage.append({"profile_id": record["profile_id"], "pointer": "/input/" + field, "value_json": "",
                "origin": "intentional_omission" if field in omitted else "optional_information_not_authored",
                "parent_source_record_key": source_key, "source_field": "", "source_value_json": ""})
        if parent:
            for index in range(len(equipment)):
                lineage.append({"profile_id": record["profile_id"], "pointer": f"/input/equipment/{index}/quantity", "value_json": "",
                    "origin": "quantity_not_provided_by_source; omitted", "parent_source_record_key": source_key,
                    "source_field": "equipment", "source_value_json": json.dumps(parent["equipment"])})
        reviews.append({"profile_id": record["profile_id"], "blueprint_slot_id": slot["blueprint_slot_id"], "draft_role": role,
            "partition": "development", "scenario_intent": slot["scenario_intent"], "proposed_family_id": slot["proposed_family_id"],
            "parent_source_record_key": source_key, "category_status": "intent_pending_full_case_review",
            "family_status": "proposal_pending_relationship_review", "feasibility_status": "not_approved",
            "expected_behavior_status": "not_prepared", "preparer": "", "second_reviewer": "", "acceptance_status": "not_reviewed"})

    require(len(records) == 7 and len({r["profile_id"] for r in records}) == 7 and all(c["pass"] for c in checks),
            "Development preflight count or source preservation failed.")
    coverage = pd.DataFrame(reviews).groupby("scenario_intent").size().to_dict()
    require(coverage == {"feasible": 3, "missing_information": 1, "conflicting_constraints": 2, "outside_scope": 1}
        and {r["input"]["age"] for r in records} == set(range(13, 18)), "Preflight coverage differs.")
    draft_bytes = b"".join((json.dumps(record, ensure_ascii=False, sort_keys=True, allow_nan=False) + "\n").encode() for record in records)
    tables = {"development_draft_review_queue.csv": pd.DataFrame(reviews), "development_draft_field_lineage.csv": pd.DataFrame(lineage),
        "development_context_changes.csv": pd.DataFrame(changes, columns=["role", "field", "proposal", "draft", "reason"]),
        "development_food_support.csv": pd.DataFrame(food_support)}
    payloads = {"development_draft_inputs.jsonl": draft_bytes,
        **{name: frame.to_csv(index=False, lineterminator="\n").encode() for name, frame in tables.items()}}
    authoring_code = "".join(linecache.getlines(prepare_step16_development_preflight.__code__.co_filename))
    require("def prepare_step16_development_preflight(" in authoring_code,
            "The drafting code could not be recorded. Run the complete Step 16-5 code directly as one Jupyter cell.")
    live_code = prepare_step16_development_preflight.__code__
    future_mask = sum(getattr(__future__, name).compiler_flag for name in __future__.all_feature_names)
    captured_module = compile(authoring_code, live_code.co_filename, "exec", flags=live_code.co_flags & future_mask, dont_inherit=True)
    captured_function = next((item for item in captured_module.co_consts if isinstance(item, types.CodeType)
        and item.co_name == "prepare_step16_development_preflight"), None)
    source_matches = captured_function == live_code
    if not source_matches:
        # IPython compiles a top-level function in interactive mode.
        node = next((item for item in ast.parse(authoring_code).body if isinstance(item, ast.FunctionDef)
            and item.name == "prepare_step16_development_preflight"), None)
        if node is not None:
            interactive = compile(ast.Interactive(body=[node]), live_code.co_filename, "single",
                flags=live_code.co_flags & future_mask, dont_inherit=True)
            source_matches = any(isinstance(item, types.CodeType) and item == live_code for item in interactive.co_consts)
    require(source_matches, "The captured drafting source differs from the executing function. Preserve and reconcile it.")
    payloads["authoring_recipe.py"] = authoring_code.encode()
    payloads["authoring_recipe.json"] = packed({"recipe_version": recipe,
        "method": "deterministic Python templates; no language-model or planner call executed by this cell",
        "code_capture": "Linecache source, checked against the executing function's compiled code; no replay executed.",
        "authoring_code_sha256": sha(authoring_code.encode()),
        "assistance": "Templates prepared with ChatGPT/Codex in CODE-3; exact served model identifier and interface settings are unavailable to this notebook.",
        "drafting_brief": "Seven development drafts: five new bases spanning ages 13-17 and four intents, two supported food questions, plus both verbatim source requests. Preserve source evidence; label additions as authored fiction; keep reviews and acceptance open.",
        "selected_slots": [{"role": role, **slot} for role, slot in selected], "authored_grades": grades,
        "focus_wording": focuses, "new_day_options": day_options, "source_day_options": source_days,
        "outside_request_templates": outside_requests, "food_questions": food_specs,
        "school_grade_policy": "Explicit fictional assignments for these drafts; not inferred or recovered from a source age.",
        "optional_history_policy": "No sleep, annual-participation, or clearance facts added.",
        "authority": "Saved drafts define this preparation version; structured and team reviews remain pending."})
    hashes = {name: sha(content) for name, content in payloads.items()}
    identity = sha(packed({"recipe_version": recipe, "blueprint_digest": summary["blueprint_digest"], "input_hashes": pinned, "artifact_hashes": hashes}))
    output = root / "results/profile_preparation" / ("development_preflight_" + identity[:16])
    payloads["step16_development_preflight_summary.json"] = packed({"recipe_version": recipe, "status": "development_drafts_pending_review",
        "draft_digest": identity, "blueprint_digest": summary["blueprint_digest"], "input_hashes": pinned,
        "artifacts": hashes, "drafts": 7, "new_fictional_bases": 5, "existing_source_parents": 2, "food_questions": 2,
        "scenario_intents": coverage, "accepted_profiles": 0, "final_profiles_created": 0, "final_profiles_frozen": False,
        "pilot_selection_performed": False, "adopted_families": 0, "expected_behaviors_prepared": 0,
        "references": config["reference_readiness"], "source_checks": checks,
        "publication": "Drafts stay in the protected preparation bundle. Preview contains only development input records, without private annotations or final material."})

    git_executable = shutil.which("git")
    if git_executable is None and os.name == "nt":
        options = [Path(base) / "Git/cmd/git.exe" for name in ["ProgramFiles", "ProgramFiles(x86)"] if (base := os.environ.get(name))]
        if os.environ.get("LOCALAPPDATA"):
            options.append(Path(os.environ["LOCALAPPDATA"]) / "Programs/Git/cmd/git.exe")
        git_executable = next((str(p) for p in options if p.is_file()), None)
    require(git_executable is not None, "Git is unavailable to this kernel.")
    def git(args, stdin=None, allowed=(0,)):
        result = subprocess.run([git_executable, "-C", str(root), *args], input=stdin, stdout=subprocess.PIPE,
            stderr=subprocess.PIPE, text=True, encoding="utf-8", check=False)
        require(result.returncode in allowed, "Git boundary check failed: " + result.stderr.strip())
        return result.stdout
    protected_exact = {"results/profile_source_lineage.csv", "results/profile_review_decisions.csv", "results/profile_quality_checks.csv",
        "results/eda/profile_coverage.csv", "results/step16_profile_preparation_summary.json", "artifacts/evaluation/profile_dataset_config.json"}
    def boundary(paths):
        require(Path(git(["rev-parse", "--show-toplevel"]).strip()).resolve() == root
            and git(["branch", "--show-current"]).strip() == "sam-development", "Use the expected project on sam-development.")
        tracked = [p for p in git(["ls-files", "--cached", "-z"]).split("\0") if p and (
            (p.startswith("data/evaluation/") and p != "data/evaluation/athlete_profiles_development.jsonl")
            or p.startswith(("results/profile_preparation/", "results/backups/step16/")) or p in protected_exact)]
        require(not tracked, "Protected evaluation paths are tracked or staged. Preserve and reconcile them before saving.")
        ignored = set(filter(None, git(["check-ignore", "--no-index", "-z", "--stdin"],
            "\0".join(paths) + "\0", allowed=(0, 1)).split("\0")))
        require(set(paths).issubset(ignored), "Private preparation paths are no longer effectively ignored.")

    targets = [relative(output / name) for name in payloads]
    boundary(targets); verified_bytes()
    if output.exists():
        require(output.is_dir() and all((output / name).is_file() and relative(output / name)
            and (output / name).read_bytes() == content for name, content in payloads.items()),
            "Existing preflight files differ. Preserve them and declare a new version.")
        mode = "reused_verified_development_drafts"
    else:
        output.parent.mkdir(parents=True, exist_ok=True)
        staging = Path(tempfile.mkdtemp(prefix="development_preflight_stage_", dir=output.parent))
        try:
            boundary([relative(staging / name) for name in payloads])
            for name, content in payloads.items():
                (staging / name).write_bytes(content)
                require((staging / name).read_bytes() == content, "Draft staging readback failed.")
            boundary(targets); verified_bytes()
            require(not output.exists(), "The draft bundle appeared while saving; inspect it before proceeding.")
            os.rename(staging, output)
            mode = "saved_and_verified_development_drafts"
        finally:
            if staging.exists():
                shutil.rmtree(staging)
    require(all((output / name).read_bytes() == content for name, content in payloads.items()), "Saved draft readback failed.")
    boundary(targets); verified_bytes()
    print("Step 16-5 — Seven development drafts saved for inspection")
    print(f"Mode: {mode} | New bases: 5 | Existing source parents: 2 | Food questions: 2")
    display(pd.DataFrame(reviews).groupby("scenario_intent").size().reset_index(name="drafts"))
    print("Accepted profiles: 0 | Final profiles created: 0 | Pilot selection: not performed")
    print("Category, family, feasibility, and team reviews remain pending. Optional history remains absent.")
    print("Private bundle:", output.relative_to(root).as_posix())
    print("DEVELOPMENT INPUT PREVIEW — seven unaccepted drafts; no private annotations:")
    for record in records:
        print(json.dumps(record, ensure_ascii=False, sort_keys=True))
    return {"status": "development_drafts_pending_review", "root": root, "bundle_root": output,
        "draft_digest": identity, "records": records, "review_queue": pd.DataFrame(reviews), "input_hashes": dict(pinned),
        "artifact_hashes": {name: sha(content) for name, content in payloads.items()},
        "accepted_profiles": 0, "final_profiles_frozen": False}


step16_development_preflight = prepare_step16_development_preflight(step16_inputs, step16_contract, step16_inventory, step16_blueprint)
step16_report.update(status="development_drafts_pending_review", profiles_created=True, development_drafts=7,
                     accepted_profiles=0, final_profiles_frozen=False)


