# Step 16-6 — Check saved development drafts and record preparation findings.
# Technical checks do not accept cases or replace teammate review.
import hashlib
import io
import json
import re
from datetime import date, timedelta
from pathlib import Path

import pandas as pd
from IPython.display import display
from jsonschema import Draft202012Validator, FormatChecker

STEP16_PRIVATE_IO_SOURCE = r'''# Shared preparation I/O. Importing this module performs no project operations.
import hashlib
import os
from pathlib import Path
import shutil
import subprocess
import tempfile

VERSION = "step16-private-io-1"


def require(condition, message):
    if not bool(condition):
        raise RuntimeError(message)


def safe_path(root, relative):
    root = Path(root).resolve()
    path = root / relative
    require(path == path.resolve() and path.is_relative_to(root), "A project path is redirected or outside the project.")
    return path


def read_verified_snapshot(root, expected_hashes):
    snapshot = {}
    for relative, expected in expected_hashes.items():
        path = safe_path(root, relative)
        require(path.is_file(), "A required saved input is absent: " + relative)
        content = path.read_bytes()
        require(hashlib.sha256(content).hexdigest() == expected, "A saved preparation input changed: " + relative)
        snapshot[relative] = content
    return snapshot


def reverify_snapshot(root, snapshot):
    require(all(safe_path(root, relative).read_bytes() == content for relative, content in snapshot.items()),
            "A saved preparation input changed during this operation.")


def assert_private_git(root, relative_paths):
    root = Path(root).resolve()
    executable = shutil.which("git")
    if executable is None and os.name == "nt":
        options = [Path(base) / "Git/cmd/git.exe" for name in ["ProgramFiles", "ProgramFiles(x86)"]
                   if (base := os.environ.get(name))]
        if os.environ.get("LOCALAPPDATA"):
            options.append(Path(os.environ["LOCALAPPDATA"]) / "Programs/Git/cmd/git.exe")
        executable = next((str(path) for path in options if path.is_file()), None)
    require(executable is not None, "Git is unavailable to this kernel.")

    def git(args, stdin=None, allowed=(0,)):
        result = subprocess.run([executable, "-C", str(root), *args], input=stdin, stdout=subprocess.PIPE,
            stderr=subprocess.PIPE, text=True, encoding="utf-8", check=False)
        require(result.returncode in allowed, "Git boundary check failed: " + result.stderr.strip())
        return result.stdout

    require(Path(git(["rev-parse", "--show-toplevel"]).strip()).resolve() == root
            and git(["branch", "--show-current"]).strip() == "sam-development", "Use the expected project on sam-development.")
    exact = {"results/profile_source_lineage.csv", "results/profile_review_decisions.csv", "results/profile_quality_checks.csv",
        "results/eda/profile_coverage.csv", "results/step16_profile_preparation_summary.json", "artifacts/evaluation/profile_dataset_config.json"}
    tracked = [path for path in git(["ls-files", "--cached", "-z"]).split("\0") if path and (
        (path.startswith("data/evaluation/") and path != "data/evaluation/athlete_profiles_development.jsonl")
        or path.startswith(("results/profile_preparation/", "results/backups/step16/")) or path in exact)]
    require(not tracked, "Protected evaluation paths are tracked or staged. Preserve and reconcile them before saving.")
    paths = list(relative_paths)
    require(paths and all(safe_path(root, path) for path in paths), "No private paths were supplied.")
    ignored = set(filter(None, git(["check-ignore", "--no-index", "-z", "--stdin"],
        "\0".join(paths) + "\0", allowed=(0, 1)).split("\0")))
    require(set(paths).issubset(ignored), "Private preparation paths are no longer effectively ignored.")


def save_immutable_bundle(root, relative_directory, payloads, input_snapshot):
    root = Path(root).resolve()
    require(relative_directory.startswith("results/profile_preparation/"), "Use the private preparation directory for these bundles.")
    require(payloads and all(Path(name).name == name and name not in [".", ".."] for name in payloads),
            "Bundle filenames must be plain basenames.")
    require(all(isinstance(content, bytes) for content in payloads.values()), "Bundle payloads must be bytes.")
    output = safe_path(root, relative_directory)
    targets = [(output / name).relative_to(root).as_posix() for name in payloads]
    assert_private_git(root, targets)
    reverify_snapshot(root, input_snapshot)
    if output.exists():
        require(output.is_dir() and {path.name for path in output.iterdir()} == set(payloads),
                "Existing bundle contents differ; preserve them and declare a new version.")
        require(all(safe_path(root, output / name).is_file() and (output / name).read_bytes() == content
            for name, content in payloads.items()), "Existing bundle bytes differ; preserve them and declare a new version.")
        mode = "reused_verified_bundle"
    else:
        output.parent.mkdir(parents=True, exist_ok=True)
        staging = Path(tempfile.mkdtemp(prefix="step16_stage_", dir=output.parent))
        stage_paths = [(staging / name).relative_to(root).as_posix() for name in payloads]
        try:
            assert_private_git(root, stage_paths)
            for name, content in payloads.items():
                (staging / name).write_bytes(content)
                require((staging / name).read_bytes() == content, "Private staging readback failed.")
            assert_private_git(root, [*targets, *stage_paths])
            reverify_snapshot(root, input_snapshot)
            require(not output.exists(), "The private bundle appeared while saving; inspect it before continuing.")
            os.rename(staging, output)
            mode = "saved_and_verified_bundle"
        finally:
            if staging.exists():
                shutil.rmtree(staging)
    require(all(safe_path(root, output / name).read_bytes() == content for name, content in payloads.items()),
            "Saved private bundle readback failed.")
    assert_private_git(root, targets)
    reverify_snapshot(root, input_snapshot)
    return output, mode
'''
step16_private_io = {"__name__": "step16_private_io"}
exec(compile(STEP16_PRIVATE_IO_SOURCE, "<step16-private-io>", "exec"), step16_private_io)

if not all(isinstance(globals().get(name), dict) for name in
           ["step16_inputs", "step16_contract", "step16_inventory", "step16_blueprint", "step16_development_preflight"]):
    raise RuntimeError("Run Steps 16-1 through 16-5 successfully first.")
step16_development_audit = None
step16_report.update(status="development_preflight_audit_incomplete", accepted_profiles=0, final_profiles_frozen=False)


def audit_step16_development_preflight(inputs, contract, inventory_receipt, blueprint_receipt, receipt):
    root = Path(receipt["root"]).resolve()
    io_tools = step16_private_io
    require = io_tools["require"]
    recipe = "development-preflight-audit-0.1.0"
    def packed(value):
        return (json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n").encode()
    def sha(content):
        return hashlib.sha256(content).hexdigest()
    def relative(path):
        return io_tools["safe_path"](root, path).relative_to(root).as_posix()

    expected = dict(receipt["input_hashes"])
    require(all(Path(stage["root"]).resolve() == root for stage in [inputs, contract, inventory_receipt, blueprint_receipt]),
            "Preparation stages identify different projects.")
    require(all(expected.get(path) == value for path, value in inputs["input_hashes"].items()), "The source receipts differ.")
    for stage in [contract, inventory_receipt, blueprint_receipt]:
        for name, value in stage["artifact_hashes"].items():
            require(expected.get(relative(Path(stage["bundle_root"]) / name)) == value, "A preparation artifact version differs.")
    require(expected.get(relative(inventory_receipt["summary_path"])) == inventory_receipt["summary_sha256"],
            "The source inventory producer differs.")
    seed_root = Path(blueprint_receipt["seed_bundle_root"])
    for name, key in [("private_authoring_seed.json", "seed_sha256"), ("seed_manifest.json", "seed_manifest_sha256")]:
        require(expected.get(relative(seed_root / name)) == blueprint_receipt[key], "The private seed receipt differs.")
    bundle = Path(receipt["bundle_root"])
    require(len(receipt["artifact_hashes"]) == 8, "Expected the eight saved preflight artifacts.")
    for name, value in receipt["artifact_hashes"].items():
        expected[relative(bundle / name)] = value
    saved = io_tools["read_verified_snapshot"](root, expected)
    def load_json(path):
        return json.loads(saved[relative(path)])
    def load_table(path):
        return pd.read_csv(io.BytesIO(saved[relative(path)]), dtype=str, keep_default_na=False)

    producer = load_json(bundle / "step16_development_preflight_summary.json")
    require(producer["input_hashes"] == receipt["input_hashes"] and producer["blueprint_digest"] == blueprint_receipt["blueprint_digest"],
            "Preflight lineage differs from its producer.")
    require(len(producer["artifacts"]) == 7 and all(receipt["artifact_hashes"].get(name) == value for name, value in producer["artifacts"].items())
        and sha(packed({"recipe_version": producer["recipe_version"], "blueprint_digest": producer["blueprint_digest"],
                       "input_hashes": producer["input_hashes"], "artifact_hashes": producer["artifacts"]}))
        == producer["draft_digest"] == receipt["draft_digest"], "Preflight identity verification failed.")
    authoring = load_json(bundle / "authoring_recipe.json")
    require(authoring["authoring_code_sha256"] == sha(saved[relative(bundle / "authoring_recipe.py")]),
            "The recorded drafting code hash differs. The drafting recipe will not be executed here.")
    records = [json.loads(line) for line in saved[relative(bundle / "development_draft_inputs.jsonl")].decode().splitlines() if line.strip()]
    queue = load_table(bundle / "development_draft_review_queue.csv")
    lineage = load_table(bundle / "development_draft_field_lineage.csv")
    food_support = load_table(bundle / "development_food_support.csv")
    inventory = load_table(Path(inventory_receipt["bundle_root"]) / "profile_source_inventory.csv")
    blueprint = load_table(Path(blueprint_receipt["bundle_root"]) / "profile_coverage_blueprint.csv").set_index("blueprint_slot_id")
    raw_sources = {row["source_record_key"]: json.loads(row["raw_source_fields_json"]) for row in inventory.to_dict("records")}
    config = load_json(Path(contract["bundle_root"]) / "profile_dataset_config.json")
    validator = Draft202012Validator(load_json(Path(contract["bundle_root"]) / "profile_input_schema.json"), format_checker=FormatChecker())
    checks, findings = [], []
    def check(name, condition, profile_id=""):
        checks.append({"check": name, "profile_id": profile_id, "status": "pass" if bool(condition) else "fail"})
        require(condition, "Development draft audit failed: " + name)
    check("saved_preflight_identity_and_authoring_hash", True)
    check("seven_unique_development_records", len(records) == len(queue) == 7 and queue["profile_id"].is_unique
        and {r["profile_id"] for r in records} == set(queue["profile_id"]) and queue["partition"].eq("development").all())
    check("no_profile_acceptance_or_final_freeze", producer["accepted_profiles"] == producer["adopted_families"] == producer["final_profiles_created"] == 0
        and producer["final_profiles_frozen"] is False and producer["pilot_selection_performed"] is False)
    check("human_reviews_and_private_expectations_still_pending", queue["preparer"].eq("").all() and queue["second_reviewer"].eq("").all()
        and queue["acceptance_status"].eq("not_reviewed").all() and queue["expected_behavior_status"].eq("not_prepared").all()
        and queue["category_status"].eq("intent_pending_full_case_review").all()
        and queue["family_status"].eq("proposal_pending_relationship_review").all() and queue["feasibility_status"].eq("not_approved").all())
    check("lineage_has_unique_profile_pointer_pairs", not lineage.duplicated(["profile_id", "pointer"]).any()
        and set(lineage["profile_id"]) == set(queue["profile_id"]))
    def leaves(value, pointer=""):
        if isinstance(value, dict) and value:
            for key, item in value.items():
                yield from leaves(item, pointer + "/" + key.replace("~", "~0").replace("/", "~1"))
        elif isinstance(value, list) and value:
            for index, item in enumerate(value):
                yield from leaves(item, pointer + "/" + str(index))
        else:
            yield pointer, value
    def resolve(value, pointer):
        try:
            for token in pointer.split("/")[1:]:
                token = token.replace("~1", "/").replace("~0", "~")
                value = value[int(token)] if isinstance(value, list) else value[token]
            return True, value
        except (KeyError, IndexError, TypeError, ValueError):
            return False, None
    def minute(clock):
        hour, minutes = map(int, clock.split(":"))
        return 60 * hour + minutes
    def finding(row, kind, observation, question):
        findings.append({"profile_id": row["profile_id"], "blueprint_slot_id": row["blueprint_slot_id"],
            "finding_kind": kind, "observation": observation, "review_question": question,
            "status": "pending_content_or_team_review", "reviewer": "", "decision": ""})
    selections = {entry["role"]: entry for entry in authoring["selected_slots"]}
    start = date.fromisoformat(config["reference_week"]["start_date"])
    week_dates = {(start + timedelta(days=index)).isoformat() for index in range(7)}
    for record in records:
        pid, data = record["profile_id"], record["input"]
        row = queue.loc[queue["profile_id"].eq(pid)].iloc[0].to_dict()
        role = row["draft_role"]
        slot = blueprint.loc[row["blueprint_slot_id"]]
        check("draft_slot_family_and_development_boundary", slot["partition"] == "development"
            and selections[role]["blueprint_slot_id"] == row["blueprint_slot_id"]
            and slot["proposed_family_id"] == row["proposed_family_id"]
            and slot["parent_source_record_key"] == row["parent_source_record_key"]
            and slot["scenario_intent"] == row["scenario_intent"] and int(slot["age"]) == data["age"], pid)
        check("public_schema_and_opaque_identifier", not list(validator.iter_errors(record))
            and re.fullmatch(r"athlete:[0-9a-f]{24}", pid) is not None, pid)
        local = lineage.loc[lineage["profile_id"].eq(pid)].to_dict("records")
        actual = dict(leaves(record))
        present = {item["pointer"] for item in local if item["value_json"] != ""}
        check("complete_typed_field_lineage", present == set(actual) and all(
            item["parent_source_record_key"] == row["parent_source_record_key"] and (
                packed(json.loads(item["value_json"])) == packed(actual[item["pointer"]]) if item["value_json"] != ""
                else not resolve(record, item["pointer"])[0]) for item in local), pid)
        check("optional_history_absent_with_lineage", "history" not in data and any(
            item["pointer"] == "/input/history" and item["origin"] == "optional_information_not_authored" for item in local), pid)
        events = [event for field in ["availability", "existing_commitments"] for event in data.get(field) or []]
        check("known_schedule_entries_use_positive_windows_in_reference_week", all(event["date"] in week_dates
            and minute(event["start_time"]) < minute(event["end_time"]) for event in events), pid)
        check("availability_and_commitments_do_not_accidentally_overlap", not any(a["date"] == c["date"] and
            max(minute(a["start_time"]), minute(c["start_time"])) < min(minute(a["end_time"]), minute(c["end_time"]))
            for a in data.get("availability") or [] for c in data.get("existing_commitments") or []), pid)
        parent = raw_sources.get(row["parent_source_record_key"])
        source_fields = {}
        check("source_lineage_metadata_resolves_to_saved_evidence", all(not item["source_field"] or (
            parent is not None and item["source_field"] in parent
            and packed(json.loads(item["source_value_json"])) == packed(parent[item["source_field"]])) for item in local), pid)
        if parent:
            names = [item.strip() for item in parent["equipment"].split(";")]
            expected_values = {"/input/age": int(parent["age"]), "/input/basketball_background/experience_level": parent["experience_level"].casefold(),
                "/input/basketball_background/position": parent["position"], "/input/goals/0": parent["primary_goal"],
                "/input/athlete_request": parent["athlete_request"], "/input/reported_limitations/0":
                "Injury status is unknown." if parent["injury_status"] == "unknown" else "No injury was reported." if parent["injury_status"] == "none_reported" else parent["injury_status"]}
            expected_values.update({f"/input/equipment/{index}/name": name for index, name in enumerate(names)})
            source_fields = {"/input/age": "age", "/input/basketball_background/experience_level": "experience_level",
                "/input/basketball_background/position": "position", "/input/goals/0": "primary_goal",
                "/input/athlete_request": "athlete_request", "/input/reported_limitations/0": "injury_status",
                **{f"/input/equipment/{index}/name": "equipment" for index in range(len(names))}}
            by_pointer = {item["pointer"]: item for item in local}
            check("source_values_and_allowed_normalizations", all(resolve(record, pointer)[0]
                and packed(resolve(record, pointer)[1]) == packed(value) for pointer, value in expected_values.items())
                and all(by_pointer[pointer]["source_field"] == field and by_pointer[pointer]["origin"] == (
                    "copied_source" if packed(parent[field]) == packed(expected_values[pointer]) else "normalized_source")
                    for pointer, field in source_fields.items()), pid)
            check("source_equipment_quantities_remain_unprovided", len(data["equipment"]) == len(names)
                and all("quantity" not in item for item in data["equipment"]) and all(any(
                    item["pointer"] == f"/input/equipment/{index}/quantity" and item["value_json"] == "" for item in local)
                    for index in range(len(names))), pid)
            check("source_day_count_constrains_authored_dates", len({event["date"] for event in data["availability"]})
                == int(parent["available_days_per_week"]) and all(item["origin"] == "authored_subject_to_source_day_count"
                    for item in local if item["pointer"].startswith("/input/availability/")), pid)
        def origin_matches(item):
            pointer, evidence = item["pointer"], item["source_field"]
            if item["value_json"] == "":
                if pointer == "/input/history":
                    return item["origin"] == "optional_information_not_authored" and not evidence
                if pointer == "/input/availability" and not parent and selections[role]["missing_group_intent"] == "availability":
                    return item["origin"] == "intentional_omission" and not evidence
                quantity = re.fullmatch(r"/input/equipment/(\d+)/quantity", pointer)
                return bool(parent and quantity and int(quantity.group(1)) < len(data["equipment"])
                    and item["origin"] == "quantity_not_provided_by_source; omitted" and evidence == "equipment")
            if pointer in source_fields:
                field = source_fields[pointer]
                expected_origin = "copied_source" if packed(parent[field]) == packed(actual[pointer]) else "normalized_source"
                return item["origin"] == expected_origin and evidence == field
            if parent and pointer.startswith("/input/availability/"):
                return item["origin"] == "authored_subject_to_source_day_count" and evidence == "available_days_per_week"
            expected_origin = "authored_fiction"
            if pointer == "/profile_id":
                expected_origin = "derived_opaque_identifier"
            elif pointer == "/schema_version" or pointer.startswith("/input/planning_window/"):
                expected_origin = "saved_contract_constant"
            elif not parent and row["scenario_intent"] == "missing_information" and actual[pointer] is None:
                expected_origin = "intentional_unknown_authored"
            return item["origin"] == expected_origin and not evidence
        check("origins_distinguish_authored_source_unknown_and_omitted_fields", all(origin_matches(item) for item in local), pid)
        if role in ["new13", "new17"]:
            area = data["space"]["court_access"]
            group = data["participants_available"]
            kind = "floor_space_and_group_arrangement_review" if area == "none" and group > 1 else "feasible_support_pending"
            finding(row, kind, f"Goal: {data['goals'][0]}; court access: {area}; participants: {group}; area: {data['space']['usable_area_description']}",
                "Can approved activities fit the stated goal, time, equipment, usable area, and participant arrangement? No feasibility approval follows from complete fields.")
        elif role == "new14":
            missing = selections[role]["missing_group_intent"]
            supplied = data.get(missing, "ABSENT")
            finding(row, "missing_group_essentiality_review", f"Declared missing group: {missing}; supplied value: {json.dumps(supplied)}; request: {data['athlete_request']}",
                "Which details are essential for this concrete request, and what conditional help remains possible while clarifying them?")
        elif role == "new15":
            mechanism = selections[role]["conflict_intent"]
            longest = max(minute(event["end_time"]) - minute(event["start_time"]) for event in data["availability"])
            duration = re.search(r"\b(\d+)[ -]minute\b", data["athlete_request"])
            requested_minutes = int(duration.group(1)) if duration else None
            observed = (requested_minutes is not None and requested_minutes > longest) if mechanism == "requested_duration_exceeds_available_windows" else (
                len({event["date"] for event in data["availability"]}) < 4 if mechanism == "extra_sessions_exceed_available_dates" else
                requested_minutes is not None and requested_minutes > data["time_limits"]["max_additional_minutes_per_week"])
            check("draft_contains_the_declared_direct_time_conflict", observed, pid)
            finding(row, "direct_constraint_review", f"Request: {data['athlete_request']}; longest window: {longest} minutes; supplied limits: {json.dumps(data['time_limits'], sort_keys=True)}",
                "Does this isolate a clear contradiction in the supplied facts? No participation-rule violation is assumed.")
        elif role == "new16":
            finding(row, "scope_request_review", data["athlete_request"],
                "Does the central requested service fall outside the project policy? A pain report alone does not determine this category.")
        elif role == "SYN006":
            dates_available = {event["date"] for event in data["availability"]}
            training_types = {"organized_basketball", "other_organized_sport", "general_conditioning", "informal_activity"}
            opportunities = dates_available | {event["date"] for event in data["existing_commitments"] if event["activity_type"] in training_types}
            check("daily_request_exceeds_dates_with_listed_training_opportunities", len(opportunities) < 7, pid)
            finding(row, "daily_request_schedule_review", f"Verbatim request: {data['athlete_request']}; extra-practice dates: {len(dates_available)}; dates with a listed training opportunity or existing training: {len(opportunities)}.",
                "How does the request relate to the available dates? Existing training stays separate from additional-training limits; no unadopted rest rule is asserted.")
        elif role == "SYN007":
            finding(row, "source_request_adaptation_review", f"Request: {data['athlete_request']}; beginner experience, ball-only reported equipment, and unknown injury status remain visible.",
                "Can appropriately adapted approved activities support the goal under the supplied resources? Advanced wording alone does not establish infeasibility or clearance.")
        for index, event in enumerate(data.get("existing_commitments") or []):
            if event["activity_type"] == "nontraining" and "sport" in event and event["sport"] is None:
                finding(row, "unknown_versus_not_applicable_annotation", f"Commitment {index}: {event['description']}; nontraining activity has sport:null.",
                    "For an authored nontraining event, should the optional sport field be absent rather than use null, which the contract reserves for explicitly unknown information? Preserve the saved draft until a versioned correction.")

    food_root = root / Path(inputs["reference_producer_paths"]["food"]).parent
    nutrients = load_table(food_root / "usda_food_nutrients.csv")
    foods = load_table(food_root / "usda_foods.csv")
    for row in food_support.to_dict("records"):
        profile = next(record for record in records if queue.loc[queue["profile_id"].eq(record["profile_id"]), "draft_role"].iloc[0] == row["role"])
        identity = foods.loc[foods["fdc_id"].eq(row["fdc_id"])]
        fact = nutrients.loc[nutrients["fdc_id"].eq(row["fdc_id"]) & nutrients["nutrient_id"].eq(row["nutrient_id"])]
        question = profile["input"]["food_question"]
        check("food_identity_quantity_and_available_reference_field", len(identity) == len(fact) == 1
            and identity.iloc[0]["description"] == row["description"] and fact.iloc[0]["numeric_status"] == "available"
            and row["description"] in question and f"{row['quantity_g']} g" in question and float(row["quantity_g"]) > 0, profile["profile_id"])
    check("two_explicit_food_questions_have_support_records", len(food_support) == sum("food_question" in record["input"] for record in records) == 2
        and food_support["role"].is_unique and set(food_support["role"]) == {
            queue.loc[queue["profile_id"].eq(record["profile_id"]), "draft_role"].iloc[0] for record in records if "food_question" in record["input"]})
    basketball = load_json(root / inputs["reference_producer_paths"]["basketball"])
    rules = load_json(root / inputs["reference_producer_paths"]["rules"])
    food = load_json(root / inputs["reference_producer_paths"]["food"])
    gates = {"planner_eligible_drills_at_selected_checkpoint": basketball["metrics"]["planner_eligible"],
        "adopted_rules_at_selected_checkpoint": rules["metrics"]["rules_adopted"],
        "enabled_rules_at_selected_checkpoint": rules["metrics"]["rules_enabled"],
        "food_application_lookup_enabled_at_selected_checkpoint": food["application_lookup_enabled"],
        "team_reviews": "pending", "feasibility_records": "pending", "case_expectations": "not_prepared",
        "scope": "Selected reference checkpoint only; recheck intended versions and runtime operations before acceptance."}
    check_frame, finding_frame = pd.DataFrame(checks), pd.DataFrame(findings)
    payloads = {"development_preflight_checks.csv": check_frame.to_csv(index=False, lineterminator="\n").encode(),
        "development_preflight_findings.csv": finding_frame.to_csv(index=False, lineterminator="\n").encode(),
        "step16_private_io.py": STEP16_PRIVATE_IO_SOURCE.encode()}
    hashes = {name: sha(content) for name, content in payloads.items()}
    identity = sha(packed({"recipe_version": recipe, "input_hashes": expected, "artifact_hashes": hashes, "shared_gates": gates}))
    payloads["step16_development_preflight_audit_summary.json"] = packed({"recipe_version": recipe, "audit_digest": identity,
        "status": "technical_checks_passed_content_review_pending", "input_hashes": expected, "artifacts": hashes,
        "draft_digest": receipt["draft_digest"], "drafts_inspected": 7, "technical_checks": len(checks), "private_findings": len(findings),
        "accepted_profiles": 0, "adopted_families": 0, "new_profiles_created": 0, "existing_development_drafts": 7,
        "final_profiles_created": 0, "final_profiles_frozen": False, "shared_gates": gates,
        "human_review_decisions_recorded": 0, "profile_values_changed": 0, "private_gold_answers_created": 0,
        "boundary": "Case-level findings remain private. This audit does not adopt categories, establish feasibility, or replace teammate review.",
        "helper_version": io_tools["VERSION"], "helper_sha256": hashes["step16_private_io.py"]})
    output, mode = io_tools["save_immutable_bundle"](root, "results/profile_preparation/development_preflight_audit_" + identity[:16], payloads, saved)
    print("Step 16-6 — Saved draft integrity and preparation findings checked")
    print(f"Mode: {mode} | Drafts inspected: 7 | Technical checks passed: {len(checks)} | Private findings: {len(findings)}")
    display(finding_frame.groupby("finding_kind").size().reset_index(name="pending_findings"))
    print("Draft values changed: 0 | Accepted profiles: 0 | Human review decisions recorded: 0 | Final profiles created: 0")
    print("Feasibility, activity/rule readiness, food lookup routing, and team review remain open.")
    print("Private audit:", output.relative_to(root).as_posix())
    return {"status": "technical_checks_passed_content_review_pending", "root": root, "bundle_root": output,
        "audit_digest": identity, "input_hashes": expected, "artifact_hashes": {name: sha(content) for name, content in payloads.items()},
        "checks": check_frame, "findings": finding_frame, "shared_gates": gates,
        "io_helper_path": output / "step16_private_io.py", "io_helper_sha256": hashes["step16_private_io.py"],
        "accepted_profiles": 0, "final_profiles_frozen": False}


step16_development_audit = audit_step16_development_preflight(step16_inputs, step16_contract, step16_inventory, step16_blueprint, step16_development_preflight)
step16_report.update(status="technical_checks_passed_content_review_pending", profiles_created=True,
                     development_drafts=7, accepted_profiles=0, final_profiles_frozen=False)


