    refinements = []
    if slot["planned_basketball_focus"] in ["shooting_consistency", "finishing_footwork"] and court == "none":
        court = "single_hoop_area"
        refinements.append("Authored hoop-area access for the proposed basket-focused case; context proposals are not source facts.")
    hoop = court != "none"
    equipment = [{"name": "Basketball", "quantity": choose(sid, "balls", [1, 2])}, {"name": "Cones", "quantity": choose(sid, "cones", [3, 6])}]
    if hoop:
        equipment.append({"name": "Hoop", "quantity": 1})
    space = {"court_access": court, "hoop_access": hoop, "usable_area_description": {
        "single_hoop_area": "One outdoor hoop with an open paved practice area.", "half_court": "Half of a basketball court with its basket available.",
        "full_court": "A full court is available for this request.", "none": "A level 7 m by 5 m practice zone with a separate waiting area; no court or hoop."}[court], "restrictions": []}
    if court == "none":
        space["restrictions"] = ["Use the marked practice zone with one moving participant at a time.", "Others remain in the separate waiting area until their turn."]
    grade = choose(sid, "authored_grade", {13: [7, 8], 14: [8, 9], 15: [9, 10], 16: [10, 11], 17: [11, 12]}[age])
