# Step 16-11 — Prepare private annotation worksheets and a provisional checkpoint.
# Draft worksheets are not adopted expectations, feasibility evidence, or accepted cases.
import hashlib
import io
import json
from pathlib import Path

import pandas as pd
from IPython.display import display
from jsonschema import Draft202012Validator, FormatChecker

step16_review_workspace = None
step16_workspace_status = {"stage": "checking_prerequisites"}
if not isinstance(globals().get("step16_report"), dict):
    step16_report = {"status": "annotation_workspace_incomplete", "accepted_profiles": 0, "final_profiles_frozen": False}


def prepare_step16_review_workspace(inputs, contract, inventory_receipt, audit_receipt, development_receipt, handoff_receipt, protected_receipt):
    root = Path(protected_receipt["root"]).resolve()
    recipe = "private-review-workspace-0.1.0"
    def require(condition, code):
        if not bool(condition):
            raise RuntimeError(code)
    def packed(value):
        return (json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n").encode()
    def sha(content):
        return hashlib.sha256(content).hexdigest()
    def relative(path):
        path = Path(path)
        require(path == path.resolve() and path.is_relative_to(root), "path_boundary")
        return path.relative_to(root).as_posix()
    step16_workspace_status["stage"] = "verifying_saved_versions"
    require(all(Path(stage["root"]).resolve() == root for stage in [inputs, contract, inventory_receipt, audit_receipt, development_receipt, handoff_receipt]), "project_roots")
    audit_root = Path(audit_receipt["bundle_root"])
    audit_bytes = {}
    for name, expected in audit_receipt["artifact_hashes"].items():
        content = (root / relative(audit_root / name)).read_bytes()
        require(sha(content) == expected, "audit_artifact_hash")
        audit_bytes[name] = content
    audit = json.loads(audit_bytes["step16_development_preflight_audit_summary.json"])
    require(len(audit_bytes) == 4 and len(audit["artifacts"]) == 3
        and all(audit_receipt["artifact_hashes"].get(name) == value for name, value in audit["artifacts"].items())
        and sha(packed({"recipe_version": audit["recipe_version"], "input_hashes": audit["input_hashes"], "artifact_hashes": audit["artifacts"], "shared_gates": audit["shared_gates"]}))
        == audit["audit_digest"] == audit_receipt["audit_digest"]
        and sha(audit_bytes["step16_private_io.py"]) == audit["helper_sha256"] == audit_receipt["io_helper_sha256"], "audit_identity")
    tools = {"__name__": "step16_private_io"}
    exec(compile(audit_bytes["step16_private_io.py"].decode(), "<verified-private-io>", "exec"), tools)
    require(tools["VERSION"] == audit["helper_version"] == "step16-private-io-1", "helper_version")
    expected = dict(protected_receipt["input_hashes"])
    for stage in [contract, inventory_receipt, audit_receipt, development_receipt, handoff_receipt]:
        for name, value in stage["artifact_hashes"].items():
            require(expected.get(relative(Path(stage["bundle_root"]) / name)) == value, "upstream_receipt")
    require(all(expected.get(path) == value for path, value in inputs["input_hashes"].items()), "source_receipt")
    protected_root = Path(protected_receipt["bundle_root"])
    require(len(protected_receipt["artifact_hashes"]) == 12, "protected_artifact_count")
    expected.update({relative(protected_root / name): value for name, value in protected_receipt["artifact_hashes"].items()})
    saved = tools["read_verified_snapshot"](root, expected)
    def load_json(path):
        return json.loads(saved[relative(path)])
    def load_table(path):
        return pd.read_csv(io.BytesIO(saved[relative(path)]), dtype=str, keep_default_na=False)
    producer = load_json(protected_root / "step16_protected_test_drafts_summary.json")
    require(producer["input_hashes"] == protected_receipt["input_hashes"] and len(producer["artifacts"]) == 11
        and all(protected_receipt["artifact_hashes"].get(name) == value for name, value in producer["artifacts"].items())
        and sha(packed({"recipe_version": producer["recipe_version"], "input_hashes": producer["input_hashes"],
            "parent_handoff_digest": producer["parent_handoff_digest"], "artifact_hashes": producer["artifacts"]}))
        == producer["draft_digest"] == protected_receipt["draft_digest"]
        and producer["parent_handoff_digest"] == handoff_receipt["review_packet_digest"] and producer["development_draft_digest"] == development_receipt["draft_digest"]
        and producer["accepted_final_profiles"] == producer["adopted_families"] == producer["human_review_decisions_recorded"] == 0
        and producer["final_profiles_frozen"] is False, "protected_identity")
    authoring = load_json(protected_root / "protected_authoring_config.json")
    require(authoring["generator_sha256"] == sha(saved[relative(protected_root / "protected_generator.py")]), "comparison_module_hash")
    comparison = {"__name__": "verified_comparison_helpers"}
    exec(compile(saved[relative(protected_root / "protected_generator.py")].decode(), "<verified-pure-comparison-module>", "exec"), comparison)
    # Only comparison helpers are used below; no authoring function is called.
    development_root = Path(development_receipt["bundle_root"])
    handoff_root = Path(handoff_receipt["bundle_root"])
    handoff = load_json(handoff_root / "protected_profile_drafting_handoff.json")
    dev_records = [json.loads(line) for line in saved[relative(development_root / "development_draft_inputs.jsonl")].decode().splitlines() if line.strip()]
    test_records = [json.loads(line) for line in saved[relative(protected_root / "protected_test_draft_inputs.jsonl")].decode().splitlines() if line.strip()]
    dev_manifest = load_table(development_root / "development_draft_review_queue.csv")
    test_manifest = load_table(protected_root / "protected_test_draft_manifest.csv")
    flags = load_table(protected_root / "protected_test_overlap_review_TEMPLATE.csv")
    for name, count in producer["table_rows"].items():
        require(len(load_table(protected_root / name)) == count, "protected_table_rows")
    require(len(dev_records) == len(dev_manifest) == 100 and len(test_records) == len(test_manifest) == 200
        and len(flags) == producer["overlap_review_flags"], "population_counts")
    dev_by_id = {row["profile_id"]: row for row in dev_records}
    test_by_id = {row["profile_id"]: row for row in test_records}
    require(len(dev_by_id) == 100 and len(test_by_id) == 200 and not set(dev_by_id) & set(test_by_id), "profile_identity_boundary")
    require(set(dev_manifest["profile_id"]) == set(dev_by_id) and set(test_manifest["profile_id"]) == set(test_by_id)
        and test_manifest["parent_source_record_key"].eq("").all() and test_manifest["acceptance_status"].eq("not_reviewed").all(), "manifest_boundary")
    inventory = load_table(Path(inventory_receipt["bundle_root"]) / "profile_source_inventory.csv")
    raw_sources = {row["source_record_key"]: json.loads(row["raw_source_fields_json"]) for row in inventory.to_dict("records")}
    raw_hashes = inventory.set_index("source_record_key")["raw_record_sha256"].to_dict()
    require(len(raw_sources) == 90, "source_baseline_count")
    for frame in [dev_manifest, test_manifest]:
        require(frame["acceptance_status"].eq("not_reviewed").all(), "unaccepted_case_state")
    require(not set(dev_manifest["proposed_family_id"]) & set(test_manifest["proposed_family_id"]), "proposal_partition_boundary")
    step16_workspace_status["stage"] = "preparing_private_review_evidence"
    all_records = {**dev_by_id, **test_by_id}
    hashes = {pid: sha(packed(record)) for pid, record in all_records.items()}
    input_hashes = {pid: sha(packed(record["input"])) for pid, record in all_records.items()}
    dev_parents = dev_manifest.set_index("profile_id")["parent_source_record_key"].to_dict()
    dev_views = {pid: comparison["comparison_view"](record) for pid, record in dev_by_id.items()}
    for pid, view in dev_views.items():
        parent = raw_sources.get(dev_parents[pid])
        if view["day_count"] is None and parent:
            view["day_count"] = int(parent.get("available_days_per_week", parent.get("available_days")))
    test_views = {pid: comparison["comparison_view"](record) for pid, record in test_by_id.items()}
    source_views = {key: comparison["comparison_view"](record, raw_source=True) for key, record in raw_sources.items()}
    def boolean(value):
        require(value in ["True", "False"], "invalid_csv_boolean")
        return value == "True"
    incident = {pid: [] for pid in test_by_id}
    review_pairs, seen_pairs = [], set()
    for row in flags.to_dict("records"):
        pid, kind, other = row["candidate_profile_id"], row["comparison_kind"], row["other_record_id"]
        require(pid in test_by_id and kind in ["legacy_source", "development", "protected_candidate"], "flag_endpoint_kind")
        if kind == "legacy_source":
            require(other in raw_sources, "legacy_endpoint")
            other_hash, other_input_hash, view = raw_hashes[other], "", source_views[other]
            raw_evidence = raw_sources[other]
            request = raw_evidence.get("athlete_request", "")
        else:
            pool = dev_by_id if kind == "development" else test_by_id
            require(other in pool and other != pid, "draft_endpoint")
            other_hash, other_input_hash = hashes[other], input_hashes[other]
            view = dev_views[other] if kind == "development" else test_views[other]
            raw_evidence, request = pool[other]["input"], pool[other]["input"]["athlete_request"]
        pair_key = (kind, *sorted([pid, other])) if kind == "protected_candidate" else (kind, pid, other)
        require(pair_key not in seen_pairs, "duplicate_screen_pair")
        seen_pairs.add(pair_key)
        require(row["candidate_record_sha256"] == hashes[pid] and row["other_record_sha256"] == other_hash
            and row["candidate_input_sha256"] == input_hashes[pid] and row["other_input_sha256"] == other_input_hash
            and row["development_draft_digest"] == development_receipt["draft_digest"] and row["screen_version"] == comparison["SCREEN_VERSION"], "flag_evidence_hashes")
        require(row["screen_pair_id"] == "screen:" + sha(packed([comparison["SCREEN_VERSION"], pid, kind, other, hashes[pid], other_hash]))[:24], "flag_identity")
        evidence = comparison["compare_views"](test_views[pid], view, test_by_id[pid]["input"]["athlete_request"], request,
            exact_full_input=kind != "legacy_source" and input_hashes[pid] == other_input_hash, partial_source=kind == "legacy_source")
        require(evidence is not None and all(boolean(row[key]) == evidence[key] for key in ["exact_full_input", "repeated_request", "partial_source_projection_match", "known_fact_similarity", "cross_goal_context_similarity"])
            and json.loads(row["matching_known_fields_json"]) == json.loads(evidence["matching_known_fields_json"])
            and json.loads(row["different_known_fields_json"]) == json.loads(evidence["different_known_fields_json"]), "flag_evidence_values")
        incident[pid].append(row["screen_pair_id"])
        if kind == "protected_candidate":
            incident[other].append(row["screen_pair_id"])
        review_pairs.append({**row, "parent_flag_row_sha256": sha(packed(row)), "protected_draft_digest": protected_receipt["draft_digest"],
            "candidate_input_json": json.dumps(test_by_id[pid]["input"], ensure_ascii=False, sort_keys=True),
            "other_raw_evidence_json": json.dumps(raw_evidence, ensure_ascii=False, sort_keys=True),
            "candidate_projection_json": json.dumps(test_views[pid], ensure_ascii=False, sort_keys=True),
            "other_projection_json": json.dumps(view, ensure_ascii=False, sort_keys=True)})
    require(all(int(row["overlap_flag_count"]) == len(incident[row["profile_id"]]) for row in test_manifest.to_dict("records")), "both_endpoint_incident_counts")
    require(flags["prepared_by"].eq("").all() and flags["reviewed_by"].eq("").all() and flags["decision"].eq("").all(), "pair_decisions_not_blank")

    step16_workspace_status["stage"] = "preparing_annotation_worksheets"
    text = {"type": "string", "minLength": 1, "pattern": r"\S"}
    def nullable(spec):
        return {"anyOf": [spec, {"type": "null"}]}
    def obj(properties, required=None):
        return {"type": "object", "properties": properties, "required": list(properties) if required is None else required, "additionalProperties": False}
    reference_list = {"type": "array", "items": text}
    rule_ref = obj({"rule_id": text, "version": text, "evidence_ref": text})
    rule_refs = {"type": "array", "items": rule_ref}
    mask_entry = obj({"requirement": {"enum": ["required", "optional", "unknown", "not_applicable"]}, "justification": text, "evidence_refs": reference_list})
    base_fields = {"schema_version": {"const": "private-profile-worksheet-1"}, "profile_id": text,
        "partition": {"enum": ["development", "test"]}, "record_sha256": {"type": "string", "pattern": "^[0-9a-f]{64}$"},
        "input_sha256": {"type": "string", "pattern": "^[0-9a-f]{64}$"}, "draft_digest": text, "input_artifact_ref": text,
        "proposed_intent": {"enum": ["feasible", "missing_information", "conflicting_constraints", "outside_scope"]}, "proposed_family_id": text,
        "annotation_status": {"enum": ["not_prepared", "in_preparation"]}, "approved": {"const": False},
        "prepared_by": nullable(text), "reviewed_by": nullable(text), "prepared_at": nullable(text), "reviewed_at": nullable(text)}
    annotation_fields = {"adopted_category": nullable({"enum": ["feasible", "missing_information", "conflicting_constraints", "outside_scope"]}),
        "actual_family_id": nullable(text), "expected_response_type": nullable({"enum": ["complete_plan", "clarification", "conflict_explanation", "scope_response"]}),
        "constraints": nullable({"type": "array", "items": obj({"input_pointer": text, "condition": text, "justification": text, "evidence_refs": reference_list})}),
        "applicable_adopted_rule_refs": nullable(rule_refs), "required_checks": nullable(reference_list),
        "required_check_mask": nullable({"type": "object", "additionalProperties": mask_entry}),
        "missing_information": nullable({"type": "array", "items": obj({"input_pointer": text, "essentiality_reason": text, "evidence_refs": reference_list})}),
        "unsupported_assumptions": nullable(reference_list), "source_policy_refs": nullable(reference_list),
        "feasibility_record_ref": nullable(text), "case_decision": nullable({"enum": ["hold", "revise", "replace_with_lineage", "propose_acceptance"]}),
        "decision_rationale": nullable(text)}
    feasibility_fields = {"feasibility_needed": nullable({"type": "boolean"}),
        "feasibility_decision": nullable({"enum": ["supported", "not_supported", "not_applicable"]}),
        "decision_rationale": nullable(text), "approved_activity_refs": nullable(reference_list), "applicable_adopted_rule_refs": nullable(rule_refs),
        "witness_schedule": nullable({"type": "array", "items": obj({"date": text, "start_time": text, "end_time": text, "approved_activity_ref": text})}),
        "verification_checks": nullable(reference_list), "runtime_lookup_evidence_refs": nullable(reference_list), "source_policy_refs": nullable(reference_list)}
    private_schemas = {}
    for kind, details in [("annotation", annotation_fields), ("feasibility", feasibility_fields)]:
        schema = {"$schema": "https://json-schema.org/draft/2020-12/schema", "title": "Private unapproved " + kind + " worksheet",
            **obj({**base_fields, **details})}
        null_fields = [*details, "prepared_by", "reviewed_by", "prepared_at", "reviewed_at"]
        schema["allOf"] = [{"if": {"properties": {"annotation_status": {"const": "not_prepared"}}},
            "then": {"properties": {name: {"type": "null"} for name in null_fields}}}]
        Draft202012Validator.check_schema(schema)
        private_schemas[kind] = schema
    annotation_validator = Draft202012Validator(private_schemas["annotation"], format_checker=FormatChecker())
    feasibility_validator = Draft202012Validator(private_schemas["feasibility"], format_checker=FormatChecker())
    annotations, feasibility, protected_cards, proposals = [], [], [], []
    version_map = {"development": development_receipt["draft_digest"], "test": protected_receipt["draft_digest"]}
    input_refs = {"development": relative(development_root / "development_draft_inputs.jsonl"), "test": relative(protected_root / "protected_test_draft_inputs.jsonl")}
    for partition, frame in [("development", dev_manifest), ("test", test_manifest)]:
        for row in frame.to_dict("records"):
            pid = row["profile_id"]
            base = {"schema_version": "private-profile-worksheet-1", "profile_id": pid, "partition": partition,
                "record_sha256": hashes[pid], "input_sha256": input_hashes[pid], "draft_digest": version_map[partition], "input_artifact_ref": input_refs[partition],
                "proposed_intent": row["scenario_intent"], "proposed_family_id": row["proposed_family_id"],
                "annotation_status": "not_prepared", "approved": False, "prepared_by": None, "reviewed_by": None, "prepared_at": None, "reviewed_at": None}
            annotation = {**base, **{field: None for field in annotation_fields}}
            witness = {**base, **{field: None for field in feasibility_fields}}
            require(not any(annotation_validator.iter_errors(annotation)) and not any(feasibility_validator.iter_errors(witness)), "worksheet_schema")
            annotations.append(annotation); feasibility.append(witness)
            if partition == "test":
                data = test_by_id[pid]["input"]
                questions = {"feasible": "Which approved activities and participation rules support a feasible witness under these actual resources and limits?",
                    "missing_information": "Which information is essential to this concrete request, and what conditional assistance is possible?",
                    "conflicting_constraints": "Which stated requirements conflict? Do not invent an unadopted participation rule.",
                    "outside_scope": "Which part of the central requested service lies outside the project role, and which policy supports that decision?"}
                protected_cards.append({"profile_id": pid, "record_sha256": hashes[pid], "input_sha256": input_hashes[pid], "protected_draft_digest": protected_receipt["draft_digest"],
                    "input_json": json.dumps(data, ensure_ascii=False, sort_keys=True), "proposed_intent": row["scenario_intent"], "proposed_family_id": row["proposed_family_id"],
                    "overlap_review_ids_json": json.dumps(incident[pid]), "review_question": questions[row["scenario_intent"]],
                    "status": "pending_content_and_team_review", "prepared_by": "", "reviewed_by": "", "category_decision": "", "family_decision": "", "case_decision": "", "rationale": "", "reviewed_at": ""})
                proposals.append({"proposed_family_id": row["proposed_family_id"], "member_profile_ids_json": json.dumps([pid]), "protected_draft_digest": protected_receipt["draft_digest"],
                    "related_screen_ids_json": json.dumps(incident[pid]), "status": "proposal_not_adopted", "prepared_by": "", "reviewed_by": "", "decision": "", "rationale": "", "reviewed_at": ""})
    require(len(annotations) == len(feasibility) == 300 and len(protected_cards) == len(proposals) == 200,
            "worksheet_counts")
    # Schema probes are generic fixtures, not study cases or adopted expectations.
    probe = dict(annotations[0]); probe.update(profile_id="generic-schema-probe", partition="development")
    require(not any(annotation_validator.iter_errors(probe)), "pending_probe")
    invalid = {**probe, "annotation_status": "in_preparation", "required_check_mask": {"example_check": False}}
    require(any(annotation_validator.iter_errors(invalid)), "boolean_mask_probe")
    require(any(annotation_validator.iter_errors({**probe, "expected_response_type": "complete_plan"})), "unprepared_expectation_probe")
    require(any(annotation_validator.iter_errors({**probe, "approved": True})), "worksheet_approval_probe")
    acceptance_requirements = {"status": "requirements_for_future_acceptance_not_a_current_acceptance_validator",
        "requirements": ["Current input and record hashes must match every annotation and feasibility record; changed cases need explicit reconciliation.",
            "Record actual case category and family decisions, supported response expectations, applicable checks, uncertainty, and source/project-policy evidence before scoring.",
            "Applicable rule IDs/versions must be adopted; explicit not-required/not-applicable decisions need review and rationale, not fabricated IDs.",
            "Every case adopted as feasible needs an accepted private witness using approved activities, adopted applicable rules and needed runtime operations. It is one existence example, not the unique correct plan.",
            "A real preparer and distinct second teammate must review the case. Assistant-created worksheets and executed cells are not human decisions.",
            "Legacy scenario labels and notes remain historical evidence, not adopted categories, expected behaviors, or clearance.",
            "Resolve actual source/development/final family relationships and exclusions. Similarity flags and distinct proposal IDs do not establish independence.",
            "Recheck the intended reference versions, runtime food routing and then-current development version before final freezing."],
        "model_boundary": "Private expectations, masks, witnesses and review material are excluded from prompts, retrieval and Version4's internal evaluator; final scoring is separate.",
        "review_workflow": "Keep this immutable preparation bundle unchanged. Copy worksheet/template files into a separate protected review version to enter real preparation evidence. A future accepted-record export needs its own acceptance validation.",
        "template_semantics": "Null means not prepared, not no checks required. Zero/False in model-visible inputs remain stated facts. Draft schemas allow no approved=True records."}
    food_questions = sum("food_question" in record["input"] for record in all_records.values())
