# Step 17-1 — Verify saved evaluation inputs and report open dependencies.
# Read-only: no profile acceptance, sample selection, scoring, or model execution.
import hashlib
import json
import os
import shutil
import subprocess
from pathlib import Path

import pandas as pd
from IPython.display import display

step17_inputs = None
step17_status = {"stage": "checking_prerequisites", "protocol_ready": False}


def inspect_step17_inputs(workspace_receipt, profile_input_receipt):
    def require(condition):
        if not bool(condition):
            raise RuntimeError("saved_input_check_failed")

    root = Path(workspace_receipt["root"]).resolve()
    require(Path(profile_input_receipt["root"]).resolve() == root)
    hashes = {}

    def path(relative):
        require(isinstance(relative, str) and "\\" not in relative)
        candidate = root / relative
        value = candidate.resolve()
        require(not Path(relative).is_absolute() and value.is_relative_to(root) and value != root)
        require(candidate == value)
        return value

    def verify(relative, expected=None):
        digest = hashlib.sha256()
        with path(relative).open("rb") as handle:
            for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                digest.update(chunk)
        observed = digest.hexdigest()
        require(expected is None or observed == expected)
        require(relative not in hashes or hashes[relative] == observed)
        hashes[relative] = observed
        return observed

    def read_json(relative):
        require(relative in hashes)
        content = path(relative).read_bytes()
        require(hashlib.sha256(content).hexdigest() == hashes[relative])
        return json.loads(content)

    def packed(value):
        return (json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n").encode()

    executable = shutil.which("git")
    if executable is None and os.name == "nt":
        options = [Path(base) / "Git/cmd/git.exe" for name in ["ProgramFiles", "ProgramFiles(x86)"]
            if (base := os.environ.get(name))]
        if os.environ.get("LOCALAPPDATA"):
            options.append(Path(os.environ["LOCALAPPDATA"]) / "Programs/Git/cmd/git.exe")
        executable = next((str(value) for value in options if value.is_file()), None)
    require(executable is not None)

    def git(*arguments):
        result = subprocess.run([executable, "-C", str(root), *arguments], capture_output=True, check=False)
        require(result.returncode == 0)
        return result.stdout

    step17_status["stage"] = "checking_git_boundary"
    require(Path(git("rev-parse", "--show-toplevel").decode().strip()).resolve() == root
        and git("branch", "--show-current").decode().strip() == "sam-development")
    private_names = {"results/profile_source_lineage.csv", "results/profile_review_decisions.csv",
        "results/profile_quality_checks.csv", "results/eda/profile_coverage.csv",
        "artifacts/evaluation/profile_dataset_config.json", "results/step16_profile_preparation_summary.json"}
    def private(relative):
        return (relative.startswith(("results/profile_preparation/", "results/backups/step16/"))
            or relative in private_names or (relative.startswith("data/evaluation/")
            and relative != "data/evaluation/athlete_profiles_development.jsonl"))
    require(not any(private(value) for value in git("ls-files", "-z").decode().split("\0") if value))

    step17_status["stage"] = "verifying_frozen_exercise_benchmark"
    producer_path = "results/step15_exercise_split_summary.json"
    verify(producer_path)
    producer = read_json(producer_path)
    require(producer["schema_version"] == "step15-exercise-split-1"
        and producer["status"] == "frozen" and producer["benchmark_frozen"] is True)
    exercise_outputs = (
        "data/processed/exercise_groups.csv", "data/processed/exercise_split_manifest.csv",
        "results/exercise_benchmark_review_decisions.csv", "results/exercise_class_eligibility.csv",
        "results/exercise_split_candidates.csv", "results/exercise_split_summary.csv",
        "results/exercise_split_checks.csv", "artifacts/splits/exercise_split_config.json")
    require(set(producer["artifacts"]) == set(exercise_outputs))
    for relative, expected in producer["input_hashes"].items():
        verify(relative, expected)
    outputs = {relative: spec["sha256"] for relative, spec in producer["artifacts"].items()}
    for relative, expected in outputs.items():
        verify(relative, expected)
    identity = json.dumps({"inputs": producer["input_hashes"], "outputs": outputs},
        ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode()
    require(producer["benchmark_id"] == "exercise-benchmark:" + hashlib.sha256(identity).hexdigest())
    config = read_json(exercise_outputs[-1])
    classes = producer["class_order"]
    require(classes == sorted(set(classes)) == config["class_order"]
        and producer["class_to_index"] == config["class_to_index"] == {label: i for i, label in enumerate(classes)}
        and config["input_hashes"] == producer["input_hashes"]
        and config["recipe_version"] == producer["recipe_version"] and config["software"] == producer["software"]
        and config["feature_contract"] == producer["feature_contract"]
        and config["feature_contract"]["input_fields"] == ["exercise_name_prepared", "description_prepared"]
        and config["feature_contract"]["target_field"] == "target_label"
        and config["feature_contract"]["model_text_field"] == "classifier_text"
        and config["feature_contract"]["source_target_field"] == "body_part_prepared"
        and config["feature_contract"]["split_group_field"] == "split_group_id"
        and config["feature_contract"]["final_splits_created"] is True
        and config["selection_uses_model_scores"] is False)
    # Parse assignment metadata only; do not inspect held-out exercise text.
    manifest_path = exercise_outputs[1]
    metadata_columns = ["catalog_id", "benchmark_eligible", "target_label", "class_index", "split_group_id", "split"]
    manifest = pd.read_csv(path(manifest_path), usecols=metadata_columns, dtype=str, keep_default_na=False)
    require(manifest["catalog_id"].is_unique and manifest["benchmark_eligible"].isin(["yes", "no"]).all())
    active = manifest.loc[manifest["benchmark_eligible"].eq("yes")]
    require(active["split"].isin(["train", "validation", "test"]).all()
        and active.groupby("split_group_id")["split"].nunique().eq(1).all()
        and sorted(active["target_label"].unique()) == classes
        and active["class_index"].tolist() == active["target_label"].map(lambda value: str(classes.index(value))).tolist())
    population = producer["population"]
    require(len(manifest) == population["source_records"] and len(active) == population["eligible_records"]
        and len(manifest) - len(active) == population["excluded_records"]
        and active["split_group_id"].nunique() == population["eligible_groups"]
        and len(classes) == population["eligible_classes"])
    splits = [{"split": split, "records": len(part), "groups": part["split_group_id"].nunique()}
        for split in ["train", "validation", "test"] for part in [active.loc[active["split"].eq(split)]]]

    step17_status["stage"] = "verifying_profile_checkpoint_metadata"
    bundle = Path(workspace_receipt["bundle_root"]).resolve()
    require(bundle.is_relative_to(root) and bundle.parent == root / "results/profile_preparation")
    bundle_relative = bundle.relative_to(root).as_posix()
    for name, expected in workspace_receipt["artifact_hashes"].items():
        require(Path(name).name == name)
        verify(bundle_relative + "/" + name, expected)
    for name in workspace_receipt["artifact_hashes"]:
        require(git("check-ignore", "--", bundle_relative + "/" + name).strip() != b"")
    workspace = read_json(bundle_relative + "/step16_review_workspace_summary.json")
    require(workspace["input_hashes"] == workspace_receipt["input_hashes"]
        and workspace["status"] == workspace_receipt["status"] == "review_workspace_prepared_all_decisions_pending"
        and workspace["parent_protected_digest"] == workspace_receipt["parent_protected_digest"]
        and workspace["development_draft_digest"] == workspace_receipt["development_draft_digest"]
        and len(workspace["artifacts"]) == 9
        and {**workspace["artifacts"], "step16_review_workspace_summary.json": hashes[bundle_relative + "/step16_review_workspace_summary.json"]}
        == workspace_receipt["artifact_hashes"])
    workspace_identity = {"recipe_version": workspace["recipe_version"], "input_hashes": workspace["input_hashes"],
        "parent_protected_digest": workspace["parent_protected_digest"], "artifact_hashes": workspace["artifacts"]}
    require(hashlib.sha256(packed(workspace_identity)).hexdigest() == workspace["workspace_digest"] == workspace_receipt["workspace_digest"])
    # Hash private case files as bytes; parse only aggregate checkpoint metadata.
    for relative, expected in workspace["input_hashes"].items():
        verify(relative, expected)
    checkpoint = read_json(bundle_relative + "/step16_provisional_checkpoint.json")
    require(checkpoint["final_profiles_frozen"] is False and checkpoint["accepted_development_profiles"] == 0
        and checkpoint["accepted_final_profiles"] == checkpoint["human_review_decisions"] == checkpoint["adopted_expectations"] == 0
        and checkpoint["development_drafts"] == 100 and checkpoint["protected_test_candidate_drafts"] == 200)
    requirements = read_json(bundle_relative + "/future_acceptance_requirements.json")
    require(requirements["status"] == "requirements_for_future_acceptance_not_a_current_acceptance_validator"
        and workspace["operational_acceptance_validator_implemented"] is False)
    schema_reference = checkpoint["public_input_schema_ref"]
    verify(schema_reference["path"], schema_reference["sha256"])
    require("properties" in read_json(schema_reference["path"]))
    # A newer accepted export needs its own verification before changing readiness.
    require(not path("results/step16_profile_preparation_summary.json").exists())

    step17_status["stage"] = "verifying_selected_reference_metadata"
    references = {}
    for kind, relative in profile_input_receipt["reference_producer_paths"].items():
        require(kind in {"basketball", "rules", "food"} and relative in workspace["input_hashes"])
        reference = read_json(relative)
        for name, spec in reference["artifacts"].items():
            require(Path(name).name == name or not Path(name).is_absolute())
            verify((Path(relative).parent / name).as_posix(), spec["sha256"])
        references[kind] = reference
    require(set(references) == {"basketball", "rules", "food"})
    ready = checkpoint["reference_readiness"]
    require(references["basketball"]["metrics"]["planner_eligible"] == ready["planner_eligible_drills_at_selected_checkpoint"] == 0
        and references["rules"]["metrics"]["rules_adopted"] == ready["adopted_rules_at_selected_checkpoint"] == 0
        and references["rules"]["metrics"]["rules_enabled"] == ready["enabled_rules_at_selected_checkpoint"] == 0
        and references["food"]["data_preparation_complete"] is True
        and references["food"]["reference_snapshot_ready_for_step24"] is True
        and references["food"]["application_lookup_enabled"] is ready["food_application_lookup_enabled_at_selected_checkpoint"] is False)

    targets = ["docs/evaluation_protocol.md", "docs/human_review_rubric.md", "artifacts/evaluation/scoring_config.json",
        "data/evaluation/human_review_sample.csv", "data/evaluation/human_review_template.csv",
        "results/evaluation_protocol_checks.csv", "results/step17_evaluation_design_summary.json"]
    target_status = [{"file": relative, "status": "present; not adopted by this check" if path(relative).exists() else "absent"}
        for relative in targets]
    readiness = [
        {"dependency": "Exercise splits and class order", "status": "frozen and verified", "next_use": "Define classifier metrics"},
        {"dependency": "Profile input schema", "status": "saved and hash verified", "next_use": "Describe public input boundary"},
        {"dependency": "Planner profiles and private expectations", "status": "drafts only; acceptance open", "next_use": "Complete real reviews before final scoring"},
        {"dependency": "Basketball activities", "status": "0 planner-eligible at selected checkpoint", "next_use": "Approve activity support"},
        {"dependency": "Planning rules", "status": "0 adopted; 0 enabled at selected checkpoint", "next_use": "Adopt applicable rules and implement checks"},
        {"dependency": "Food reference", "status": "frozen reference; application lookup pending", "next_use": "Verify routing and factual checks"},
        {"dependency": "Shared planner output and parsing contracts", "status": "not verified by this input audit", "next_use": "Define and verify before scoring"},
        {"dependency": "Protocol, scoring implementation, human rubric", "status": "Step 17 preparation pending", "next_use": "Define settings and check development fixtures"}]
    step17_status["stage"] = "rechecking_saved_bytes"
    for relative, expected in dict(hashes).items():
        verify(relative, expected)
    require(git("branch", "--show-current").decode().strip() == "sam-development")
    print("Step 17-1 — Evaluation input integrity and readiness checked")
    print(f"Project: {root} | Branch: sam-development | Verified files: {len(hashes)}")
    print(f"Exercise benchmark: {len(active):,} eligible records | {len(classes)} classes")
    display(pd.DataFrame(splits))
    with pd.option_context("display.max_colwidth", 75, "display.max_rows", 12, "display.max_columns", None):
        display(pd.DataFrame(readiness))
        display(pd.DataFrame(target_status))
    print("Selected profile checkpoint: development 100 drafts; protected test 200 candidates; accepted profiles 0.")
    print("Protocol definition can proceed. Final planner scoring and profile freezing remain blocked by open dependencies.")
    print("Final classifier scoring waits for selected trained models and Step 32.")
    print("Protected case content was hashed, not parsed or printed. Held-out exercise text was not inspected.")
    print("No files changed. No samples selected, decisions adopted, models run, or scores calculated.")
    return {"status": "inputs_verified_protocol_definition_allowed", "root": root, "input_hashes": hashes,
        "benchmark_id": producer["benchmark_id"], "class_order": list(classes), "class_to_index": producer["class_to_index"],
        "exercise_population": population, "split_counts": splits, "profile_workspace_digest": workspace["workspace_digest"],
        "profile_checkpoint": checkpoint, "profile_schema_ref": schema_reference,
        "reference_producer_paths": profile_input_receipt["reference_producer_paths"],
        "readiness": pd.DataFrame(readiness), "step17_target_status": pd.DataFrame(target_status),
        "classifier_metric_definition_ready": True, "final_classifier_scoring_ready": False,
        "protocol_ready": False, "final_planner_scoring_ready": False, "files_changed": False}


try:
    if not all(isinstance(globals().get(name), dict) for name in ["step16_review_workspace", "step16_inputs"]):
        raise RuntimeError("Run Step 16-11 successfully before this cell.")
    step17_inputs = inspect_step17_inputs(step16_review_workspace, step16_inputs)
    step17_status.update(stage="complete", status=step17_inputs["status"])
except Exception:
    step17_inputs = None
    raise RuntimeError("Step 17-1 stopped at stage: " + step17_status["stage"]
        + ". Preserve the saved files and share this stage message. Case content and underlying exception details are excluded.") from None


