# Step 17-2 — Save the classifier metric contract and check artificial examples.
# No exercise predictions, profile cases, model fitting, or held-out evaluation.
import hashlib
import io
import json
import math
import os
import platform
import shutil
import subprocess
import tempfile
from importlib.metadata import version
from pathlib import Path

import pandas as pd
from IPython.display import display

step17_classifier_contract = None
step17_classifier_status = {"stage": "checking_prerequisites"}

METRIC_MODULE_SOURCE = '''"""Pure classification summaries using an explicitly supplied frozen class order."""

from collections.abc import Mapping, Set

from sklearn.metrics import (
    accuracy_score,
    confusion_matrix,
    f1_score,
    precision_recall_fscore_support,
)

VERSION = "classifier-metrics-1"


def summarize_classifier_predictions(y_true, y_pred, split_group_ids, class_order):
    """Summarize supplied predictions without fitting, predicting, or reading files.

    Confusion-matrix rows are actual classes and columns are predicted classes.
    Undefined per-class ratios use sklearn's zero-division convention and carry
    separate definition flags. An empty evaluation reports unavailable metrics.
    """

    def string_vector(values):
        if (isinstance(values, (str, bytes, bytearray, Mapping, Set))
                or getattr(values, "ndim", 1) != 1):
            raise ValueError("Expected a one-dimensional string sequence.")
        try:
            result = list(values)
        except TypeError:
            raise ValueError("Expected a one-dimensional string sequence.") from None
        if any(not isinstance(value, str) or not value.strip() for value in result):
            raise ValueError("Expected nonblank string values without nested entries.")
        return result

    order = string_vector(class_order)
    if not order or len(set(order)) != len(order):
        raise ValueError("Class order must be nonempty and contain unique labels.")
    actual = string_vector(y_true)
    predicted = string_vector(y_pred)
    groups = string_vector(split_group_ids)
    if not len(actual) == len(predicted) == len(groups):
        raise ValueError("Evaluation sequences must have identical lengths.")
    allowed = set(order)
    if any(value not in allowed for value in actual + predicted):
        raise ValueError("Evaluation labels must belong to the supplied class order.")

    count = len(actual)
    class_count = len(order)
    if count:
        precision, recall, f1, support = precision_recall_fscore_support(
            actual, predicted, labels=order, average=None, zero_division=0
        )
        confusion = confusion_matrix(actual, predicted, labels=order).tolist()
        accuracy = float(accuracy_score(actual, predicted))
        macro_f1 = float(f1_score(
            actual, predicted, labels=order, average="macro", zero_division=0
        ))
    else:
        precision = recall = f1 = [None] * class_count
        support = [0] * class_count
        confusion = [[0] * class_count for _ in order]
        accuracy = macro_f1 = None

    per_class, proportions = [], []
    for index, label in enumerate(order):
        actual_count = int(support[index])
        predicted_count = sum(row[index] for row in confusion)
        class_groups = {group for target, group in zip(actual, groups) if target == label}
        per_class.append({
            "class_index": index,
            "label": label,
            "precision": float(precision[index]) if count else None,
            "recall": float(recall[index]) if count else None,
            "f1": float(f1[index]) if count else None,
            "support_records": actual_count,
            "support_groups": len(class_groups),
            "predicted_records": predicted_count,
            "precision_defined": predicted_count > 0,
            "recall_defined": actual_count > 0,
            "f1_defined": actual_count + predicted_count > 0,
        })
        proportions.append(
            [value / actual_count for value in confusion[index]]
            if actual_count else [None] * class_count
        )
    return {
        "version": VERSION,
        "status": "available" if count else "unavailable_no_evaluated_records",
        "class_order": order,
        "n_records": count,
        "n_groups": len(set(groups)),
        "accuracy": accuracy,
        "macro_f1": macro_f1,
        "per_class": per_class,
        "confusion_axes": {"rows": "actual", "columns": "predicted"},
        "confusion_counts": confusion,
        "confusion_row_proportions": proportions,
    }
'''


def prepare_step17_classifier_contract(inputs):
    def require(condition, message):
        if not bool(condition):
            raise RuntimeError(message)

    root = Path(inputs["root"]).resolve()
    recipe = "classifier-metric-contract-0.1.0"
    def path(relative):
        candidate = root / relative
        require(not Path(relative).is_absolute() and candidate == candidate.resolve()
            and candidate.is_relative_to(root), "Invalid project path.")
        return candidate
    def packed(value):
        return (json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n").encode()
    def sha(content):
        return hashlib.sha256(content).hexdigest()
    def file_sha(relative):
        digest = hashlib.sha256()
        with path(relative).open("rb") as handle:
            for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                digest.update(chunk)
        return digest.hexdigest()

    step17_classifier_status["stage"] = "verifying_classifier_dependencies"
    require(inputs["status"] == "inputs_verified_protocol_definition_allowed", "Run Step 17-1 successfully first.")
    producer_path = "results/step15_exercise_split_summary.json"
    config_path = "artifacts/splits/exercise_split_config.json"
    producer_bytes = path(producer_path).read_bytes()
    require(sha(producer_bytes) == inputs["input_hashes"][producer_path], "The frozen exercise producer changed.")
    producer = json.loads(producer_bytes)
    public_outputs = {"data/processed/exercise_groups.csv", "data/processed/exercise_split_manifest.csv",
        "results/exercise_benchmark_review_decisions.csv", "results/exercise_class_eligibility.csv",
        "results/exercise_split_candidates.csv", "results/exercise_split_summary.csv",
        "results/exercise_split_checks.csv", config_path}
    require(set(producer["artifacts"]) == public_outputs and producer["benchmark_frozen"] is True
        and producer["status"] == "frozen" and producer["schema_version"] == "step15-exercise-split-1",
        "A frozen Step 15 benchmark is required.")
    # Only these nine public files enter this classifier-only producer.
    dependencies = {producer_path: sha(producer_bytes), **{name: spec["sha256"] for name, spec in producer["artifacts"].items()}}
    def verify_dependencies():
        require(all(inputs["input_hashes"].get(name) == expected and file_sha(name) == expected
            for name, expected in dependencies.items()), "A classifier dependency changed; preserve the saved benchmark.")
    verify_dependencies()
    output_hashes = {name: producer["artifacts"][name]["sha256"] for name in public_outputs}
    identity_bytes = json.dumps({"inputs": producer["input_hashes"], "outputs": output_hashes},
        ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode()
    require("exercise-benchmark:" + sha(identity_bytes) == producer["benchmark_id"] == inputs["benchmark_id"],
        "The frozen exercise identity differs.")
    source_config = json.loads(path(config_path).read_bytes())
    classes = producer["class_order"]
    require(classes == source_config["class_order"] == inputs["class_order"] == sorted(set(classes))
        and producer["class_to_index"] == source_config["class_to_index"] == {label: i for i, label in enumerate(classes)}
        and source_config["feature_contract"] == producer["feature_contract"], "Class or feature definitions differ.")
    support = pd.read_csv(path("results/exercise_split_summary.csv"), dtype=str, keep_default_na=False,
        usecols=["scope", "split", "records", "groups", "classes_present"])
    overall = support.loc[support["scope"].eq("overall")].set_index("split")
    require(overall.index.is_unique and set(overall.index) == {"train", "validation", "test"}
        and overall["classes_present"].eq(str(len(classes))).all(), "Saved split support differs.")
    split_support = [{"split": name, "records": int(overall.at[name, "records"]), "groups": int(overall.at[name, "groups"])}
        for name in ["train", "validation", "test"]]
    require(sum(row["records"] for row in split_support) == producer["population"]["eligible_records"]
        and sum(row["groups"] for row in split_support) == producer["population"]["eligible_groups"], "Saved totals differ.")

    step17_classifier_status["stage"] = "checking_artificial_metric_examples"
    module = {"__name__": "classifier_metric_contract"}
    exec(compile(METRIC_MODULE_SOURCE, "<classifier-metrics>", "exec"), module)
    score = module["summarize_classifier_predictions"]
    a, b, c = "toy_A", "toy_B", "toy_C"
    toy_order = [a, b, c]
    # Expectations below are hand-specified arithmetic, independent of the scorer.
    probes = [
        {"name": "perfect_with_reordered_classes", "kind": "calculation", "class_order": [c, a, b],
         "y_true": [a, a, b, c], "y_pred": [a, a, b, c], "groups": ["g1", "g1", "g2", "g3"],
         "expected": {"status": "available", "accuracy": 1, "macro_f1": 1, "n_records": 4, "n_groups": 3,
            "class_order": [c, a, b], "per_class.0.label": c, "per_class.1.support_records": 2,
            "confusion_counts": [[1, 0, 0], [0, 2, 0], [0, 0, 1]],
            "confusion_row_proportions": [[1, 0, 0], [0, 1, 0], [0, 0, 1]]}},
        {"name": "asymmetric_counts_and_overlapping_groups", "kind": "calculation", "class_order": toy_order,
         "y_true": [a, a, a, b, b, c], "y_pred": [a, a, b, b, c, c], "groups": ["g1", "g1", "g2", "g1", "g3", "g4"],
         "expected": {"accuracy": 2 / 3, "macro_f1": 59 / 90, "n_records": 6, "n_groups": 4,
            "per_class.0.precision": 1, "per_class.0.recall": 2 / 3, "per_class.0.f1": 4 / 5,
            "per_class.1.precision": 1 / 2, "per_class.1.recall": 1 / 2, "per_class.1.f1": 1 / 2,
            "per_class.2.precision": 1 / 2, "per_class.2.recall": 1, "per_class.2.f1": 2 / 3,
            "per_class.0.support_groups": 2, "per_class.1.support_groups": 2, "per_class.2.support_groups": 1,
            "confusion_counts": [[2, 1, 0], [0, 1, 1], [0, 0, 1]],
            "confusion_row_proportions": [[2 / 3, 1 / 3, 0], [0, 1 / 2, 1 / 2], [0, 0, 1]],
            "confusion_axes": {"rows": "actual", "columns": "predicted"}}},
        {"name": "class_predicted_without_actual_support", "kind": "calculation", "class_order": toy_order,
         "y_true": [a, a], "y_pred": [a, b], "groups": ["g1", "g2"],
         "expected": {"accuracy": 1 / 2, "macro_f1": 2 / 9, "per_class.0.f1": 2 / 3,
            "per_class.1.support_records": 0, "per_class.1.predicted_records": 1, "per_class.1.recall": 0,
            "per_class.1.precision_defined": True, "per_class.1.recall_defined": False, "per_class.1.f1_defined": True,
            "per_class.2.f1": 0, "per_class.2.f1_defined": False,
            "confusion_row_proportions": [[1 / 2, 1 / 2, 0], [None, None, None], [None, None, None]]}},
        {"name": "actual_class_never_predicted", "kind": "calculation", "class_order": toy_order,
         "y_true": [a, b], "y_pred": [a, a], "groups": ["g1", "g2"],
         "expected": {"accuracy": 1 / 2, "macro_f1": 2 / 9, "per_class.0.f1": 2 / 3,
            "per_class.1.support_records": 1, "per_class.1.predicted_records": 0,
            "per_class.1.precision": 0, "per_class.1.recall": 0, "per_class.1.f1": 0,
            "per_class.1.precision_defined": False, "per_class.1.recall_defined": True,
            "confusion_counts": [[1, 0, 0], [1, 0, 0], [0, 0, 0]]}},
        {"name": "all_incorrect_observations", "kind": "calculation", "class_order": toy_order,
         "y_true": [a, b, c], "y_pred": [b, c, a], "groups": ["g1", "g2", "g3"],
         "expected": {"status": "available", "accuracy": 0, "macro_f1": 0,
            "per_class.0.recall_defined": True, "confusion_counts": [[0, 1, 0], [0, 0, 1], [1, 0, 0]]}},
        {"name": "empty_evaluation_is_unavailable", "kind": "unavailable", "class_order": toy_order,
         "y_true": [], "y_pred": [], "groups": [],
         "expected": {"status": "unavailable_no_evaluated_records", "accuracy": None, "macro_f1": None,
            "n_records": 0, "n_groups": 0, "per_class.0.precision": None, "per_class.0.recall": None,
            "per_class.0.f1": None, "confusion_row_proportions": [[None] * 3] * 3}},
        {"name": "fixed_benchmark_order_with_two_artificial_classes_present", "kind": "calculation", "class_order": classes,
         "y_true": classes[:2], "y_pred": classes[:2], "groups": ["toy:frozen1", "toy:frozen2"],
         "expected": {"status": "available", "accuracy": 1, "macro_f1": 2 / len(classes), "class_order": classes,
            "per_class.2.f1": 0, "per_class.2.support_records": 0, "per_class.2.f1_defined": False}},
    ]
    invalid = [
        ("unknown_prediction", [a], ["toy_unknown"], ["g1"], toy_order),
        ("unknown_actual_label", ["toy_unknown"], [a], ["g1"], toy_order),
        ("incomplete_predictions", [a, b], [a], ["g1", "g2"], toy_order),
        ("missing_predictions", [a], None, ["g1"], toy_order),
        ("group_count_mismatch", [a], [a], [], toy_order),
        ("blank_group", [a], [a], [" "], toy_order),
        ("duplicate_class_order", [a], [a], ["g1"], [a, a]),
        ("numeric_prediction_is_not_a_label", [a], [0], ["g1"], toy_order),
        ("empty_class_order", [], [], [], []),
    ]
    probes.extend({"name": name, "kind": "input_rejection", "y_true": actual, "y_pred": predicted,
        "groups": groups, "class_order": order, "expected_exception": "ValueError"}
        for name, actual, predicted, groups, order in invalid)
    def equivalent(expected, observed):
        if expected is None or isinstance(expected, (str, bool)):
            return type(expected) is type(observed) and expected == observed
        if isinstance(expected, (int, float)):
            return isinstance(observed, (int, float)) and not isinstance(observed, bool) and math.isclose(expected, observed, rel_tol=1e-12, abs_tol=1e-12)
        if isinstance(expected, list):
            return isinstance(observed, list) and len(expected) == len(observed) and all(equivalent(a, b) for a, b in zip(expected, observed))
        return isinstance(observed, dict) and set(expected) == set(observed) and all(equivalent(value, observed[key]) for key, value in expected.items())
    checks = []
    for probe in probes:
        try:
            observed = score(probe["y_true"], probe["y_pred"], probe["groups"], probe["class_order"])
        except ValueError:
            require(probe["kind"] == "input_rejection", "A valid artificial calculation was rejected.")
            checks.append({"probe": probe["name"], "kind": probe["kind"], "check": "invalid_input_rejected",
                "expected": "ValueError", "observed": "ValueError", "status": "pass"})
            continue
        require(probe["kind"] != "input_rejection", "An invalid artificial input was accepted.")
        packed(observed)  # All exported values must be JSON-safe, without NaN.
        for field, expected in probe["expected"].items():
            value = observed
            for key in field.split("."):
                value = value[int(key)] if isinstance(value, list) else value[key]
            passed = equivalent(expected, value)
            checks.append({"probe": probe["name"], "kind": probe["kind"], "check": field,
                "expected": json.dumps(expected, ensure_ascii=False, allow_nan=False),
                "observed": json.dumps(value, ensure_ascii=False, allow_nan=False), "status": "pass" if passed else "fail"})
            require(passed, "An artificial metric expectation failed: " + probe["name"] + "/" + field)
    results = pd.DataFrame(checks)
    require(results["status"].eq("pass").all(), "Metric checks did not pass.")
    metric_config = {"schema_version": "classifier-metric-contract-1", "recipe_version": recipe,
        "status": "classifier_component_prepared; full_Step17_protocol_not_ready", "benchmark_id": producer["benchmark_id"],
        "input_hashes": dependencies, "class_order": classes, "class_to_index": producer["class_to_index"],
        "feature_contract": producer["feature_contract"], "population": producer["population"], "split_support": split_support,
        "primary_metric": {"name": "macro_f1", "average": "macro", "labels": "all_frozen_classes_in_saved_order", "zero_division": 0},
        "other_metrics": ["accuracy", "per_class_precision", "per_class_recall", "per_class_f1"],
        "weighting": "Unweighted record-level metrics; macro-F1 gives each frozen class equal weight.",
        "support": "Report actual record counts, distinct actual-label split-group counts, and predicted counts. Per-class group counts can overlap.",
        "undefined_ratios": "For nonempty evaluations, zero_division=0 with precision/recall/F1 definition flags and support. For empty evaluations, metrics are null and unavailable.",
        "confusion_matrix": {"rows": "actual", "columns": "predicted", "normalization": "divide each row by its actual support; null row when support is zero"},
        "prediction_coverage": "One exact string label per intended record, joined by catalog_id with full coverage. Do not silently drop missing predictions or normalize unknown labels. Incomplete predictions are not scored.",
        "model_selection": "Use validation macro-F1; majority baseline learns only training labels.",
        "shared_population": "Training-majority baseline, TF-IDF logistic regression and neural classifier use the same frozen records, groups and eligible class order.",
        "held_out_test": "No test transformation, prediction or scoring in this step. Final evaluation waits for selected configurations/checkpoints and Step32.",
        "label_limitations": "Agreement with unverified source body-part categories does not establish anatomical correctness or athlete suitability.",
        "paired_uncertainty": {"status": "planned; implementation and operational details wait for Step31", "resamples": 2000,
            "seed": 42, "confidence_level": 0.95, "method": "paired group bootstrap with percentile intervals", "unit": "split_group_id",
            "interpretation": "Benchmark-case sensitivity, not real-athlete outcomes or training-seed variability."},
        "scorer_version": module["VERSION"], "scorer_sha256": sha(METRIC_MODULE_SOURCE.encode()),
        "software": {"python": platform.python_version(), "numpy": version("numpy"), "scikit_learn": version("scikit-learn"), "pandas": pd.__version__},
        "execution_scope": "Artificial arithmetic and input-boundary fixtures only; no source predictions, model fitting, profile access, or planner scoring."}
    payloads = {"classifier_metric_config.json": packed(metric_config), "classifier_metrics.py": METRIC_MODULE_SOURCE.encode(),
        "classifier_metric_probes.json": packed({"scope": "artificial metric examples, not benchmark observations", "probes": probes}),
        "classifier_metric_probe_checks.csv": results.to_csv(index=False, lineterminator="\n").encode()}
    artifacts = {name: sha(content) for name, content in payloads.items()}
    identity = sha(packed({"recipe_version": recipe, "input_hashes": dependencies, "artifact_hashes": artifacts}))
    summary = {"schema_version": "step17-classifier-metric-producer-1", "recipe_version": recipe, "component_digest": identity,
        "status": "classifier_metric_contract_and_artificial_checks_prepared", "input_hashes": dependencies, "artifacts": artifacts,
        "benchmark_id": producer["benchmark_id"], "eligible_classes": len(classes), "artificial_probes": len(probes),
        "checks_passed": len(checks), "source_records_scored": 0, "models_trained": 0, "models_evaluated": 0,
        "protocol_ready": False, "final_test_scoring_performed": False, "planner_scoring_performed": False,
        "remaining_scope": "Planner scoring policies, human rubric, full-protocol checks and operational finalization remain open."}
    payloads["step17_classifier_metric_summary.json"] = packed(summary)

    step17_classifier_status["stage"] = "saving_classifier_metric_component"
    executable = shutil.which("git")
    if executable is None and os.name == "nt":
        options = [Path(base) / "Git/cmd/git.exe" for name in ["ProgramFiles", "ProgramFiles(x86)"] if (base := os.environ.get(name))]
        if os.environ.get("LOCALAPPDATA"):
            options.append(Path(os.environ["LOCALAPPDATA"]) / "Programs/Git/cmd/git.exe")
        executable = next((str(value) for value in options if value.is_file()), None)
    require(executable is not None, "Git is unavailable to this kernel.")
    def verify_git():
        def git(*arguments):
            result = subprocess.run([executable, "-C", str(root), *arguments], capture_output=True, text=True, encoding="utf-8", check=False)
            require(result.returncode == 0, "The Git boundary could not be checked.")
            return result.stdout.strip()
        require(Path(git("rev-parse", "--show-toplevel")).resolve() == root and git("branch", "--show-current") == "sam-development",
            "Use this project on sam-development.")
    parent = path("artifacts/evaluation")
    bundle = path("artifacts/evaluation/classifier_metrics_" + identity[:16])
    verify_git()
    verify_dependencies()
    mode = "reused_verified_classifier_component"
    if bundle.exists():
        require(bundle.is_dir() and {value.name for value in bundle.iterdir()} == set(payloads)
            and all(path((bundle / name).relative_to(root).as_posix()).read_bytes() == content for name, content in payloads.items()),
            "Existing classifier component differs. Preserve it and declare a new version.")
    else:
        parent.mkdir(parents=True, exist_ok=True)
        staging = Path(tempfile.mkdtemp(prefix="classifier_metrics_stage_", dir=parent))
        try:
            # The producer is written last, then the complete directory is published.
            for name, content in payloads.items():
                (staging / name).write_bytes(content)
                require((staging / name).read_bytes() == content, "Classifier component staging readback failed.")
            verify_dependencies()
            verify_git()
            require(not bundle.exists(), "The component appeared during saving; inspect it before continuing.")
            os.rename(staging, bundle)
            mode = "saved_and_verified_classifier_component"
        finally:
            if staging.exists():
                shutil.rmtree(staging)
    require(all((bundle / name).read_bytes() == content for name, content in payloads.items()), "Classifier component readback failed.")
    verify_dependencies()
    print("Step 17-2 — Classifier metric contract and artificial calculation checks saved")
    print(f"Mode: {mode} | Fixed classes: {len(classes)} | Artificial scenarios: {len(probes)} | Checks passed: {len(checks)}")
    display(results.groupby("kind", sort=False).agg(scenarios=("probe", "nunique"), checks=("status", "size")).reset_index())
    print("Primary metric: macro-F1 across all frozen classes; zero_division=0.")
    print("Confusion matrix: actual rows, predicted columns. Empty evaluations remain unavailable.")
    print("Saved files: 5 | Component:", bundle.relative_to(root).as_posix())
    print("Artificial checks are not classifier performance results. No exercise records were scored and no model was trained or evaluated.")
    print("Existing inputs and historical records unchanged. Planner policies, human rubric and full Step 17 readiness remain open.")
    return {"status": summary["status"], "root": root, "bundle_root": bundle, "component_digest": identity,
        "input_hashes": dependencies, "artifact_hashes": {name: sha(content) for name, content in payloads.items()},
        "config": metric_config, "checks": results, "summarize_classifier_predictions": score,
        "source_records_scored": 0, "protocol_ready": False}


if not isinstance(globals().get("step17_inputs"), dict):
    raise RuntimeError("Run Step 17-1 successfully before this cell.")
step17_classifier_contract = prepare_step17_classifier_contract(step17_inputs)
step17_classifier_status["stage"] = "complete"


