# Step 17-3 — Prepare planner assessment policies using artificial facts only.
# This does not parse planner text, validate participation rules, or score profiles.
import copy
import hashlib
import json
import math
import os
import platform
import shutil
import subprocess
import tempfile
from pathlib import Path

import pandas as pd
from IPython.display import display

step17_planner_contract = None
step17_planner_status = {"stage": "checking_prerequisites"}
PLANNER_POLICY_SOURCE = '''"""Pure assessment aggregation and feasible-case outcome policy."""

from copy import deepcopy

VERSION = "planner-assessment-policy-1"
_RESULTS = ("met", "violated", "unknown", "not_applicable")
_REQUIREMENTS = ("required", "advisory")


def _text(value):
    if not isinstance(value, str) or not value.strip():
        raise ValueError("Expected a nonblank string.")
    return value


def _basis(value):
    if not isinstance(value, dict):
        raise ValueError("Non-applicability requires an evidence basis.")
    _text(value.get("reason"))
    _text(value.get("evidence_ref"))
    return deepcopy(value)


def _requirement(value):
    if value not in _REQUIREMENTS:
        raise ValueError("Invalid requirement designation.")
    return value


def _obligations(values):
    if not isinstance(values, list):
        raise ValueError("Expected an obligations list.")
    result = {}
    for row in values:
        if not isinstance(row, dict):
            raise ValueError("Expected an obligation record.")
        key = _text(row.get("parent_id"))
        if key in result:
            raise ValueError("Duplicate obligation identifier.")
        result[key] = _requirement(row.get("requirement"))
    return result


def guarded_ratio(numerator, denominator):
    """Return a bounded count ratio, with no value for an empty denominator."""
    if (type(numerator) is not int or type(denominator) is not int
            or not 0 <= numerator <= denominator):
        raise ValueError("Expected nonnegative integer counts with numerator at most denominator.")
    return None if denominator == 0 else numerator / denominator


def aggregate_parent_check(parent_id, requirement, expected_instance_ids,
                           observations, not_applicable_basis=None):
    """Keep checker completeness separate from known semantic findings."""
    _text(parent_id)
    _requirement(requirement)
    if not isinstance(expected_instance_ids, list) or not isinstance(observations, list):
        raise ValueError("Expected instance and observation lists.")
    expected = [_text(value) for value in expected_instance_ids]
    if len(set(expected)) != len(expected):
        raise ValueError("Duplicate expected instance identifier.")
    basis = _basis(not_applicable_basis) if not_applicable_basis is not None else None
    seen, results, issues = set(), [], []
    for row in observations:
        if not isinstance(row, dict):
            raise ValueError("Expected an observation record.")
        key = _text(row.get("instance_id"))
        if key not in expected or key in seen:
            raise ValueError("Duplicate or unexpected observation identifier.")
        seen.add(key)
        error = row.get("checker_error")
        if error is not None:
            _text(error)
            if row.get("result") is not None:
                raise ValueError("A checker error cannot include a semantic result.")
            if "checker_error" not in issues:
                issues.append("checker_error")
        result = row.get("result")
        if result is None:
            if error is None:
                raise ValueError("An absent semantic result requires a checker error.")
        elif not isinstance(result, str) or result not in _RESULTS:
            raise ValueError("Invalid semantic result.")
        if result == "not_applicable":
            _basis(row.get("not_applicable_basis"))
        results.append(result)
    if set(expected) != seen:
        issues.append("missing_expected_observations")
    if not expected and basis is None:
        issues.append("empty_instances_without_non_applicability_basis")
    complete = not issues
    if "violated" in results:
        result = "violated"
    elif not complete:
        result = None
    elif not expected or all(value == "not_applicable" for value in results):
        result = "not_applicable"
    elif "unknown" in results:
        result = "unknown"
    else:
        result = "met"
    return {"parent_id": parent_id, "requirement": requirement, "result": result,
            "assessment_complete": complete, "issues": issues,
            "expected_instance_ids": deepcopy(expected),
            "observations": deepcopy(observations), "not_applicable_basis": basis}


def summarize_check_coverage(obligations, parents):
    """Count only complete parent assessments; never count instances as parents."""
    expected = _obligations(obligations)
    if not isinstance(parents, list):
        raise ValueError("Expected a parent assessment list.")
    observed = {}
    for row in parents:
        if not isinstance(row, dict):
            raise ValueError("Expected a parent assessment record.")
        key = _text(row.get("parent_id"))
        if key not in expected or key in observed:
            raise ValueError("Duplicate or unexpected parent identifier.")
        if row.get("requirement") != expected[key]:
            raise ValueError("Parent requirement differs from its obligation.")
        complete, result = row.get("assessment_complete"), row.get("result")
        if type(complete) is not bool or (result is not None and result not in _RESULTS):
            raise ValueError("Invalid parent assessment state.")
        if complete and result is None:
            raise ValueError("A complete parent requires a semantic result.")
        if result == "not_applicable":
            if row.get("not_applicable_basis") is not None:
                _basis(row["not_applicable_basis"])
            else:
                instances = row.get("observations")
                if not isinstance(instances, list) or not instances:
                    raise ValueError("Non-applicability requires an evidence basis.")
                for instance in instances:
                    if not isinstance(instance, dict) or instance.get("result") != "not_applicable":
                        raise ValueError("Non-applicability requires an evidence basis.")
                    _basis(instance.get("not_applicable_basis"))
        observed[key] = row
    coverage = {}
    for requirement in _REQUIREMENTS:
        keys = [key for key, value in expected.items() if value == requirement]
        counts = {status: 0 for status in _RESULTS}
        incomplete = 0
        for key in keys:
            row = observed.get(key)
            if row is None or not row["assessment_complete"]:
                incomplete += 1
            else:
                counts[row["result"]] += 1
        numerator = counts["met"] + counts["violated"]
        denominator = numerator + counts["unknown"]
        reason = ("assessment_incomplete" if incomplete else
                  "no_expected_parent_checks" if not keys else
                  "no_applicable_semantic_assessments" if not denominator else None)
        coverage[requirement] = {"expected_parent_checks": len(keys), "counts": counts,
            "assessment_incomplete": incomplete, "numerator": numerator, "denominator": denominator,
            "ratio": None if incomplete else guarded_ratio(numerator, denominator),
            "reason": reason, "status": "available" if reason is None else "unavailable"}
    return coverage


def feasible_case_disposition(job_state, response, obligations, parents, case_scoring_ready):
    """Apply ordered gates without requesting downstream checks after a decisive gate."""
    states = ("not_started", "pending", "returned", "timeout", "failed", "missing_response")
    if job_state not in states or type(case_scoring_ready) is not bool:
        raise ValueError("Invalid execution state or scoring-readiness flag.")

    def outcome(disposition, success, complete, reasons, coverage=None):
        result = {"disposition": disposition, "success": success,
                  "scoring_complete": complete, "reasons": reasons}
        if coverage is not None:
            result["coverage"] = coverage
        return result

    if not case_scoring_ready or obligations is None or obligations == []:
        return outcome("not_ready", None, False, ["case_or_obligation_mask_not_ready"])
    expected = _obligations(obligations)
    if "required" not in expected.values():
        return outcome("not_ready", None, False,
                       ["no_required_obligation_or_applicability_evidence"])
    if job_state in ("not_started", "pending"):
        return outcome("execution_incomplete", None, False, ["execution_not_terminal"])
    if job_state in ("timeout", "failed", "missing_response"):
        return outcome("non_success", False, True, ["terminal_execution_failure"])
    if response is None:
        response = {}
    if not isinstance(response, dict):
        raise ValueError("Expected normalized response assessment fields.")
    gates = ("designated_response_present", "parse_valid", "required_plan_present",
             "plan_complete", "required_activity_content_present")
    for gate in gates:
        value = response.get(gate)
        if value is not None and type(value) is not bool:
            raise ValueError("Expected Boolean or unavailable response assessments.")
        if value is False:
            return outcome("non_success", False, True, [gate + "_false"])
        if value is None:
            return outcome("assessment_incomplete", None, False, [gate + "_unavailable"])
    coverage = summarize_check_coverage(obligations, parents)
    if any(item["assessment_incomplete"] for item in coverage.values()):
        return outcome("assessment_incomplete", None, False, ["expected_assessments_incomplete"], coverage)
    required = coverage["required"]["counts"]
    if required["violated"] or required["unknown"]:
        return outcome("non_success", False, True, ["required_check_not_met"], coverage)
    advisory = coverage["advisory"]["counts"]
    reasons = ["advisory_findings_reported"] if advisory["violated"] or advisory["unknown"] else []
    return outcome("success", True, True, reasons, coverage)
'''


def prepare_step17_planner_contract(classifier_receipt):
    def require(condition, message):
        if not bool(condition):
            raise RuntimeError(message)
    root = Path(classifier_receipt["root"]).resolve()
    recipe = "planner-assessment-contract-0.1.0"
    def path(relative):
        value = root / relative
        require(not Path(relative).is_absolute() and value == value.resolve() and value.is_relative_to(root), "Invalid project path.")
        return value
    def packed(value):
        return (json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n").encode()
    def sha(content):
        return hashlib.sha256(content).hexdigest()
    def file_sha(relative):
        value = hashlib.sha256()
        with path(relative).open("rb") as handle:
            for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                value.update(chunk)
        return value.hexdigest()

    step17_planner_status["stage"] = "verifying_public_preparation_component"
    previous = Path(classifier_receipt["bundle_root"])
    require(previous == previous.resolve() and previous.parent == root / "artifacts/evaluation"
        and previous.name == "classifier_metrics_" + classifier_receipt["component_digest"][:16], "Classifier component path differs.")
    names = {"classifier_metric_config.json", "classifier_metrics.py", "classifier_metric_probes.json",
        "classifier_metric_probe_checks.csv", "step17_classifier_metric_summary.json"}
    require(set(classifier_receipt["artifact_hashes"]) == names, "Unexpected classifier component files.")
    dependencies = {(previous / name).relative_to(root).as_posix(): expected
        for name, expected in classifier_receipt["artifact_hashes"].items()}
    summary_path = (previous / "step17_classifier_metric_summary.json").relative_to(root).as_posix()
    require(file_sha(summary_path) == dependencies[summary_path], "The preceding component changed.")
    previous_summary = json.loads(path(summary_path).read_bytes())
    expected_sources = {"results/step15_exercise_split_summary.json", "data/processed/exercise_groups.csv",
        "data/processed/exercise_split_manifest.csv", "results/exercise_benchmark_review_decisions.csv",
        "results/exercise_class_eligibility.csv", "results/exercise_split_candidates.csv",
        "results/exercise_split_summary.csv", "results/exercise_split_checks.csv", "artifacts/splits/exercise_split_config.json"}
    require(set(previous_summary["input_hashes"]) == expected_sources
        and previous_summary["input_hashes"] == classifier_receipt["input_hashes"], "The public dependency slice differs.")
    previous_identity = {"recipe_version": previous_summary["recipe_version"], "input_hashes": previous_summary["input_hashes"],
        "artifact_hashes": previous_summary["artifacts"]}
    require(sha(packed(previous_identity)) == previous_summary["component_digest"] == classifier_receipt["component_digest"]
        and previous_summary["artifacts"] == {name: classifier_receipt["artifact_hashes"][name] for name in names if name != "step17_classifier_metric_summary.json"}
        and previous_summary["protocol_ready"] is False and previous_summary["source_records_scored"] == 0,
        "The classifier preparation identity or scope differs.")
    dependencies.update(previous_summary["input_hashes"])
    def verify_dependencies():
        require(all(file_sha(relative) == expected for relative, expected in dependencies.items()),
            "A public preparation dependency changed. Preserve the saved versions.")
    verify_dependencies()

    step17_planner_status["stage"] = "checking_artificial_assessment_examples"
    policy = {"__name__": "planner_assessment_policy"}
    exec(compile(PLANNER_POLICY_SOURCE, "<planner-assessment-policy>", "exec"), policy)
    basis = {"reason": "This artificial prerequisite is absent in the fixture.", "evidence_ref": "fixture:applicability"}
    def observation(key, result, error=None):
        row = {"instance_id": key, "result": result, "checker_error": error}
        if result == "not_applicable":
            row["not_applicable_basis"] = copy.deepcopy(basis)
        return row
    def parent(key, result, requirement="required", complete=True):
        row = {"parent_id": key, "requirement": requirement, "result": result, "assessment_complete": complete}
        if result == "not_applicable":
            row["not_applicable_basis"] = copy.deepcopy(basis)
        return row
    def obligation(key, requirement="required"):
        return {"parent_id": key, "requirement": requirement}
    probes = []
    def add(name, group, function, arguments, expected=None, reject=False):
        probes.append({"name": name, "group": group, "function": function, "arguments": arguments,
            **({"expected_exception": "ValueError"} if reject else {"expected": expected})})
    parent_function = "aggregate_parent_check"
    add("all_needed_instances_met", "parent_aggregation", parent_function,
        ["toy:parent", "required", ["i1", "i2"], [observation("i1", "met"), observation("i2", "met")]],
        {"result": "met", "assessment_complete": True})
    add("violation_dominates_unknown", "parent_aggregation", parent_function,
        ["toy:parent", "required", ["i1", "i2"], [observation("i1", "violated"), observation("i2", "unknown")]],
        {"result": "violated", "assessment_complete": True})
    add("necessary_unknown_prevents_met", "parent_aggregation", parent_function,
        ["toy:parent", "required", ["i1", "i2"], [observation("i1", "met"), observation("i2", "unknown")]],
        {"result": "unknown", "assessment_complete": True})
    add("all_justified_non_applicable", "parent_aggregation", parent_function,
        ["toy:parent", "required", ["i1", "i2"], [observation("i1", "not_applicable"), observation("i2", "not_applicable")]],
        {"result": "not_applicable", "assessment_complete": True})
    add("met_and_non_applicable", "parent_aggregation", parent_function,
        ["toy:parent", "required", ["i1", "i2"], [observation("i1", "met"), observation("i2", "not_applicable")]],
        {"result": "met", "assessment_complete": True})
    add("known_violation_retained_during_checker_error", "parent_aggregation", parent_function,
        ["toy:parent", "required", ["i1", "i2"], [observation("i1", "violated"), observation("i2", None, "fixture checker exception")]],
        {"result": "violated", "assessment_complete": False, "issues": ["checker_error"]})
    add("missing_observation_is_not_semantic_unknown", "parent_aggregation", parent_function,
        ["toy:parent", "required", ["i1", "i2"], [observation("i1", "met")]],
        {"result": None, "assessment_complete": False, "issues": ["missing_expected_observations"]})
    add("empty_instances_are_not_automatically_met", "parent_aggregation", parent_function,
        ["toy:parent", "required", [], []], {"result": None, "assessment_complete": False})
    add("explicit_empty_instance_non_applicability_basis", "parent_aggregation", parent_function,
        ["toy:parent", "required", [], [], basis], {"result": "not_applicable", "assessment_complete": True})

    coverage_function = "summarize_check_coverage"
    mixed = [parent("r1", "met"), parent("r2", "met"), parent("r3", "violated"), parent("r4", "unknown"), parent("r5", "not_applicable"),
        parent("a1", "unknown", "advisory"), parent("a2", "not_applicable", "advisory")]
    add("required_and_advisory_coverage_are_separate", "coverage", coverage_function,
        [[obligation(row["parent_id"], row["requirement"]) for row in mixed], mixed],
        {"required.counts": {"met": 2, "violated": 1, "unknown": 1, "not_applicable": 1}, "required.expected_parent_checks": 5,
         "required.numerator": 3, "required.denominator": 4, "required.ratio": 3 / 4,
         "advisory.denominator": 1, "advisory.ratio": 0, "advisory.counts.not_applicable": 1})
    add("all_non_applicable_coverage_is_unavailable", "coverage", coverage_function,
        [[obligation("r1")], [parent("r1", "not_applicable")]],
        {"required.ratio": None, "required.denominator": 0, "required.counts.not_applicable": 1})
    add("no_expected_checks_gives_no_coverage_ratio", "coverage", coverage_function,
        [[], []], {"required.ratio": None, "required.expected_parent_checks": 0, "advisory.ratio": None})
    add("missing_parent_does_not_disappear_from_coverage", "coverage", coverage_function,
        [[obligation("r1"), obligation("r2")], [parent("r1", "met")]],
        {"required.expected_parent_checks": 2, "required.counts.met": 1, "required.counts.unknown": 0,
         "required.assessment_incomplete": 1, "required.ratio": None})
    add("partial_violation_is_not_completed_coverage", "coverage", coverage_function,
        [[obligation("r1")], [parent("r1", "violated", complete=False)]],
        {"required.assessment_incomplete": 1, "required.counts.violated": 0, "required.ratio": None})

    case_function = "feasible_case_disposition"
    gates = {key: True for key in ["designated_response_present", "parse_valid", "required_plan_present", "plan_complete", "required_activity_content_present"]}
    required = [obligation("r1")]
    met = [parent("r1", "met")]
    def case(name, job="returned", response=None, obligations=None, parents=None, ready=True,
             disposition="success", success=True, complete=True, extra=None):
        arguments = [job, copy.deepcopy(gates if response is None else response),
            copy.deepcopy(required if obligations is None else obligations), copy.deepcopy(met if parents is None else parents), ready]
        add(name, "feasible_case_policy", case_function, arguments,
            {"disposition": disposition, "success": success, "scoring_complete": complete, **(extra or {})})
    case("complete_plan_with_required_met")
    case("incomplete_plan_fails_despite_met_activity_checks", response={**gates, "plan_complete": False}, disposition="non_success", success=False)
    case("omitted_activity_content_cannot_pass_vacuously", response={**gates, "required_activity_content_present": False}, parents=[], disposition="non_success", success=False)
    case("missing_designated_response_needs_no_activity_checks", response={"designated_response_present": False}, parents=[], disposition="non_success", success=False)
    case("malformed_output_is_observed_non_success", response={**gates, "parse_valid": False}, parents=[], disposition="non_success", success=False)
    case("inappropriate_refusal_has_no_required_plan", response={**gates, "required_plan_present": False}, parents=[], disposition="non_success", success=False)
    case("required_unknown_prevents_success", parents=[parent("r1", "unknown")], disposition="non_success", success=False)
    case("advisory_unknown_does_not_fail_required_success", obligations=[*required, obligation("a1", "advisory")],
        parents=[*met, parent("a1", "unknown", "advisory")], extra={"coverage.advisory.ratio": 0})
    case("justified_non_applicability_with_complete_plan", parents=[parent("r1", "not_applicable")], extra={"coverage.required.ratio": None})
    for state in ["not_started", "pending"]:
        case("execution_" + state + "_is_incomplete", job=state, response={}, parents=[],
            disposition="execution_incomplete", success=None, complete=False)
    for state in ["timeout", "failed", "missing_response"]:
        case("terminal_" + state + "_cannot_use_diagnostic_draft", job=state, parents=[], disposition="non_success", success=False)
    case("checker_error_keeps_external_assessment_incomplete", parents=[parent("r1", None, complete=False)],
        disposition="assessment_incomplete", success=None, complete=False)
    case("missing_parent_assessment_is_incomplete", parents=[], disposition="assessment_incomplete", success=None, complete=False)
    case("parser_not_assessed_is_not_a_planner_violation", response={**gates, "parse_valid": None}, parents=[],
        disposition="assessment_incomplete", success=None, complete=False)
    case("unprepared_case_cannot_be_scored", ready=False, disposition="not_ready", success=None, complete=False)
    case("bare_empty_mask_is_not_a_readiness_proof", obligations=[], parents=[], disposition="not_ready", success=None, complete=False)
    case("advisory_only_mask_does_not_prove_required_readiness", obligations=[obligation("a1", "advisory")],
        parents=[parent("a1", "met", "advisory")], disposition="not_ready", success=None, complete=False)
    add("null_mask_remains_unprepared", "feasible_case_policy", case_function, ["returned", gates, None, [], True],
        {"disposition": "not_ready", "success": None, "scoring_complete": False})

    for name, numerator, denominator, expected in [("zero_denominator", 0, 0, None), ("known_zero_ratio", 0, 3, 0), ("fractional_ratio", 2, 3, 2 / 3)]:
        add(name, "count_ratio", "guarded_ratio", [numerator, denominator], {"value": expected})
    for name, arguments in [("ratio_above_one", [3, 2]), ("negative_ratio_count", [-1, 2]), ("boolean_is_not_a_count", [False, 1])]:
        add(name, "input_rejection", "guarded_ratio", arguments, reject=True)
    add("non_applicable_without_basis_rejected", "input_rejection", parent_function,
        ["toy:parent", "required", ["i1"], [{"instance_id": "i1", "result": "not_applicable", "checker_error": None}]], reject=True)
    add("checker_error_cannot_also_claim_met", "input_rejection", parent_function,
        ["toy:parent", "required", ["i1"], [observation("i1", "met", "fixture checker exception")]], reject=True)
    add("duplicate_parent_cannot_inflate_coverage", "input_rejection", coverage_function,
        [required, [parent("r1", "met"), parent("r1", "met")]], reject=True)

    def same(expected, observed):
        if expected is None or isinstance(expected, (str, bool)):
            return type(expected) is type(observed) and expected == observed
        if isinstance(expected, (int, float)):
            return isinstance(observed, (int, float)) and not isinstance(observed, bool) and math.isclose(expected, observed, rel_tol=1e-12, abs_tol=1e-12)
        if isinstance(expected, list):
            return isinstance(observed, list) and len(expected) == len(observed) and all(same(a, b) for a, b in zip(expected, observed))
        return isinstance(observed, dict) and set(expected) == set(observed) and all(same(value, observed[key]) for key, value in expected.items())
    checks = []
    for probe in probes:
        before = packed(probe["arguments"])
        try:
            observed = policy[probe["function"]](*probe["arguments"])
        except ValueError:
            require(probe.get("expected_exception") == "ValueError", "A valid artificial assessment was rejected.")
            checks.append({"probe": probe["name"], "group": probe["group"], "check": "invalid_input_rejected", "expected": "ValueError", "observed": "ValueError", "status": "pass"})
        else:
            require("expected_exception" not in probe, "An invalid artificial assessment was accepted.")
            if probe["function"] == "guarded_ratio":
                observed = {"value": observed}
            packed(observed)
            for field, expected in probe["expected"].items():
                value = observed
                for key in field.split("."):
                    value = value[int(key)] if isinstance(value, list) else value[key]
                passed = same(expected, value)
                checks.append({"probe": probe["name"], "group": probe["group"], "check": field,
                    "expected": json.dumps(expected, ensure_ascii=False, allow_nan=False), "observed": json.dumps(value, ensure_ascii=False, allow_nan=False), "status": "pass" if passed else "fail"})
                require(passed, "An artificial policy expectation failed: " + probe["name"] + "/" + field)
        require(before == packed(probe["arguments"]), "An assessment calculator changed its supplied facts.")
    results = pd.DataFrame(checks)
    config = {"schema_version": "planner-assessment-contract-1", "recipe_version": recipe,
        "status": "policy_calculators_prepared; operational_scoring_and_full_protocol_not_ready",
        "source_sections": ["17.4", "17.5", "17.6", "17.7", "17.12"], "input_hashes": dependencies,
        "parent_preparation_component": classifier_receipt["component_digest"], "policy_version": policy["VERSION"], "policy_sha256": sha(PLANNER_POLICY_SOURCE.encode()),
        "planned_populations_per_version": {"feasible": 150, "missing_information": 20, "conflicting_constraints": 15, "outside_scope": 15, "all_scheduled_cases": 200},
        "planned_versions": 4, "planned_jobs": 800, "actual_rates_available": False,
        "primary_measure": "Successful feasible cases divided by all 150 accepted feasible final cases per version once the declared roster and assessment are complete.",
        "population_readiness": "These counts are design targets. Do not calculate final rates from unaccepted drafts, drop failed jobs, or describe an incomplete experiment as complete.",
        "case_success": "Require the designated returned response, valid shared parsing, required plan and activity content, request completeness, and every required applicable check met.",
        "expectation_boundary": "Expected obligations and applicability must come from accepted private annotations and adopted public contracts/rules/policies before final outputs. This helper does not prepare or approve them.",
        "case_scoring_ready": "An externally supplied prerequisite in artificial fixtures; not an implemented case-acceptance validator or proof of reference readiness.",
        "empty_mask": "A bare empty, missing or advisory-only obligation list cannot establish required-check readiness in this component. Reviewed non-applicability is an explicit required parent assessment with an evidence basis; required plan/completeness gates still apply. This readiness hold is not a planner failure.",
        "expected_instances": "Instances needed for the parent condition, established by adopted applicability. Keep unrelated advisory/optional findings separate from required conditions.",
        "semantic_results": ["met", "violated", "unknown", "not_applicable"],
        "parent_aggregation": "An established violation dominates. Otherwise necessary unknowns prevent met. Preserve all instance findings and evidence; justified non-applicability needs a reason and evidence reference.",
        "assessment_completeness": "Checker errors and missing expected assessments remain external assessment failures. Retain known partial violations separately; do not convert an absent checker result into semantic unknown or a model violation.",
        "scoring_complete_scope": "The case calculator's scoring_complete flag resolves its primary disposition only. A decisive missing response or incomplete-plan failure does not certify every ancillary assessment as finished. Preserve any existing checker-error ledger and unresolved coverage independently; this flag alone cannot finalize an experiment.",
        "coverage": {"unit": "expected parent checks, not number of activity instances", "numerator": "met + violated", "denominator": "met + violated + unknown",
            "required_and_advisory_separate": True, "not_applicable_reported_separately": True, "zero_denominator": None,
            "incomplete_assessment_ratio": None, "interpretation": "Conclusive coverage is not a pass rate."},
        "execution": "Unstarted or awaiting permitted resumption is incomplete. Terminal timeout, failed execution or missing designated response prevents success without requiring downstream activity assessments.",
        "response_assessment": "Malformed output, missing required plan, incomplete scope or omitted required activity content prevents success. Unavailable or failed external parsing/assessment remains incomplete.",
        "advisory_findings": "Report advisory unknowns and violations separately; they do not alone fail the required-check primary measure. Essentiality follows the accepted request and adopted policy, not a blanket missing-history penalty.",
        "evidence_ratios": {"id_validity": "Resolvable distinct IDs / supplied distinct IDs", "cited_claim_support": "Supported cited claims / cited claims assessed",
            "attribution_coverage": "Source-dependent claims with usable attribution / source-dependent claims reviewed",
            "empty_denominator": "Unavailable, with counts. No supplied IDs does not mean perfect attribution. ID validity and factual support remain separate."},
        "format_and_independence": "Optional source-ID fields remain optional. Version4 internal acceptance does not determine the external outcome; earlier diagnostic drafts cannot replace the designated response after fatal execution.",
        "human_review": "Preserve malformed but readable returned text for later independent human review; no automated human scores or reviewer decisions are assigned here.",
        "deferred_implementation": ["accepted-case and mask import validation", "shared planner response parser", "participation-rule and activity constraint execution", "runtime food and evidence checks", "real-case population aggregation", "human rubric and ratings", "pilot operational finalization"],
        "software": {"python": platform.python_version(), "pandas": pd.__version__},
        "scope": "Pure aggregation of supplied artificial facts. No planner text, profile content, rule thresholds, source lookups or model calls are evaluated."}
    payloads = {"planner_assessment_config.json": packed(config), "planner_assessment_policy.py": PLANNER_POLICY_SOURCE.encode(),
        "planner_assessment_probes.json": packed({"scope": "artificial assessment facts; not study profiles or accepted expectations", "probes": probes}),
        "planner_assessment_probe_checks.csv": results.to_csv(index=False, lineterminator="\n").encode()}
    artifacts = {name: sha(content) for name, content in payloads.items()}
    identity = sha(packed({"recipe_version": recipe, "input_hashes": dependencies, "artifact_hashes": artifacts}))
    payloads["step17_planner_assessment_summary.json"] = packed({"schema_version": "step17-planner-assessment-producer-1", "recipe_version": recipe,
        "component_digest": identity, "status": "planner_policy_calculators_and_artificial_checks_prepared", "input_hashes": dependencies, "artifacts": artifacts,
        "artificial_scenarios": len(probes), "checks_passed": len(checks), "study_profiles_read": 0, "study_cases_scored": 0, "planner_jobs": 0,
        "rules_adopted": 0, "profiles_accepted": 0, "human_ratings": 0, "protocol_ready": False, "runtime_validator_ready": False, "response_parser_ready": False})

    step17_planner_status["stage"] = "saving_public_policy_component"
    executable = shutil.which("git")
    if executable is None and os.name == "nt":
        options = [Path(base) / "Git/cmd/git.exe" for name in ["ProgramFiles", "ProgramFiles(x86)"] if (base := os.environ.get(name))]
        if os.environ.get("LOCALAPPDATA"):
            options.append(Path(os.environ["LOCALAPPDATA"]) / "Programs/Git/cmd/git.exe")
        executable = next((str(value) for value in options if value.is_file()), None)
    require(executable is not None, "Git is unavailable to this kernel.")
    def verify_git():
        def git(*arguments):
            result = subprocess.run([executable, "-C", str(root), *arguments], capture_output=True, text=True, encoding="utf-8", check=False)
            require(result.returncode == 0, "The Git boundary could not be checked.")
            return result.stdout.strip()
        require(Path(git("rev-parse", "--show-toplevel")).resolve() == root and git("branch", "--show-current") == "sam-development", "Use this project on sam-development.")
    parent_directory = path("artifacts/evaluation")
    bundle = path("artifacts/evaluation/planner_assessment_" + identity[:16])
    verify_git()
    verify_dependencies()
    mode = "reused_verified_planner_policy_component"
    if bundle.exists():
        require(bundle.is_dir() and {value.name for value in bundle.iterdir()} == set(payloads)
            and all(path((bundle / name).relative_to(root).as_posix()).read_bytes() == content for name, content in payloads.items()),
            "Existing planner policy component differs. Preserve it and declare a new version.")
    else:
        parent_directory.mkdir(parents=True, exist_ok=True)
        staging = Path(tempfile.mkdtemp(prefix="planner_assessment_stage_", dir=parent_directory))
        try:
            for name, content in payloads.items():
                (staging / name).write_bytes(content)
                require((staging / name).read_bytes() == content, "Planner policy staging readback failed.")
            verify_dependencies()
            verify_git()
            require(not bundle.exists(), "The component appeared during saving; inspect it before continuing.")
            os.rename(staging, bundle)
            mode = "saved_and_verified_planner_policy_component"
        finally:
            if staging.exists():
                shutil.rmtree(staging)
    require(all((bundle / name).read_bytes() == content for name, content in payloads.items()), "Planner policy readback failed.")
    verify_dependencies()
    print("Step 17-3 — Planner assessment policies and artificial checks saved")
    print(f"Mode: {mode} | Artificial scenarios: {len(probes)} | Checks passed: {len(checks)}")
    display(results.groupby("group", sort=False).agg(scenarios=("probe", "nunique"), checks=("status", "size")).reset_index())
    print("Unknown required results prevent success; missing or failed assessments remain incomplete.")
    print("Coverage uses expected parent checks, separates required/advisory findings, and leaves unavailable ratios null.")
    print("The 150/20/15/15 profile counts remain planned targets; no actual study rates were calculated.")
    print("Saved files: 5 | Component:", bundle.relative_to(root).as_posix())
    print("No study profiles read or scored, planner jobs run, rules adopted, profiles accepted, or human ratings assigned.")
    print("Existing files unchanged. Actual parsers, rule validators, accepted expectations, and full protocol readiness remain open.")
    return {"status": "planner_policy_calculators_and_artificial_checks_prepared", "root": root, "bundle_root": bundle,
        "component_digest": identity, "input_hashes": dependencies, "artifact_hashes": {name: sha(content) for name, content in payloads.items()},
        "config": config, "checks": results, "policy_functions": {name: policy[name] for name in [parent_function, coverage_function, case_function, "guarded_ratio"]},
        "protocol_ready": False, "study_cases_scored": 0}


if not isinstance(globals().get("step17_classifier_contract"), dict):
    raise RuntimeError("Run Step 17-2 successfully before this cell.")
step17_planner_contract = prepare_step17_planner_contract(step17_classifier_contract)
step17_planner_status["stage"] = "complete"


