# Step 17-4 — Prepare the human rubric and check artificial rating examples.
# No final sample, response assignments, reviewer decisions, or real ratings.
import copy
import hashlib
import json
import math
import os
import platform
import shutil
import subprocess
import tempfile
from importlib.metadata import version
from pathlib import Path

import pandas as pd
from IPython.display import display
from jsonschema import Draft202012Validator

step17_human_contract = None
step17_human_status = {"stage": "checking_prerequisites"}
HUMAN_REVIEW_SOURCE = '''"""Pure validation and paired agreement summaries for a fixed human-review rubric."""

import math

VERSION = "human-review-metrics-1"
DIMENSIONS = (
    "response_suitability", "profile_fit", "practicality_completeness",
    "evidence_accuracy", "clarity",
)
_REQUIRED = {"response_id", "reviewer_id", "dimension", "rating_status",
             "score", "comment", "not_applicable_reason"}
_STATUSES = ("rated", "not_applicable", "missing")


def _text(value):
    if not isinstance(value, str) or not value.strip():
        raise ValueError("Expected nonblank text.")
    return value


def _dimension(value):
    if not isinstance(value, str) or value not in DIMENSIONS:
        raise ValueError("Invalid review dimension.")
    return value


def _ids(values):
    if not isinstance(values, list):
        raise ValueError("Expected an identifier list.")
    result = [_text(value) for value in values]
    if len(set(result)) != len(result):
        raise ValueError("Expected unique identifiers.")
    return result


def validate_rating_entry(entry):
    """Validate supplied fields without inserting defaults or changing source values."""
    if (not isinstance(entry, dict) or not _REQUIRED.issubset(entry)
            or not set(entry).issubset(_REQUIRED | {"evidence_refs"})):
        raise ValueError("Invalid review entry fields.")
    _text(entry["response_id"])
    _text(entry["reviewer_id"])
    _dimension(entry["dimension"])
    if entry["comment"] is not None:
        _text(entry["comment"])
    if "evidence_refs" in entry:
        if not isinstance(entry["evidence_refs"], list):
            raise ValueError("Expected evidence references as a list.")
        for reference in entry["evidence_refs"]:
            _text(reference)
    status, score, reason = entry["rating_status"], entry["score"], entry["not_applicable_reason"]
    if not isinstance(status, str) or status not in _STATUSES:
        raise ValueError("Invalid rating status.")
    if status == "rated":
        if (type(score) not in (int, float) or score not in (0, 1, 2)
                or not math.isfinite(score) or reason is not None):
            raise ValueError("Rated entries require an integer score from zero through two.")
    elif status == "not_applicable":
        if entry["dimension"] != "evidence_accuracy" or score is not None:
            raise ValueError("Non-applicability is restricted to evidence accuracy without a score.")
        _text(reason)
    elif score is not None or reason is not None:
        raise ValueError("Missing ratings require no score or non-applicability reason.")
    return True


def summarize_reviewer_agreement(records, response_ids, reviewer_ids, dimension):
    """Pair by response ID; use only joint numeric pairs for weighted kappa."""
    roster, reviewers = _ids(response_ids), _ids(reviewer_ids)
    _dimension(dimension)
    if len(reviewers) != 2 or not isinstance(records, list):
        raise ValueError("Expected two reviewers and a review-entry list.")
    response_set, reviewer_set, entries = set(roster), set(reviewers), {}
    for entry in records:
        validate_rating_entry(entry)
        if (entry["dimension"] != dimension or entry["response_id"] not in response_set
                or entry["reviewer_id"] not in reviewer_set):
            raise ValueError("Review entry falls outside the declared comparison roster or dimension.")
        key = (entry["response_id"], entry["reviewer_id"])
        if key in entries:
            raise ValueError("Duplicate response and reviewer pair.")
        entries[key] = entry
    per_reviewer = {reviewer: {"status_counts": dict.fromkeys(_STATUSES, 0),
        "numeric_score_counts": dict.fromkeys(("0", "1", "2"), 0),
        "not_recorded": 0, "recorded_missing": 0} for reviewer in reviewers}
    states = dict.fromkeys(("both_not_applicable", "one_reviewer_not_applicable",
        "na_with_numeric_peer", "na_with_missing_peer", "pairs_with_missing", "missing_rating_entries"), 0)
    status_crosstab = {row: dict.fromkeys(_STATUSES, 0) for row in _STATUSES}
    confusion = [[0, 0, 0] for _ in range(3)]
    for response_id in roster:
        pair, scores = [], []
        for reviewer in reviewers:
            entry = entries.get((response_id, reviewer))
            status = entry["rating_status"] if entry is not None else "missing"
            counts = per_reviewer[reviewer]
            counts["status_counts"][status] += 1
            counts["not_recorded"] += int(entry is None)
            counts["recorded_missing"] += int(entry is not None and status == "missing")
            score = int(entry["score"]) if status == "rated" else None
            if score is not None:
                counts["numeric_score_counts"][str(score)] += 1
            pair.append(status)
            scores.append(score)
        status_crosstab[pair[0]][pair[1]] += 1
        na_count, missing_count = pair.count("not_applicable"), pair.count("missing")
        states["both_not_applicable"] += int(na_count == 2)
        states["one_reviewer_not_applicable"] += int(na_count == 1)
        states["na_with_numeric_peer"] += int(na_count == 1 and "rated" in pair)
        states["na_with_missing_peer"] += int(na_count == 1 and missing_count == 1)
        states["pairs_with_missing"] += int(missing_count > 0)
        states["missing_rating_entries"] += missing_count
        if pair == ["rated", "rated"]:
            confusion[scores[0]][scores[1]] += 1
    rows = [sum(row) for row in confusion]
    columns = [sum(row[j] for row in confusion) for j in range(3)]
    n_joint = sum(rows)
    exact = sum(confusion[i][i] for i in range(3))
    observed = expected = kappa = None
    unavailable = "no_joint_numeric_ratings"
    if n_joint:
        observed = sum(confusion[i][j] * abs(i - j) for i in range(3) for j in range(3)) / (2 * n_joint)
        expected = sum(rows[i] * columns[j] * abs(i - j) for i in range(3) for j in range(3)) / (2 * n_joint**2)
        unavailable = "zero_expected_disagreement" if expected == 0 else None
        if expected:
            kappa = 1 - observed / expected
    return {"version": VERSION, "dimension": dimension, "reviewer_order": list(reviewers),
        "score_order": [0, 1, 2], "n_expected_responses": len(roster),
        "n_joint_numeric": n_joint, "n_exact_matches": exact,
        "exact_agreement": exact / n_joint if n_joint else None,
        "joint_numeric_confusion": confusion, "observed_linear_disagreement": observed,
        "expected_linear_disagreement": expected, "linear_weighted_kappa": kappa,
        "kappa_unavailable_reason": unavailable, "state_counts": states,
        "status_crosstab": status_crosstab,
        "per_reviewer": per_reviewer,
        "joint_numeric_marginals": {reviewers[0]: dict(zip(("0", "1", "2"), rows)),
                                    reviewers[1]: dict(zip(("0", "1", "2"), columns))},
        "state_count_note": "State counts overlap; one-reviewer NA can also have a missing peer. "
            "Missing counts include recorded-missing and not-recorded roster slots; not_recorded is separate. "
            "Per-reviewer score counts include all numeric ratings; agreement uses only joint numeric pairs."}
'''


def prepare_step17_human_contract(planner_receipt):
    def require(condition, message):
        if not bool(condition):
            raise RuntimeError(message)
    root = Path(planner_receipt["root"]).resolve()
    recipe = "human-review-contract-0.1.0"
    def path(relative):
        value = root / relative
        require(not Path(relative).is_absolute() and value == value.resolve() and value.is_relative_to(root), "Invalid project path.")
        return value
    def packed(value):
        return (json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n").encode()
    def sha(content):
        return hashlib.sha256(content).hexdigest()
    def file_sha(relative):
        value = hashlib.sha256()
        with path(relative).open("rb") as handle:
            for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                value.update(chunk)
        return value.hexdigest()

    step17_human_status["stage"] = "verifying_public_preparation_component"
    previous = Path(planner_receipt["bundle_root"])
    require(previous == previous.resolve() and previous.parent == root / "artifacts/evaluation"
        and previous.name == "planner_assessment_" + planner_receipt["component_digest"][:16], "Planner component path differs.")
    names = {"planner_assessment_config.json", "planner_assessment_policy.py", "planner_assessment_probes.json",
        "planner_assessment_probe_checks.csv", "step17_planner_assessment_summary.json"}
    require(set(planner_receipt["artifact_hashes"]) == names, "Unexpected planner component files.")
    dependencies = {(previous / name).relative_to(root).as_posix(): expected for name, expected in planner_receipt["artifact_hashes"].items()}
    summary_path = (previous / "step17_planner_assessment_summary.json").relative_to(root).as_posix()
    require(file_sha(summary_path) == dependencies[summary_path], "The preceding component changed.")
    previous_summary = json.loads(path(summary_path).read_bytes())
    sources = {"results/step15_exercise_split_summary.json", "data/processed/exercise_groups.csv", "data/processed/exercise_split_manifest.csv",
        "results/exercise_benchmark_review_decisions.csv", "results/exercise_class_eligibility.csv", "results/exercise_split_candidates.csv",
        "results/exercise_split_summary.csv", "results/exercise_split_checks.csv", "artifacts/splits/exercise_split_config.json"}
    extra = set(previous_summary["input_hashes"]) - sources
    classifier_names = {"classifier_metric_config.json", "classifier_metrics.py", "classifier_metric_probes.json", "classifier_metric_probe_checks.csv", "step17_classifier_metric_summary.json"}
    require(sources.issubset(previous_summary["input_hashes"]) and len(extra) == 5
        and {Path(value).name for value in extra} == classifier_names and len({Path(value).parent for value in extra}) == 1
        and all(value.startswith("artifacts/evaluation/classifier_metrics_") for value in extra), "The public dependency slice differs.")
    identity_input = {"recipe_version": previous_summary["recipe_version"], "input_hashes": previous_summary["input_hashes"], "artifact_hashes": previous_summary["artifacts"]}
    require(sha(packed(identity_input)) == previous_summary["component_digest"] == planner_receipt["component_digest"]
        and previous_summary["input_hashes"] == planner_receipt["input_hashes"]
        and previous_summary["artifacts"] == {name: planner_receipt["artifact_hashes"][name] for name in names if name != "step17_planner_assessment_summary.json"}
        and previous_summary["protocol_ready"] is False and previous_summary["study_cases_scored"] == 0,
        "The preceding preparation identity or scope differs.")
    dependencies.update(previous_summary["input_hashes"])
    def verify_dependencies():
        require(all(file_sha(relative) == expected for relative, expected in dependencies.items()), "A public preparation dependency changed. Preserve the saved versions.")
    verify_dependencies()

    step17_human_status["stage"] = "preparing_rubric_and_rating_states"
    module = {"__name__": "human_review_metrics"}
    exec(compile(HUMAN_REVIEW_SOURCE, "<human-review-metrics>", "exec"), module)
    dimensions = [
        {"id": "response_suitability", "name": "Response suitability", "anchors": ["Misses the central issue or gives an inappropriate response", "Addresses the issue but leaves an important part unresolved", "Gives the appropriate plan, clarification, conflict explanation, or scope response"]},
        {"id": "profile_fit", "name": "Profile fit", "anchors": ["Ignores or contradicts relevant profile information", "Uses some relevant details but misses important constraints or goals", "Reflects the information needed for this request"]},
        {"id": "practicality_completeness", "name": "Practicality and completeness", "anchors": ["Is unusable or substantially incomplete for its purpose", "Provides some useful guidance but leaves important gaps", "Gives sufficiently complete and practical guidance for the request"]},
        {"id": "evidence_accuracy", "name": "Evidence accuracy", "anchors": ["Contains materially unsupported or misleading claims", "Has partial support or omits important qualifications", "Agrees with the reviewed evidence and communicates relevant uncertainty"]},
        {"id": "clarity", "name": "Clarity", "anchors": ["Is confusing or internally inconsistent", "Is understandable but noticeably ambiguous", "Is clear, consistent, and easy to follow"]},
    ]
    require(tuple(row["id"] for row in dimensions) == module["DIMENSIONS"], "Rubric dimensions differ from the helper.")
    text = {"type": "string", "minLength": 1, "pattern": r"\S"}
