# Step 17-5 — Prepare evidence accounting and check artificial assessments.
# Source resolution, claim extraction, factual checking, and study scoring stay pending.
import copy
import hashlib
import json
import math
import os
import platform
import shutil
import subprocess
import tempfile
from pathlib import Path

import pandas as pd
from IPython.display import display

step17_evidence_contract = None
step17_evidence_status = {"stage": "checking_prerequisites"}
EVIDENCE_METRICS_SOURCE = '"""Account for supplied evidence assessments; no extraction, lookup, or factual checking."""\n\nVERSION = "evidence-accounting-1"\nSUPPORT_RESULTS = ("supported", "contradicted", "insufficient_support", "missing_qualification", "unknown")\nRESOLUTION_RESULTS = ("resolved", "unresolved", "unknown")\nATTRIBUTION_RESULTS = ("usable", "absent", "unusable", "unknown")\nASSESSMENT_STATES = ("completed", "unrun", "error", "not_recorded")\n\n\ndef _text(value):\n    if not isinstance(value, str) or not value.strip():\n        raise ValueError("Expected nonblank text.")\n    return value\n\n\ndef _ids(values, unique=True):\n    if not isinstance(values, list):\n        raise ValueError("Expected an identifier list.")\n    for value in values:\n        _text(value)\n    if unique and len(set(values)) != len(values):\n        raise ValueError("Expected unique identifiers.")\n    return list(values)\n\n\ndef _claims(values):\n    if not isinstance(values, list):\n        raise ValueError("Expected a declared claim roster.")\n    result = {}\n    for row in values:\n        if not isinstance(row, dict) or set(row) != {"claim_id", "has_citation", "source_dependent"}:\n            raise ValueError("Invalid claim-roster fields.")\n        key = _text(row["claim_id"])\n        if key in result or type(row["has_citation"]) is not bool or type(row["source_dependent"]) is not bool:\n            raise ValueError("Invalid claim-roster values.")\n        result[key] = row\n    return result\n\n\ndef _assessments(records, roster, key_field, results, require_basis=False):\n    if not isinstance(records, list):\n        raise ValueError("Expected assessment records.")\n    indexed = {}\n    fields = {key_field, "assessment_status", "result", "note", "basis_refs", "error_code"}\n    for row in records:\n        if not isinstance(row, dict) or set(row) != fields:\n            raise ValueError("Invalid assessment fields.")\n        key = _text(row[key_field])\n        if key not in roster or key in indexed:\n            raise ValueError("Unexpected or duplicate assessment identifier.")\n        status = row["assessment_status"]\n        if not isinstance(status, str) or status not in ASSESSMENT_STATES[:3]:\n            raise ValueError("Invalid assessment status.")\n        basis = _ids(row["basis_refs"])\n        if row["note"] is not None:\n            _text(row["note"])\n        if status == "completed":\n            if not isinstance(row["result"], str) or row["result"] not in results or row["error_code"] is not None:\n                raise ValueError("Invalid completed assessment.")\n            _text(row["note"])\n            if require_basis and row["result"] in ("supported", "contradicted", "missing_qualification") and not basis:\n                raise ValueError("This support finding requires a recorded evidence basis.")\n        else:\n            if row["result"] is not None or basis:\n                raise ValueError("Unfinished assessments cannot carry a completed result or evidence basis.")\n            if status == "error":\n                _text(row["error_code"])\n            elif row["error_code"] is not None:\n                raise ValueError("Unrun assessments cannot carry an execution error.")\n        indexed[key] = row\n    return indexed\n\n\ndef _summary(roster, records, results, positive, denominator_basis):\n    states = dict.fromkeys(ASSESSMENT_STATES, 0)\n    counts = dict.fromkeys(results, 0)\n    for key in roster:\n        row = records.get(key)\n        status = "not_recorded" if row is None else row["assessment_status"]\n        states[status] += 1\n        if status == "completed":\n            counts[row["result"]] += 1\n    complete = states["completed"] == len(roster)\n    denominator = len(roster) if denominator_basis == "expected" else states["completed"]\n    unavailable = "assessment_incomplete" if not complete else ("zero_denominator" if not denominator else None)\n    return {"expected_items": len(roster), "completed_items": states["completed"],\n        "assessment_complete": complete, "assessment_counts": states, "result_counts": counts,\n        "numerator": counts[positive], "denominator": denominator,\n        "ratio": counts[positive] / denominator if unavailable is None else None,\n        "unavailable_reason": unavailable}\n\n\ndef summarize_reference_ids(supplied_reference_ids, assessments, inventory_complete):\n    """Count distinct supplied identifiers; existence is independent of claim support."""\n    if type(inventory_complete) is not bool:\n        raise ValueError("Declare whether reference inventory is complete.")\n    occurrences = _ids(supplied_reference_ids, unique=False)\n    roster = list(dict.fromkeys(occurrences))\n    records = _assessments(assessments, roster, "reference_id", RESOLUTION_RESULTS)\n    summary = _summary(roster, records, RESOLUTION_RESULTS, "resolved", "expected")\n    if not inventory_complete:\n        summary["ratio"] = None\n        summary["unavailable_reason"] = "reference_inventory_incomplete"\n    return {"version": VERSION, "measure": "supplied_distinct_id_validity",\n        "reference_inventory_complete": inventory_complete,\n        "measure_complete": inventory_complete and summary["assessment_complete"],\n        "supplied_occurrences": len(occurrences), "distinct_supplied_ids": len(roster),\n        "duplicate_occurrences": len(occurrences) - len(roster),\n        **summary}\n\n\ndef summarize_claim_support(claims, assessments, roster_complete):\n    """Summarize supplied support findings by declared citation presence."""\n    if type(roster_complete) is not bool:\n        raise ValueError("Declare whether claim inventory is complete.")\n    roster = _claims(claims)\n    records = _assessments(assessments, roster, "claim_id", SUPPORT_RESULTS, require_basis=True)\n    output = {"version": VERSION, "measure": "claim_support", "claim_roster_complete": roster_complete}\n    for group, keys in (("all_claims", list(roster)),\n        ("cited", [key for key, row in roster.items() if row["has_citation"]]),\n        ("uncited", [key for key, row in roster.items() if not row["has_citation"]])):\n        summary = _summary(keys, records, SUPPORT_RESULTS, "supported", "completed")\n        summary["inventory_complete"] = roster_complete\n        if not roster_complete:\n            summary["ratio"] = None\n            summary["unavailable_reason"] = "claim_inventory_incomplete"\n        summary["measure_complete"] = roster_complete and summary["assessment_complete"]\n        output[group] = summary\n    return output\n\n\ndef summarize_attribution(claims, assessments, roster_complete):\n    """Use declared source-dependent claims; a citation token alone is not usable attribution."""\n    if type(roster_complete) is not bool:\n        raise ValueError("Declare whether claim inventory is complete.")\n    roster = _claims(claims)\n    keys = [key for key, row in roster.items() if row["source_dependent"]]\n    records = _assessments(assessments, keys, "claim_id", ATTRIBUTION_RESULTS)\n    for key, row in records.items():\n        if row["assessment_status"] == "completed":\n            if row["result"] in ("usable", "unusable") and not roster[key]["has_citation"]:\n                raise ValueError("Usable or unusable attribution requires a supplied citation.")\n            if row["result"] == "absent" and roster[key]["has_citation"]:\n                raise ValueError("A supplied citation must be assessed separately from absent attribution.")\n    summary = _summary(keys, records, ATTRIBUTION_RESULTS, "usable", "completed")\n    if not roster_complete:\n        summary["ratio"] = None\n        summary["unavailable_reason"] = "claim_inventory_incomplete"\n    return {"version": VERSION, "measure": "source_dependent_claim_attribution", "claim_roster_complete": roster_complete,\n        "source_independent_claims_excluded": len(roster) - len(keys),\n        "measure_complete": roster_complete and summary["assessment_complete"], **summary}\n'


def build_evidence_probes():
    probes = []
    def add(name, group, function, arguments, expected=None, reject=False, illustration=None):
        probes.append({"name": name, "group": group, "function": function, "arguments": arguments,
            **({"expected_exception": "ValueError"} if reject else {"expected": expected}),
            **({"illustration": illustration} if illustration else {})})
    def claim(key, cited=True, source=True):
        return {"claim_id": key, "has_citation": cited, "source_dependent": source}
    def record(key, result, field="claim_id", status="completed", basis=None):
        return {field: key, "assessment_status": status, "result": result,
            "note": "Authored assessment for an artificial fixture." if status == "completed" else None,
            "basis_refs": (["toy:evidence-version-1"] if basis is None else basis) if status == "completed" else [],
            "error_code": "toy_checker_error" if status == "error" else None}
    refs = "summarize_reference_ids"
    support = "summarize_claim_support"
    attribution = "summarize_attribution"
    add("distinct_references_not_occurrences", "reference_ids", refs,
        [["toy:a", "toy:a", "toy:b", "toy:c"], [record("toy:a", "resolved", "reference_id"),
        record("toy:b", "unresolved", "reference_id"), record("toy:c", "unknown", "reference_id")], True],
        {"supplied_occurrences": 4, "distinct_supplied_ids": 3, "duplicate_occurrences": 1,
         "numerator": 1, "denominator": 3, "ratio": 1 / 3, "measure_complete": True,
         "result_counts": {"resolved": 1, "unresolved": 1, "unknown": 1}})
    add("no_supplied_references_is_unavailable", "reference_ids", refs, [[], [], True],
        {"ratio": None, "denominator": 0, "unavailable_reason": "zero_denominator", "measure_complete": True})
    add("all_resolvable_does_not_establish_support", "reference_ids", refs,
        [["toy:turns"], [record("toy:turns", "resolved", "reference_id")], True],
        {"ratio": 1, "numerator": 1, "denominator": 1},
        illustration={"source_id": "toy:turns", "source_text": "Only one toy marker may occupy the square at a time.",
            "claim_text": "Two toy markers may occupy the square at the same time [toy:turns].",
            "scope": "The ID exists. The separate authored support finding is contradicted; no text checker runs here."})
    add("unresolved_reference_is_a_completed_negative", "reference_ids", refs,
        [["toy:a"], [record("toy:a", "unresolved", "reference_id")], True],
        {"ratio": 0, "result_counts.unresolved": 1, "assessment_complete": True})
    add("unknown_resolution_remains_distinct", "reference_ids", refs,
        [["toy:a"], [record("toy:a", "unknown", "reference_id")], True],
        {"ratio": 0, "result_counts.unknown": 1, "result_counts.unresolved": 0})
    for name, assessment in [("missing", []), ("unrun", [record("toy:b", None, "reference_id", "unrun")]),
        ("error", [record("toy:b", None, "reference_id", "error")])]:
        add("reference_" + name + "_keeps_assessment_incomplete", "reference_ids", refs,
            [["toy:a", "toy:b"], [record("toy:a", "resolved", "reference_id"), *assessment], True],
            {"ratio": None, "numerator": 1, "denominator": 2, "completed_items": 1,
             "assessment_complete": False, "unavailable_reason": "assessment_incomplete"})
    add("reference_inventory_incomplete_is_not_perfect", "reference_ids", refs,
        [["toy:a"], [record("toy:a", "resolved", "reference_id")], False],
        {"ratio": None, "assessment_complete": True, "measure_complete": False,
         "unavailable_reason": "reference_inventory_incomplete"})
    cases = [claim("toy:s"), claim("toy:c"), claim("toy:i"), claim("toy:q"), claim("toy:u"), claim("toy:uncited", False)]
    observations = [record(row["claim_id"], result) for row, result in zip(cases,
        ["supported", "contradicted", "insufficient_support", "missing_qualification", "unknown", "supported"])]
    add("cited_and_uncited_support_have_separate_denominators", "claim_support", support,
        [cases, observations, True], {"all_claims.ratio": 1 / 3, "all_claims.denominator": 6,
         "cited.ratio": 1 / 5, "cited.denominator": 5, "uncited.ratio": 1,
         "uncited.denominator": 1, "cited.result_counts.unknown": 1,
         "cited.result_counts.insufficient_support": 1, "cited.result_counts.contradicted": 1,
         "cited.result_counts.missing_qualification": 1})
    add("valid_reference_can_contradict_claim", "claim_support", support,
        [[claim("toy:turns-claim")], [record("toy:turns-claim", "contradicted", basis=["toy:turns"])], True],
        {"cited.ratio": 0, "cited.result_counts.contradicted": 1, "cited.assessment_complete": True})
    add("uncited_fact_can_be_supported", "claim_support", support,
        [[claim("toy:uncited", False)], [record("toy:uncited", "supported")], True],
        {"cited.ratio": None, "cited.denominator": 0, "uncited.ratio": 1, "all_claims.ratio": 1})
    add("absent_attribution_does_not_rewrite_supported_fact", "attribution", attribution,
        [[claim("toy:uncited", False)], [record("toy:uncited", "absent", basis=[])], True],
        {"ratio": 0, "result_counts.absent": 1, "denominator": 1, "measure_complete": True})
    add("insufficient_support_is_not_contradiction", "claim_support", support,
        [[claim("toy:c")], [record("toy:c", "insufficient_support", basis=[])], True],
        {"cited.ratio": 0, "cited.result_counts.contradicted": 0, "cited.result_counts.insufficient_support": 1})
    add("missing_qualification_is_separate", "claim_support", support,
        [[claim("toy:c")], [record("toy:c", "missing_qualification")], True],
        {"cited.ratio": 0, "cited.result_counts.missing_qualification": 1})
    add("unknown_is_not_a_checker_error", "claim_support", support,
        [[claim("toy:c")], [record("toy:c", "unknown", basis=[])], True],
        {"cited.ratio": 0, "cited.measure_complete": True, "cited.assessment_counts.error": 0,
         "cited.result_counts.unknown": 1})
    for name, rows in [("missing", []), ("unrun", [record("toy:b", None, status="unrun")]),
        ("error", [record("toy:b", None, status="error")])]:
        add("claim_" + name + "_does_not_disappear", "claim_support", support,
            [[claim("toy:a"), claim("toy:b")], [record("toy:a", "supported"), *rows], True],
            {"cited.ratio": None, "cited.expected_items": 2, "cited.completed_items": 1,
             "cited.numerator": 1, "cited.denominator": 1, "cited.unavailable_reason": "assessment_incomplete"})
    add("incomplete_claim_inventory_blocks_rates", "claim_support", support,
        [[claim("toy:a")], [record("toy:a", "supported")], False],
        {"cited.ratio": None, "all_claims.ratio": None, "cited.assessment_complete": True,
         "cited.measure_complete": False, "cited.unavailable_reason": "claim_inventory_incomplete"})
    add("empty_complete_claim_inventory_has_no_rate", "claim_support", support, [[], [], True],
        {"all_claims.ratio": None, "all_claims.denominator": 0, "cited.ratio": None,
         "uncited.ratio": None, "all_claims.unavailable_reason": "zero_denominator"})
    add("pending_uncited_claim_does_not_hide_complete_cited_subset", "claim_support", support,
        [[claim("toy:cited"), claim("toy:uncited", False)], [record("toy:cited", "supported")], True],
        {"all_claims.ratio": None, "cited.ratio": 1, "uncited.ratio": None,
         "uncited.assessment_counts.not_recorded": 1})
    roster = [claim("toy:usable"), claim("toy:absent", False), claim("toy:unusable"), claim("toy:unknown"), claim("toy:choice", False, False)]
    attributed = [record("toy:" + value, value) for value in ["usable", "absent", "unusable", "unknown"]]
    add("source_dependent_attribution_uses_reviewed_claims", "attribution", attribution,
        [roster, attributed, True], {"source_independent_claims_excluded": 1, "expected_items": 4,
         "completed_items": 4, "denominator": 4, "numerator": 1, "ratio": 1 / 4,
         "result_counts": {"usable": 1, "absent": 1, "unusable": 1, "unknown": 1}})
    add("supplied_citation_can_be_unusable", "attribution", attribution,
        [[claim("toy:c")], [record("toy:c", "unusable")], True], {"ratio": 0, "result_counts.unusable": 1})
    add("attribution_missing_is_not_absent", "attribution", attribution,
        [[claim("toy:c", False)], [], True], {"ratio": None, "result_counts.absent": 0,
         "assessment_counts.not_recorded": 1, "unavailable_reason": "assessment_incomplete"})
    add("attribution_checker_error_remains_incomplete", "attribution", attribution,
        [[claim("toy:c")], [record("toy:c", None, status="error")], True],
        {"ratio": None, "assessment_counts.error": 1, "result_counts.unknown": 0})
    add("no_source_dependent_claims_has_no_attribution_rate", "attribution", attribution,
        [[claim("toy:choice", False, False)], [], True],
        {"ratio": None, "denominator": 0, "source_independent_claims_excluded": 1, "measure_complete": True})
    add("incomplete_claim_inventory_blocks_attribution_rate", "attribution", attribution,
        [[claim("toy:c")], [record("toy:c", "usable")], False],
        {"ratio": None, "assessment_complete": True, "measure_complete": False,
         "unavailable_reason": "claim_inventory_incomplete"})
    for name, arguments in [
        ("duplicate_resolution", [["toy:a"], [record("toy:a", "resolved", "reference_id")] * 2, True]),
        ("out_of_roster_reference", [["toy:a"], [record("toy:b", "resolved", "reference_id")], True]),
        ("blank_reference", [[" "], [], True]),
        ("non_list_references", ["toy:a", [], True]),
        ("nonboolean_reference_inventory", [[], [], 1]),
    ]:
        add(name, "input_rejection", refs, arguments, reject=True)
    valid = record("toy:c", "supported")
    for name, bad in [
        ("unsupported_result_code", {**valid, "result": "false"}),
        ("boolean_result", {**valid, "result": True}),
        ("missing_support_basis", {**valid, "basis_refs": []}),
        ("blank_assessment_note", {**valid, "note": " "}),
        ("completed_with_error", {**valid, "error_code": "toy:error"}),
        ("unrun_with_result", {**valid, "assessment_status": "unrun"}),
        ("error_without_error_code", {**record("toy:c", None, status="error"), "error_code": None}),
        ("extra_assessment_field", {**valid, "automatic_pass": True}),
        ("duplicate_basis_refs", {**valid, "basis_refs": ["toy:a", "toy:a"]}),
    ]:
        add(name, "input_rejection", support, [[claim("toy:c")], [bad], True], reject=True)
    add("duplicate_claim_identifiers", "input_rejection", support, [[claim("toy:c")] * 2, [], True], reject=True)
    add("duplicate_support_assessments", "input_rejection", support, [[claim("toy:c")], [valid, valid], True], reject=True)
    add("out_of_roster_claim", "input_rejection", support, [[claim("toy:a")], [valid], True], reject=True)
    add("nonboolean_citation_presence", "input_rejection", support, [[{**claim("toy:c"), "has_citation": 1}], [], True], reject=True)
    add("nonboolean_claim_inventory", "input_rejection", support, [[], [], None], reject=True)
    add("uncited_claim_cannot_have_usable_attribution", "input_rejection", attribution,
        [[claim("toy:c", False)], [record("toy:c", "usable")], True], reject=True)
    add("cited_claim_cannot_be_marked_absent", "input_rejection", attribution,
        [[claim("toy:c")], [record("toy:c", "absent")], True], reject=True)
    add("source_independent_assessment_cannot_be_hidden", "input_rejection", attribution,
        [[claim("toy:c", False, False)], [record("toy:c", "absent")], True], reject=True)
    return probes



def prepare_step17_evidence_contract(human_receipt):
    def require(condition, message):
        if not bool(condition):
            raise RuntimeError(message)
    root = Path(human_receipt["root"]).resolve()
    recipe = "evidence-accounting-contract-0.1.0"
    def path(relative):
        require(isinstance(relative, str) and "\\" not in relative, "Invalid project path.")
        value = root / relative
        require(not Path(relative).is_absolute() and value == value.resolve()
            and value.is_relative_to(root) and value != root, "Invalid project path.")
        return value
    def packed(value):
        return (json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n").encode()
    def sha(content):
        return hashlib.sha256(content).hexdigest()
    def file_sha(relative):
        value = hashlib.sha256()
        with path(relative).open("rb") as handle:
            for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                value.update(chunk)
        return value.hexdigest()

    step17_evidence_status["stage"] = "verifying_public_preparation_component"
    previous = Path(human_receipt["bundle_root"])
    require(previous == previous.resolve() and previous.parent == root / "artifacts/evaluation"
        and previous.name == "human_review_" + human_receipt["component_digest"][:16], "Human-review component path differs.")
    names = {"human_review_rubric.md", "human_review_config.json", "human_rating_entry_schema.json",
        "human_review_metrics.py", "human_review_examples.json", "human_review_probes.json",
        "human_review_probe_checks.csv", "step17_human_review_summary.json"}
    require(set(human_receipt["artifact_hashes"]) == names, "Unexpected human-review component files.")
    dependencies = {(previous / name).relative_to(root).as_posix(): expected
        for name, expected in human_receipt["artifact_hashes"].items()}
    summary_path = (previous / "step17_human_review_summary.json").relative_to(root).as_posix()
    require(file_sha(summary_path) == dependencies[summary_path], "The preceding component changed.")
    summary_bytes = path(summary_path).read_bytes()
    require(sha(summary_bytes) == dependencies[summary_path], "The preceding summary changed during reading.")
    previous_summary = json.loads(summary_bytes)
    sources = {"results/step15_exercise_split_summary.json", "data/processed/exercise_groups.csv", "data/processed/exercise_split_manifest.csv",
        "results/exercise_benchmark_review_decisions.csv", "results/exercise_class_eligibility.csv", "results/exercise_split_candidates.csv",
        "results/exercise_split_summary.csv", "results/exercise_split_checks.csv", "artifacts/splits/exercise_split_config.json"}
    component_sets = {
        "classifier_metrics_": {"classifier_metric_config.json", "classifier_metrics.py", "classifier_metric_probes.json",
            "classifier_metric_probe_checks.csv", "step17_classifier_metric_summary.json"},
        "planner_assessment_": {"planner_assessment_config.json", "planner_assessment_policy.py", "planner_assessment_probes.json",
            "planner_assessment_probe_checks.csv", "step17_planner_assessment_summary.json"}}
    remaining = set(previous_summary["input_hashes"]) - sources
    require(sources.issubset(previous_summary["input_hashes"]), "The public source dependency slice differs.")
    for prefix, expected_names in component_sets.items():
        selected = {value for value in remaining if value.startswith("artifacts/evaluation/" + prefix)}
        require(len(selected) == len(expected_names) and {Path(value).name for value in selected} == expected_names
            and len({Path(value).parent for value in selected}) == 1, "The public component dependency slice differs.")
        remaining -= selected
    require(not remaining and previous_summary["input_hashes"] == human_receipt["input_hashes"], "Unexpected dependency scope.")
    previous_identity = {"recipe_version": previous_summary["recipe_version"], "input_hashes": previous_summary["input_hashes"],
        "artifact_hashes": previous_summary["artifacts"]}
    require(sha(packed(previous_identity)) == previous_summary["component_digest"] == human_receipt["component_digest"]
        and previous_summary["artifacts"] == {name: human_receipt["artifact_hashes"][name] for name in names if name != "step17_human_review_summary.json"}
        and previous_summary["protocol_ready"] is False
        and all(previous_summary[key] == 0 for key in ["sample_ids_selected", "response_assignments", "actual_human_ratings", "study_profiles_read", "study_responses_read"]),
        "The preceding preparation identity or scope differs.")
    dependencies.update(previous_summary["input_hashes"])
    def verify_dependencies():
        require(all(file_sha(relative) == expected for relative, expected in dependencies.items()),
            "A public preparation dependency changed. Preserve the saved versions.")
    verify_dependencies()

    step17_evidence_status["stage"] = "checking_artificial_evidence_accounting"
    module = {"__name__": "evidence_accounting"}
    exec(compile(EVIDENCE_METRICS_SOURCE, "<evidence-accounting>", "exec"), module)
    probes = build_evidence_probes()
    require(len({probe["name"] for probe in probes}) == len(probes), "Artificial scenario names must be unique.")
    def same(expected, observed):
        if expected is None or isinstance(expected, (str, bool)):
            return type(expected) is type(observed) and expected == observed
        if isinstance(expected, (int, float)):
            return type(observed) in (int, float) and math.isclose(expected, observed, rel_tol=1e-12, abs_tol=1e-12)
        if isinstance(expected, list):
            return isinstance(observed, list) and len(expected) == len(observed) and all(same(a, b) for a, b in zip(expected, observed))
        return isinstance(observed, dict) and set(expected) == set(observed) and all(same(value, observed[key]) for key, value in expected.items())
    checks = []
    for probe in probes:
        arguments = copy.deepcopy(probe["arguments"])
        before = packed(arguments)
        try:
            observed = module[probe["function"]](*arguments)
        except ValueError:
            require(probe.get("expected_exception") == "ValueError", "A valid artificial evidence record was rejected.")
            checks.append({"probe": probe["name"], "group": probe["group"], "check": "invalid_input_rejected",
                "expected": "ValueError", "observed": "ValueError", "status": "pass"})
        else:
            require("expected_exception" not in probe, "An invalid artificial evidence record was accepted.")
            packed(observed)
            for field, expected in probe["expected"].items():
                value = observed
                for key in field.split("."):
                    value = value[key]
                passed = same(expected, value)
                checks.append({"probe": probe["name"], "group": probe["group"], "check": field,
                    "expected": json.dumps(expected, ensure_ascii=False), "observed": json.dumps(value, ensure_ascii=False), "status": "pass" if passed else "fail"})
                require(passed, "An artificial evidence expectation failed: " + probe["name"] + "/" + field)
        require(before == packed(arguments), "An evidence helper changed the supplied input values.")
    results = pd.DataFrame(checks)
    config = {"schema_version": "evidence-accounting-config-1", "recipe_version": recipe, "helper_version": module["VERSION"],
        "status": "accounting_preparation_only", "unit": "one declared response and an identified evidence-assessment scope per call",
        "measures": {
            "reference_ids": {"numerator": "resolved distinct supplied IDs", "denominator": "all distinct supplied IDs in this response",
                "results": list(module["RESOLUTION_RESULTS"]), "deduplication": "exact supplied identifier strings within one response; preserve occurrences separately"},
            "claim_support": {"numerator": "claims with a completed supported finding", "denominator": "completed claim support assessments in the declared subset",
                "subsets": ["all_claims", "cited", "uncited"], "primary_evidence_support_subset": "cited",
                "results": list(module["SUPPORT_RESULTS"]), "unit": "claim, not citation occurrence or claim-reference link"},
            "attribution": {"numerator": "reviewed source-dependent claims with usable attribution", "denominator": "completed attribution reviews of source-dependent claims",
                "results": list(module["ATTRIBUTION_RESULTS"]), "source_independent_claims": "excluded and counted separately"}},
        "ratio_policy": "Empty denominators stay null. An incomplete declared inventory or unfinished assessment makes the affected subset ratio unavailable. Counts remain visible; no partial ratio is presented as a completed measure.",
        "unknown_policy": "A completed unknown finding is counted separately and is not supported/resolved/usable. It is not a proven contradiction, absent attribution, or checker crash.",
        "inventory_policy": "The caller must enumerate the declared response/sampling scope completely, save claim/reference inventories, and attest completeness. These helpers cannot establish that no claim or reference was omitted. Partial inventories cannot yield a numeric rate.",
        "claim_scope": "Inventory substantive factual/instructional claims actually present in the returned text. An omitted requested answer is a completeness failure, not an invented unsupported claim. Citation presence and source dependence require separate upstream annotation and review.",
        "completion_meaning": "measure_complete means inventory and assessment work are complete for the declared scope. It does not mean findings are conclusive, evidence is adequate, or a response passes; completed unknowns remain visible.",
        "assessment_policy": "Completed support findings have a note and a recorded evidence basis for supported, contradicted, and missing-qualification findings. Basis strings are provenance placeholders; these helpers do not resolve or verify them.",
        "citation_presence": "A declared supplied citation can be unresolved or unusable. Presence alone establishes neither usable attribution nor support. Record absent attribution only when no citation was supplied for that claim.",
        "cited_support": "Assess whether supplied cited evidence supports the associated claim under relevant age, units, quantities, conditions, and qualifications. An unrelated but valid ID can coexist with insufficient support or contradiction.",
        "uncited_support": "Uncited substantive factual/instructional claims can be checked against adopted neutral references. Their accuracy is reported separately from missing attribution; no uncited claim is assumed false.",
        "source_prescription": "Separate planner scheduling choices from source-prescribed doses or durations; authored scheduling choices must not be labelled as copied source facts.",
        "finding_scope": "Each supplied assessment records one primary finding. Retain detailed findings and source qualifiers in later case-level evidence records; these counts do not replace them.",
        "reporting": "Save response/version identifiers, assessed sample and claim roster, source versions and locators, evaluator/checker version, notes and error codes in the later evidence ledger. Report per-response and per-version counts/denominators; do not deduplicate IDs globally across responses or treat all claim samples as the entire benchmark.",
        "independence": "Use independent external evaluation. Version 4 internal acceptance and checker output do not assign these external research findings.",
        "retrieval_handoff": {"step": 23, "status": "planned; no retrieval scores computed here", "hit_at_k": [1, 3, 5],
            "recall_at_k": [1, 3, 5], "mrr_at_k": 5, "accepted_complete_evidence_bundle": True,
            "selection_order": ["development Recall@5", "development MRR@5", "simpler lexical method"],
            "separate_reporting": ["unsupported questions", "evidence-adequacy failures"], "substitutes_for_planner_or_claim_scores": False},
        "operational_implementations": {key: "pending" for key in ["reference_resolver", "claim_inventory_extraction", "source_version_binding",
            "factual_support_checks", "attribution_review_workflow", "accepted_reference_integration", "retrieval_benchmark"]},
        "software": {"python": platform.python_version(), "pandas": pd.__version__}, "protocol_ready": False}
    documentation = """# Evidence accounting — prepared evaluation component

This component checks arithmetic and bookkeeping using supplied artificial assessments. It does not extract claims, resolve actual source IDs, judge factual support, or score study responses. Those operational implementations remain pending.

| Measure | Numerator | Denominator |
|---|---|---|
| Supplied reference validity | Resolvable distinct supplied IDs | All distinct supplied IDs in the declared response |
| Cited claim support | Supported cited claims assessed | Cited claims assessed |
| Attribution coverage | Reviewed source-dependent claims with usable attribution | Source-dependent claims reviewed |

Call the helpers for one declared response and evidence-assessment scope. Preserve response/version IDs, source versions, locators, sample/claim inventories, evaluator version, and detailed findings in the later evidence ledger. These pure helpers return counts, not an auditable case ledger or factual verdict.

Duplicate occurrences of one ID do not increase its validity denominator. Do not deduplicate identifiers across an entire set of responses. A resolved ID establishes existence only. A citation may be unusable or fail to support its claim. An uncited claim can still be correct; check it against adopted neutral evidence and report its attribution separately.

Claim support reports cited and uncited subsets separately. Each claim has one supplied primary support finding: supported, contradicted, insufficient support, missing qualification, or unknown. Retain richer source findings separately. A completed unknown is an unresolved semantic finding, not an execution error or proven falsehood.

Before publishing a ratio, finish the declared inventory and its expected assessments. Missing records, unrun checks, and checker errors retain separate counts and leave the affected ratio unavailable. A completed empty scope has denominator zero and a null ratio. A complete cited subset can be reported while an uncited subset is still pending, with both scopes disclosed. No assessment is inserted or inferred by the helpers.

Complete assessment work can still contain unknown findings. The completion flag does not establish conclusive support, adequate evidence, or a successful response. Inventories concern substantive claims actually present in returned text; omitted requested answers belong to completeness checks. Source dependence and citation presence are upstream annotations requiring review, not facts established by this helper. In particular, changing source dependence must not become a way to discard attribution obligations.

For support, use the evidence associated with the claim and its relevant ages, units, quantities, conditions, and qualifications. Do not label an authored scheduling duration as a publisher prescription. Evidence-basis strings must later be bound to adopted source versions; their presence here does not verify a source.

The artificial marker-square example pairs a resolvable reference with an independently authored contradiction finding. The code checks the accounting of those supplied findings. It does not interpret the example's text.

Retrieval has a separate Step 23 benchmark: Hit@k and Recall@k at 1, 3, and 5; MRR@5; and accepted complete evidence bundles. Select using development Recall@5, then MRR@5, then the simpler lexical method. Report unsupported questions and evidence-adequacy failures separately. No retrieval evaluation occurs here.

Actual adopted references, claim extraction, source resolution, source-dependent checkers and human evidence review remain open. These measures do not produce a human evidence-accuracy rating, approve any planning rule, or establish full Step 17 readiness.
"""
    payloads = {"evidence_accounting_policy.md": documentation.encode(), "evidence_accounting_config.json": packed(config),
        "evidence_accounting.py": EVIDENCE_METRICS_SOURCE.encode(),
        "evidence_accounting_probes.json": packed({"scope": "authored artificial inventories, supplied assessments, and independent arithmetic expectations only", "probes": probes}),
        "evidence_accounting_probe_checks.csv": results.to_csv(index=False, lineterminator="\n").encode()}
    artifacts = {name: sha(content) for name, content in payloads.items()}
    identity = sha(packed({"recipe_version": recipe, "input_hashes": dependencies, "artifact_hashes": artifacts}))
    payloads["step17_evidence_accounting_summary.json"] = packed({"schema_version": "step17-evidence-accounting-producer-1", "recipe_version": recipe,
        "component_digest": identity, "status": "evidence_accounting_and_artificial_checks_prepared", "input_hashes": dependencies, "artifacts": artifacts,
        "measures": 3, "artificial_scenarios": len(probes), "checks_passed": len(checks),
        "study_profiles_read": 0, "study_responses_read": 0, "actual_source_ids_resolved": 0,
        "actual_claims_assessed": 0, "actual_attribution_reviews": 0, "human_ratings_assigned": 0,
        "operational_evidence_checkers_implemented": False, "protocol_ready": False})

    step17_evidence_status["stage"] = "saving_public_evidence_component"
    executable = shutil.which("git")
    if executable is None and os.name == "nt":
        options = [Path(base) / "Git/cmd/git.exe" for name in ["ProgramFiles", "ProgramFiles(x86)"] if (base := os.environ.get(name))]
        if os.environ.get("LOCALAPPDATA"):
            options.append(Path(os.environ["LOCALAPPDATA"]) / "Programs/Git/cmd/git.exe")
        executable = next((str(value) for value in options if value.is_file()), None)
    require(executable is not None, "Git is unavailable to this kernel.")
    def verify_git():
        def git(*arguments):
            value = subprocess.run([executable, "-C", str(root), *arguments], capture_output=True, text=True, encoding="utf-8", check=False)
            require(value.returncode == 0, "The Git boundary could not be checked.")
            return value.stdout.strip()
        require(Path(git("rev-parse", "--show-toplevel")).resolve() == root and git("branch", "--show-current") == "sam-development", "Use this project on sam-development.")
    parent_directory = path("artifacts/evaluation")
    bundle = path("artifacts/evaluation/evidence_accounting_" + identity[:16])
    verify_git(); verify_dependencies()
    mode = "reused_verified_evidence_accounting_component"
    if bundle.exists():
        require(bundle.is_dir() and {value.name for value in bundle.iterdir()} == set(payloads)
            and all(path((bundle / name).relative_to(root).as_posix()).read_bytes() == content for name, content in payloads.items()),
            "Existing evidence component differs. Preserve it and declare a new version.")
    else:
        parent_directory.mkdir(parents=True, exist_ok=True)
        staging = Path(tempfile.mkdtemp(prefix="evidence_stage_", dir=parent_directory))
        try:
            for name, content in payloads.items():
                (staging / name).write_bytes(content)
                require((staging / name).read_bytes() == content, "Evidence staging readback failed.")
            verify_dependencies(); verify_git()
            require(not bundle.exists(), "The component appeared during saving; inspect it before continuing.")
            os.rename(staging, bundle)
            mode = "saved_and_verified_evidence_accounting_component"
        finally:
            if staging.exists():
                shutil.rmtree(staging)
    require(all(path((bundle / name).relative_to(root).as_posix()).read_bytes() == content for name, content in payloads.items()), "Evidence component readback failed.")
    verify_dependencies()
    print("Step 17-5 — Evidence accounting policies and artificial checks saved")
    print(f"Mode: {mode} | Separate measures: 3 | Artificial scenarios: {len(probes)} | Checks passed: {len(checks)}")
    display(results.groupby("group", sort=False).agg(scenarios=("probe", "nunique"), checks=("status", "size")).reset_index())
    print("Reference resolution, claim support, and usable attribution retain separate counts and denominators.")
    print("Unknown findings are distinct from contradiction. Empty or unfinished measures remain unavailable.")
    print("Actual source IDs resolved: 0 | Study claims assessed: 0 | Study profiles/responses read: 0 | Human ratings assigned: 0")
    print("Saved files: 6 | Component:", bundle.relative_to(root).as_posix())
    print("Claim extraction, source resolution and factual checkers remain pending; retrieval evaluation belongs to Step 23.")
    print("Existing files unchanged. Full Step 17 protocol readiness and final evaluation remain open.")
    return {"status": "evidence_accounting_and_artificial_checks_prepared", "root": root, "bundle_root": bundle,
        "component_digest": identity, "input_hashes": dependencies, "artifact_hashes": {name: sha(content) for name, content in payloads.items()},
        "config": config, "checks": results, "evidence_functions": {name: module[name] for name in
            ["summarize_reference_ids", "summarize_claim_support", "summarize_attribution"]},
        "actual_claims_assessed": 0, "protocol_ready": False}


if not isinstance(globals().get("step17_human_contract"), dict):
    raise RuntimeError("Run Step 17-4 successfully before this cell.")
step17_evidence_contract = prepare_step17_evidence_contract(step17_human_contract)
step17_evidence_status["stage"] = "complete"


