# Step 17-6 — Prepare runtime/resource accounting with artificial observations.
# This cell runs no planner jobs and records no actual benchmark measurements.
import copy
import hashlib
import json
import math
import os
import platform
import shutil
import subprocess
import tempfile
from pathlib import Path

import pandas as pd
from IPython.display import display

step17_runtime_contract = None
step17_runtime_status = {"stage": "checking_prerequisites"}
RUNTIME_METRICS_SOURCE = '"""Pure accounting for supplied workflow timing and model-transport usage records."""\n\nimport math\n\nVERSION = "runtime-accounting-1"\nJOB_STATES = ("not_started", "running", "returned", "failed", "timeout")\nTERMINAL_STATES = ("returned", "failed", "timeout")\nROLES = ("generator", "coordinator", "specialist", "evaluator")\n\n\ndef _text(value):\n    if not isinstance(value, str) or not value.strip():\n        raise ValueError("Expected nonblank text.")\n    return value\n\n\ndef _quantity(value, count=False):\n    if value is not None and (type(value) not in ((int,) if count else (int, float))\n            or value < 0 or (not count and not math.isfinite(value))):\n        raise ValueError("Expected a finite nonnegative measurement or null.")\n    return value\n\n\ndef _roster(values):\n    if not isinstance(values, list):\n        raise ValueError("Expected an identifier list.")\n    for value in values:\n        _text(value)\n    if len(set(values)) != len(values):\n        raise ValueError("Expected unique identifiers.")\n    return list(values)\n\n\ndef _measure(values, complete, empty_is_zero=False):\n    available = [value for value in values if value is not None]\n    total = sum(available) if available or (not values and empty_is_zero and complete) else None\n    fully_measured = complete and len(available) == len(values)\n    return {"expected_measurements": len(values), "available_measurements": len(available),\n        "missing_measurements": len(values) - len(available), "observed_total": total,\n        "observed_mean": total / len(available) if available else None,\n        "complete_total": total if fully_measured else None,\n        "complete_mean": total / len(available) if fully_measured and available else None,\n        "measure_complete": fully_measured,\n        "unavailable_reason": None if fully_measured and total is not None else\n            ("inventory_or_execution_incomplete" if not complete else "missing_measurements" if len(available) < len(values) else "empty_group")}\n\n\ndef summarize_workflow_runtime(job_ids, records, inventory_complete):\n    """Keep terminal and pending jobs separate; never sum stage durations into wall time."""\n    roster = _roster(job_ids)\n    if type(inventory_complete) is not bool or not isinstance(records, list):\n        raise ValueError("Declare inventory completeness and supply workflow records.")\n    fields = {"job_id", "job_status", "workflow_elapsed_seconds", "startup_elapsed_seconds",\n        "stages", "cache_state", "retrieval_calls", "lookup_calls"}\n    rows = {}\n    stage_observations = stage_missing = startup_available = 0\n    for row in records:\n        if not isinstance(row, dict) or set(row) != fields:\n            raise ValueError("Invalid workflow-record fields.")\n        key = _text(row["job_id"])\n        if key not in roster or key in rows:\n            raise ValueError("Unexpected or duplicate job identifier.")\n        state = row["job_status"]\n        if not isinstance(state, str) or state not in JOB_STATES:\n            raise ValueError("Invalid workflow status.")\n        elapsed = _quantity(row["workflow_elapsed_seconds"])\n        startup = _quantity(row["startup_elapsed_seconds"])\n        retrieval = _quantity(row["retrieval_calls"], count=True)\n        lookup = _quantity(row["lookup_calls"], count=True)\n        if state not in TERMINAL_STATES and elapsed is not None:\n            raise ValueError("Unfinished jobs cannot carry a completed workflow duration.")\n        if not isinstance(row["cache_state"], str) or row["cache_state"] not in ("unknown", "warm", "cold", "disabled"):\n            raise ValueError("Invalid declared cache state.")\n        if not isinstance(row["stages"], list):\n            raise ValueError("Expected stage observations.")\n        stages = set()\n        for stage in row["stages"]:\n            if not isinstance(stage, dict) or set(stage) != {"stage_id", "elapsed_seconds"}:\n                raise ValueError("Invalid stage-observation fields.")\n            stage_id = _text(stage["stage_id"])\n            duration = _quantity(stage["elapsed_seconds"])\n            if stage_id in stages or (elapsed is not None and duration is not None and duration > elapsed):\n                raise ValueError("Stage identity or duration differs from its whole-workflow boundary.")\n            stages.add(stage_id)\n            stage_observations += 1\n            stage_missing += int(duration is None)\n        if state == "not_started" and (startup is not None or row["stages"] or retrieval not in (None, 0) or lookup not in (None, 0)):\n            raise ValueError("Unstarted jobs cannot carry observed runtime activity.")\n        startup_available += int(startup is not None)\n        rows[key] = row\n    states = dict.fromkeys((*JOB_STATES, "not_recorded"), 0)\n    for key in roster:\n        states[rows[key]["job_status"] if key in rows else "not_recorded"] += 1\n    terminal = [row for row in rows.values() if row["job_status"] in TERMINAL_STATES]\n    complete = inventory_complete and len(terminal) == len(roster)\n    groups = {}\n    for state in (*TERMINAL_STATES, "all_terminal"):\n        selected = terminal if state == "all_terminal" else [row for row in terminal if row["job_status"] == state]\n        groups[state] = {"jobs": len(selected), **_measure([row["workflow_elapsed_seconds"] for row in selected], complete)}\n    return {"version": VERSION, "expected_jobs": len(roster), "inventory_complete": inventory_complete,\n        "execution_complete": complete, "status_counts": states, "workflow_seconds": groups,\n        "lookup_retrieval_summary_scope": "terminal_jobs_only",\n        "stage_startup_summary_scope": "all_recorded_jobs",\n        "retrieval_calls": _measure([row["retrieval_calls"] for row in terminal], complete, empty_is_zero=True),\n        "lookup_calls": _measure([row["lookup_calls"] for row in terminal], complete, empty_is_zero=True),\n        "stage_observations": stage_observations, "stage_measurements_missing": stage_missing,\n        "stage_durations_summed": False, "startup_measurements_available": startup_available,\n        "startup_included_in_request_time": False, "returned_does_not_establish_planner_success": True}\n\n\ndef summarize_model_transport(calls, attempts, inventory_complete):\n    """One workflow job; charge tokens and estimates only at the transport-attempt level."""\n    if type(inventory_complete) is not bool or not isinstance(calls, list) or not isinstance(attempts, list):\n        raise ValueError("Declare inventory completeness and supply call/attempt lists.")\n    indexed = {}\n    for row in calls:\n        if not isinstance(row, dict) or set(row) != {"call_id", "role", "phase", "revision_index"}:\n            raise ValueError("Invalid logical-call fields.")\n        key = _text(row["call_id"])\n        if key in indexed or not isinstance(row["role"], str) or row["role"] not in ROLES:\n            raise ValueError("Invalid logical-call identity or role.")\n        revision = _quantity(row["revision_index"], count=True)\n        if revision is None or row["phase"] not in ("initial", "revision") or (row["phase"] == "initial") != (revision == 0):\n            raise ValueError("Initial calls use index zero; revision calls use a positive revision index.")\n        indexed[key] = row\n    identifiers = set()\n    by_call = dict.fromkeys(indexed, 0)\n    states = dict.fromkeys(("returned", "failed", "timeout", "running"), 0)\n    for row in attempts:\n        if not isinstance(row, dict) or set(row) != {"attempt_id", "call_id", "attempt_status", "input_tokens", "output_tokens", "cost_estimate"}:\n            raise ValueError("Invalid transport-attempt fields.")\n        key = _text(row["attempt_id"])\n        parent = _text(row["call_id"])\n        if key in identifiers or parent not in indexed:\n            raise ValueError("Duplicate attempt or missing logical-call parent.")\n        identifiers.add(key)\n        by_call[parent] += 1\n        state = row["attempt_status"]\n        if not isinstance(state, str) or state not in states:\n            raise ValueError("Invalid transport-attempt status.")\n        states[state] += 1\n        _quantity(row["input_tokens"], count=True)\n        _quantity(row["output_tokens"], count=True)\n        cost = row["cost_estimate"]\n        if cost is not None:\n            if not isinstance(cost, dict) or set(cost) != {"amount", "currency", "basis_ref"}:\n                raise ValueError("Invalid model-transport cost estimate.")\n            if _quantity(cost["amount"]) is None:\n                raise ValueError("An estimate needs an observed amount and recorded basis.")\n            currency = _text(cost["currency"])\n            if len(currency) != 3 or not currency.isascii() or not currency.isalpha() or not currency.isupper():\n                raise ValueError("Expected an explicit three-letter currency code.")\n            _text(cost["basis_ref"])\n    absent = sum(count == 0 for count in by_call.values())\n    complete = inventory_complete and states["running"] == 0 and absent == 0\n    role_counts = {role: sum(row["role"] == role for row in calls) for role in ROLES}\n    phase_counts = {phase: sum(row["phase"] == phase for row in calls) for phase in ("initial", "revision")}\n    retry_count = sum(max(count - 1, 0) for count in by_call.values())\n    revisions = len({row["revision_index"] for row in calls if row["phase"] == "revision"})\n    costs = [row["cost_estimate"] for row in attempts if row["cost_estimate"] is not None]\n    currencies = sorted({row["currency"] for row in costs})\n    cost_ready = complete and bool(attempts) and len(costs) == len(attempts) and len(currencies) == 1\n    return {"version": VERSION, "inventory_complete": inventory_complete, "usage_complete": complete,\n        "logical_calls_observed": len(calls), "transport_attempts_observed": len(attempts),\n        "retry_attempts_observed": retry_count, "revision_calls_observed": phase_counts["revision"], "revision_rounds_observed": revisions,\n        "logical_calls_total": len(calls) if complete else None,\n        "transport_attempts_total": len(attempts) if complete else None,\n        "retry_attempts_total": retry_count if complete else None,\n        "revision_rounds_total": revisions if complete else None,\n        "calls_without_attempts": absent, "attempt_status_counts": states,\n        "logical_call_roles_observed": role_counts, "logical_call_phases_observed": phase_counts,\n        "role_and_phase_breakdowns_overlap": True,\n        "input_tokens": _measure([row["input_tokens"] for row in attempts], complete, empty_is_zero=True),\n        "output_tokens": _measure([row["output_tokens"] for row in attempts], complete, empty_is_zero=True),\n        "model_transport_cost_estimate": {"scope": "model_transport_only", "expected_estimates": len(attempts),\n            "available_estimates": len(costs), "missing_estimates": len(attempts) - len(costs),\n            "observed_totals_by_currency": {currency: sum(row["amount"] for row in costs if row["currency"] == currency) for currency in currencies},\n            "estimate_total": sum(row["amount"] for row in costs) if cost_ready else None,\n            "currency": currencies[0] if cost_ready else None,\n            "basis_refs": sorted({row["basis_ref"] for row in costs}),\n            "measure_complete": cost_ready, "unavailable_reason": None if cost_ready else\n                ("inventory_or_execution_incomplete" if not complete else "empty_group" if not attempts else "missing_estimates" if len(costs) < len(attempts) else "mixed_currencies")}}\n'


def build_runtime_probes():
    probes = []
    def add(name, group, function, arguments, expected=None, reject=False):
        probes.append({"name": name, "group": group, "function": function, "arguments": arguments,
            **({"expected_exception": "ValueError"} if reject else {"expected": expected})})
    def job(key, state="returned", seconds=10, **extra):
        return {"job_id": key, "job_status": state, "workflow_elapsed_seconds": seconds,
            "startup_elapsed_seconds": None, "stages": [], "cache_state": "unknown",
            "retrieval_calls": 0, "lookup_calls": 0, **extra}
    def call(key, role="generator", revision=0):
        return {"call_id": key, "role": role, "phase": "revision" if revision else "initial", "revision_index": revision}
    def attempt(key, parent, state="returned", inp=10, out=4, cost=0.1, currency="USD"):
        return {"attempt_id": key, "call_id": parent, "attempt_status": state,
            "input_tokens": inp, "output_tokens": out,
            "cost_estimate": None if cost is None else {"amount": cost, "currency": currency, "basis_ref": "toy:price-basis-v1"}}
    runtime = "summarize_workflow_runtime"
    usage = "summarize_model_transport"
    add("whole_workflow_and_overlapping_stages", "workflow_time", runtime,
        [["toy:a"], [job("toy:a", seconds=12, startup_elapsed_seconds=30,
            stages=[{"stage_id": "coordinator", "elapsed_seconds": 9}, {"stage_id": "specialist", "elapsed_seconds": 8},
                    {"stage_id": "last_model_call", "elapsed_seconds": 2}])], True],
        {"workflow_seconds.returned.complete_total": 12, "workflow_seconds.returned.complete_mean": 12,
         "stage_observations": 3, "stage_durations_summed": False, "startup_included_in_request_time": False,
         "startup_measurements_available": 1, "returned_does_not_establish_planner_success": True})
    add("failures_and_timeouts_retain_consumed_time", "workflow_time", runtime,
        [["toy:a", "toy:b", "toy:c"], [job("toy:a", seconds=12), job("toy:b", "failed", 5), job("toy:c", "timeout", 20)], True],
        {"execution_complete": True, "workflow_seconds.returned.complete_mean": 12,
         "workflow_seconds.failed.complete_total": 5, "workflow_seconds.timeout.complete_total": 20,
         "workflow_seconds.all_terminal.complete_total": 37, "workflow_seconds.all_terminal.complete_mean": 37 / 3})
    add("missing_duration_is_not_zero", "workflow_time", runtime,
        [["toy:a", "toy:b"], [job("toy:a", seconds=8), job("toy:b", seconds=None)], True],
        {"execution_complete": True, "workflow_seconds.returned.available_measurements": 1,
         "workflow_seconds.returned.missing_measurements": 1, "workflow_seconds.returned.observed_mean": 8,
         "workflow_seconds.returned.complete_mean": None, "workflow_seconds.returned.complete_total": None})
    add("explicit_zero_duration_is_valid", "workflow_time", runtime,
        [["toy:a"], [job("toy:a", seconds=0)], True], {"workflow_seconds.returned.complete_total": 0, "workflow_seconds.returned.complete_mean": 0})
    add("pending_jobs_are_not_failures", "workflow_time", runtime,
        [["toy:a", "toy:b", "toy:c", "toy:d"], [job("toy:a", seconds=6), job("toy:b", "not_started", None), job("toy:c", "running", None)], True],
        {"execution_complete": False, "status_counts.not_started": 1, "status_counts.running": 1, "status_counts.not_recorded": 1,
         "status_counts.failed": 0, "workflow_seconds.returned.observed_mean": 6, "workflow_seconds.returned.complete_mean": None})
    add("incomplete_job_inventory_cannot_make_full_latency", "workflow_time", runtime,
        [["toy:a"], [job("toy:a")], False], {"execution_complete": False, "workflow_seconds.returned.observed_mean": 10,
         "workflow_seconds.returned.complete_mean": None})
    add("empty_runtime_group_has_no_latency", "workflow_time", runtime, [[], [], True],
        {"workflow_seconds.returned.complete_mean": None, "workflow_seconds.all_terminal.observed_total": None,
         "retrieval_calls.complete_total": 0, "expected_jobs": 0})
    add("unknown_lookups_are_not_zero", "workflow_time", runtime,
        [["toy:a", "toy:b"], [job("toy:a", retrieval_calls=2, lookup_calls=1), job("toy:b", retrieval_calls=None, lookup_calls=3)], True],
        {"retrieval_calls.observed_total": 2, "retrieval_calls.complete_total": None, "retrieval_calls.missing_measurements": 1,
         "lookup_calls.complete_total": 4})
    add("unknown_stage_duration_stays_missing", "workflow_time", runtime,
        [["toy:a"], [job("toy:a", stages=[{"stage_id": "toy:stage", "elapsed_seconds": None}])], True],
        {"stage_measurements_missing": 1, "workflow_seconds.returned.complete_total": 10})
    calls = [call("toy:c1", "coordinator"), call("toy:c2", "specialist"), call("toy:c3", "coordinator", revision=1)]
    attempts = [attempt("toy:a1", "toy:c1", "failed", inp=5, out=0, cost=0.02),
        attempt("toy:a2", "toy:c1", inp=7, out=3, cost=0.03),
        attempt("toy:a3", "toy:c2", inp=11, out=4, cost=0.04),
        attempt("toy:a4", "toy:c3", inp=13, out=6, cost=0.05)]
    add("retries_revisions_and_roles_remain_separate", "model_usage", usage, [calls, attempts, True],
        {"logical_calls_total": 3, "transport_attempts_total": 4, "retry_attempts_total": 1,
         "revision_rounds_total": 1, "revision_calls_observed": 1, "logical_call_roles_observed.coordinator": 2,
         "logical_call_phases_observed.revision": 1, "role_and_phase_breakdowns_overlap": True,
         "input_tokens.complete_total": 36, "output_tokens.complete_total": 13,
         "model_transport_cost_estimate.estimate_total": 0.14, "model_transport_cost_estimate.currency": "USD"})
    add("multiple_calls_in_one_revision_round", "model_usage", usage,
        [[call("toy:c1", "specialist", 1), call("toy:c2", "evaluator", 1)], [attempt("toy:a1", "toy:c1"), attempt("toy:a2", "toy:c2")], True],
        {"revision_calls_observed": 2, "revision_rounds_total": 1, "retry_attempts_total": 0})
    add("failed_attempts_keep_measured_usage", "model_usage", usage,
        [[call("toy:c")], [attempt("toy:a", "toy:c", "timeout", inp=9, out=2, cost=0.03)], True],
        {"usage_complete": True, "attempt_status_counts.timeout": 1, "input_tokens.complete_total": 9,
         "output_tokens.complete_total": 2, "model_transport_cost_estimate.estimate_total": 0.03})
    add("partial_tokens_do_not_become_full_total", "model_usage", usage,
        [[call("toy:c")], [attempt("toy:a", "toy:c", inp=12), attempt("toy:b", "toy:c", inp=None, out=None)], True],
        {"input_tokens.observed_total": 12, "input_tokens.complete_total": None, "input_tokens.missing_measurements": 1,
         "output_tokens.observed_total": 4, "output_tokens.complete_total": None})
    add("incomplete_call_inventory_keeps_total_unavailable", "model_usage", usage,
        [[call("toy:c")], [attempt("toy:a", "toy:c")], False],
        {"logical_calls_observed": 1, "logical_calls_total": None, "transport_attempts_total": None,
         "input_tokens.observed_total": 10, "input_tokens.complete_total": None,
         "model_transport_cost_estimate.estimate_total": None})
    add("running_attempt_not_completed_usage", "model_usage", usage,
        [[call("toy:c")], [attempt("toy:a", "toy:c", "running", inp=None, out=None, cost=None)], True],
        {"usage_complete": False, "transport_attempts_observed": 1, "transport_attempts_total": None,
         "input_tokens.complete_total": None})
    add("declared_call_without_attempt_is_incomplete", "model_usage", usage,
        [[call("toy:c")], [], True], {"calls_without_attempts": 1, "usage_complete": False, "logical_calls_total": None})
    add("complete_empty_call_inventory_has_zero_counts_tokens", "model_usage", usage, [[], [], True],
        {"logical_calls_total": 0, "transport_attempts_total": 0, "input_tokens.complete_total": 0,
         "output_tokens.complete_total": 0, "model_transport_cost_estimate.estimate_total": None})
    add("incomplete_empty_inventory_is_not_zero_usage", "model_usage", usage, [[], [], False],
        {"logical_calls_total": None, "input_tokens.complete_total": None, "input_tokens.observed_total": None})
    add("missing_estimate_is_not_free_usage", "cost_estimates", usage,
        [[call("toy:c")], [attempt("toy:a", "toy:c", cost=None)], True],
        {"model_transport_cost_estimate.estimate_total": None, "model_transport_cost_estimate.missing_estimates": 1,
         "model_transport_cost_estimate.unavailable_reason": "missing_estimates"})
    add("mixed_currency_estimates_are_not_added", "cost_estimates", usage,
        [[call("toy:c")], [attempt("toy:a", "toy:c", cost=0.1), attempt("toy:b", "toy:c", cost=0.2, currency="EUR")], True],
        {"model_transport_cost_estimate.estimate_total": None, "model_transport_cost_estimate.currency": None,
         "model_transport_cost_estimate.observed_totals_by_currency": {"EUR": 0.2, "USD": 0.1},
         "model_transport_cost_estimate.unavailable_reason": "mixed_currencies"})
    add("explicit_zero_estimate_requires_basis", "cost_estimates", usage,
        [[call("toy:c")], [attempt("toy:a", "toy:c", inp=0, out=0, cost=0)], True],
        {"model_transport_cost_estimate.estimate_total": 0, "model_transport_cost_estimate.currency": "USD",
         "input_tokens.complete_total": 0, "output_tokens.complete_total": 0})
    for name, bad in [("negative_duration", -1), ("boolean_duration", True), ("nonnumeric_duration", "12")]:
        add(name, "input_rejection", runtime, [["toy:a"], [job("toy:a", seconds=bad)], True], reject=True)
    for name, rows in [
        ("duplicate_job_ids", [job("toy:a"), job("toy:a")]),
        ("out_of_roster_job", [job("toy:b")]),
        ("pending_job_with_completed_duration", [job("toy:a", "running", 5)]),
        ("unstarted_job_with_activity", [job("toy:a", "not_started", None, retrieval_calls=1)]),
        ("stage_exceeds_whole_workflow", [job("toy:a", stages=[{"stage_id": "x", "elapsed_seconds": 20}])]),
        ("duplicate_stage_identity", [job("toy:a", stages=[{"stage_id": "x", "elapsed_seconds": 2}] * 2)]),
        ("boolean_lookup_count", [job("toy:a", lookup_calls=False)]),
    ]:
        add(name, "input_rejection", runtime, [["toy:a"], rows, True], reject=True)
    add("duplicate_scheduled_job", "input_rejection", runtime, [["toy:a", "toy:a"], [], True], reject=True)
    add("nonboolean_job_inventory", "input_rejection", runtime, [[], [], 1], reject=True)
    for name, call_rows, attempt_rows in [
        ("duplicate_call_id", [call("toy:c"), call("toy:c")], []),
        ("duplicate_attempt_id", [call("toy:c")], [attempt("toy:a", "toy:c")] * 2),
        ("unknown_call_parent", [call("toy:c")], [attempt("toy:a", "toy:other")]),
        ("boolean_token_count", [call("toy:c")], [attempt("toy:a", "toy:c", inp=True)]),
        ("fractional_token_count", [call("toy:c")], [attempt("toy:a", "toy:c", out=1.5)]),
        ("negative_token_count", [call("toy:c")], [attempt("toy:a", "toy:c", inp=-1)]),
        ("unrecorded_cost_basis", [call("toy:c")], [{**attempt("toy:a", "toy:c"), "cost_estimate": {"amount": 0.1, "currency": "USD", "basis_ref": " "}}]),
        ("missing_currency", [call("toy:c")], [attempt("toy:a", "toy:c", currency="")]),
        ("negative_estimate", [call("toy:c")], [attempt("toy:a", "toy:c", cost=-1)]),
        ("boolean_revision_index", [{**call("toy:c"), "revision_index": False}], []),
        ("revision_with_zero_index", [{**call("toy:c"), "phase": "revision"}], []),
        ("double_countable_logical_tokens", [{**call("toy:c"), "input_tokens": 10}], []),
    ]:
        add(name, "input_rejection", usage, [call_rows, attempt_rows, True], reject=True)
    add("nonboolean_usage_inventory", "input_rejection", usage, [[], [], "yes"], reject=True)
    return probes



def prepare_step17_runtime_contract(evidence_receipt):
    def require(condition, message):
        if not bool(condition):
            raise RuntimeError(message)
    root = Path(evidence_receipt["root"]).resolve()
    recipe = "runtime-accounting-contract-0.1.0"
    def path(relative):
        require(isinstance(relative, str) and "\\" not in relative, "Invalid project path.")
        value = root / relative
        require(not Path(relative).is_absolute() and value == value.resolve()
            and value.is_relative_to(root) and value != root, "Invalid project path.")
        return value
    def packed(value):
        return (json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n").encode()
    def sha(content):
        return hashlib.sha256(content).hexdigest()
    def file_sha(relative):
        value = hashlib.sha256()
        with path(relative).open("rb") as handle:
            for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                value.update(chunk)
        return value.hexdigest()

    step17_runtime_status["stage"] = "verifying_public_preparation_component"
    previous = Path(evidence_receipt["bundle_root"])
    require(previous == previous.resolve() and previous.parent == root / "artifacts/evaluation"
        and previous.name == "evidence_accounting_" + evidence_receipt["component_digest"][:16], "Evidence component path differs.")
    names = {"evidence_accounting_policy.md", "evidence_accounting_config.json", "evidence_accounting.py",
        "evidence_accounting_probes.json", "evidence_accounting_probe_checks.csv", "step17_evidence_accounting_summary.json"}
    require(set(evidence_receipt["artifact_hashes"]) == names, "Unexpected evidence component files.")
    dependencies = {(previous / name).relative_to(root).as_posix(): expected
        for name, expected in evidence_receipt["artifact_hashes"].items()}
    summary_path = (previous / "step17_evidence_accounting_summary.json").relative_to(root).as_posix()
    require(file_sha(summary_path) == dependencies[summary_path], "The preceding component changed.")
    summary_bytes = path(summary_path).read_bytes()
    require(sha(summary_bytes) == dependencies[summary_path], "The preceding summary changed during reading.")
    previous_summary = json.loads(summary_bytes)
    sources = {"results/step15_exercise_split_summary.json", "data/processed/exercise_groups.csv", "data/processed/exercise_split_manifest.csv",
        "results/exercise_benchmark_review_decisions.csv", "results/exercise_class_eligibility.csv", "results/exercise_split_candidates.csv",
        "results/exercise_split_summary.csv", "results/exercise_split_checks.csv", "artifacts/splits/exercise_split_config.json"}
    component_sets = {
        "classifier_metrics_": {"classifier_metric_config.json", "classifier_metrics.py", "classifier_metric_probes.json",
            "classifier_metric_probe_checks.csv", "step17_classifier_metric_summary.json"},
        "planner_assessment_": {"planner_assessment_config.json", "planner_assessment_policy.py", "planner_assessment_probes.json",
            "planner_assessment_probe_checks.csv", "step17_planner_assessment_summary.json"},
        "human_review_": {"human_review_rubric.md", "human_review_config.json", "human_rating_entry_schema.json", "human_review_metrics.py",
            "human_review_examples.json", "human_review_probes.json", "human_review_probe_checks.csv", "step17_human_review_summary.json"}}
    remaining = set(previous_summary["input_hashes"]) - sources
    require(sources.issubset(previous_summary["input_hashes"]), "The public source dependency slice differs.")
    for prefix, expected_names in component_sets.items():
        selected = {value for value in remaining if value.startswith("artifacts/evaluation/" + prefix)}
        require(len(selected) == len(expected_names) and {Path(value).name for value in selected} == expected_names
            and len({Path(value).parent for value in selected}) == 1, "The public component dependency slice differs.")
        remaining -= selected
    require(not remaining and previous_summary["input_hashes"] == evidence_receipt["input_hashes"], "Unexpected dependency scope.")
    previous_identity = {"recipe_version": previous_summary["recipe_version"], "input_hashes": previous_summary["input_hashes"],
        "artifact_hashes": previous_summary["artifacts"]}
    require(sha(packed(previous_identity)) == previous_summary["component_digest"] == evidence_receipt["component_digest"]
        and previous_summary["artifacts"] == {name: evidence_receipt["artifact_hashes"][name] for name in names if name != "step17_evidence_accounting_summary.json"}
        and previous_summary["protocol_ready"] is False and previous_summary["operational_evidence_checkers_implemented"] is False
        and all(previous_summary[key] == 0 for key in ["study_profiles_read", "study_responses_read", "actual_source_ids_resolved",
            "actual_claims_assessed", "actual_attribution_reviews", "human_ratings_assigned"]), "The preceding preparation identity or scope differs.")
    dependencies.update(previous_summary["input_hashes"])
    def verify_dependencies():
        require(all(file_sha(relative) == expected for relative, expected in dependencies.items()),
            "A public preparation dependency changed. Preserve the saved versions.")
    verify_dependencies()

    step17_runtime_status["stage"] = "checking_artificial_runtime_records"
    module = {"__name__": "runtime_accounting"}
    exec(compile(RUNTIME_METRICS_SOURCE, "<runtime-accounting>", "exec"), module)
    probes = build_runtime_probes()
    require(len({probe["name"] for probe in probes}) == len(probes), "Artificial scenario names must be unique.")
    def same(expected, observed):
        if expected is None or isinstance(expected, (str, bool)):
            return type(expected) is type(observed) and expected == observed
        if isinstance(expected, (int, float)):
            return type(observed) in (int, float) and math.isclose(expected, observed, rel_tol=1e-12, abs_tol=1e-12)
        if isinstance(expected, list):
            return isinstance(observed, list) and len(expected) == len(observed) and all(same(a, b) for a, b in zip(expected, observed))
        return isinstance(observed, dict) and set(expected) == set(observed) and all(same(value, observed[key]) for key, value in expected.items())
    checks = []
    for probe in probes:
        arguments = copy.deepcopy(probe["arguments"])
        before = packed(arguments)
        try:
            observed = module[probe["function"]](*arguments)
        except ValueError:
            require(probe.get("expected_exception") == "ValueError", "A valid artificial runtime record was rejected.")
            checks.append({"probe": probe["name"], "group": probe["group"], "check": "invalid_input_rejected",
                "expected": "ValueError", "observed": "ValueError", "status": "pass"})
        else:
            require("expected_exception" not in probe, "An invalid artificial runtime record was accepted.")
            packed(observed)
            for field, expected in probe["expected"].items():
                value = observed
                for key in field.split("."):
                    value = value[key]
