step18_text_rules = None
step18_text_status = {"stage": "checking_prerequisites", "check": "input_receipt"}
TEXT_RULES_SOURCE = '"""Fixed exercise-text rules; learned representations are prepared separately."""\n\nimport re\nimport unicodedata\n\nTEXT_RULES_VERSION = "exercise-text-rules-0.1.0"\nTOKEN_PATTERN = r"(?u)\\b\\w+(?:[.\'’/-]\\w+)*\\b"\n_TOKENS = re.compile(TOKEN_PATTERN)\n\n\ndef _string(value):\n    if not isinstance(value, str):\n        raise TypeError("Text preparation requires a string without coercion.")\n    return value\n\n\ndef normalize_model_text(canonical_text):\n    """Apply NFKC, compact whitespace, strip, then casefold, in that order.\n\n    This generic operation permits empty strings. Validate canonical exercise\n    input through prepare_canonical_text before using it as a model example.\n    Apply this function once to canonical text, never again to saved model_text.\n    """\n    normalized = unicodedata.normalize("NFKC", _string(canonical_text))\n    return re.sub(r"\\s+", " ", normalized).strip().casefold()\n\n\ndef tokenize_model_text(model_text):\n    """Tokenize already prepared text; do not normalize again or insert UNK."""\n    return _TOKENS.findall(_string(model_text))\n\n\ndef prepare_canonical_text(canonical_text):\n    """Validate a nonblank canonical input and prepare both shared representations."""\n    text = _string(canonical_text)\n    if not text.strip():\n        raise ValueError("Canonical exercise text must not be empty or whitespace-only.")\n    model_text = normalize_model_text(text)\n    if not model_text:\n        raise ValueError("Canonical exercise text became empty after fixed normalization.")\n    return {"model_text": model_text, "tokens": tokenize_model_text(model_text)}\n\n\ndef tokenize_canonical_text(canonical_text):\n    """Sklearn tokenizer for canonical input: normalize once, then tokenize.\n\n    Keep the vectorizer\'s word analyzer, disable extra lowercasing and use no\n    additional preprocessor. Pass classifier_text, not saved model_text.\n    """\n    return prepare_canonical_text(canonical_text)["tokens"]\n'


def build_text_rule_probes():
    probes = []
    def add(name, group, function, arguments, expected=None, exception=None):
        probes.append({"name": name, "group": group, "function": function, "arguments": arguments,
            **({"expected_exception": exception} if exception else {"expected": expected})})
    normalize = "normalize_model_text"
    tokenize = "tokenize_model_text"
    prepare = "prepare_canonical_text"
    canonical_tokens = "tokenize_canonical_text"
    for name, raw, model in [
        ("ascii_case_and_space", "  Push-UP  HOLD ", "push-up hold"),
        ("unicode_whitespace", "\tKeep\u00a0the\u2003KNEE\r\nsteady\t", "keep the knee steady"),
        ("quoted_multiline_canonical_text", "One-Arm Row\n\nDo NOT rotate.", "one-arm row do not rotate."),
        ("fullwidth_compatibility", "ＰＵＳＨ－ＵＰ ２．５", "push-up 2.5"),
        ("compatibility_ligature", "ﬂy and Kettlebell", "fly and kettlebell"),
        ("casefold_and_accents", "Straße ÉPAULE", "strasse épaule"),
        ("empty_generic_text", "", ""),
        ("whitespace_generic_text", " \t\r\n", ""),
        ("literal_missing_words_are_strings", "NaN None", "nan none"),
        ("casefold_combining_dot", "İstanbul", "i\u0307stanbul"),
        ("exactly_once_sharp_s_combining_acute", "ß\u0301", "ss\u0301"),
        ("second_normalization_is_a_different_input", "ss\u0301", "sś"),
    ]:
        add(name, "normalization", normalize, [raw], {"value": model})
    for name, model, tokens in [
        ("ascii_internal_connectors", "one-arm don't 1/2 2.5", ["one-arm", "don't", "1/2", "2.5"]),
        ("curly_apostrophe", "don’t force it", ["don’t", "force", "it"]),
        ("punctuation_delimiters", "row, press; hold: stop!", ["row", "press", "hold", "stop"]),
        ("unicode_dash_delimiters", "one–arm one—arm", ["one", "arm", "one", "arm"]),
        ("repeated_connectors_split", "a--b c//d e..f", ["a", "b", "c", "d", "e", "f"]),
        ("underscores_are_word_characters", "a__b c_d", ["a__b", "c_d"]),
        ("accented_letters_retained", "épaule café", ["épaule", "café"]),
        ("combining_dot_is_a_delimiter", "i\u0307stanbul", ["i", "stanbul"]),
        ("tokenizer_does_not_normalize_again", "ss\u0301", ["ss"]),
        ("connector_tokens_are_not_numeric_validation", "2.5.3 a/b-c", ["2.5.3", "a/b-c"]),
        ("leading_signs_and_edges_are_delimiters", "-2.5 +3 /hold/", ["2.5", "3", "hold"]),
        ("unicode_fraction_slash_is_a_delimiter", "1⁄2", ["1", "2"]),
        ("punctuation_only_has_no_tokens", "--- !!! /", []),
        ("generic_empty_tokens", "", []),
        ("generic_blank_tokens", " \t", []),
    ]:
        add(name, "tokenization", tokenize, [model], {"value": tokens})
    add("canonical_text_has_one_shared_preparation", "canonical_boundary", prepare,
        ["  One-Arm Row\n\nDo NOT rotate.  "],
        {"model_text": "one-arm row do not rotate.", "tokens": ["one-arm", "row", "do", "not", "rotate"]})
    add("name_only_input_is_retained", "canonical_boundary", prepare,
        ["Goblet Squat"], {"model_text": "goblet squat", "tokens": ["goblet", "squat"]})
    add("valid_punctuation_does_not_insert_neural_fallback", "canonical_boundary", prepare,
        ["!!!"], {"model_text": "!!!", "tokens": []})
    add("raw_wrapper_uses_the_same_exact_once_path", "canonical_boundary", canonical_tokens,
        ["ß\u0301"], {"value": ["ss"]})
    add("canonical_wrapper_keeps_negation_and_numbers", "canonical_boundary", canonical_tokens,
        ["Do NOT hold 2.5 seconds"], {"value": ["do", "not", "hold", "2.5", "seconds"]})
    for raw, name in [("", "empty_canonical_rejected"), (" \t\n", "blank_canonical_rejected")]:
        add(name, "input_rejection", prepare, [raw], exception="ValueError")
        add(name + "_vectorizer_path", "input_rejection", canonical_tokens, [raw], exception="ValueError")
    for function in [normalize, tokenize, prepare, canonical_tokens]:
        for name, raw in [("none", None), ("numeric", 4), ("boolean", True), ("list", ["hold"]), ("mapping", {"text": "hold"})]:
            add(function + "_rejects_" + name, "input_rejection", function, [raw], exception="TypeError")
    for name, raw, expected in [
        ("word_analyzer_keeps_unigrams_and_bigrams", " One-Arm\tDON'T stop 2.5 / 1/2 ",
         ["one-arm", "don't", "stop", "2.5", "1/2", "one-arm don't", "don't stop", "stop 2.5", "2.5 1/2"]),
        ("word_analyzer_uses_exactly_once_normalization", "ß\u0301", ["ss"]),
        ("word_analyzer_punctuation_has_no_invented_token", "!!!", []),
    ]:
        add(name, "tfidf_analyzer", "artificial_tfidf_analyzer", [raw], {"value": expected})
    return probes



def prepare_step18_text_rules(inputs):
    def require(condition, name):
        step18_text_status["check"] = name
        if not bool(condition):
            raise RuntimeError("text_policy_check_failed")
    root = Path(inputs["root"]).resolve()
    recipe = "shared-text-rules-preparation-0.1.0"
    def packed(value):
        return (json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n").encode()
    def sha(content):
        return hashlib.sha256(content).hexdigest()
    def path(relative):
        require(isinstance(relative, str) and not Path(relative).is_absolute() and "\\" not in relative, "relative_input_path")
        value = root / relative
        require(value == value.resolve() and value.is_relative_to(root) and value != root, "canonical_input_path")
        return value
    def file_sha(relative):
        digest = hashlib.sha256()
        with path(relative).open("rb") as handle:
            for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                digest.update(chunk)
        return digest.hexdigest()
    def table_sha(table):
        return sha(table.to_csv(index=False, lineterminator="\n").encode())
    require(inputs["status"] == "frozen_inputs_verified_development_text_retained"
        and inputs["features_prepared"] is inputs["test_text_retained"] is inputs["files_changed"] is False, "verified_input_receipt")
    require(inputs["permitted_text_fields"] == ["exercise_name_prepared", "description_prepared"]
        and inputs["input_text_column"] == "classifier_text" and inputs["target_column"] == "target_label", "permitted_text_boundary")
    dependencies = dict(inputs["input_hashes"])
    require(len(dependencies) == 43, "input_dependency_scope")
    def verify_inputs():
        require(all(file_sha(relative) == digest for relative, digest in dependencies.items()), "saved_input_hashes")
        require(all(table_sha(inputs[split]) == inputs["development_table_hashes"][split] for split in ["train", "validation"]),
            "retained_development_table_hashes")
    step18_text_status["stage"] = "verifying_input_and_kernel_state"
    verify_inputs()
    executable = shutil.which("git")
    if executable is None and os.name == "nt":
        choices = [Path(base) / "Git/cmd/git.exe" for name in ["ProgramFiles", "ProgramFiles(x86)"] if (base := os.environ.get(name))]
        if os.environ.get("LOCALAPPDATA"):
            choices.append(Path(os.environ["LOCALAPPDATA"]) / "Programs/Git/cmd/git.exe")
        executable = next((str(value) for value in choices if value.is_file()), None)
    require(executable is not None, "git_available")
    def verify_git():
        def git(*arguments):
            result = subprocess.run([executable, "-C", str(root), *arguments], capture_output=True, check=False)
            require(result.returncode == 0, "git_boundary_available")
            return result.stdout.decode().strip()
        require(Path(git("rev-parse", "--show-toplevel")).resolve() == root and git("branch", "--show-current") == "sam-development", "project_and_branch")
    verify_git()
    module = {"__name__": "champion_athletic_map.text_preprocessing"}
    exec(compile(TEXT_RULES_SOURCE, "<shared-text-rules>", "exec"), module)
    policy = {"schema_version": "shared-exercise-text-policy-1", "recipe_version": recipe,
        "text_rules_version": module["TEXT_RULES_VERSION"], "text_rules_source_sha256": sha(TEXT_RULES_SOURCE.encode()),
        "input": {"canonical_column": "classifier_text", "canonical_fields": ["exercise_name_prepared", "description_prepared"],
            "target_column": "target_label", "target_or_metadata_concatenation": False,
            "missing_descriptions": "Preserve absence and name-only inputs; never coerce missing values to strings or generate descriptions.",
            "canonical_validity": "Actual canonical exercise input must be nonblank. Generic normalization/tokenization can represent empty strings, but prepare_canonical_text and the raw vectorizer tokenizer reject empty/whitespace canonical input."},
        "normalization": {"ordered_operations": ["Unicode NFKC", "collapse Unicode whitespace to one ASCII space", "strip", "Unicode casefold"],
            "exactly_once": True, "idempotence_assumed": False,
            "paths": {"neural": "classifier_text -> prepare_canonical_text -> model_text and tokens",
                "tfidf": "classifier_text -> tokenize_canonical_text -> normalize once -> tokenize_model_text",
                "already_prepared_text": "model_text -> tokenize_model_text only; do not normalize it again"},
            "stopword_removal": False, "stemming": False, "lemmatization": False, "accent_stripping": False,
            "source_text_modified": False},
        "tokenization": {"pattern": module["TOKEN_PATTERN"], "core_function": "tokenize_model_text",
            "canonical_wrapper": "tokenize_canonical_text", "fallback_inserted": False,
            "scope": "Regex word-like tokens, not linguistic or numeric validation. Internal ASCII apostrophe, right-curly apostrophe, period, slash and hyphen can join word runs. Other punctuation and combining marks may delimit tokens; retain the exact rule.",
            "empty_tokens": "Valid nonblank punctuation-only text may produce no tokens. Later neural preparation uses one UNK position with a flag; the shared tokenizer inserts no token. Genuinely empty canonical text remains an input-contract error."},
        "tfidf": {"input_column": "classifier_text", "analyzer": "word", "tokenizer_function": "tokenize_canonical_text",
            "preprocessor": None, "token_pattern": None, "lowercase": False, "strip_accents": None,
            "ngram_range": [1, 2], "max_features": 10000, "min_df": 1, "max_df": 1.0, "stop_words": None,
            "binary": False, "use_idf": True, "smooth_idf": True, "sublinear_tf": False, "norm": "l2", "dtype": "float64",
            "fit_owner_step": 19, "normalization_location": "inside the canonical tokenizer wrapper exactly once",
            "prepared_model_text_is_not_this_input": True},
        "neural_vocabulary_policy": {"fit_split": "train", "frequency_basis": "total token occurrences over full untruncated training text",
            "min_token_frequency": 2, "max_ordinary_tokens": 10000, "reserved_ids": {"PAD": 0, "UNK": 1},
            "first_ordinary_id": 2, "maximum_entries_including_reserved": 10002,
            "ordering": ["descending training frequency", "lexical token order for ties"], "validation_or_test_expansion": False},
        "neural_sequence_policy": {"fit_split": "train", "percentile": 0.95, "method": "nearest rank", "minimum": 16, "maximum": 256,
            "length_basis": "full token lengths after nonempty-token fallback, before truncation",
            "truncation": "retain prefix; truncate right", "padding": "right-pad each batch to its longest retained sequence within the saved limit",
            "mask": "Boolean non-PAD positions; UNK counts as an input position", "all_padding": "error",
            "target_class_zero": "valid label index; separate from token PAD ID zero"},
        "data_access": {"normalization_applied_to_dataset": False, "tokenization_applied_to_dataset": False,
            "vocabulary_fitted": False, "tfidf_fitted": False, "test_text_accessed": False},
        "module_status": "source and functions prepared in memory; complete importable module saved in a later Step 18 cell",
        "software": {"python": platform.python_version(), "unicode_database": unicodedata.unidata_version,
            "pandas": pd.__version__, "numpy": np.__version__, "scikit_learn": sklearn.__version__}}

    step18_text_status["stage"] = "checking_artificial_text_examples"
    settings = policy["tfidf"]
    vectorizer = TfidfVectorizer(analyzer=settings["analyzer"], tokenizer=module[settings["tokenizer_function"]],
        preprocessor=settings["preprocessor"], token_pattern=settings["token_pattern"], lowercase=settings["lowercase"],
        strip_accents=settings["strip_accents"], ngram_range=tuple(settings["ngram_range"]),
        max_features=settings["max_features"], min_df=settings["min_df"], max_df=settings["max_df"],
        stop_words=settings["stop_words"], binary=settings["binary"], use_idf=settings["use_idf"],
        smooth_idf=settings["smooth_idf"], sublinear_tf=settings["sublinear_tf"], norm=settings["norm"], dtype=np.float64)
    # build_analyzer exercises fixed rules and ngrams, without fitting features.
    analyzer = vectorizer.build_analyzer()
    functions = {name: module[name] for name in ["normalize_model_text", "tokenize_model_text", "prepare_canonical_text", "tokenize_canonical_text"]}
    functions["artificial_tfidf_analyzer"] = analyzer
    probes = build_text_rule_probes()
    require(len({probe["name"] for probe in probes}) == len(probes), "unique_artificial_scenario_names")
    checks = []
    for probe in probes:
        arguments = copy.deepcopy(probe["arguments"])
        before = packed(arguments)
        step18_text_status["check"] = probe["name"]
        try:
            observed = functions[probe["function"]](*arguments)
        except (TypeError, ValueError) as error:
            require(probe.get("expected_exception") == type(error).__name__, probe["name"])
            checks.append({"probe": probe["name"], "group": probe["group"], "check": "invalid_input_rejected",
                "expected": probe["expected_exception"], "observed": type(error).__name__, "status": "pass"})
        else:
            require("expected_exception" not in probe, probe["name"])
            observed = observed if isinstance(observed, dict) else {"value": observed}
            packed(observed)
            for field, expected in probe["expected"].items():
                passed = type(expected) is type(observed[field]) and expected == observed[field]
                require(passed, probe["name"] + ":" + field)
                checks.append({"probe": probe["name"], "group": probe["group"], "check": field,
                    "expected": json.dumps(expected, ensure_ascii=False), "observed": json.dumps(observed[field], ensure_ascii=False), "status": "pass"})
        require(before == packed(arguments), "artificial_arguments_preserved")
    require("vocabulary_" not in vars(vectorizer) and "_tfidf" not in vars(vectorizer), "vectorizer_unfitted")
    step18_text_status["stage"] = "rechecking_unchanged_inputs"
    verify_inputs(); verify_git()
    results = pd.DataFrame(checks)
    policy_identity = sha(packed({"recipe_version": recipe, "input_hashes": dependencies,
        "development_table_hashes": inputs["development_table_hashes"], "policy": policy,
        "probes": probes, "checks": checks}))
    print("Step 18-2 — Shared text policy and artificial tokenizer checks prepared")
    print(f"Artificial scenarios: {len(probes)} | Checks passed: {len(checks)} | Input files reverified: {len(dependencies)}")
    display(results.groupby("group", sort=False).agg(scenarios=("probe", "nunique"), checks=("status", "size")).reset_index())
    print("Text path: canonical input -> NFKC -> compact whitespace -> strip -> casefold -> tokenize once.")
    print("TF-IDF keeps the word analyzer and custom canonical tokenizer; artificial unigram/bigram checks passed without fitting.")
    print("Empty canonical input is rejected. Punctuation-only input keeps empty tokens; neural UNK handling comes later.")
    print("Unicode normalization is not assumed idempotent; saved model_text must not pass through the canonical wrapper again.")
    print("Dataset normalization/tokenization: not started | Vocabularies fitted: 0 | Models trained: 0 | Files changed: 0")
    print("Module source and policy are held in memory for the later Step 18 save. No test text was processed.")
    print("Next: apply these fixed rules to training and validation inputs; learn neural settings from training only.")
    return {"status": "shared_text_rules_prepared_artificial_checks_passed", "root": root,
        "input_hashes": dependencies, "benchmark_id": inputs["benchmark_id"],
        "development_table_hashes": dict(inputs["development_table_hashes"]), "policy": policy,
        "policy_digest": policy_identity, "module_source": TEXT_RULES_SOURCE, "module_source_sha256": sha(TEXT_RULES_SOURCE.encode()),
        "functions": {name: module[name] for name in ["normalize_model_text", "tokenize_model_text", "prepare_canonical_text", "tokenize_canonical_text"]},
        "probes": probes, "checks": results, "artificial_check_records": checks,
        "module_saved": False, "dataset_text_processed": False, "vocabulary_fitted": False, "tfidf_fitted": False, "files_changed": False}


