    print(f"Training nearest-rank percentile: rank {sequence['percentile_rank']:,} of {sequence['n_sequences']:,}; length {sequence['nearest_rank_length']}; prepared sequence limit {sequence['max_sequence_length']}")
    visible = ["split", "records", "raw_token_positions", "retained_positions", "unknown_rate_retained", "truncated_records", "empty_token_fallback_records"]
