BATCH_HELPERS_SOURCE = '"""Right-pad validated neural examples; tensor conversion belongs to modeling."""\n\nBATCH_SCHEMA_VERSION = "neural-batch-1"\n\n\ndef pad_neural_batch(examples, max_sequence_length, vocabulary_size, num_classes):\n    """Preserve row order and repeated IDs; emit PAD zero and Boolean masks.\n\n    Inputs must already be encoded and truncated under the saved text policy.\n    This helper performs no truncation, tensor conversion, model math or fitting.\n    """\n    for value, lower in ((max_sequence_length, 1), (vocabulary_size, 2), (num_classes, 2)):\n        if type(value) is not int or value < lower:\n            raise ValueError("Invalid batch dimensions; use integers without Boolean coercion.")\n    if not isinstance(examples, list) or not examples:\n        raise ValueError("Expected a nonempty list of encoded examples.")\n    record_ids, sequences, lengths, targets = [], [], [], []\n    for example in examples:\n        if not isinstance(example, dict) or set(example) != {"record_id", "token_ids", "target"}:\n            raise ValueError("Each batch example needs exactly record_id, token_ids and target.")\n        record_id = example["record_id"]\n        if not isinstance(record_id, str) or not record_id.strip():\n            raise ValueError("Record identifiers must be nonblank strings.")\n        ids = example["token_ids"]\n        if not isinstance(ids, list) or not ids or len(ids) > max_sequence_length:\n            raise ValueError("Encoded token lists must be nonempty and within the saved limit.")\n        if any(type(token_id) is not int or not 1 <= token_id < vocabulary_size for token_id in ids):\n            raise ValueError("Unpadded tokens must be valid positive vocabulary IDs; PAD is not input.")\n        target = example["target"]\n        if type(target) is not int or not 0 <= target < num_classes:\n            raise ValueError("Targets must be valid class indices, including class zero.")\n        record_ids.append(record_id)\n        sequences.append(list(ids))\n        lengths.append(len(ids))\n        targets.append(target)\n    width = max(lengths)\n    token_ids = [ids + [0] * (width - length) for ids, length in zip(sequences, lengths)]\n    mask = [[True] * length + [False] * (width - length) for length in lengths]\n    return {"record_ids": record_ids, "token_ids": token_ids, "mask": mask,\n        "lengths": lengths, "targets": targets}\n'
POOLING_REFERENCE_SOURCE = '"""Artificial masking arithmetic only; this is not the later neural model."""\n\nimport numpy as _batch_np\n\n\ndef artificial_masked_mean(token_ids, mask, embedding_table):\n    """Check the intended pooling equation on supplied toy vectors."""\n    ids = _batch_np.asarray(token_ids)\n    positions = _batch_np.asarray(mask)\n    vectors = _batch_np.asarray(embedding_table, dtype=_batch_np.float64)\n    if (ids.ndim != 2 or not ids.size or ids.dtype.kind not in ("i", "u")\n            or positions.shape != ids.shape or positions.dtype.kind != "b"\n            or vectors.ndim != 2 or not vectors.size or not _batch_np.isfinite(vectors).all()\n            or (ids < 0).any() or (ids >= len(vectors)).any()\n            or not _batch_np.array_equal(positions, ids != 0)):\n        raise ValueError("Invalid artificial pooling inputs.")\n    lengths = positions.sum(axis=1)\n    if (lengths < 1).any():\n        raise ValueError("All-padding rows have no valid pooling denominator.")\n    selected = vectors[ids]\n    sums = _batch_np.where(positions[..., None], selected, 0.0).sum(axis=1)\n    return {"means": (sums / lengths[:, None]).tolist(), "lengths": lengths.tolist()}\n'


"""Authored batch and masked-mean expectations using artificial token IDs only."""


def build_batch_probes():
    from copy import deepcopy

    probes = []

    def add(name, group, function, arguments, expected=None, reject=False):
        probes.append({"name": name, "group": group, "function": function,
            "arguments": deepcopy(arguments),
            **({"expected_exception": "ValueError"} if reject else {"expected": deepcopy(expected)})})

    def row(record_id="toy:row", token_ids=None, target=0):
        return {"record_id": record_id, "token_ids": [2] if token_ids is None else token_ids, "target": target}

    pad = "pad_neural_batch"
    pool = "artificial_masked_mean"
    add("right_padding_keeps_order_repeats_zero_target_and_unk", "padding", pad,
        [[row("toy:b", [2, 1, 4], 0), row("toy:a", [3], 2), row("toy:b", [1, 2], 1)], 8, 5, 3],
        {"record_ids": ["toy:b", "toy:a", "toy:b"], "token_ids": [[2, 1, 4], [3, 0, 0], [1, 2, 0]],
         "mask": [[True, True, True], [True, False, False], [True, True, False]],
         "lengths": [3, 1, 2], "targets": [0, 2, 1]})
    add("singleton_unk_has_no_padding_to_global_cap", "padding", pad,
        [[row("toy:only", [1], 0)], 256, 5, 2],
        {"record_ids": ["toy:only"], "token_ids": [[1]], "mask": [[True]], "lengths": [1], "targets": [0]})
    add("sequence_at_saved_limit_is_preserved", "padding", pad,
        [[row("toy:limit", [4, 3, 2], 1)], 3, 5, 2],
        {"token_ids": [[4, 3, 2]], "mask": [[True, True, True]], "lengths": [3], "targets": [1]})

    invalid_batches = [
        ("empty_batch_rejected", [[], 4, 5, 2]),
        ("empty_unpadded_token_row_rejected", [[row(token_ids=[])], 4, 5, 2]),
        ("pad_zero_cannot_enter_unpadded_input", [[row(token_ids=[2, 0])], 4, 5, 2]),
        ("over_limit_input_is_not_silently_truncated", [[row(token_ids=[1, 2, 3])], 2, 5, 2]),
        ("negative_token_id_rejected", [[row(token_ids=[-1])], 4, 5, 2]),
        ("token_id_at_vocabulary_size_rejected", [[row(token_ids=[5])], 4, 5, 2]),
        ("boolean_token_id_rejected", [[row(token_ids=[True])], 4, 5, 2]),
        ("boolean_target_rejected", [[row(target=False)], 4, 5, 2]),
        ("negative_target_rejected", [[row(target=-1)], 4, 5, 2]),
        ("target_at_class_count_rejected", [[row(target=2)], 4, 5, 2]),
        ("boolean_batch_dimension_rejected", [[row()], True, 5, 2]),
        ("vocabulary_requires_pad_and_unk", [[row(token_ids=[1])], 4, 1, 2]),
        ("classification_requires_two_classes", [[row()], 4, 5, 1]),
        ("missing_example_field_rejected", [[{"record_id": "toy:x", "token_ids": [2]}], 4, 5, 2]),
        ("extra_example_field_rejected", [[{**row(), "padding_mask": [True]}], 4, 5, 2]),
        ("blank_record_id_rejected", [[row(record_id=" \t")], 4, 5, 2]),
    ]
    for name, arguments in invalid_batches:
        add(name, "input_rejection", pad, arguments, reject=True)

    embeddings = [[1000.0, 2000.0], [0.0, 0.0], [2.0, 4.0], [6.0, 8.0], [-2.0, 2.0]]
    add("padding_embedding_is_excluded_from_sum_and_denominator", "masked_pooling", pool,
        [[[2, 3], [2, 0]], [[True, True], [True, False]], embeddings],
        {"means": [[4.0, 6.0], [2.0, 4.0]], "lengths": [2, 1]})
    add("zero_unk_vector_still_counts_in_denominator", "masked_pooling", pool,
        [[[1, 2]], [[True, True]], embeddings],
        {"means": [[1.0, 2.0]], "lengths": [2]})
    add("unk_only_row_has_one_valid_position", "masked_pooling", pool,
        [[[1]], [[True]], embeddings],
        {"means": [[0.0, 0.0]], "lengths": [1]})
    changed_unk = deepcopy(embeddings)
    changed_unk[1] = [10.0, 20.0]
    add("changed_unk_vector_contributes_to_numerator", "masked_pooling", pool,
        [[[1, 2]], [[True, True]], changed_unk],
        {"means": [[6.0, 12.0]], "lengths": [2]})
    add("unpadded_known_token_reference_mean", "masked_pooling", pool,
        [[[2]], [[True]], embeddings],
        {"means": [[2.0, 4.0]], "lengths": [1]})
    add("right_padding_leaves_known_token_mean_unchanged", "masked_pooling", pool,
        [[[2, 0, 0]], [[True, False, False]], embeddings],
        {"means": [[2.0, 4.0]], "lengths": [1]})

    invalid_pooling = [
        ("all_pad_row_cannot_be_pooled", [[[0, 0]], [[False, False]], embeddings]),
        ("empty_mask_is_invalid", [[[2]], [[]], embeddings]),
        ("integer_mask_is_not_boolean", [[[2]], [[1]], embeddings]),
        ("mask_shape_must_match_token_ids", [[[2, 3]], [[True]], embeddings]),
        ("pooling_id_outside_embedding_table_rejected", [[[5]], [[True]], embeddings]),
    ]
    for name, arguments in invalid_pooling:
        add(name, "masked_pooling_rejection", pool, arguments, reject=True)
    return probes



def validate_step18_batches(inputs, rules, development):
    checks = []
    def require(condition, name):
        step18_batch_status["check"] = name
        if not bool(condition):
            raise RuntimeError("batch_preparation_check_failed")
    def record(name, condition, observed="verified"):
        require(condition, name)
        checks.append({"check": name, "status": "pass", "observed": str(observed)})
    root = Path(inputs["root"]).resolve()
    recipe = "development-batch-validation-0.1.0"
    def sha(value):
        return hashlib.sha256(value).hexdigest()
    def packed(value):
        return (json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n").encode()
    def table_sha(value):
        return sha(value.to_csv(index=False, lineterminator="\n").encode())
    def path(relative):
        require(isinstance(relative, str) and not Path(relative).is_absolute() and "\\" not in relative, "relative_input_path")
        value = root / relative
        require(value == value.resolve() and value.is_relative_to(root) and value != root, "canonical_input_path")
        return value
    def file_sha(relative):
        value = hashlib.sha256()
        with path(relative).open("rb") as handle:
            for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                value.update(chunk)
        return value.hexdigest()

    step18_batch_status["stage"] = "verifying_preparation_receipts"
    record("prerequisite_scope", Path(rules["root"]).resolve() == Path(development["root"]).resolve() == root
        and development["status"] == "development_neural_inputs_prepared_training_only"
        and development["vocabulary_fitted"] is True
        and development["test_text_processed"] is development["tfidf_fitted"] is development["files_changed"] is False
        and development["models_trained"] == 0)
    dependencies = dict(inputs["input_hashes"])
    record("dependency_and_class_mapping_identity", len(dependencies) == 43 and dependencies == rules["input_hashes"] == development["input_hashes"]
        and inputs["benchmark_id"] == rules["benchmark_id"] == development["benchmark_id"]
        and inputs["class_order"] == development["class_order"]
        and inputs["class_to_index"] == development["class_to_index"]
        and inputs["class_to_index"] == {label: index for index, label in enumerate(inputs["class_order"])})
    text_identity = {"recipe_version": rules["policy"]["recipe_version"], "input_hashes": dependencies,
        "development_table_hashes": rules["development_table_hashes"], "policy": rules["policy"],
        "probes": rules["probes"], "checks": rules["artificial_check_records"]}
    record("text_policy_identity", sha(packed(text_identity)) == rules["policy_digest"] == development["text_policy_digest"]
        and packed(rules["policy"]) == packed(development["policy_snapshot"]))
    development_identity = {"recipe_version": development["recipe_version"], "input_hashes": dependencies,
        "text_policy_digest": development["text_policy_digest"], "module_source_sha256": development["module_source_sha256"],
        "prepared_table_hashes": development["prepared_table_hashes"], "raw_token_hashes": development["raw_token_hashes"],
        "encoded_sequence_hashes": development["encoded_sequence_hashes"], "vocabulary_sha256": development["vocabulary_sha256"],
        "sequence_settings_sha256": development["sequence_settings_sha256"], "diagnostics_sha256": development["diagnostics_sha256"],
        "neural_probes": development["neural_probes"], "neural_probe_checks": development["neural_probe_check_records"],
        "preparation_checks": development["preparation_check_records"]}
    record("development_preparation_identity", sha(packed(development_identity)) == development["development_digest"]
        and development["neural_probe_checks"].to_dict("records") == development["neural_probe_check_records"]
        and development["preparation_checks"].to_dict("records") == development["preparation_check_records"]
        and all(row["status"] == "pass" for row in development["neural_probe_check_records"] + development["preparation_check_records"]))
    def verify_inputs_and_preparation():
        require(all(file_sha(relative) == value for relative, value in dependencies.items()), "saved_input_hashes")
        require(development["original_development_table_hashes"] == inputs["development_table_hashes"] == rules["development_table_hashes"], "original_table_hash_bindings")
        require(all(table_sha(inputs[split]) == inputs["development_table_hashes"][split] for split in ["train", "validation"]), "original_table_bytes")
        require(sha(development["module_source"].encode()) == development["module_source_sha256"], "development_module_source")
        require(sha(packed(development["vocabulary"])) == development["vocabulary_sha256"]
            and sha(packed(development["sequence_settings"])) == development["sequence_settings_sha256"], "fitted_setting_hashes")
        require(table_sha(development["diagnostics"]) == development["diagnostics_sha256"], "diagnostic_hash")
        for split in ["train", "validation"]:
            require(table_sha(development["prepared"][split]) == development["prepared_table_hashes"][split]
                and sha(packed(development["raw_tokens"][split])) == development["raw_token_hashes"][split]
                and sha(packed(development["encoded_sequences"][split])) == development["encoded_sequence_hashes"][split], "prepared_payload_hashes:" + split)
            require(development["prepared"][split][inputs[split].columns].equals(inputs[split]), "original_metadata_alignment:" + split)
    verify_inputs_and_preparation()
    executable = shutil.which("git")
    if executable is None and os.name == "nt":
        choices = [Path(base) / "Git/cmd/git.exe" for name in ["ProgramFiles", "ProgramFiles(x86)"] if (base := os.environ.get(name))]
        if os.environ.get("LOCALAPPDATA"):
            choices.append(Path(os.environ["LOCALAPPDATA"]) / "Programs/Git/cmd/git.exe")
        executable = next((str(value) for value in choices if value.is_file()), None)
    require(executable is not None, "git_available")
    def verify_git():
        def git(*arguments):
            result = subprocess.run([executable, "-C", str(root), *arguments], capture_output=True, check=False)
            require(result.returncode == 0, "git_boundary_available")
            return result.stdout.decode().strip()
        require(Path(git("rev-parse", "--show-toplevel")).resolve() == root and git("branch", "--show-current") == "sam-development", "project_and_branch")
    verify_git()
    record("project_and_branch_reverified", True)
    training_ids = inputs["train"]["catalog_id"].tolist()
    provenance = development["fit_provenance"]
    record("training_fit_provenance", development["ordered_training_catalog_ids"] == training_ids
        and provenance["ordered_training_ids_sha256"] == sha(packed(training_ids))
        and provenance["training_input_table_sha256"] == inputs["development_table_hashes"]["train"]
        and provenance["training_records"] == len(training_ids) and provenance["fit_split"] == "train"
        and provenance["validation_used_for_fit"] is provenance["test_used_for_fit"] is False
        and development["vocabulary"]["fit_provenance"] == development["sequence_settings"]["fit_provenance"] == provenance)
    source = development["module_source"].rstrip() + "\n\n" + BATCH_HELPERS_SOURCE
    module = {"__name__": "champion_athletic_map.text_preprocessing"}
    exec(compile(source, "<step18-batch-module>", "exec"), module)
    record("fitted_vocabulary_structure", module["validate_neural_vocabulary"](development["vocabulary"]))
    reference = {"__name__": "artificial_pooling_reference"}
    exec(compile(POOLING_REFERENCE_SOURCE, "<artificial-pooling-reference>", "exec"), reference)
    functions = {"pad_neural_batch": module["pad_neural_batch"], "artificial_masked_mean": reference["artificial_masked_mean"]}

    step18_batch_status["stage"] = "checking_artificial_batches_and_reference_pooling"
    probes = build_batch_probes()
    require(len({probe["name"] for probe in probes}) == len(probes), "unique_batch_probe_names")
    def same(a, b):
        if a is None or isinstance(a, (str, bool)):
            return type(a) is type(b) and a == b
        if isinstance(a, (int, float)):
            return type(b) in (int, float) and math.isclose(a, b, rel_tol=1e-12, abs_tol=1e-12)
        if isinstance(a, list):
            return isinstance(b, list) and len(a) == len(b) and all(same(x, y) for x, y in zip(a, b))
        return isinstance(b, dict) and set(a) == set(b) and all(same(value, b[key]) for key, value in a.items())
    probe_checks = []
    for probe in probes:
        arguments = copy.deepcopy(probe["arguments"])
        before = packed(arguments)
        try:
            observed = functions[probe["function"]](*arguments)
        except ValueError:
            require(probe.get("expected_exception") == "ValueError", probe["name"])
            probe_checks.append({"probe": probe["name"], "group": probe["group"], "check": "invalid_input_rejected",
                "expected": "ValueError", "observed": "ValueError", "status": "pass"})
        else:
            require("expected_exception" not in probe, probe["name"])
            packed(observed)
            for field, expected in probe["expected"].items():
                value = observed
                for key in field.split("."):
                    value = value[int(key)] if isinstance(value, list) else value[key]
                require(same(expected, value), probe["name"] + ":" + field)
                probe_checks.append({"probe": probe["name"], "group": probe["group"], "check": field,
                    "expected": json.dumps(expected, ensure_ascii=False), "observed": json.dumps(value, ensure_ascii=False), "status": "pass"})
        require(before == packed(arguments), "artificial_batch_inputs_preserved")

    step18_batch_status["stage"] = "checking_all_development_encoded_batches"
    chunk_size = 64  # Verification traversal only; not a selected training batch size.
    limit = development["sequence_settings"]["max_sequence_length"]
    size = development["vocabulary"]["vocabulary_size"]
    num_classes = len(inputs["class_order"])
    batch_rows = []
    total_records = 0
    for split in ["train", "validation"]:
        frame = development["prepared"][split]
        encoded = development["encoded_sequences"][split]
        require(len(frame) == len(encoded), "encoded_record_coverage:" + split)
        examples = [{"record_id": record_id, "token_ids": list(row["token_ids"]), "target": int(target)}
            for record_id, row, target in zip(frame["catalog_id"], encoded, frame["class_index"])]
        observed_ids, observed_targets, observed_sequences = [], [], []
        token_positions = padding_positions = unknown_positions = batches = max_width = 0
        for start in range(0, len(examples), chunk_size):
            selected = examples[start:start + chunk_size]
            batch = module["pad_neural_batch"](selected, limit, size, num_classes)
            width = max(len(value["token_ids"]) for value in selected)
            require(batch["record_ids"] == [value["record_id"] for value in selected]
                and batch["targets"] == [value["target"] for value in selected], "batch_record_and_target_alignment:" + split)
            for original, ids, mask, length in zip(selected, batch["token_ids"], batch["mask"], batch["lengths"]):
                require(len(ids) == len(mask) == width <= limit and length == len(original["token_ids"])
                    and ids[:length] == original["token_ids"] and ids[length:] == [0] * (width - length)
                    and mask == [True] * length + [False] * (width - length)
                    and all(type(value) is bool for value in mask) and sum(mask) == length
                    and all(type(value) is int and 0 <= value < size for value in ids)
                    and [value for value, keep in zip(ids, mask) if keep] == original["token_ids"], "right_padding_and_mask_invariants:" + split)
                observed_sequences.append(ids[:length])
                token_positions += length
                padding_positions += width - length
                unknown_positions += sum(value == 1 for value, keep in zip(ids, mask) if keep)
            observed_ids.extend(batch["record_ids"])
            observed_targets.extend(batch["targets"])
            batches += 1
            max_width = max(max_width, width)
        expected_targets = frame["class_index"].astype(int).tolist()
        record("complete_batch_traversal:" + split, observed_ids == frame["catalog_id"].tolist()
            and observed_targets == expected_targets and observed_sequences == [row["token_ids"] for row in encoded]
            and token_positions == int(frame["retained_length"].sum())
            and unknown_positions == int(frame["unknown_tokens_after_truncation"].sum()), len(observed_ids))
        zero_targets = sum(value == 0 for value in observed_targets)
        record("class_zero_preserved:" + split, zero_targets == int(frame["class_index"].eq(0).sum()) and zero_targets > 0, zero_targets)
        total_records += len(observed_ids)
        batch_rows.append({"split": split, "records": len(observed_ids), "verification_batches": batches,
            "largest_batch_width": max_width, "retained_token_positions": token_positions,
            "temporary_pad_positions": padding_positions, "retained_unk_positions": unknown_positions,
            "class_zero_targets": zero_targets})
    record("all_development_examples_verified", total_records == len(inputs["train"]) + len(inputs["validation"]), total_records)
    record("training_unk_count_preserved", batch_rows[0]["retained_unk_positions"] == development["training_unk_positions_after_truncation"])
    batch_summary = pd.DataFrame(batch_rows)
    contract = {"schema_version": module["BATCH_SCHEMA_VERSION"], "representation": "Python integer lists and Boolean masks; tensor conversion in Step 20",
        "pad_id": 0, "unk_id": 1, "padding": "right to longest retained sequence in current batch", "maximum_sequence_length": limit,
        "token_id_tensor_dtype": "int64", "mask_tensor_dtype": "bool", "target_tensor_dtype": "int64",
        "target_range": [0, num_classes - 1], "class_zero_valid": True, "unk_in_mask_and_pooling_denominator": True,
        "empty_or_all_padding_rows": "error", "overlong_unpadded_sequences": "error; no silent second truncation",
        "row_order_and_repeated_identifiers": "preserved", "verification_chunk_size": chunk_size,
        "verification_chunk_size_is_training_hyperparameter": False,
        "reference_pooling_scope": "Artificial NumPy arithmetic, not a neural model or PyTorch gradient/embedding integration check",
        "step20_checks_pending": ["tensor/device conversion", "actual masked-pooling model", "padding_idx and zero PAD embedding", "UNK embedding training", "loss target handling"]}
    step18_batch_status["stage"] = "rechecking_unchanged_sources_and_fitted_settings"
    verify_inputs_and_preparation()
    verify_git()
    record("sources_and_fitted_payloads_unchanged", True, len(dependencies))
    summary_hash = table_sha(batch_summary)
    batch_identity = sha(packed({"recipe_version": recipe, "input_hashes": dependencies,
        "development_digest": development["development_digest"], "module_source_sha256": sha(source.encode()),
        "batch_contract": contract, "batch_summary_sha256": summary_hash,
        "pooling_reference_sha256": sha(POOLING_REFERENCE_SOURCE.encode()),
        "batch_probes": probes, "batch_probe_checks": probe_checks, "preparation_checks": checks}))
    print("Step 18-4 — Development batching, Boolean masks and label alignment checked")
    print(f"Artificial batch scenarios: {len(probes)} | Artificial checks passed: {len(probe_checks)} | Preparation checks passed: {len(checks)}")
    with pd.option_context("display.max_columns", None):
        display(batch_summary)
    print("PAD=0 is outside valid positions; UNK=1 remains a valid masked-in position. Target class 0 is preserved.")
    print("Chunk size 64 was used only to verify traversal; no training batch size was selected.")
    print("Toy masked-mean checks passed. Actual PyTorch model, embedding-gradient and loss integration remain Step 20 work.")
    print("Vocabulary, sequence limit, prepared tables and original inputs remain unchanged. Test text was not processed.")
    print("Complete preprocessing module source remains in memory for the next save cell. Files changed: 0 | Models trained: 0")
    return {"status": "development_batch_contract_verified", "recipe_version": recipe, "root": root, "input_hashes": dependencies,
        "benchmark_id": inputs["benchmark_id"], "development_digest": development["development_digest"],
        "module_source": source, "module_source_sha256": sha(source.encode()), "batch_contract": contract,
        "batch_summary": batch_summary, "batch_summary_sha256": summary_hash, "batch_digest": batch_identity,
        "batch_probes": probes, "batch_probe_checks": pd.DataFrame(probe_checks), "batch_probe_check_records": probe_checks,
        "preparation_checks": pd.DataFrame(checks), "preparation_check_records": checks,
        "pooling_reference_source": POOLING_REFERENCE_SOURCE, "pooling_reference_sha256": sha(POOLING_REFERENCE_SOURCE.encode()),
        "batch_functions": {"pad_neural_batch": module["pad_neural_batch"]},
        "module_saved": False, "test_text_processed": False, "torch_model_integration_checked": False, "models_trained": 0, "files_changed": False}


try:
    if not all(isinstance(globals().get(name), dict) for name in ["step18_inputs", "step18_text_rules", "step18_development"]):
        raise RuntimeError("Run Steps 18-1 through 18-3 successfully in this kernel first.")
    step18_batching = validate_step18_batches(step18_inputs, step18_text_rules, step18_development)
    step18_batch_status["stage"] = "complete"
except Exception:
    step18_batching = None
    raise RuntimeError("Step 18-4 stopped at stage: " + step18_batch_status["stage"] + "; check: " + step18_batch_status["check"]
        + ". Preserve the saved inputs and share this message. Dataset content and underlying exception details are excluded.") from None


