def verify_step20_preparation(inputs, runtime, preparation):
    """Verify immutable receipts, bound files and the active runtime; do no model math."""
    import hashlib
    import json
    import os
    import platform
    import shutil
    import subprocess
    import unicodedata
    from pathlib import Path, PurePosixPath

    import numpy as np
    import pandas as pd
    import sklearn
    import torch

    stage, checks = "receipts", []

    def packed(value):
        return (json.dumps(value, sort_keys=True, indent=2, ensure_ascii=False,
                           allow_nan=False) + "\n").encode("utf-8")

    def sha(content):
        return hashlib.sha256(content).hexdigest()

    def check(name, condition, observed=True):
        nonlocal stage
        stage = name
        if not bool(condition):
            raise ValueError("neural_preparation_verification_failed")
        checks.append({"check": name, "status": "pass", "observed": str(observed)})

    try:
        check("successful_step20_preparation", all(isinstance(value, dict) for value in (inputs, runtime, preparation))
              and inputs["status"] == "neural_inputs_and_saved_baselines_verified"
              and runtime["status"] == "neural_runtime_and_initial_policy_prepared"
              and preparation["status"] == "neural_inputs_runtime_and_initial_settings_verified")
        root = Path(inputs["root"]).resolve()
        dependencies, policy, recorded = dict(inputs["input_hashes"]), runtime["policy"], runtime["runtime"]
        check("parent_roots_and_identities", root == Path(preparation["root"]).resolve()
              and len(dependencies) == 72 and dependencies == preparation["input_hashes"] == policy["input_hashes"]
              and all(inputs[key] == preparation[key] == policy[key]
                      for key in ("benchmark_id", "preprocessing_id", "baseline_id")))

        def path(relative):
            if not isinstance(relative, str) or not relative or "\\" in relative or ":" in relative:
                raise ValueError("invalid_relative_input_path")
            parsed, target = PurePosixPath(relative), root / relative
            if (parsed.is_absolute() or parsed.as_posix() != relative
                    or any(part in (".", "..") for part in parsed.parts) or target == root
                    or target != target.resolve() or not target.is_relative_to(root) or target.is_symlink()):
                raise ValueError("invalid_canonical_input_path")
            return target

        executable = shutil.which("git")
        if executable is None and os.name == "nt":
            choices = [Path(base) / "Git/cmd/git.exe" for key in ("ProgramFiles", "ProgramFiles(x86)")
                       if (base := os.environ.get(key))]
            if os.environ.get("LOCALAPPDATA"):
                choices.append(Path(os.environ["LOCALAPPDATA"]) / "Programs/Git/cmd/git.exe")
            executable = next((str(item) for item in choices if item.is_file()), None)

        def verify_bound_files():
            try:
                if executable is None:
                    raise ValueError("git_unavailable")
                results = [subprocess.run([executable, "-C", str(root), *arguments], capture_output=True, check=False)
                           for arguments in [("rev-parse", "--show-toplevel"), ("branch", "--show-current")]]
                if (any(result.returncode for result in results)
                        or Path(results[0].stdout.decode().strip()).resolve() != root
                        or results[1].stdout.decode().strip() != "sam-development"):
                    raise ValueError("project_or_branch_changed")
                for relative, expected in dependencies.items():
                    digest = hashlib.sha256()
                    with path(relative).open("rb") as handle:
                        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                            digest.update(chunk)
                    if digest.hexdigest() != expected:
                        raise ValueError("bound_input_changed")
                return True
            except Exception:
                raise RuntimeError("step20_preparation_verification_failed:bound_files_and_branch") from None

        stage = "bound_files_and_branch"
        verify_bound_files()
        check("bound_files_and_branch", True, len(dependencies))
        check("initial_policy_digest", sha(packed(policy)) == runtime["policy_digest"] == preparation["policy_digest"])
        check("recorded_runtime_bound_to_policy", recorded == policy["runtime"])
        identity = {"recipe_version": "initial-neural-preparation-0.1.0", "benchmark_id": inputs["benchmark_id"],
            "baseline_id": inputs["baseline_id"], "preprocessing_id": inputs["preprocessing_id"],
            "input_hashes": dependencies, "development_table_hashes": inputs["development_table_hashes"],
            "policy_digest": runtime["policy_digest"]}
        check("initial_preparation_digest", sha(packed(identity)) == preparation["preparation_digest"])
        check("receipt_scope_and_pass_records", inputs["test_text_processed"] is inputs["test_text_retained"] is False
              and inputs["vocabulary_refitted"] is inputs["sequences_encoded"] is False
              and runtime["models_created"] == runtime["optimizers_created"] == runtime["neural_training_runs"] == 0
              and runtime["training_seeds_applied"] is False and preparation["neural_training_runs"] == 0
              and inputs["files_changed"] is runtime["files_changed"] is preparation["files_changed"] is False
              and runtime["test_text_processed"] is preparation["test_text_processed"] is False
              and preparation["neural_models_created"] == preparation["optimizers_created"] == 0
              and preparation["sequence_encoding_completed"] is preparation["model_gradient_and_loss_integration_checked"] is False
              and inputs["checks"].to_dict("records") == inputs["check_records"]
              and runtime["checks"].to_dict("records") == runtime["check_records"]
              and inputs["checks"]["status"].eq("pass").all() and runtime["checks"]["status"].eq("pass").all())
        check("development_table_hashes", all(sha(inputs[split].to_csv(index=False, lineterminator="\n").encode("utf-8"))
              == inputs["development_table_hashes"][split] for split in ("train", "validation")))
        vocabulary, sequence = inputs["vocabulary"], inputs["sequence_settings"]
        configuration = json.loads(path("artifacts/preprocessing/preprocessing_config.json").read_bytes())
        labels = json.loads(path("artifacts/preprocessing/label_mapping.json").read_bytes())
        check("saved_settings_unchanged", inputs["preprocessing_config"] == configuration
              and vocabulary == json.loads(path("artifacts/preprocessing/neural_vocabulary.json").read_bytes())
              and sequence == configuration["sequence_settings"]
              and sha(packed(vocabulary)) == configuration["vocabulary"]["sha256"])
        classes, mapping = list(inputs["class_order"]), dict(inputs["class_to_index"])
        check("frozen_targets_and_dimensions", classes == labels["class_order"] == policy["class_order"]
              and mapping == labels["class_to_index"] == policy["class_to_index"]
              == {label: index for index, label in enumerate(classes)}
              and policy["architecture"]["output_classes"] == len(classes)
              and policy["architecture"]["vocabulary_size"] == vocabulary["vocabulary_size"]
              and vocabulary["id_to_token"][:2] == ["<PAD>", "<UNK>"]
              and vocabulary["token_to_id"] == {token: index for index, token in enumerate(vocabulary["id_to_token"])}
              and policy["neural_inputs"]["maximum_sequence_length"] == sequence["max_sequence_length"]
              and policy["neural_inputs"]["padding_idx"] == 0 and policy["neural_inputs"]["unknown_idx"] == 1)
        check("frozen_step18_dimensions", len(classes) == 16 and vocabulary["vocabulary_size"] == 1748
              and sequence["max_sequence_length"] == 81)
        check("training_only_saved_fit_provenance", vocabulary["fit_provenance"] == sequence["fit_provenance"]
              == configuration["fit_provenance"] and sequence["fit_split"] == "train"
              and vocabulary["fit_provenance"]["validation_used_for_fit"] is False
              and vocabulary["fit_provenance"]["test_used_for_fit"] is False
              and policy["neural_inputs"]["renormalize_model_text"] is False
              and policy["neural_inputs"]["tokenization_from_saved_text"] == "model_text -> tokenize_model_text only")
        check("development_partition_alignment", all(frame["catalog_id"].is_unique
              and frame["split"].eq(split).all() and frame["target_label"].tolist()
              == [classes[index] for index in frame["class_index"]]
              for split, frame in (("train", inputs["train"]), ("validation", inputs["validation"]))))
        check("separate_development_ids_and_groups", set(inputs["train"]["catalog_id"]).isdisjoint(inputs["validation"]["catalog_id"])
              and set(inputs["train"]["split_group_id"]).isdisjoint(inputs["validation"]["split_group_id"]))
        module = inputs["text_module"]
        check("bound_importable_preprocessing_module", module.__name__ == "champion_athletic_map.text_preprocessing"
              and Path(module.__file__).resolve() == path(configuration["module"]["relative_path"])
              and configuration["module"]["sha256"] == dependencies[configuration["module"]["relative_path"]]
              and all(callable(getattr(module, name, None)) for name in
                      ("tokenize_model_text", "encode_neural_tokens", "pad_neural_batch")))
        software = {"python": platform.python_version(), "unicode_database": unicodedata.unidata_version,
            "numpy": np.__version__, "pandas": pd.__version__, "scikit_learn": sklearn.__version__}
        check("current_software_matches_initial_policy", software == policy["shared_software"]
              and str(torch.__version__) == recorded["torch"] and torch.version.cuda == recorded["cuda_build"])
        check("current_device_matches_initial_policy", str(runtime["device"]) == recorded["selected_device"]
              and bool(torch.cuda.is_available()) == recorded["cuda_available"]
              and torch.backends.cudnn.version() == recorded["cudnn_version"])
        check("deterministic_runtime_unchanged", torch.are_deterministic_algorithms_enabled() is True
              and torch.is_deterministic_algorithms_warn_only_enabled() is False
              and torch.backends.cudnn.benchmark is False and torch.backends.cudnn.deterministic is True
              and os.environ.get("CUBLAS_WORKSPACE_CONFIG") == recorded["cublas_workspace_config"]
              and int(torch.get_num_threads()) == recorded["cpu_intraop_threads"]
              and int(torch.get_num_interop_threads()) == recorded["cpu_interop_threads"])
        precision = recorded["float32_precision"]
        if precision["api"] == "fp32_precision":
            check("float32_precision_unchanged", torch.backends.fp32_precision == precision["global"] == "ieee"
                  and torch.backends.cuda.matmul.fp32_precision == precision["cuda_matmul"] == "ieee"
                  and torch.backends.cudnn.fp32_precision == precision["cudnn"] == "ieee")
        else:
            check("float32_precision_unchanged", precision["api"] == "allow_tf32"
                  and torch.backends.cuda.matmul.allow_tf32 is False and torch.backends.cudnn.allow_tf32 is False)
        if recorded["cuda_available"]:
            check("selected_cuda_identity_unchanged", torch.cuda.get_device_name(runtime["device"]) == recorded["device_name"]
                  and list(torch.cuda.get_device_capability(runtime["device"])) == recorded["cuda_compute_capability"])
        return {"status": "initial_neural_preparation_reverified", "root": root, "input_hashes": dependencies,
            "policy": policy, "vocabulary": vocabulary, "sequence_settings": sequence, "class_order": classes,
            "class_to_index": mapping, "text_module": module, "checks": pd.DataFrame(checks), "check_records": checks,
            "verify_bound_files": verify_bound_files, "preparation_digest": preparation["preparation_digest"],
            "policy_digest": runtime["policy_digest"]}
    except Exception:
        raise RuntimeError("step20_preparation_verification_failed:" + stage) from None


def prepare_step20_sequences(inputs, runtime, preparation):
    """Tokenize saved model_text once and apply the existing mapping, without fitting."""
    import hashlib
    import json

    import pandas as pd

    stage = "initial_preparation_verification"
    try:
        context = verify_step20_preparation(inputs, runtime, preparation)
        checks = [{"check": "preparation:" + row["check"], "status": row["status"], "observed": row["observed"]}
                  for row in context["check_records"]]

        def packed(value):
            return (json.dumps(value, sort_keys=True, indent=2, ensure_ascii=False,
                               allow_nan=False) + "\n").encode("utf-8")

        def sha(content):
            return hashlib.sha256(content).hexdigest()

        def check(name, condition, observed=True):
            nonlocal stage
            stage = name
            if not bool(condition):
                raise ValueError("neural_sequence_check_failed")
            checks.append({"check": name, "status": "pass", "observed": str(observed)})

        module, vocabulary, sequence = context["text_module"], context["vocabulary"], context["sequence_settings"]
        limit, size, classes = sequence["max_sequence_length"], vocabulary["vocabulary_size"], context["class_order"]
        batch_size = context["policy"]["training"]["batch_size"]
        check("recorded_batch_and_token_policy", type(batch_size) is int and batch_size == 32
              and context["policy"]["neural_inputs"]["vocabulary_refitted"] is False
              and context["policy"]["neural_inputs"]["sequence_limit_refitted"] is False)
        examples, encodings, ordered_ids, rows = {}, {}, {}, []
        diagnostic_fields = ["raw_token_count", "effective_token_count", "retained_length", "truncated_tokens",
            "unknown_tokens_before_truncation", "unknown_tokens_after_truncation", "empty_token_fallback", "all_unknown_after_truncation"]
        for split in ("train", "validation"):
            frame = inputs[split]
            stage = "saved_model_text_reconstruction:" + split
            encoded, records = [], []
            for row in frame.to_dict("records"):
                tokens = module.tokenize_model_text(row["model_text"])
                item = module.encode_neural_tokens(tokens, vocabulary, limit)
                if any(type(item[key]) is not type(row[key]) or item[key] != row[key] for key in diagnostic_fields):
                    raise ValueError("saved_diagnostics_mismatch")
                encoded.append(item)
                records.append({"record_id": row["catalog_id"], "token_ids": list(item["token_ids"]), "target": int(row["class_index"])})
            check("all_saved_sequence_diagnostics_match:" + split, len(encoded) == len(frame), len(encoded))
            check("ordered_ids_and_targets_preserved:" + split, [row["record_id"] for row in records] == frame["catalog_id"].tolist()
                  and [row["target"] for row in records] == frame["class_index"].tolist())
            check("unpadded_token_bounds_and_lengths:" + split, all(1 <= len(row["token_ids"]) <= limit
                  and all(type(value) is int and 1 <= value < size for value in row["token_ids"]) for row in records))
            traversal_ids, traversal_targets, batches, retained, pads, unks, maximum = [], [], 0, 0, 0, 0, 0
            stage = "python_batch_contract_reconstruction:" + split
            for start in range(0, len(records), batch_size):
                selected = records[start:start + batch_size]
                batch = module.pad_neural_batch(selected, limit, size, len(classes))
                if (set(batch) != {"record_ids", "token_ids", "mask", "lengths", "targets"}
                        or any(not isinstance(batch[key], list) or len(batch[key]) != len(selected) for key in batch)
                        or batch["record_ids"] != [row["record_id"] for row in selected]
                        or batch["targets"] != [row["target"] for row in selected]):
                    raise ValueError("batch_order_mismatch")
                width = max(len(row["token_ids"]) for row in selected)
                for row, ids, mask, length in zip(selected, batch["token_ids"], batch["mask"], batch["lengths"]):
                    if (length != len(row["token_ids"]) or ids != row["token_ids"] + [0] * (width - length)
                            or any(type(value) is not bool for value in mask)
                            or mask != [True] * length + [False] * (width - length)
                            or mask != [value != 0 for value in ids]):
                        raise ValueError("batch_padding_or_mask_mismatch")
                    retained += length
                    pads += width - length
                    unks += sum(value == 1 and keep for value, keep in zip(ids, mask))
                traversal_ids.extend(batch["record_ids"])
                traversal_targets.extend(batch["targets"])
                batches += 1
                maximum = max(maximum, width)
            check("complete_ordered_batch_traversal:" + split, traversal_ids == frame["catalog_id"].tolist()
                  and traversal_targets == frame["class_index"].tolist()
                  and batches == (len(frame) + batch_size - 1) // batch_size, batches)
            check("retained_positions_and_unk_counts_preserved:" + split,
                  retained == int(frame["retained_length"].sum())
                  and unks == inputs["retained_unknown_positions"][split], retained)
            class_zero = sum(target == 0 for target in traversal_targets)
            check("target_class_zero_preserved:" + split, class_zero == int(frame["class_index"].eq(0).sum()), class_zero)
            examples[split], encodings[split], ordered_ids[split] = records, encoded, traversal_ids
            rows.append({"split": split, "records": len(frame), "groups": int(frame["split_group_id"].nunique()),
                "verification_batches": batches, "batch_size": batch_size,
                "last_batch_size": len(frame) - (batches - 1) * batch_size, "largest_batch_width": maximum,
                "raw_token_positions": int(frame["raw_token_count"].sum()), "retained_token_positions": retained,
                "temporary_pad_positions": pads, "retained_unk_positions": unks,
                "truncated_records": int(frame["truncated_tokens"].gt(0).sum()),
                "empty_token_fallback_records": int(frame["empty_token_fallback"].sum()),
                "all_unknown_records": int(frame["all_unknown_after_truncation"].sum()), "class_zero_targets": class_zero})
        stage = "unchanged_inputs_after_reconstruction"
        context["verify_bound_files"]()
        check("source_tables_and_saved_fit_settings_unchanged", all(sha(inputs[split].to_csv(index=False, lineterminator="\n").encode("utf-8"))
              == inputs["development_table_hashes"][split] for split in ("train", "validation"))
              and sha(packed(vocabulary)) == inputs["preprocessing_config"]["vocabulary"]["sha256"])
        summary = pd.DataFrame(rows)
        example_hashes = {split: sha(packed(value)) for split, value in examples.items()}
        encoding_hashes = {split: sha(packed(value)) for split, value in encodings.items()}
        identity = {"recipe_version": "saved-neural-sequence-reconstruction-0.1.0",
            "preparation_digest": preparation["preparation_digest"], "policy_digest": runtime["policy_digest"],
            "input_hashes": dict(inputs["input_hashes"]), "development_table_hashes": dict(inputs["development_table_hashes"]),
            "vocabulary_sha256": sha(packed(vocabulary)), "sequence_settings_sha256": sha(packed(sequence)),
            "example_hashes": example_hashes, "encoded_sequence_hashes": encoding_hashes,
            "summary_sha256": sha(summary.to_csv(index=False, lineterminator="\n").encode("utf-8")), "checks": checks}
        return {"status": "neural_development_sequences_reconstructed", "recipe_version": identity["recipe_version"],
            "root": inputs["root"], "input_hashes": dict(inputs["input_hashes"]),
            "benchmark_id": inputs["benchmark_id"], "preprocessing_id": inputs["preprocessing_id"],
            "baseline_id": inputs["baseline_id"], "class_order": list(classes),
            "class_to_index": dict(context["class_to_index"]), "vocabulary_size": size,
            "maximum_sequence_length": limit,
            "preparation_digest": preparation["preparation_digest"], "policy_digest": runtime["policy_digest"],
            "examples": examples, "encoded_sequences": encodings, "ordered_ids": ordered_ids,
            "development_table_hashes": dict(inputs["development_table_hashes"]),
            "example_hashes": example_hashes, "sequence_hashes": encoding_hashes, "encoded_sequence_hashes": encoding_hashes,
            "vocabulary_sha256": identity["vocabulary_sha256"], "sequence_settings_sha256": identity["sequence_settings_sha256"],
            "summary": summary, "summary_df": summary, "summary_sha256": identity["summary_sha256"],
            "checks": pd.DataFrame(checks), "check_records": checks, "sequence_digest": sha(packed(identity)),
            "verification_order": "saved record order before training shuffle", "torch_loaders_created": 0,
            "models_created": 0, "vocabulary_refitted": False, "sequence_limit_refitted": False,
            "test_text_processed": False, "files_changed": False}
    except Exception:
        raise RuntimeError("step20_sequence_preparation_failed:" + stage) from None


"""Source for the importable, initially untrained neural exercise classifier."""

NEURAL_CLASSIFIER_SOURCE = '''"""Small bag-of-tokens classifier with explicit padding and unknown-token rules."""

import math

import torch
from torch import nn


MODEL_VERSION = "masked-mean-neural-classifier-1"


class NeuralExerciseClassifier(nn.Module):
    """Learn token embeddings and classify their masked mean using raw logits."""

    def __init__(self, vocab_size, num_classes, embedding_dim=64, hidden_dim=64,
                 dropout=0.2, max_sequence_length=81, padding_idx=0, unknown_idx=1):
        dimensions = (vocab_size, num_classes, embedding_dim, hidden_dim, max_sequence_length)
        if any(type(value) is not int for value in dimensions):
            raise TypeError("invalid_neural_model_configuration")
        if (vocab_size < 2 or num_classes < 2 or embedding_dim < 1
                or hidden_dim < 1 or max_sequence_length < 1):
            raise ValueError("invalid_neural_model_configuration")
        if type(padding_idx) is not int or type(unknown_idx) is not int:
            raise TypeError("invalid_neural_model_configuration")
        if padding_idx != 0 or unknown_idx != 1:
            raise ValueError("invalid_neural_model_configuration")
        if type(dropout) is not float:
            raise TypeError("invalid_neural_model_configuration")
        if not math.isfinite(dropout) or not 0.0 <= dropout < 1.0:
            raise ValueError("invalid_neural_model_configuration")

        super().__init__()
        self.vocab_size = vocab_size
        self.num_classes = num_classes
        self.embedding_dim = embedding_dim
        self.hidden_dim = hidden_dim
        self.dropout_probability = dropout
        self.max_sequence_length = max_sequence_length
        self.padding_idx = padding_idx
        self.unknown_idx = unknown_idx

        self.embedding = nn.Embedding(vocab_size, embedding_dim,
                                      padding_idx=padding_idx, dtype=torch.float32, device="cpu")
        self.hidden = nn.Linear(embedding_dim, hidden_dim, dtype=torch.float32, device="cpu")
        self.activation = nn.ReLU()
        self.dropout = nn.Dropout(p=dropout)
        self.output = nn.Linear(hidden_dim, num_classes, dtype=torch.float32, device="cpu")
        with torch.no_grad():
            self.embedding.weight[padding_idx].zero_()
            self.embedding.weight[unknown_idx].zero_()

    def _check_inputs(self, input_ids, mask):
        if not isinstance(input_ids, torch.Tensor) or not isinstance(mask, torch.Tensor):
            raise TypeError("invalid_neural_input_contract")
        if input_ids.dtype != torch.long or mask.dtype != torch.bool:
            raise TypeError("invalid_neural_input_contract")
        if (input_ids.ndim != 2 or mask.ndim != 2 or input_ids.shape != mask.shape
                or input_ids.shape[0] < 1 or input_ids.shape[1] < 1
                or input_ids.shape[1] > self.max_sequence_length):
            raise ValueError("invalid_neural_input_contract")
        if input_ids.device != mask.device or input_ids.device != self.embedding.weight.device:
            raise ValueError("invalid_neural_input_contract")
        if bool(((input_ids < 0) | (input_ids >= self.vocab_size)).any()):
            raise ValueError("invalid_neural_input_contract")
        if not bool(torch.equal(mask, input_ids.ne(self.padding_idx))):
            raise ValueError("invalid_neural_input_contract")
        if not bool(mask.any(dim=1).all()):
            raise ValueError("invalid_neural_input_contract")
        if bool((mask[:, 1:] & ~mask[:, :-1]).any()):
            raise ValueError("invalid_neural_input_contract")

    def pooled_representation(self, input_ids, mask):
        """Average valid positions; UNK contributes to the count even when zero."""
        self._check_inputs(input_ids, mask)
        embeddings = self.embedding(input_ids)
        valid = mask.unsqueeze(-1).to(dtype=embeddings.dtype)
        denominator = mask.sum(dim=1, keepdim=True).to(dtype=embeddings.dtype)
        return (embeddings * valid).sum(dim=1) / denominator

    def forward(self, input_ids, mask):
        pooled = self.pooled_representation(input_ids, mask)
        hidden = self.activation(self.hidden(pooled))
        return self.output(self.dropout(hidden))
'''


"""Authored tensor checks for the neural model; no exercise records are read."""


def run_neural_model_probes(model_class, model_config, device):
    import copy
    import hashlib
    import json
    import random

    import numpy as np
    import pandas as pd
    import torch

    stage, checks = "probe_configuration", []
    models_created, optimizer_steps = 0, 0
    python_rng, numpy_rng = random.getstate(), np.random.get_state()
    cpu_rng = torch.random.get_rng_state().clone()
    selected = torch.device(device)
    if selected.type == "cuda" and selected.index is None:
        selected = torch.device("cuda", torch.cuda.current_device())
    cuda_devices = [selected.index] if selected.type == "cuda" else []
    cuda_rng = torch.cuda.get_rng_state(selected).clone() if selected.type == "cuda" else None
    backend_before = (torch.are_deterministic_algorithms_enabled(),
        torch.is_deterministic_algorithms_warn_only_enabled(), torch.backends.cudnn.benchmark,
        torch.backends.cudnn.deterministic)

    def packed(value):
        return (json.dumps(value, ensure_ascii=False, sort_keys=True,
                           indent=2, allow_nan=False) + "\n").encode("utf-8")

    def record(probe, name, observed, expected=True):
        nonlocal stage
        stage = probe["name"] + ":" + name
        if packed(observed) != packed(expected):
            raise ValueError("neural_probe_condition_failed")
        checks.append({"probe": probe["name"], "group": probe["group"], "check": name,
            "expected": json.dumps(expected, ensure_ascii=False, allow_nan=False),
            "observed": json.dumps(observed, ensure_ascii=False, allow_nan=False), "status": "pass"})

    def new_model(configuration):
        nonlocal models_created
        model = model_class(**copy.deepcopy(configuration)).to(selected)
        models_created += 1
        return model

    def ids(values, dtype=torch.long):
        return torch.tensor(values, dtype=dtype, device=selected)

    probes = [
        {"name": "reserved_embeddings_start_at_zero", "group": "initialization"},
        {"name": "unknown_position_counts_in_masked_mean", "group": "masking",
         "token_ids": [[2, 1, 0]], "known_embedding_value": 2.0, "expected_pooled_value": 1.0},
        {"name": "extra_right_padding_preserves_eval_result", "group": "masking",
         "short_ids": [[2, 3, 1], [4, 1, 0]],
         "padded_ids": [[2, 3, 1, 0, 0, 0], [4, 1, 0, 0, 0, 0]],
         "rtol": 1e-6, "atol": 1e-7},
        {"name": "network_returns_raw_logits", "group": "output_contract",
         "output_bias_start": -2.0, "output_bias_end": 3.0},
        {"name": "target_class_zero_is_scored_by_cross_entropy", "group": "loss_contract",
         "logit_start": -0.4, "logit_end": 0.7, "ignore_index": -100,
         "rtol": 1e-6, "atol": 1e-7},
        {"name": "adamw_updates_valid_embeddings_and_classifier", "group": "gradient_and_update",
         "token_ids": [[2, 1, 0], [3, 1, 0]], "targets": "zero and highest frozen class",
         "learning_rate": 0.001, "weight_decay": 0.0001},
        {"name": "dropout_inactive_in_evaluation", "group": "evaluation_mode"},
        {"name": "all_unknown_input_is_valid", "group": "input_contract", "token_ids": [[1, 1, 0]]},
        {"name": "reject_all_padding", "group": "input_rejection", "expected_exception": "ValueError"},
        {"name": "reject_mask_excluding_unknown", "group": "input_rejection", "expected_exception": "ValueError"},
        {"name": "reject_non_boolean_mask", "group": "input_rejection", "expected_exception": "TypeError"},
        {"name": "reject_non_integer_token_tensor", "group": "input_rejection", "expected_exception": "TypeError"},
        {"name": "reject_out_of_range_token", "group": "input_rejection", "expected_exception": "ValueError"},
        {"name": "reject_negative_token", "group": "input_rejection", "expected_exception": "ValueError"},
        {"name": "reject_non_right_padding", "group": "input_rejection", "expected_exception": "ValueError"},
        {"name": "reject_overlong_sequence", "group": "input_rejection", "expected_exception": "ValueError"},
        {"name": "reject_mismatched_mask_shape", "group": "input_rejection", "expected_exception": "ValueError"},
        {"name": "reject_empty_batch", "group": "input_rejection", "expected_exception": "ValueError"},
        {"name": "reject_empty_sequence_width", "group": "input_rejection", "expected_exception": "ValueError"},
        {"name": "reject_rank_one_inputs", "group": "input_rejection", "expected_exception": "ValueError"},
    ]

    try:
        config = copy.deepcopy(model_config)
        original_configuration = packed(model_config)
        if (not isinstance(config, dict) or config["vocab_size"] < 5 or config["num_classes"] < 2
                or config["max_sequence_length"] < 6 or selected.type not in ("cpu", "cuda")):
            raise ValueError("unsupported_probe_configuration")
        with torch.random.fork_rng(devices=cuda_devices, enabled=True):
            generator = torch.Generator(device="cpu").manual_seed(42)
            torch.set_rng_state(generator.get_state())
            if selected.type == "cuda":
                with torch.cuda.device(selected):
                    torch.cuda.manual_seed(42)

            initial = new_model(config)
            probe = probes[0]
            record(probe, "pad_and_unknown_embeddings_are_zero",
                {"pad_zero": bool(torch.count_nonzero(initial.embedding.weight[0]).item() == 0),
                 "unknown_zero": bool(torch.count_nonzero(initial.embedding.weight[1]).item() == 0)},
                {"pad_zero": True, "unknown_zero": True})
            record(probe, "all_model_parameters_are_float32",
                   all(parameter.dtype == torch.float32 for parameter in initial.parameters()))
            record(probe, "embedding_padding_index_is_reserved_zero", initial.embedding.padding_idx, 0)

            probe = probes[1]
            with torch.no_grad():
                initial.embedding.weight[2].fill_(probe["known_embedding_value"])
            token_ids = ids(probe["token_ids"])
            pooled = initial.pooled_representation(token_ids, token_ids.ne(0))
            record(probe, "known_plus_zero_unknown_means_half_known_embedding",
                bool(torch.equal(pooled, torch.full_like(pooled, probe["expected_pooled_value"]))))
            record(probe, "padding_is_excluded_but_unknown_remains_counted",
                   token_ids.ne(0).sum(dim=1).cpu().tolist(), [2])

            evaluation = new_model(config).eval()
            probe = probes[2]
            short, padded = ids(probe["short_ids"]), ids(probe["padded_ids"])
            with torch.no_grad():
                short_pool = evaluation.pooled_representation(short, short.ne(0))
                long_pool = evaluation.pooled_representation(padded, padded.ne(0))
                short_logits = evaluation(short, short.ne(0))
                padded_logits = evaluation(padded, padded.ne(0))
            record(probe, "pooled_features_ignore_extra_right_padding", bool(torch.allclose(
                short_pool, long_pool, rtol=probe["rtol"], atol=probe["atol"])))
            record(probe, "evaluation_logits_ignore_extra_right_padding", bool(torch.allclose(
                short_logits, padded_logits, rtol=probe["rtol"], atol=probe["atol"])))

            raw = new_model(config).eval()
            probe = probes[3]
            bias = torch.linspace(probe["output_bias_start"], probe["output_bias_end"], config["num_classes"],
                                  dtype=torch.float32, device=selected)
            with torch.no_grad():
                raw.output.weight.zero_()
                raw.output.bias.copy_(bias)
                logits = raw(short, short.ne(0))
            record(probe, "output_shape_and_dtype", {"shape": list(logits.shape), "dtype": str(logits.dtype)},
                   {"shape": [2, config["num_classes"]], "dtype": "torch.float32"})
            record(probe, "output_is_untransformed_negative_and_above_one_logits",
                   bool(torch.equal(logits, bias.unsqueeze(0).expand(2, -1)))
                   and bool((logits[:, 0] < 0).all()) and bool((logits[:, -1] > 1).all()))

            probe = probes[4]
            logits = torch.linspace(probe["logit_start"], probe["logit_end"], config["num_classes"],
                dtype=torch.float32, device=selected).repeat(2, 1).clone().requires_grad_()
            targets = ids([0, config["num_classes"] - 1])
            criterion = torch.nn.CrossEntropyLoss(weight=None, label_smoothing=0.0)
            loss = criterion(logits, targets)
            manual = -torch.log_softmax(logits, dim=1)[torch.arange(2, device=selected), targets].mean()
            record(probe, "loss_uses_raw_logits_and_scores_target_zero", bool(torch.allclose(
                loss, manual, rtol=probe["rtol"], atol=probe["atol"])))
            record(probe, "loss_ignore_index_is_not_target_class_zero", criterion.ignore_index, probe["ignore_index"])
            loss.backward()
            record(probe, "class_zero_example_receives_nonzero_logit_gradient",
                   bool(logits.grad is not None and logits.grad[0].abs().sum().item() > 0))

            update = new_model(config).train()
            probe = probes[5]
            with torch.no_grad():
                update.embedding.weight[2].fill_(0.25)
                update.embedding.weight[3].fill_(0.5)
                update.hidden.weight.fill_(0.1)
                update.hidden.bias.fill_(0.1)
                slopes = (torch.arange(config["num_classes"], dtype=torch.float32, device=selected) + 1) * 0.01
                update.output.weight.copy_(slopes.unsqueeze(1).expand(-1, config["hidden_dim"]))
                update.output.bias.zero_()
            before = {"embedding": update.embedding.weight.detach().clone(),
                      "hidden": update.hidden.weight.detach().clone(), "output": update.output.weight.detach().clone()}
            optimizer = torch.optim.AdamW(update.parameters(), lr=probe["learning_rate"],
                weight_decay=probe["weight_decay"], betas=(0.9, 0.999), eps=1e-8, amsgrad=False)
            token_ids = ids(probe["token_ids"])
            targets = ids([0, config["num_classes"] - 1])
            optimizer.zero_grad(set_to_none=True)
            update_loss = torch.nn.CrossEntropyLoss(weight=None, label_smoothing=0.0)(
                update(token_ids, token_ids.ne(0)), targets)
            record(probe, "synthetic_training_loss_is_finite", bool(torch.isfinite(update_loss).item()))
            update_loss.backward()
            record(probe, "all_parameter_gradients_are_present_and_finite", all(
                parameter.grad is not None and bool(torch.isfinite(parameter.grad).all()) for parameter in update.parameters()))
            record(probe, "pad_gradient_is_zero", bool(update.embedding.weight.grad[0].eq(0).all()))
            record(probe, "unknown_gradient_and_relevant_layer_gradients_are_nonzero", all(
                bool(gradient.abs().sum().item() > 0) for gradient in
                [update.embedding.weight.grad[1], update.embedding.weight.grad[2], update.hidden.weight.grad, update.output.weight.grad]))
            optimizer.step()
            optimizer_steps += 1
            record(probe, "embedding_hidden_and_output_weights_receive_updates", all(
                not torch.equal(before[name], parameter.detach()) for name, parameter in
                [("embedding", update.embedding.weight), ("hidden", update.hidden.weight), ("output", update.output.weight)]))
            record(probe, "unknown_embedding_learns_from_its_zero_initialization", bool(update.embedding.weight[1].abs().sum().item() > 0))
            record(probe, "pad_embedding_stays_exactly_zero_after_adamw", bool(update.embedding.weight[0].eq(0).all()))
            record(probe, "updated_model_parameters_remain_finite", all(
                bool(torch.isfinite(parameter).all()) for parameter in update.parameters()))

            probe = probes[6]
            with torch.no_grad():
                first = evaluation(short, short.ne(0))
                repeated = evaluation(short, short.ne(0))
            record(probe, "evaluation_mode_disables_dropout", evaluation.training is False and evaluation.dropout.training is False)
            record(probe, "repeated_evaluation_logits_are_identical", bool(torch.equal(first, repeated)))
            probe = probes[7]
            unknown = ids(probe["token_ids"])
            with torch.no_grad():
                pooled = evaluation.pooled_representation(unknown, unknown.ne(0))
                logits = evaluation(unknown, unknown.ne(0))
            record(probe, "all_unknown_input_keeps_valid_positions", unknown.ne(0).sum(dim=1).cpu().tolist(), [2])
            record(probe, "all_unknown_input_produces_finite_frozen_class_logits",
                   list(logits.shape) == [1, config["num_classes"]] and bool(torch.isfinite(logits).all())
                   and bool(pooled.eq(0).all()))

            bad_inputs = [
                (ids([[0, 0]]), ids([[0, 0]], torch.bool)),
                (ids([[2, 1, 0]]), ids([[1, 0, 0]], torch.bool)),
                (ids([[2, 0]]), ids([[1, 0]], torch.long)),
                (ids([[2, 0]], torch.float32), ids([[1, 0]], torch.bool)),
                (ids([[config["vocab_size"], 0]]), ids([[1, 0]], torch.bool)),
                (ids([[-1, 0]]), ids([[1, 0]], torch.bool)),
                (ids([[2, 0, 3]]), ids([[1, 0, 1]], torch.bool)),
                (torch.full((1, config["max_sequence_length"] + 1), 2, dtype=torch.long, device=selected),
                 torch.ones((1, config["max_sequence_length"] + 1), dtype=torch.bool, device=selected)),
                (ids([[2, 0]]), ids([[1]], torch.bool)),
                (torch.empty((0, 1), dtype=torch.long, device=selected), torch.empty((0, 1), dtype=torch.bool, device=selected)),
                (torch.empty((1, 0), dtype=torch.long, device=selected), torch.empty((1, 0), dtype=torch.bool, device=selected)),
                (ids([2, 0]), ids([1, 0], torch.bool)),
            ]
            for probe, (bad_ids, bad_mask) in zip(probes[8:], bad_inputs):
                stage = probe["name"]
                try:
                    evaluation(bad_ids, bad_mask)
                except (TypeError, ValueError) as error:
                    record(probe, "invalid_tensor_contract_rejected", type(error).__name__, probe["expected_exception"])
                else:
                    raise ValueError("invalid_tensor_contract_accepted")

        random.setstate(python_rng)
        np.random.set_state(numpy_rng)
        state_probe = {"name": "diagnostics_preserve_rng_and_backend_state", "group": "diagnostic_isolation"}
        probes.append(state_probe)
        record(state_probe, "cpu_rng_restored_after_synthetic_updates", bool(torch.equal(cpu_rng, torch.random.get_rng_state())))
        if cuda_rng is not None:
            record(state_probe, "selected_cuda_rng_restored_after_synthetic_updates", bool(torch.equal(cuda_rng, torch.cuda.get_rng_state(selected))))
        record(state_probe, "python_and_numpy_rng_states_restored", random.getstate() == python_rng
               and np.random.get_state()[0] == numpy_rng[0] and np.array_equal(np.random.get_state()[1], numpy_rng[1])
               and np.random.get_state()[2:] == numpy_rng[2:])
        record(state_probe, "global_backend_flags_unchanged", backend_before == (
            torch.are_deterministic_algorithms_enabled(), torch.is_deterministic_algorithms_warn_only_enabled(),
            torch.backends.cudnn.benchmark, torch.backends.cudnn.deterministic))
        record(state_probe, "caller_model_configuration_unchanged", packed(model_config) == original_configuration)
        identity = {"recipe_version": "neural-model-artificial-checks-0.1.0", "model_config": config,
            "device": str(selected), "torch": str(torch.__version__), "probes": probes, "checks": checks,
            "synthetic_models_created": models_created, "synthetic_optimizer_steps": optimizer_steps}
        return {"status": "artificial_neural_model_contract_passed", "recipe_version": identity["recipe_version"],
            "probes": probes, "checks": pd.DataFrame(checks), "check_records": checks,
            "probe_digest": hashlib.sha256(packed(identity)).hexdigest(), "scenario_count": len(probes),
            "checks_passed": len(checks), "synthetic_models_created": models_created,
            "synthetic_optimizers_created": 1, "synthetic_optimizer_steps": optimizer_steps,
            "selected_device_tested": str(selected), "actual_dataset_records_read": 0,
            "recorded_neural_training_runs": 0, "rng_restored": True,
            "global_backend_flags_unchanged": True, "test_text_processed": False, "files_changed": False}
    except Exception:
        raise RuntimeError("step20_neural_artificial_checks_failed:" + stage) from None
    finally:
        random.setstate(python_rng)
        np.random.set_state(numpy_rng)


"""One disposable training-only update, isolated from the recorded N0 run."""


def check_training_only_neural_update(model_class, model_config, examples, policy, device, pad_batch):
    import hashlib
    import json

    import numpy as np
    import pandas as pd
    import torch
    import torch.nn.functional as functional

    stage, checks = "training_examples", []

    def packed(value):
        return (json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n").encode("utf-8")

    def check(name, condition, observed=True):
        nonlocal stage
        stage = name
        if not bool(condition):
            raise ValueError("training_diagnostic_condition_failed")
        checks.append({"check": name, "status": "pass", "observed": str(observed)})

    try:
        check("nonempty_training_examples", isinstance(examples, list) and bool(examples))
        count = min(policy["training"]["batch_size"], len(examples))
        zero_index = next((index for index, row in enumerate(examples) if row["target"] == 0), None)
        unknown_index = next((index for index, row in enumerate(examples) if 1 in row["token_ids"]), None)
        short_index = next((index for index, row in enumerate(examples)
                            if len(row["token_ids"]) < model_config["max_sequence_length"]), None)
        check("training_only_class_zero_and_unknown_support", zero_index is not None
              and short_index is not None
              and (unknown_index is not None or policy["neural_inputs"]["retained_training_unk_positions"] == 0))
        selected = []
        for index in [zero_index, unknown_index, short_index, *range(len(examples))]:
            if index is not None and index not in selected:
                selected.append(index)
            if len(selected) == count:
                break
        rows = [examples[index] for index in selected]
        batch = pad_batch(rows, model_config["max_sequence_length"], model_config["vocab_size"], model_config["num_classes"])
        check("training_diagnostic_row_and_target_alignment", batch["record_ids"] == [row["record_id"] for row in rows]
              and batch["targets"] == [row["target"] for row in rows])
        cpu_before = torch.random.get_rng_state().clone()
        device_indices = [device.index if device.index is not None else torch.cuda.current_device()] if device.type == "cuda" else []
        gpu_before = torch.cuda.get_rng_state(device).clone() if device.type == "cuda" else None
        stage = "isolated_diagnostic_model_and_update"
        with torch.random.fork_rng(devices=device_indices):
            torch.set_rng_state(torch.Generator(device="cpu").manual_seed(policy["seed"]).get_state())
            if device.type == "cuda":
                with torch.cuda.device(device):
                    torch.cuda.manual_seed(policy["seed"])
            model = model_class(**model_config).to(device=device, dtype=torch.float32)
            optimizer = torch.optim.AdamW(model.parameters(), lr=policy["optimizer"]["lr"],
                weight_decay=policy["optimizer"]["weight_decay"], betas=tuple(policy["optimizer"]["betas"]),
                eps=policy["optimizer"]["eps"], amsgrad=policy["optimizer"]["amsgrad"])
            criterion = torch.nn.CrossEntropyLoss(weight=None, ignore_index=-100, reduction="mean", label_smoothing=0.0)
            effective_optimizer = json.loads(json.dumps({key: value for key, value in optimizer.param_groups[0].items()
                                                         if key != "params"}, allow_nan=False))
            ids = torch.tensor(batch["token_ids"], dtype=torch.long, device=device)
            mask = torch.tensor(batch["mask"], dtype=torch.bool, device=device)
            targets = torch.tensor(batch["targets"], dtype=torch.long, device=device)
            check("tensor_types_ranges_and_device", ids.dtype == targets.dtype == torch.long and mask.dtype == torch.bool
                  and ids.device == mask.device == targets.device == device
                  and targets.shape == (len(rows),) and bool(((targets >= 0) & (targets < model_config["num_classes"])).all()))
            unknown_positions = int(((ids == 1) & mask).sum().item())
            check("class_zero_valid_and_unknown_masked_in", int(targets.eq(0).sum().item()) > 0
                  and (unknown_positions > 0 or policy["neural_inputs"]["retained_training_unk_positions"] == 0)
                  and bool(torch.equal(mask, ids.ne(0))))
            check("pad_and_unknown_embeddings_start_at_zero", bool(torch.count_nonzero(model.embedding.weight[0]) == 0)
                  and bool(torch.count_nonzero(model.embedding.weight[1]) == 0))
            before = {name: value.detach().clone() for name, value in model.named_parameters()}
            model.train()
            with torch.enable_grad():
                optimizer.zero_grad(set_to_none=True)
                logits = model(ids, mask)
                check("finite_raw_logits_with_frozen_output_width", logits.shape == (len(rows), model_config["num_classes"])
                      and logits.dtype == torch.float32 and bool(torch.isfinite(logits).all()))
                loss = criterion(logits, targets)
                hand_loss = -functional.log_softmax(logits, dim=1).gather(1, targets.unsqueeze(1)).mean()
                check("loss_includes_target_class_zero_without_softmax_input", criterion.ignore_index == -100
                      and bool(torch.isfinite(loss)) and bool(torch.allclose(loss, hand_loss, rtol=1e-6, atol=1e-7)))
                loss.backward()
                check("all_parameter_gradients_are_finite", all(value.grad is not None and bool(torch.isfinite(value.grad).all())
                      for value in model.parameters()))
                check("padding_gradient_is_zero", bool(torch.count_nonzero(model.embedding.weight.grad[0]) == 0))
                check("embedding_hidden_and_output_receive_gradients", bool(torch.count_nonzero(model.embedding.weight.grad[2:]) > 0)
                      and bool(torch.count_nonzero(model.hidden.weight.grad) > 0)
                      and bool(torch.count_nonzero(model.output.weight.grad) > 0))
                unknown_gradient = float(model.embedding.weight.grad[1].norm().item())
                check("observed_unknown_positions_receive_gradient", unknown_gradient > 0 if unknown_positions else unknown_gradient == 0)
                optimizer.step()
            check("all_updated_parameters_finite", all(bool(torch.isfinite(value).all()) for value in model.parameters()))
            changes = {name: float((value.detach() - before[name]).norm().item()) for name, value in model.named_parameters()}
            check("embedding_hidden_and_output_parameters_updated", changes["embedding.weight"] > 0
                  and changes["hidden.weight"] > 0 and changes["output.weight"] > 0)
            check("pad_embedding_stays_zero_after_adamw", bool(torch.count_nonzero(model.embedding.weight[0]) == 0))
            unknown_after = float(model.embedding.weight[1].detach().norm().item())
            check("unknown_embedding_can_learn_when_present", unknown_after > 0 if unknown_positions else unknown_after == 0)
            model.eval()
            short = next((row for row in rows if len(row["token_ids"]) < model_config["max_sequence_length"]), None)
            check("training_padding_invariance_fixture_available", short is not None)
            extra = min(3, model_config["max_sequence_length"] - len(short["token_ids"]))
            short_ids = torch.tensor([short["token_ids"]], dtype=torch.long, device=device)
            extended_ids = torch.tensor([short["token_ids"] + [0] * extra], dtype=torch.long, device=device)
            with torch.no_grad():
                short_output = model(short_ids, short_ids.ne(0))
                extended_output = model(extended_ids, extended_ids.ne(0))
            max_padding_difference = float((short_output - extended_output).abs().max().item())
            check("evaluation_predictions_invariant_to_extra_valid_padding", bool(torch.allclose(short_output, extended_output,
                  rtol=1e-5, atol=1e-6)) and bool(torch.equal(short_output.argmax(dim=1), extended_output.argmax(dim=1))))
            parameter_count = sum(value.numel() for value in model.parameters())
            check("parameter_count_matches_saved_dimensions", parameter_count == model_config["vocab_size"] * model_config["embedding_dim"]
                  + model_config["embedding_dim"] * model_config["hidden_dim"] + model_config["hidden_dim"]
                  + model_config["hidden_dim"] * model_config["num_classes"] + model_config["num_classes"])
            observed_loss = float(loss.detach().item())
        check("diagnostic_cpu_rng_restored", bool(torch.equal(cpu_before, torch.random.get_rng_state())))
        if device.type == "cuda":
            check("diagnostic_selected_cuda_rng_restored", bool(torch.equal(gpu_before, torch.cuda.get_rng_state(device))))
        identity = {"recipe_version": "training-only-neural-update-check-0.1.0", "model_config": model_config,
            "selected_training_indices": selected, "training_records": len(rows), "unknown_positions": unknown_positions,
            "diagnostic_loss": observed_loss, "unknown_gradient_norm": unknown_gradient,
            "unknown_embedding_norm_after_update": unknown_after, "parameter_change_norms": changes,
            "maximum_padding_difference": max_padding_difference, "parameter_count": parameter_count,
            "effective_optimizer": effective_optimizer, "device": str(device), "checks": checks}
        return {"status": "training_only_neural_update_verified", **identity,
            "checks": pd.DataFrame(checks), "check_records": checks,
            "diagnostic_digest": hashlib.sha256(packed(identity)).hexdigest(),
            "diagnostic_models_created": 1, "diagnostic_optimizer_steps": 1,
            "validation_examples_used": 0, "recorded_n0_training_runs": 0, "rng_restored": True,
            "diagnostic_model_discarded": True, "files_changed": False, "test_text_processed": False}
    except Exception:
        raise RuntimeError("step20_training_only_diagnostic_failed:" + stage) from None


"""Prepare the neural implementation without starting the recorded N0 run."""


