"""Validate completed runs and avoid extra training on an identical cell rerun."""


def verify_step20_completed_training(receipt, inputs, runtime, preparation, implementation):
    import hashlib
    import json
    import math
    import numpy as np
    import pandas as pd
    import torch

    stage, checks = "completed_training_receipt", []

    def packed(value):
        return (json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n").encode("utf-8")

    def check(name, condition, observed=True):
        nonlocal stage
        stage = name
        if not bool(condition):
            raise ValueError("completed_neural_run_condition_failed")
        checks.append({"check": name, "status": "pass", "observed": str(observed)})

    try:
        check("completed_training_receipt", isinstance(receipt, dict)
              and receipt["status"] == "initial_neural_candidate_trained_and_restored")
        check("same_data_policy_and_implementation", receipt["input_hashes"] == inputs["input_hashes"]
              and receipt["policy_digest"] == runtime["policy_digest"]
              and receipt["preparation_digest"] == preparation["preparation_digest"]
              and receipt["implementation_digest"] == implementation["implementation_digest"]
              and receipt["sequence_digest"] == implementation["sequence_digest"]
              and receipt["model_config"] == implementation["model_config"]
              and receipt["class_order"] == inputs["class_order"] and receipt["class_to_index"] == inputs["class_to_index"]
              and receipt["module_source"] == implementation["module_source"]
              and receipt["module_sha256"] == implementation["module_sha256"]
              and receipt["cell_recipe_sha256"] == STEP20_N0_CELL_RECIPE_SHA256)
        identity = step20_training_receipt_identity(receipt)
        check("completed_run_identity_and_state_hashes", identity == receipt["receipt_identity"]
              and hashlib.sha256(packed(identity)).hexdigest() == receipt["training_digest"]
              and identity["live_model_state_sha256"] == identity["copied_best_state_sha256"] == receipt["best_state_digest"]
              == receipt["selected_state_sha256"] and receipt["initial_state_digest"] == receipt["initial_state_sha256"]
              and step20_state_digest(receipt["selected_state_dict"]) == step20_state_digest(receipt["model_state"])
              == receipt["best_state_digest"])
        check("complete_check_and_history_tables", receipt["checks"].to_dict("records") == receipt["check_records"]
              and receipt["checks"]["status"].eq("pass").all()
              and receipt["history"].to_dict("records") == receipt["history_records"]
              and receipt["epoch_order_log"].to_dict("records") == receipt["epoch_order_records"])
        history, patience = receipt["history_records"], runtime["policy"]["checkpoint"]["patience"]
        check("complete_epochs_and_optimizer_steps", len(history) == receipt["epochs_completed"]
              and 1 <= len(history) <= runtime["policy"]["training"]["maximum_epochs"]
              and [row["epoch"] for row in history] == list(range(1, len(history) + 1))
              and receipt["timing_and_counts"]["optimizer_steps"] == 63 * len(history)
              and all(row["train_records"] == len(inputs["train"]) and row["validation_records"] == len(inputs["validation"])
                      and math.isfinite(row["train_loss"]) and math.isfinite(row["validation_loss"]) for row in history))
        score, stale, best_epoch = -1.0, 0, None
        for index, row in enumerate(history):
            control = update_neural_checkpoint_control(score, stale, row["validation_macro_f1"], patience)
            if control["improved"]:
                best_epoch = row["epoch"]
            score, stale = control["best_score"], control["stale_epochs"]
            if (row["checkpoint_improved"] != control["improved"] or row["best_epoch_so_far"] != best_epoch
                    or row["epochs_without_improvement"] != stale or row["best_macro_f1_so_far"] != score
                    or (control["should_stop"] and index < len(history) - 1)):
                raise ValueError("checkpoint_history_changed")
        check("strict_checkpoint_history_and_stop_reason", best_epoch == receipt["best_epoch"]
              and score == receipt["best_macro_f1"]
              and receipt["stop_reason"] == ("patience_exhausted" if stale >= patience else "maximum_epochs_reached")
              and (stale >= patience or len(history) == runtime["policy"]["training"]["maximum_epochs"]))
        predictions = receipt["validation_predictions"]
        metadata = ["catalog_id", "split_group_id", "split", "target_label", "class_index", "text_availability"]
        check("same_full_validation_population", len(predictions) == len(inputs["validation"])
              and predictions[metadata].equals(inputs["validation"][metadata])
              and predictions["model_id"].eq(receipt["model_id"]).all()
              and predictions["configuration_id"].eq(receipt["configuration_id"]).all()
              and predictions["run_id"].eq(receipt["run_id"]).all())
        columns = ["prob_class_" + str(index) for index in range(len(inputs["class_order"]))]
        probabilities, logits = receipt["validation_probabilities"], receipt["validation_logits"]
        indices = predictions["predicted_class_index"].to_numpy(dtype=np.int64)
        check("frozen_probability_order_and_cached_argmax", receipt["probability_columns"] == columns
              and [name for name in predictions if name.startswith("prob_class_")] == columns
              and np.array_equal(predictions[columns].to_numpy(dtype=np.float64), probabilities)
              and np.array_equal(logits.argmax(axis=1), indices) and np.array_equal(probabilities.argmax(axis=1), indices)
              and predictions["predicted_label"].tolist() == [inputs["class_order"][index] for index in indices]
              and np.isfinite(logits).all() and np.isfinite(probabilities).all()
              and np.allclose(probabilities.sum(axis=1), 1.0, rtol=1e-12, atol=1e-12))
        namespace = {"__name__": "_step20_completed_run_metric_verification"}
        exec(compile(inputs["classifier_component"]["source"], "<step20-bound-classifier-metrics>", "exec"), namespace)
        metrics = namespace["summarize_classifier_predictions"](inputs["validation"]["target_label"].tolist(),
            predictions["predicted_label"].tolist(), inputs["validation"]["split_group_id"].tolist(), inputs["class_order"])
        check("cached_predictions_reproduce_frozen_metrics", metrics == receipt["validation_metrics"] == receipt["validation_result"]
              and metrics["macro_f1"] == receipt["best_macro_f1"]
              and pd.DataFrame(metrics["per_class"]).equals(receipt["validation_class_report"]))
        check("selected_model_is_finite_and_in_evaluation_mode", not receipt["model"].training
              and all(value.device == runtime["device"] and value.dtype == torch.float32
                      and bool(torch.isfinite(value).all()) for value in receipt["model"].parameters())
              and bool(torch.count_nonzero(receipt["model"].embedding.weight[0]) == 0))
        check("single_recorded_run_and_held_out_boundary", receipt["neural_training_runs"]
              == receipt["benchmark_models_created"] == receipt["benchmark_optimizers_created"] == 1
              and receipt["training_seeds_reset"] is receipt["fresh_model_created"] is True
              and receipt["test_text_processed"] is receipt["files_changed"] is False
              and receipt["vocabulary_refitted"] is receipt["sequence_limit_refitted"] is False
              and receipt["baseline_refits"] == 0)
        return {"status": "completed_neural_training_reverified", "checks": pd.DataFrame(checks), "check_records": checks}
    except Exception:
        raise RuntimeError("step20_completed_training_verification_failed:" + stage) from None


def execute_step20_training(namespace):
    from datetime import datetime, timezone

    required = ("step20_inputs", "step20_runtime", "step20_preparation", "step20_implementation")
    if any(namespace.get(name) is None for name in required):
        raise RuntimeError("step20_3_requires_successful_steps20_1_and20_2_in_this_kernel")
    inputs, runtime, preparation, implementation = [namespace[name] for name in required]
    context = verify_step20_training_inputs(inputs, runtime, preparation, implementation)
    controls = run_step20_training_control_probes()
    previous = namespace.get("step20_training")
    if previous is not None:
        verification = verify_step20_completed_training(previous, inputs, runtime, preparation, implementation)
        return previous, {"mode": "reused_verified_initial_neural_training", "preflight": context,
            "controls": controls, "completed_run_verification": verification, "additional_training_runs": 0,
            "additional_model_forward_passes": 0}
    attempts = namespace.setdefault("step20_training_attempt_log", [])
    if any(row.get("status") == "completed" for row in attempts):
        raise RuntimeError("step20_3_completed_run_object_missing_preserve_kernel_and_share_message")
    attempt = {"attempt": len(attempts) + 1, "candidate_id": "N0", "seed": runtime["policy"]["seed"],
        "status": "running", "started_at_utc": datetime.now(timezone.utc).isoformat(),
        "implementation_digest": implementation["implementation_digest"], "policy_digest": runtime["policy_digest"]}
    attempts.append(attempt)
    try:
        trusted = dict(implementation)
        trusted["model_class"] = context["model_class"]
        result = train_step20_n0(inputs, runtime, preparation, trusted)
        result["cell_recipe_sha256"] = STEP20_N0_CELL_RECIPE_SHA256
        verify_step20_training_inputs(inputs, runtime, preparation, implementation)
        verification = verify_step20_completed_training(result, inputs, runtime, preparation, implementation)
        attempt.update(status="completed", finished_at_utc=datetime.now(timezone.utc).isoformat(),
                       training_digest=result["training_digest"])
        return result, {"mode": "trained_and_verified_initial_neural_candidate", "preflight": context,
            "controls": controls, "completed_run_verification": verification, "additional_training_runs": 1,
            "additional_model_forward_passes": 63 * result["epochs_completed"] + 14 * (result["epochs_completed"] + 1)}
    except BaseException as error:
        attempt.update(status="interrupted" if isinstance(error, KeyboardInterrupt) else "failed",
                       finished_at_utc=datetime.now(timezone.utc).isoformat(),
                       failure_code=str(error) if str(error).startswith("step20_") else "neural_training_did_not_complete")
        raise


