"""Apply the fixed optimization retry while retaining interrupted fit attempts."""


def fit_step21_tfidf_with_retry(factory, texts, targets, *, clock=None):
    import copy
    import time
    import warnings
    from datetime import datetime, timezone

    import numpy as np
    from sklearn.exceptions import ConvergenceWarning

    timer = time.perf_counter if clock is None else clock
    attempts, models = [], []
    baseline_parameters = None
    for attempt, limit in enumerate((1000, 5000), 1):
        started, elapsed, captured = None, None, []
        parameters, pipeline = None, None
        stage = "fresh_pipeline_construction"
        try:
            pipeline = factory(limit)
            if any(pipeline is earlier for earlier in models):
                raise ValueError("fresh_pipeline_required")
            estimator = pipeline.named_steps["classifier"]
            parameters = copy.deepcopy(estimator.get_params(deep=False))
            if parameters["max_iter"] != limit or parameters["warm_start"] is not False:
                raise ValueError("iteration_or_warm_start_policy")
            comparable = {key: value for key, value in parameters.items() if key != "max_iter"}
            if baseline_parameters is None:
                baseline_parameters = comparable
            elif comparable != baseline_parameters:
                raise ValueError("retry_changed_noniteration_parameters")
            models.append(pipeline)
            stage = "pipeline_fit"
            started = datetime.now(timezone.utc).isoformat()
            begin = timer()
            try:
                with warnings.catch_warnings(record=True) as captured:
                    warnings.simplefilter("always")
                    pipeline.fit(texts, targets)
            finally:
                elapsed = float(timer() - begin)
            recorded = [{"category": item.category.__name__, "message": str(item.message)} for item in captured]
            converged_warning = any(issubclass(item.category, ConvergenceWarning) for item in captured)
            iterations = np.asarray(getattr(estimator, "n_iter_", []), dtype=np.int64).reshape(-1).astype(int).tolist()
            attempts.append({"attempt": attempt, "max_iter": limit, "started_at_utc": started,
                "fit_seconds": elapsed, "parameters": parameters, "fit_status": "completed",
                "warnings": recorded, "warning_count": len(recorded),
                "convergence_warning": converged_warning, "solver_iterations": iterations,
                "iteration_limit_reached": bool(iterations and max(iterations) >= limit),
                "convergence_status": "warning" if converged_warning else "completed_without_convergence_warning",
                "failure_stage": None, "failure_type": None})
            if not converged_warning:
                return {"status": "converged", "pipeline": pipeline, "attempts": attempts,
                    "attempt_models": models, "selected_attempt": attempt}
            if attempt == 2:
                return {"status": "unresolved", "pipeline": None, "attempts": attempts,
                    "attempt_models": models, "selected_attempt": None}
        except KeyboardInterrupt:
            attempts.append({"attempt": attempt, "max_iter": limit, "started_at_utc": started,
                "fit_seconds": elapsed, "parameters": parameters, "fit_status": "interrupted",
                "warnings": [{"category": item.category.__name__, "message": str(item.message)} for item in captured],
                "warning_count": len(captured), "convergence_warning": any(
                    issubclass(item.category, ConvergenceWarning) for item in captured),
                "solver_iterations": [], "iteration_limit_reached": None, "convergence_status": "interrupted",
                "failure_stage": stage, "failure_type": "KeyboardInterrupt"})
            return {"status": "interrupted", "pipeline": None, "attempts": attempts,
                "attempt_models": models, "selected_attempt": None}
        except Exception as error:
            attempts.append({"attempt": attempt, "max_iter": limit, "started_at_utc": started,
                "fit_seconds": elapsed, "parameters": parameters, "fit_status": "failed",
                "warnings": [{"category": item.category.__name__, "message": str(item.message)} for item in captured],
                "warning_count": len(captured), "convergence_warning": any(
                    issubclass(item.category, ConvergenceWarning) for item in captured),
                "solver_iterations": [], "iteration_limit_reached": None, "convergence_status": "failed",
                "failure_stage": stage, "failure_type": type(error).__name__})
            return {"status": "failed", "pipeline": None, "attempts": attempts,
                "attempt_models": models, "selected_attempt": None}


"""Reverify the saved search plan before loading references or fitting candidates."""


def verify_step21_logistic_search_inputs(namespace):
    import hashlib
    import io
    import json
    from pathlib import Path
    import pandas as pd

    stage, checks = "successful_step21_1", []

    def packed(value):
        return (json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n").encode("utf-8")

    def check(name, condition, observed=True):
        nonlocal stage
        stage = name
        if not bool(condition):
            raise ValueError("logistic_search_preflight_condition_failed")
        checks.append({"check": name, "status": "pass", "observed": str(observed)})

    try:
        check("successful_step21_1", namespace.get("step21_preparation_ready") is True
              and all(isinstance(namespace.get(name), dict) for name in
                  ("step21_inputs", "step21_runtime", "step21_plan_receipt", "step21_preparation")))
        existing = namespace["step21_preparation"]
        root = Path(namespace["step21_inputs"]["root"]).resolve()
        stage = "saved_classifier_inputs_and_current_runtime"
        inputs = load_step21_inputs({"project_root": root})
        runtime = prepare_step21_runtime(inputs)
        plan = build_step21_search_plan(inputs, runtime)
        check("same_frozen_inputs_and_plan", inputs["input_hashes"] == namespace["step21_inputs"]["input_hashes"]
              and runtime["policy_digest"] == namespace["step21_runtime"]["policy_digest"]
              and plan["plan_id"] == namespace["step21_plan_receipt"]["plan_id"] == existing["plan_id"]
              and plan["plan_digest"] == namespace["step21_plan_receipt"]["plan_digest"] == existing["plan_digest"])
        preparation_hashes = {}
        for relative in ("artifacts/tuning/search_plan.json", "results/tuning/search_plan_checks.csv",
                         "results/tuning/step21_preparation_summary.json"):
            target = root / relative
            if target != target.resolve() or target.is_symlink():
                raise ValueError("invalid_search_preparation_path")
            preparation_hashes[relative] = hashlib.sha256(target.read_bytes()).hexdigest()
        summary_path = "results/tuning/step21_preparation_summary.json"
        summary = json.loads((root / summary_path).read_bytes())
        check("saved_plan_matches_frozen_search", (root / "artifacts/tuning/search_plan.json").read_bytes()
              == packed(plan["plan"]) and summary["status"] == "search_plan_saved_and_verified_no_new_fits"
              and summary["plan_id"] == plan["plan_id"] and summary["plan_digest"] == plan["plan_digest"]
              and summary["input_hashes"] == inputs["input_hashes"] and summary == existing["summary"])
        check("preparation_producer_hash_and_artifacts", summary["preparation_id"] == "classifier-search-preparation:"
              + hashlib.sha256(packed(summary["producer_identity"])).hexdigest()
              and summary["producer_identity"]["plan_id"] == plan["plan_id"]
              and summary["producer_identity"]["input_hashes"] == inputs["input_hashes"]
              and all(preparation_hashes[relative] == spec["sha256"]
                      == summary["producer_identity"]["artifact_hashes"][relative]
                      for relative, spec in summary["artifacts"].items()))
        ledger = pd.read_csv(io.BytesIO((root / "results/tuning/search_plan_checks.csv").read_bytes()),
                             dtype=str, keep_default_na=False)
        check("saved_plan_checks_are_complete_and_passing", len(ledger) == summary["checks"]["saved_cumulative_records"]
              and ledger["status"].eq("pass").all()
              and {key: int(value) for key, value in ledger.groupby("scope").size().items()}
              == summary["checks"]["scope_counts"])

        def verify_unchanged():
            verify_step21_preparation_unchanged(inputs, runtime, plan)
            for relative, expected in preparation_hashes.items():
                if hashlib.sha256((root / relative).read_bytes()).hexdigest() != expected:
                    raise RuntimeError("step21_logistic_preflight_failed:saved_search_plan_changed")
            for key, relative in (("baseline_config", "artifacts/baselines/baseline_config.json"),
                                  ("neural_config", "artifacts/neural/initial_run_config.json"),
                                  ("preprocessing_config", "artifacts/preprocessing/preprocessing_config.json"),
                                  ("vocabulary", "artifacts/preprocessing/neural_vocabulary.json")):
                if inputs[key] != json.loads((root / relative).read_bytes()):
                    raise RuntimeError("step21_logistic_preflight_failed:in_memory_settings_changed")
            return True

        verify_unchanged()
        check("all_search_dependencies_verified", len(inputs["input_hashes"]) + len(preparation_hashes) == 95, 95)
        return {"status": "logistic_search_inputs_and_saved_plan_reverified", "root": root, "inputs": inputs,
            "runtime": runtime, "plan_receipt": plan, "preparation": existing, "preparation_hashes": preparation_hashes,
            "input_hashes": {**inputs["input_hashes"], **preparation_hashes},
            "checks": pd.DataFrame(checks), "check_records": checks, "verify_unchanged": verify_unchanged}
    except Exception as error:
        message = str(error)
        if message.startswith(("step21_", "step20_")):
            raise RuntimeError(message) from None
        raise RuntimeError("step21_logistic_preflight_failed:" + stage) from None


