# Step 23-1 — Retrieval inputs, saved source-preparation audit and eligibility boundaries
# This cell preserves prior inputs and writes three versioned metadata-audit files.
# It does not admit records, construct passages, fit retrieval features or load models.
_STEP23_INPUT_IMPLEMENTATION_SHA256 = '03c3b69bdc45e09ebaf4d25b3b2bf3cf0ba16d650c69f439029557b2b525d06d'

_STEP22_HANDOFF_REFERENCE_PATHS = {
    "development_catalog": "data/processed/exercise_catalog_tagged.csv",
    "suggestions": "data/processed/exercise_tag_predictions.csv",
    "review_worklist": "results/exercise_tag_review.csv",
    "population_accounting": "results/exercise_tagging_population.csv",
    "tagging_checks": "results/exercise_tagging_checks.csv",
    "catalog_producer": "results/step22_catalog_tagging_summary.json",
    "bundle_producer": "results/step22_classifier_bundle_summary.json",
    "model_card": "docs/classifier_model_card.md",
    "model_reload_checks": "results/model_reload_checks.csv",
    "selection_record": "artifacts/model_selection.json",
}

def _step22_handoff_packed(value):
    import json
    return (json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n").encode("utf-8")

def _step22_handoff_digest(value):
    import hashlib
    return hashlib.sha256(_step22_handoff_packed(value)).hexdigest()

def _step22_handoff_identity_keys():
    return ("recipe_version", "status", "release_id", "catalog_version", "selection_id",
        "bundle_producer_id", "catalog_producer_id", "artifact_references", "research_artifacts",
        "tagging_model", "class_order", "development_population", "protected_population",
        "new_records", "label_policy", "approval_gate", "information_use", "version_controls",
        "model_bundle_verified", "development_tagging_exports_complete", "handoff_prepared",
        "human_tag_review_complete", "retrieval_approval_ready", "reviewed_catalog_readiness",
        "planner_eligibility_granted", "retrieval_index_built", "test_text_processed")

def validate_step22_catalog_handoff(handoff):
    """Check version bindings and prevent preparation from becoming approval."""
    import re
    from pathlib import PurePosixPath

    def require(condition):
        if not bool(condition):
            raise ValueError("invalid_classifier_catalog_handoff")

    require(isinstance(handoff, dict))
    keys = _step22_handoff_identity_keys()
    require(set(handoff) == set(keys) | {"schema_version", "handoff_id", "identity_sha256"})
    require(handoff["schema_version"] == "step22-step23-classifier-catalog-handoff-1")
    identity = {key: handoff[key] for key in keys}
    digest = _step22_handoff_digest(identity)
    require(handoff["identity_sha256"] == digest
            and handoff["handoff_id"] == "classifier-catalog-handoff:" + digest)
    require(handoff["recipe_version"] == "classifier-catalog-handoff-0.1.0"
            and handoff["status"] == "prepared_with_open_source_and_eligibility_reviews")
    require(isinstance(handoff["release_id"], str)
            and re.fullmatch(r"exercise-classifier-[0-9a-f]{24}", handoff["release_id"]))
    require(isinstance(handoff["catalog_version"], str)
            and re.fullmatch(r"exercise-development-tags-[0-9a-f]{24}", handoff["catalog_version"]))
    for key, prefix in (("selection_id", "classifier-model-selection:"),
                        ("bundle_producer_id", "classifier-bundle-save:"),
                        ("catalog_producer_id", "development-catalog-tagging:")):
        require(isinstance(handoff[key], str) and handoff[key].startswith(prefix)
                and re.fullmatch(r"[0-9a-f]{64}", handoff[key][len(prefix):]))
    expected_paths = dict(_STEP22_HANDOFF_REFERENCE_PATHS)
    expected_paths["bundle_manifest"] = "artifacts/classifiers/" + handoff["release_id"] + "/manifest.json"
    refs = handoff["artifact_references"]
    require(isinstance(refs, dict) and set(refs) == set(expected_paths))
    for role, relative in expected_paths.items():
        spec = refs[role]
        require(isinstance(spec, dict) and set(spec) == {"relative_path", "sha256"}
                and spec["relative_path"] == relative
                and isinstance(spec["sha256"], str) and re.fullmatch(r"[0-9a-f]{64}", spec["sha256"]))
        parsed = PurePosixPath(spec["relative_path"])
        require(not parsed.is_absolute() and parsed.as_posix() == spec["relative_path"]
                and "\\" not in spec["relative_path"] and ":" not in spec["relative_path"]
                and all(part not in (".", "..") for part in parsed.parts))
    research = handoff["research_artifacts"]
    require(isinstance(research, dict) and set(research) == {"majority", "logistic_regression", "neural"})
    for role, spec in research.items():
        require(isinstance(spec, dict) and set(spec) == {"model_id", "candidate_id", "configuration_id", "run_id", "seed", "best_epoch"}
                and all(isinstance(spec[key], str) and spec[key] for key in ("model_id", "configuration_id", "run_id"))
                and spec["seed"] == 42)
    require(research["majority"]["candidate_id"] is None
            and research["logistic_regression"]["candidate_id"] == "L5"
            and research["neural"]["candidate_id"] == "N3"
            and isinstance(research["neural"]["best_epoch"], int) and research["neural"]["best_epoch"] >= 1)
    tag = handoff["tagging_model"]
    require(isinstance(tag, dict) and set(tag) == {"status", "model_family", "candidate_id", "model_id", "configuration_id", "run_id"}
            and tag["status"] == "selected" and tag["model_family"] == "logistic_regression"
            and all(tag[key] == research["logistic_regression"][key] for key in ("candidate_id", "model_id", "configuration_id", "run_id")))
    classes = handoff["class_order"]
    require(isinstance(classes, list) and len(classes) == len(set(classes)) == 16
            and all(isinstance(value, str) and value for value in classes))
    require(handoff["development_population"] == {"catalog_records": 2434, "training_in_sample_previews": 1999,
        "validation_development_previews": 435, "pending_review_entries": 2434, "actual_human_review_decisions": 0,
        "source_verification_pending_records": 2434, "effective_source_labels": 2434,
        "approved_retrieval_record_ids": [], "approved_planner_record_ids": []})
    require(handoff["protected_population"] == {"held_out_groups": 385, "all_group_related_catalog_records": 439,
        "eligible_test_records": 438, "group_related_excluded_records": 1, "other_excluded_review_only_records": 36,
        "protected_predictions": 0, "other_excluded_predictions": 0, "identifier_exported": False,
        "text_transformed": False, "held_out_classifier_evaluation_step": 32})
    require(handoff["new_records"] == {"population_selected": False, "population_count": None,
        "screening_complete": False, "predictions": 0, "action": "defer_until_complete_protected_group_screening",
        "repeated_relation_digests_alone_clear_records": False})
    require(handoff["label_policy"] == {"pending_suggestions_adopted": False,
        "effective_label_origin": "source", "source_verification_status": "original_source_verification_pending",
        "frozen_benchmark_targets_changed": False, "source_labels_changed": False,
        "documented_review_has_precedence": True, "rejected_source_cannot_be_fallback": True,
        "new_model_or_input_does_not_inherit_acceptance": True,
        "body_part_labels_do_not_replace_basketball_skill_categories": True})
    gate = handoff["approval_gate"]
    require(gate == _step22_handoff_approval_gate())
    require(handoff["information_use"] == _step22_handoff_information_use())
    require(handoff["version_controls"] == {"same_identified_model_and_catalog_for_planner_workflows": True,
        "planner_versions_with_retrieval": ["V2", "V3", "V4"], "final_experiment_freeze_step": 31,
        "classifier_final_evaluation_step": 32, "post_test_tagging_requires_separate_catalog_revision": True,
        "post_test_revision_changes_frozen_planner_comparison": False,
        "later_corrections_preserve_original_history_and_affected_versions": True})
    require(all(handoff[key] is True for key in ("model_bundle_verified", "development_tagging_exports_complete", "handoff_prepared")))
    require(all(handoff[key] is False for key in ("human_tag_review_complete", "retrieval_approval_ready",
        "planner_eligibility_granted", "retrieval_index_built", "test_text_processed")))
    require(handoff["reviewed_catalog_readiness"] == "pending")
    return True

