"""Verify the saved classifier/catalog handoff without model inference."""


def verify_step23_classifier_handoff(namespace):
    """Bind Step 23 to completed packaging and its unresolved approval states."""
    import hashlib
    import io
    import json
    import re
    from pathlib import Path, PurePosixPath
    import pandas as pd

    stage, checks = "completed_step22_handoff_receipt", []

    def packed(value):
        return (json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n").encode("utf-8")

    def sha(value):
        return hashlib.sha256(value).hexdigest()

    def check(name, condition, observed=True):
        nonlocal stage
        stage = name
        if not bool(condition):
            raise ValueError("classifier_handoff_preflight_condition_failed")
        checks.append({"check": name, "status": "pass", "observed": str(observed)})

    def json_object(content):
        def unique(items):
            result = {}
            for key, value in items:
                if key in result:
                    raise ValueError("duplicate_classifier_handoff_json_key")
                result[key] = value
            return result
        result = json.loads(content, object_pairs_hook=unique,
            parse_constant=lambda _value: (_ for _ in ()).throw(ValueError("nonfinite_classifier_handoff_json")))
        if not isinstance(result, dict) or content != packed(result):
            raise ValueError("noncanonical_classifier_handoff_json")
        return result

    try:
        check("completed_packaging_and_handoff_receipts_available", isinstance(namespace, dict)
              and namespace.get("step22_packaging_ready") is True
              and namespace.get("step22_handoff_ready") is True
              and isinstance(namespace.get("step22_packaging"), dict)
              and isinstance(namespace.get("step22_handoff"), dict))
        receipt = namespace["step22_packaging"]
        check("saved_packaging_completion_is_scoped_to_preparation", receipt.get("status")
              == "classifier_packaging_and_development_handoff_saved_and_verified"
              and receipt.get("step22_preparation_complete") is True
              and receipt.get("step22_reviewed_catalog_ready") is False
              and receipt.get("models_loaded") == receipt.get("predictions_produced")
              == receipt.get("review_decisions_created") == 0
              and receipt.get("test_text_processed") is False
              and callable(receipt.get("verify_unchanged")))
        receipt["verify_unchanged"]()
        root = Path(receipt["root"]).resolve(strict=True)
        upstream = receipt["preflight"]
        check("handoff_and_upstream_share_the_same_project", root.is_dir()
              and root == Path(upstream["root"]).resolve(strict=True)
              and callable(upstream.get("verify_unchanged")))

        def safe_path(relative):
            if not isinstance(relative, str) or "\\" in relative or ":" in relative:
                raise ValueError("unsafe_classifier_handoff_dependency")
            parsed = PurePosixPath(relative)
            path = root / relative
            if (not parsed.parts or parsed.is_absolute() or parsed.as_posix() != relative
                    or any(part in (".", "..") for part in parsed.parts)
                    or path.resolve() != path or not path.is_relative_to(root)
                    or path.is_symlink() or not path.is_file()):
                raise ValueError("unsafe_classifier_handoff_dependency")
            return path

        producer_path = "results/step22_classifier_packaging_summary.json"
        handoff_path = "results/step22_step23_classifier_catalog_handoff.json"
        checks_path = "results/classifier_packaging_checks.csv"
        producer_bytes = safe_path(producer_path).read_bytes()
        summary = json_object(producer_bytes)
        identity_keys = ("recipe_version", "implementation_sha256", "input_hashes", "release_id",
            "catalog_version", "bundle_producer_id", "catalog_producer_id", "handoff_id", "output_hashes")
        producer_identity = {key: summary[key] for key in identity_keys}
        check("final_packaging_producer_identity_matches_saved_receipt", summary == receipt["summary"]
              and summary["schema_version"] == "step22-classifier-packaging-producer-1"
              and summary["status"] == receipt["status"]
              and summary["recipe_version"] == "classifier-catalog-development-handoff-0.1.0"
              and summary["producer_id"] == "classifier-packaging-handoff:" + sha(packed(producer_identity)))
        check("final_stage_outputs_and_prior_hashes_are_explicit", set(summary["output_hashes"]) == {handoff_path, checks_path}
              and len(summary["input_hashes"]) == summary["prior_bound_files_reverified"] == 294
              and summary["input_hashes"] == upstream["input_hashes"]
              and set(summary["output_hashes"]).isdisjoint(summary["input_hashes"])
              and producer_path not in summary["input_hashes"])
        saved_hashes = {**summary["output_hashes"], producer_path: sha(producer_bytes)}
        check("all_three_final_stage_artifacts_match_the_completed_receipt", saved_hashes
              == receipt["save"]["artifact_hashes"] and set(saved_hashes) == set(receipt["saved_files"]))
        hashes = {**summary["input_hashes"], **saved_hashes}
        check("all_297_classifier_input_and_handoff_files_are_unchanged", len(hashes) == 297
              and all(isinstance(digest, str) and re.fullmatch(r"[0-9a-f]{64}", digest)
                      and sha(safe_path(relative).read_bytes()) == digest for relative, digest in hashes.items()), len(hashes))
        check("all_31_step22_canonical_files_are_bound", len(summary["prior_step22_output_hashes"]) == 28
              and summary["canonical_stage_files"] == 3 and summary["canonical_step22_files"] == 31
              and all(hashes[relative] == digest for relative, digest in summary["prior_step22_output_hashes"].items()))

        handoff = json_object(safe_path(handoff_path).read_bytes())
        validate_step22_catalog_handoff(handoff)
        check("saved_handoff_matches_the_frozen_release_and_catalog", handoff == receipt["handoff"]
              == namespace["step22_handoff"]
              and handoff["handoff_id"] == summary["handoff_id"]
              and handoff["release_id"] == summary["release_id"]
              and handoff["catalog_version"] == summary["catalog_version"])
        references = handoff["artifact_references"]
        check("all_eleven_handoff_references_are_bound_to_actual_saved_bytes", len(references) == 11
              and all(spec["relative_path"] in hashes
                      and spec["sha256"] == hashes[spec["relative_path"]]
                      and sha(safe_path(spec["relative_path"]).read_bytes()) == spec["sha256"]
                      for spec in references.values()))
        manifest = json_object(safe_path(summary["manifest_relative_path"]).read_bytes())
        manifest_identity = manifest["identity"]
        classes = list(upstream["class_order"])
        check("explicit_model_release_and_frozen_class_axis_are_preserved", manifest["release_id"] == summary["release_id"]
              and manifest["identity_sha256"] == sha(packed(manifest_identity))
              and manifest["release_id"] == "exercise-classifier-" + manifest["identity_sha256"][:24]
              and sha(safe_path(summary["manifest_relative_path"]).read_bytes()) == summary["manifest_sha256"]
              and handoff["class_order"] == manifest_identity["class_order"] == classes
              and len(classes) == len(set(classes)) == 16
              and manifest_identity["class_to_index"] == {value: index for index, value in enumerate(classes)})
        release_root = root / str(PurePosixPath(summary["manifest_relative_path"]).parent)
        release_files = set(manifest_identity["payloads"]) | {"manifest.json"}
        release_directories = {parent.as_posix() for relative in release_files
            for parent in PurePosixPath(relative).parents if parent.as_posix() != "."}

        def verify_release_inventory():
            observed_files, observed_directories = set(), set()
            for path in release_root.rglob("*"):
                if path.is_symlink():
                    return False
                if path.is_file():
                    observed_files.add(path.relative_to(release_root).as_posix())
                elif path.is_dir():
                    observed_directories.add(path.relative_to(release_root).as_posix())
                else:
                    return False
            return observed_files == release_files and observed_directories == release_directories

        check("the_explicit_release_preserves_its_complete_seventeen_file_inventory", len(release_files) == 17
              and verify_release_inventory())
        check("tagging_selection_and_original_research_artifacts_remain_identified", summary["tagging_decision"]["status"] == "selected"
              and summary["tagging_decision"]["model_family"] == "logistic_regression"
              and summary["tagging_decision"]["candidate_id"] == "L5"
              and set(summary["research_artifacts"]) == {"majority", "logistic_regression", "neural"}
              and handoff["research_artifacts"]["neural"]["seed"] == 42
              and handoff["tagging_model"]["configuration_id"] == summary["tagging_decision"]["configuration_id"]
              and handoff["tagging_model"]["run_id"] == summary["tagging_decision"]["run_id"])
        check_table = pd.read_csv(io.BytesIO(safe_path(checks_path).read_bytes()), dtype=str, keep_default_na=False)
        check("saved_final_handoff_checks_are_passing_implementation_evidence", len(check_table)
              == summary["saved_handoff_check_records"] == 73
              and check_table.columns.is_unique and check_table["status"].eq("pass").all()
              and summary["artificial_handoff_scenarios"] == summary["artificial_handoff_checks"] == 36)

        readiness = summary["readiness"]
        check("preparation_completion_does_not_adopt_reviews_or_eligibility", summary["step22_preparation_complete"] is True
              and summary["step22_reviewed_catalog_ready"] is summary["step22_all_readiness_requirements_complete"] is False
              and summary["step23_handoff_created"] is summary["step23_handoff_ready_for_eligibility_preparation"] is True
              and readiness["human_tag_review"] == readiness["independent_source_verification"] == "pending"
              and readiness["retrieval_eligibility_review"] == "pending_step23"
              and readiness["retrieval_index_and_benchmark"] == "not_executed_step23"
              and handoff["human_tag_review_complete"] is handoff["retrieval_approval_ready"] is False
              and handoff["planner_eligibility_granted"] is handoff["retrieval_index_built"] is False)
        check("development_population_retains_pending_source_and_tag_review_states", summary["development_records"]
              == summary["catalog_suggestions_previously_produced"] == summary["pending_review_entries"] == 2434
              and summary["actual_human_review_decisions"] == 0
              and summary["source_verification_status_counts"] == {"original_source_verification_pending": 2434}
              and summary["effective_label_origin_counts"] == {"source": 2434}
              and summary["source_catalog_labels_changed"] is summary["frozen_benchmark_targets_changed"] is False)
        check("this_handoff_supplies_no_approval_list_or_global_eligibility_count", handoff["approval_gate"]["assessment_scope"]
              == "this_development_export_only"
              and handoff["development_population"]["approved_retrieval_record_ids"] == []
              and handoff["development_population"]["approved_planner_record_ids"] == []
              and summary["retrieval_eligibility_granted_this_step"] == summary["planner_eligibility_granted_this_step"] == 0
              and summary["global_retrieval_or_planner_eligible_records"] is None)
        boundary = upstream["population_boundary"]
        private = boundary["private_boundary"]
        check("whole_test_groups_and_other_exclusions_stay_protected", len(private["protected_catalog_ids"]) == 439
              and len(private["protected_group_ids"]) == 385 and len(private["other_excluded_catalog_ids"]) == 36
              and handoff["protected_population"]["all_group_related_catalog_records"] == 439
              and handoff["protected_population"]["eligible_test_records"] == 438
              and handoff["protected_population"]["group_related_excluded_records"] == 1
              and handoff["protected_population"]["protected_predictions"] == 0)
        check("unfamiliar_records_and_final_evaluation_remain_unexecuted", summary["new_record_population_selected"]
              is summary["new_record_screening_complete"] is False
              and summary["new_record_population_count"] is None
              and summary["final_classifier_evaluation_complete"] is summary["final_experiment_freeze_complete"] is False
              and summary["test_text_processed"] is handoff["test_text_processed"] is False
              and all(summary[key] == 0 for key in ("models_loaded_this_execution", "predictions_produced_this_execution",
                  "new_model_fits", "new_neural_training_runs", "vocabulary_or_sequence_refits", "review_decisions_created_this_execution")))

        frozen_metadata = {"summary": summary, "handoff": handoff, "manifest": manifest,
                           "classes": classes, "input_hashes": hashes}
        metadata_digest = sha(packed(frozen_metadata))
        protected_digest = sha(packed({key: sorted(value) for key, value in private.items()}))

        def verify_unchanged():
            receipt["verify_unchanged"]()
            if (sha(packed(frozen_metadata)) != metadata_digest
                    or sha(packed({key: sorted(value) for key, value in private.items()})) != protected_digest
                    or any(sha(safe_path(relative).read_bytes()) != digest for relative, digest in hashes.items())
                    or not verify_release_inventory()):
                raise RuntimeError("step23_classifier_preflight_failed:verified_classifier_handoff_changed")
            return True

        check("read_only_classifier_handoff_verification_is_stable", verify_unchanged())
        return {"status": "verified_step22_classifier_catalog_handoff", "root": root,
            "step22_summary": summary, "summary": summary, "handoff": handoff,
            "manifest": manifest, "input_hashes": hashes, "class_order": classes,
            "artifact_references": references, "population_boundary": boundary,
            "boundary": boundary, "private_boundary": private,
            "context": upstream.get("context"), "checks": pd.DataFrame(checks), "check_records": checks,
            "verify_unchanged": verify_unchanged, "models_loaded": 0, "model_predictions": 0,
            "new_model_fits": 0, "test_text_processed": False, "files_changed": False,
            "retrieval_or_planner_eligibility_granted": False, "review_decisions_created": 0}
    except Exception as error:
        message = str(error)
        if message.startswith(("step23_", "step22_", "step21_", "step20_", "step19_")):
            raise RuntimeError(message) from None
        raise RuntimeError("step23_classifier_preflight_failed:" + stage) from None


"""Audit explicit saved reference-preparation bundles without admitting a corpus."""


def prepare_step23_source_inventory(project_root, prior_input_hashes):
    """Bind source-preparation metadata and distinguish it from record approval.

    Only explicitly named producer/handoff JSON is decoded. Referenced payloads
    are byte-hashed, including review-only tables, rather than read as passages.
    The declared upstream manifests are not claimed to be a verified full closure.
    """
    import copy
    import hashlib
    import json
    import re
    from pathlib import Path, PurePosixPath
    import pandas as pd

    root = Path(project_root).resolve(strict=True)
    stage, checks, bindings, snapshots = "source_inventory_arguments", [], {}, {}

    def packed(value):
        return (json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n").encode("utf-8")

    def digest(value):
        return hashlib.sha256(value).hexdigest()

    def check(name, condition, observed=True):
        nonlocal stage
        stage = name
        if not bool(condition):
            raise ValueError("reference_preparation_inventory_condition_failed")
        checks.append({"check": name, "status": "pass", "observed": str(observed)})

    def safe_path(relative):
        if not isinstance(relative, str) or not relative or "\\" in relative or ":" in relative:
            raise ValueError("invalid_reference_metadata_path")
        parts = PurePosixPath(relative)
        target = root / relative
        if (parts.is_absolute() or parts.as_posix() != relative or any(part in (".", "..") for part in parts.parts)
                or target.resolve() != target or not target.is_relative_to(root) or target.is_symlink()
                or not target.is_file()):
            raise ValueError("unsafe_reference_metadata_path")
        return target

    def read_bound(relative, expected=None, size=None):
        content = safe_path(relative).read_bytes()
        actual = digest(content)
        if (expected is not None and actual != expected) or (size is not None and len(content) != size):
            raise ValueError("reference_metadata_hash_or_size_mismatch")
        if relative in bindings and bindings[relative] != actual:
            raise ValueError("reference_metadata_changed_during_audit")
        if relative in prior_input_hashes and prior_input_hashes[relative] != actual:
            raise ValueError("reference_metadata_conflicts_with_frozen_classifier_input")
        bindings[relative] = actual
        return content

    def object_json(content):
        def pairs(items):
            result = {}
            for key, value in items:
                if key in result:
                    raise ValueError("duplicate_reference_metadata_key")
                result[key] = value
            return result
        result = json.loads(content, object_pairs_hook=pairs,
            parse_constant=lambda _value: (_ for _ in ()).throw(ValueError("nonfinite_reference_metadata")))
        if not isinstance(result, dict) or content != packed(result):
            raise ValueError("invalid_reference_metadata_document")
        return result

    patterns = {
        "basketball_drills": "results/basketball_catalog_review/source_linked_schema_*/step12_source_linked_schema_summary.json",
        "participation_guidance": "results/planning_rule_review/decision_tests_*/step13_decision_test_summary.json",
        "food_lookup": "results/usda_preparation/source_validation_*/step14_source_validation_summary.json"}
    selected_patterns = {}
    sibling_specs = {
        "basketball_drills": ("step12-source-linked-schema-producer-1", "source_linked_schema_", "step12_step13_source_linked_handoff.json", "step12-linked-schema-step13-handoff-1"),
        "participation_guidance": ("step13-decision-test-producer-1", "decision_tests_", "step13_preparation_handoff.json", "step13-preparation-handoff-1"),
        "food_lookup": ("step14-source-validation-producer-1", "source_validation_", "step14_validation_review_handoff.json", "step14-validation-review-handoff-1")}

    def discover(pattern):
        # This bounded filename discovery does not enumerate or index project content.
        return tuple(sorted(path.relative_to(root).as_posix() for path in root.glob(pattern)))

    def verify_producer(relative, schema, prefix, expected=None):
        content = read_bound(relative, expected)
        value = object_json(content)
        if (value.get("schema_version") != schema or Path(relative).parent.name != prefix + digest(content)[:16]
                or not isinstance(value.get("input_hashes"), dict)
                or not isinstance(value.get("artifacts"), dict) or not value["artifacts"]):
            raise ValueError("invalid_content_addressed_reference_producer")
        declared = value["input_hashes"]
        if any(not isinstance(key, str) or not isinstance(item, str) or not re.fullmatch(r"[0-9a-f]{64}", item)
               for key, item in declared.items()):
            raise ValueError("invalid_declared_reference_dependency")
        for key in set(declared).intersection(prior_input_hashes):
            if declared[key] != prior_input_hashes[key]:
                raise ValueError("upstream_preparation_and_frozen_input_hashes_disagree")
        parent = PurePosixPath(relative).parent
        # Artifact names are relative to this named preparation bundle only.
        for name, spec in value["artifacts"].items():
            parsed = PurePosixPath(name)
            if (not isinstance(name, str) or "\\" in name or ":" in name or parsed.is_absolute()
                    or parsed.as_posix() != name or any(part in (".", "..") for part in parsed.parts)
                    or not isinstance(spec, dict) or not re.fullmatch(r"[0-9a-f]{64}", str(spec.get("sha256", "")))
                    or type(spec.get("bytes")) is not int or spec["bytes"] < 0):
                raise ValueError("invalid_reference_bundle_payload")
            read_bound((parent / parsed).as_posix(), spec["sha256"], spec["bytes"])
        if any(row.get("status") != "pass" for row in value.get("verified_checks", [])):
            raise ValueError("nonpassing_saved_reference_preparation_check")
        snapshots[relative] = value
        return value

    def explicit_upstream(owner, relative, schema, prefix, artifacts=True):
        if relative not in owner["input_hashes"]:
            raise ValueError("unbound_explicit_upstream_reference_metadata")
        if artifacts:
            return verify_producer(relative, schema, prefix, owner["input_hashes"][relative])
        content = read_bound(relative, owner["input_hashes"][relative])
        value = object_json(content)
        if value.get("schema_version") != schema or Path(relative).parent.name != prefix + digest(content)[:16]:
            raise ValueError("invalid_upstream_reference_metadata_identity")
        snapshots[relative] = value
        return value

    try:
        check("reference_inventory_uses_explicit_project_and_prior_bindings", root.is_dir()
              and isinstance(prior_input_hashes, dict)
              and all(isinstance(key, str) and re.fullmatch(r"[0-9a-f]{64}", str(value))
                      for key, value in prior_input_hashes.items()))
        resources, blockers, receipts = [], [], {}
        for family, pattern in patterns.items():
            stage = "unique_saved_preparation_producer:" + family
            choices = discover(pattern)
            selected_patterns[family] = choices
            if len(choices) > 1:
                raise ValueError("ambiguous_reference_preparation_versions")
            if not choices:
                resources.append({"resource_family": family, "preparation_status": "unavailable_missing_saved_preparation",
                    "reported_prepared_records": None, "record_unit": "unavailable",
                    "documented_retrieval_approved_records": None, "retrieval_admission_status": "not_assessed_no_inclusion_list",
                    "planner_eligible_in_preparation_snapshot": None, "adopted_rules_in_preparation_snapshot": None,
                    "producer_path": "", "handoff_path": ""})
                blockers.append({"resource_family": family, "requirement": "saved_preparation_metadata",
                    "status": "unavailable", "detail": "Locate one explicitly versioned preparation bundle; no version was selected."})
                check("missing_preparation_is_reported_unavailable:" + family, True)
                continue
            relative = choices[0]
            schema, prefix, handoff_name, handoff_schema = sibling_specs[family]
            producer = verify_producer(relative, schema, prefix)
            handoff_relative = (PurePosixPath(relative).parent / handoff_name).as_posix()
            if handoff_name not in producer["artifacts"]:
                raise ValueError("handoff_not_bound_by_reference_producer")
            handoff = object_json(read_bound(handoff_relative, producer["artifacts"][handoff_name]["sha256"]))
            if handoff.get("schema_version") != handoff_schema:
                raise ValueError("unsupported_reference_preparation_handoff")
            snapshots[handoff_relative] = handoff
            check("producer_handoff_and_saved_payloads_verified:" + family, True,
                  str(len(producer["artifacts"])) + " byte-hashed payloads; no passage text parsed")
            metrics = producer["metrics"]
            if family == "basketball_drills":
                check("drill_preparation_counts_match_the_handoff", metrics == handoff["metrics"]
                      and metrics["catalog_candidates"] == handoff["basketball_candidates"] + handoff["general_warmups"]
                      and handoff["approved_distinct_drills"] == metrics["approvals_created"] == 0
                      and handoff["planner_eligible"] == metrics["planner_eligible"] == 0
                      and handoff["full_step12_approval_objective_complete"] is False)
                assessment = handoff["assessment_producer"]
                stage = "drill_assessment_producer_binding"
                explicit_upstream(producer, assessment, "step12-schema-assessment-1", "schema_assessment_", artifacts=False)
                reported, unit, planner, adopted = metrics["catalog_candidates"], "drill_or_warmup_candidates", 0, None
                receipts[family] = {"producer": producer, "handoff": handoff,
                    "reported_candidate_groups": reported, "reported_source_occurrences": metrics["source_occurrences"],
                    "reported_basketball_candidates": handoff["basketball_candidates"],
                    "reported_general_warmups": handoff["general_warmups"],
                    "reported_source_locators": metrics["recorded_source_locators"],
                    "snapshot_catalog_approved_drills": handoff["approved_distinct_drills"],
                    "snapshot_planner_eligible": handoff["planner_eligible"]}
            elif family == "participation_guidance":
                check("guidance_preparation_counts_and_adoption_states_match", metrics == handoff["metrics"]
                      and metrics["decision_candidates"] == sum(metrics["origin_counts"].values())
                      and metrics["published_candidates"] == metrics["origin_counts"]["published_guidance"]
                      and metrics["rules_adopted"] == metrics["rules_enabled"] == metrics["independently_reviewed_specifications"] == 0
                      and handoff["full_step13_adoption_complete"] is handoff["source_coverage_complete"] is False)
                interpretation_path = handoff["interpretation_producer"]
                stage = "guidance_interpretation_and_inventory_bindings"
                interpretation = explicit_upstream(producer, interpretation_path,
                    "step13-interpretation-producer-1", "interpretation_")
                explicit_upstream(interpretation, interpretation["inventory_producer"],
                    "step13-rule-inventory-producer-1", "inventory_")
                reported, unit, planner, adopted = metrics["published_candidates"], "published_guidance_candidates", None, 0
                receipts[family] = {"producer": producer, "handoff": handoff,
                    "reported_published_guidance_candidates": reported,
                    "reported_total_decision_candidates": metrics["decision_candidates"],
                    "reported_project_policy_templates": metrics["origin_counts"]["project_policy"],
                    "reported_user_constraint_templates": metrics["origin_counts"]["user_constraint"],
                    "reported_draft_test_specifications": metrics["distinct_test_specifications"],
                    "snapshot_rules_adopted": 0, "snapshot_rules_enabled": 0,
                    "source_coverage_complete": handoff["source_coverage_complete"],
                    "AAP_full_report_direct_access_complete": handoff["AAP_full_report_direct_access_complete"]}
            else:
                check("food_lookup_remains_a_separate_unfinished_structured_tool", metrics == handoff["metrics"]
                      and handoff["lookup_ready"] is producer["lookup_ready"] is False
                      and handoff["prototype_selection"] == "pending"
                      and metrics["prototype_selected_foods"] == 0
                      and handoff["lookup_calculation_tests"] == "not_executed")
                acquisition_path = handoff["source_acquisition_producer"]
                # Bind the acquisition receipt without reading raw food tables.
                stage = "food_acquisition_metadata_binding"
                acquisition = object_json(read_bound(acquisition_path, producer["input_hashes"][acquisition_path]))
                if acquisition.get("schema_version") != "step14-source-acquisition-producer-1":
                    raise ValueError("unsupported_food_acquisition_metadata")
                snapshots[acquisition_path] = acquisition
                reported, unit, planner, adopted = metrics["source_food_records"], "source_food_records_for_structured_lookup", None, None
                receipts[family] = {"producer": producer, "handoff": handoff,
                    "reported_source_food_records": reported, "reported_selected_prototype_foods": 0,
                    "lookup_ready": False, "lookup_calculation_tests": "not_executed",
                    "retrieval_role": "structured_lookup_not_passage_corpus"}
            resources.append({"resource_family": family, "preparation_status": producer["status"],
                "reported_prepared_records": reported, "record_unit": unit,
                "documented_retrieval_approved_records": None,
                "retrieval_admission_status": "structured_tool_not_passage_corpus" if family == "food_lookup" else "pending_explicit_source_and_reference_use_review",
                "planner_eligible_in_preparation_snapshot": planner,
                "adopted_rules_in_preparation_snapshot": adopted,
                "producer_path": relative, "handoff_path": handoff_relative})
            for requirement in (("structured_lookup_selection_and_calculation_validation",) if family == "food_lookup"
                    else ("source_verification", "permitted_use_review", "reference_use_review_and_explicit_inclusion_list")):
                blockers.append({"resource_family": family, "requirement": requirement, "status": "pending_not_completed_by_this_audit",
                    "detail": "Preparation metadata is not an adoption or retrieval-approval decision."})
        check("preparation_does_not_establish_retrieval_admission", all(row["documented_retrieval_approved_records"] is None for row in resources))
        resources_frame = pd.DataFrame(resources)
        blocker_frame = pd.DataFrame(blockers)
        frozen_metadata = {"receipts": receipts, "resources": resources, "blockers": blockers,
                           "bindings": bindings, "selected_patterns": selected_patterns}
        identity = digest(packed(frozen_metadata))
        expected = copy.deepcopy(bindings)
        prior_manifest_digest = digest(packed(prior_input_hashes))
        table_digests = [digest(frame.to_csv(index=False, lineterminator="\n").encode("utf-8"))
                         for frame in (resources_frame, blocker_frame)]

        def verify_unchanged():
            if (digest(packed(frozen_metadata)) != identity
                    or digest(packed(prior_input_hashes)) != prior_manifest_digest
                    or any(digest(safe_path(relative).read_bytes()) != value for relative, value in expected.items())
                    or any(discover(patterns[family]) != choices for family, choices in selected_patterns.items())
                    or table_digests != [digest(frame.to_csv(index=False, lineterminator="\n").encode("utf-8"))
                                         for frame in (resources_frame, blocker_frame)]):
                raise RuntimeError("step23_source_inventory_failed:verified_source_preparation_metadata_changed")
            return True

        check("saved_source_metadata_audit_is_stable", verify_unchanged())
        return {"status": "saved_reference_preparation_metadata_verified_no_corpus_admitted",
            "root": root, "resource_inventory": resources_frame, "resources": resources,
            "blockers": blocker_frame, "blocker_records": blockers, "source_receipts": receipts,
            "input_hashes": bindings, "verified_metadata_files": len(bindings),
            "source_metadata_digest": identity, "checks": pd.DataFrame(checks), "check_records": checks,
            "verify_unchanged": verify_unchanged, "full_upstream_dependency_closure_verified": False,
            "record_level_retrieval_admission_assessed": False,
            "global_retrieval_eligible_records": None, "corpus_records_admitted": 0,
            "source_content_decoded_as_passages": False, "source_refresh_performed": False,
            "source_or_review_decisions_created": 0, "retrieval_index_built": False,
            "model_downloads": 0, "embedding_operations": 0, "retrieval_queries_executed": 0,
            "protected_classifier_text_transformed": False, "files_changed": False}
    except Exception as error:
        message = str(error)
        if message.startswith(("step23_", "step22_")):
            raise RuntimeError(message) from None
        raise RuntimeError("step23_source_inventory_failed:" + stage) from None


"""Pure metadata gates for reference preparation, without adopting source records."""


def classify_step23_reference_state(metadata):
    """Classify supplied metadata; do not verify sources, read text or grant approval.

    A verified status here must come from a separate source/decision verifier.
    A caller scope, a prepared bundle or an accepted body-part suggestion is not
    such evidence. Missing metadata remains pending. This helper is deliberately
    independent of any existing project's source-table column names.
    """
    if not isinstance(metadata, dict):
        raise ValueError("invalid_step23_reference_metadata")
    enums = {
        "record_kind": ({"general_exercise", "basketball_drill", "guideline", "structured_rule", "food_fact", "unknown"}, "unknown"),
        "membership_status": ({"eligible_development", "verified_reference_candidate", "reviewed_reference", "protected_group", "excluded", "review_only", "unproven", "evaluation_material"}, "unproven"),
        "source_identity_status": ({"verified", "pending", "unknown", "rejected"}, "pending"),
        "source_version_status": ({"verified", "pending", "unknown", "rejected"}, "pending"),
        "locator_status": ({"verified", "pending", "unknown", "rejected"}, "pending"),
        "source_context_status": ({"preserved", "pending", "unknown", "rejected"}, "pending"),
        "permission_status": ({"permitted", "pending", "unknown", "denied"}, "pending"),
        "reference_review_status": ({"accepted", "pending", "unknown", "rejected"}, "pending"),
        "planner_review_status": ({"accepted", "pending", "unknown", "rejected"}, "pending"),
        "planner_requirements_status": ({"verified", "pending", "unknown", "rejected"}, "pending"),
        "body_part_tag_status": ({"accepted", "pending", "unknown", "rejected", "not_applicable"}, "not_applicable"),
        "executable_rule_adoption_status": ({"adopted", "pending", "unknown", "unadopted", "not_applicable"}, "not_applicable"),
    }
    flags = ("membership_verified", "reference_review_documented", "reference_review_version_matches",
             "planner_review_documented", "planner_review_version_matches", "source_preparation_verified")
    hashes = ("record_version_sha256", "reference_review_record_sha256", "planner_review_record_sha256")
    identifiers = ("reference_review_decision_id", "reference_review_evidence_id", "planner_review_decision_id", "planner_review_evidence_id")
    allowed = set(enums) | set(flags) | set(hashes) | set(identifiers) | {"input_scope"}
    if set(metadata) - allowed:
        raise ValueError("unexpected_step23_reference_metadata_fields")
    values = {}
    for key, (accepted, default) in enums.items():
        value = metadata.get(key, default)
        if not isinstance(value, str) or value not in accepted:
            raise ValueError("invalid_step23_reference_metadata_state:" + key)
        values[key] = value
    for key in flags:
        value = metadata.get(key, False)
        if type(value) is not bool:
            raise ValueError("invalid_step23_reference_metadata_flag:" + key)
        values[key] = value
    if "input_scope" in metadata and not isinstance(metadata["input_scope"], str):
        raise ValueError("invalid_step23_reference_scope")
    import re
    for key in hashes:
        value = metadata.get(key, "")
        if not isinstance(value, str) or (value and not re.fullmatch(r"[0-9a-f]{64}", value)):
            raise ValueError("invalid_step23_reference_version_binding:" + key)
        values[key] = value
    for key in identifiers:
        value = metadata.get(key, "")
        if not isinstance(value, str) or value != value.strip():
            raise ValueError("invalid_step23_reference_review_binding:" + key)
        values[key] = value

    result = {"decision_scope": "metadata_policy_only_no_actual_record_adoption",
        "record_kind": values["record_kind"], "membership_status": values["membership_status"],
        "reference_eligible": False, "planner_eligible": False,
        "source_verification_performed": False, "actual_record_approval_created": False,
        "source_text_read": False, "caller_scope_establishes_membership": False,
        "body_part_tag_acceptance_establishes_eligibility": False,
        "preparation_verification_establishes_eligibility": False,
        "executable_rule_enabled_by_reference_review": False,
        "structured_tool_eligibility_assessed": False,
        "executable_rule_adoption_status": values["executable_rule_adoption_status"],
        "disposition": "pending", "blocking_reasons": [], "pending_requirements": [],
        "planner_pending_requirements": [], "planner_blocking_reasons": []}
    membership = values["membership_status"]
    if membership in ("protected_group", "excluded", "evaluation_material"):
        result.update(disposition="excluded", blocking_reasons=[{
            "protected_group": "protected_group_excluded_before_text_access",
            "excluded": "outside_current_reference_candidate_population",
            "evaluation_material": "private_or_evaluation_material_excluded_from_corpus",
        }[membership]])
        return result
    if membership == "review_only":
        result.update(disposition="deferred", pending_requirements=["separate_review_only_record_inclusion_decision"])
        return result
    if membership == "unproven" or not values["membership_verified"]:
        result.update(disposition="deferred", pending_requirements=["verified_candidate_membership_and_complete_protected_group_exclusion"])
        return result
    if values["record_kind"] in ("structured_rule", "food_fact"):
        result.update(disposition="structured_tool_route", blocking_reasons=["structured_resource_is_not_generic_passage_material"])
        return result
    if values["record_kind"] == "unknown":
        result.update(disposition="deferred", pending_requirements=["supported_record_kind"])
        return result

    gates = (("source_identity_status", "verified", "rejected"),
             ("source_version_status", "verified", "rejected"),
             ("locator_status", "verified", "rejected"),
             ("source_context_status", "preserved", "rejected"),
             ("permission_status", "permitted", "denied"),
             ("reference_review_status", "accepted", "rejected"))
    for key, ready, rejected in gates:
        if values[key] == rejected:
            result["blocking_reasons"].append(key + ":" + rejected)
        elif values[key] != ready:
            result["pending_requirements"].append(key)
    for key in ("reference_review_documented", "reference_review_version_matches"):
        if not values[key]:
            result["pending_requirements"].append(key)
    for key in ("record_version_sha256", "reference_review_record_sha256", "reference_review_decision_id", "reference_review_evidence_id"):
        if not values[key]:
            result["pending_requirements"].append(key)
    if (values["record_version_sha256"] and values["reference_review_record_sha256"]
            and values["record_version_sha256"] != values["reference_review_record_sha256"]):
        result["pending_requirements"].append("reference_review_binding_to_current_record_version")
    if result["blocking_reasons"]:
        result["disposition"] = "rejected"
        return result
    if result["pending_requirements"]:
        result["disposition"] = "pending"
        return result

    result["reference_eligible"] = True
    result["disposition"] = "reference_eligible_by_supplied_verified_metadata"
    if values["record_kind"] == "guideline":
        result["planner_pending_requirements"] = ["guideline_is_reference_material_not_an_activity_selection"]
        return result
    for key, ready in (("planner_review_status", "accepted"), ("planner_requirements_status", "verified")):
        if values[key] == "rejected":
            result["planner_blocking_reasons"].append(key + ":rejected")
        elif values[key] != ready:
            result["planner_pending_requirements"].append(key)
    for key in ("planner_review_documented", "planner_review_version_matches"):
        if not values[key]:
            result["planner_pending_requirements"].append(key)
    for key in ("planner_review_record_sha256", "planner_review_decision_id", "planner_review_evidence_id"):
        if not values[key]:
            result["planner_pending_requirements"].append(key)
    if (values["planner_review_record_sha256"]
            and values["record_version_sha256"] != values["planner_review_record_sha256"]):
        result["planner_pending_requirements"].append("planner_review_binding_to_current_record_version")
    result["planner_eligible"] = not result["planner_blocking_reasons"] and not result["planner_pending_requirements"]
    return result


def run_step23_readiness_probes():
    """Check authored metadata cases; no real source record is read or approved."""
    import copy

    checks = []

    def check(name, condition):
        if not bool(condition):
            raise ValueError("step23_readiness_probe_failed:" + name)
        checks.append({"check": name, "status": "pass", "observed": "authored_metadata_only"})

    def rejected_input(name, metadata):
        try:
            classify_step23_reference_state(metadata)
        except ValueError:
            check(name, True)
        else:
            check(name, False)

    reference = {"record_kind": "general_exercise", "membership_status": "eligible_development",
        "membership_verified": True, "source_identity_status": "verified", "source_version_status": "verified",
        "locator_status": "verified", "source_context_status": "preserved", "permission_status": "permitted",
        "reference_review_status": "accepted", "reference_review_documented": True,
        "reference_review_version_matches": True, "record_version_sha256": "a" * 64,
        "reference_review_record_sha256": "a" * 64,
        "reference_review_decision_id": "authored-reference-decision:1",
        "reference_review_evidence_id": "authored-reference-evidence:1"}
    original = copy.deepcopy(reference)
    ready = classify_step23_reference_state(reference)
    check("documented_current_reference_can_be_eligible_metadata", ready["reference_eligible"] and not ready["planner_eligible"])
    check("reference_review_does_not_grant_planner_approval", len(ready["planner_pending_requirements"]) == 7)
    planner = dict(reference, planner_review_status="accepted", planner_requirements_status="verified",
        planner_review_documented=True, planner_review_version_matches=True,
        planner_review_record_sha256="a" * 64, planner_review_decision_id="authored-planner-decision:1",
        planner_review_evidence_id="authored-planner-evidence:1")
    check("separate_documented_planner_gates_can_pass_metadata", classify_step23_reference_state(planner)["planner_eligible"])
    for kind in ("basketball_drill", "guideline"):
        result = classify_step23_reference_state(dict(reference, record_kind=kind,
            membership_status="verified_reference_candidate"))
        check("supported_reference_kind:" + kind, result["reference_eligible"])
    guideline = classify_step23_reference_state(dict(planner, record_kind="guideline",
        executable_rule_adoption_status="unadopted"))
    check("guideline_reference_does_not_adopt_executable_rule", guideline["reference_eligible"]
          and not guideline["planner_eligible"] and not guideline["executable_rule_enabled_by_reference_review"]
          and guideline["executable_rule_adoption_status"] == "unadopted")
    for membership in ("protected_group", "excluded", "evaluation_material"):
        result = classify_step23_reference_state(dict(planner, membership_status=membership))
        check("exclusion_precedes_all_ready_flags:" + membership, not result["reference_eligible"]
              and not result["planner_eligible"] and result["disposition"] == "excluded" and not result["source_text_read"])
    for membership in ("review_only", "unproven"):
        result = classify_step23_reference_state(dict(planner, membership_status=membership))
        check("unapproved_membership_is_deferred:" + membership, result["disposition"] == "deferred"
              and not result["reference_eligible"])
    check("scope_string_is_not_membership_evidence", not classify_step23_reference_state(
        dict(reference, membership_verified=False, input_scope="development_train"))["reference_eligible"])
    check("reviewed_reference_membership_supports_public_guidelines", classify_step23_reference_state(
        dict(reference, record_kind="guideline", membership_status="reviewed_reference"))["reference_eligible"])
    check("preparation_verification_alone_is_not_approval", not classify_step23_reference_state(
        {"record_kind": "guideline", "source_preparation_verified": True})["reference_eligible"])
    check("accepted_body_part_tag_alone_is_not_approval", not classify_step23_reference_state(
        {"record_kind": "general_exercise", "body_part_tag_status": "accepted"})["reference_eligible"])
    check("missing_metadata_keeps_unknowns_pending", classify_step23_reference_state({})["disposition"] == "deferred")
    for key in ("source_identity_status", "source_version_status", "locator_status", "source_context_status", "permission_status", "reference_review_status"):
        result = classify_step23_reference_state(dict(reference, **{key: "pending"}))
        check("missing_reference_gate_stays_pending:" + key, not result["reference_eligible"]
              and result["disposition"] == "pending" and key in result["pending_requirements"])
    check("unknown_permission_is_not_denied_or_permitted", classify_step23_reference_state(
        dict(reference, permission_status="unknown"))["disposition"] == "pending")
    for key, value in (("permission_status", "denied"), ("reference_review_status", "rejected")):
        result = classify_step23_reference_state(dict(reference, **{key: value}))
        check("explicit_rejection_remains_distinct:" + key, result["disposition"] == "rejected"
              and not result["reference_eligible"] and result["blocking_reasons"])
    for key in ("reference_review_documented", "reference_review_version_matches"):
        result = classify_step23_reference_state(dict(reference, **{key: False}))
        check("review_documentation_and_version_are_required:" + key, not result["reference_eligible"])
    for key in ("record_version_sha256", "reference_review_record_sha256", "reference_review_decision_id", "reference_review_evidence_id"):
        result = classify_step23_reference_state(dict(reference, **{key: ""}))
        check("explicit_reference_binding_is_required:" + key, not result["reference_eligible"]
              and result["disposition"] == "pending")
    check("accepted_flags_cannot_hide_mismatched_record_version", not classify_step23_reference_state(
        dict(reference, reference_review_record_sha256="b" * 64))["reference_eligible"])
    check("planner_rejection_does_not_remove_reference_permission", classify_step23_reference_state(
        dict(planner, planner_review_status="rejected"))["reference_eligible"]
        and not classify_step23_reference_state(dict(planner, planner_review_status="rejected"))["planner_eligible"])
    check("planner_version_cannot_migrate_silently", not classify_step23_reference_state(
        dict(planner, planner_review_version_matches=False))["planner_eligible"])
    check("planner_hash_binding_cannot_migrate_silently", not classify_step23_reference_state(
        dict(planner, planner_review_record_sha256="b" * 64))["planner_eligible"])
    for key in ("planner_review_record_sha256", "planner_review_decision_id", "planner_review_evidence_id"):
        result = classify_step23_reference_state(dict(planner, **{key: ""}))
        check("explicit_planner_binding_is_required:" + key, result["reference_eligible"] and not result["planner_eligible"])
    for kind in ("structured_rule", "food_fact"):
        result = classify_step23_reference_state(dict(planner, record_kind=kind))
        check("structured_tools_are_separate:" + kind, result["disposition"] == "structured_tool_route"
              and not result["reference_eligible"] and not result["structured_tool_eligibility_assessed"])
    rejected_input("nonmapping_input_rejected", "guideline")
    rejected_input("invalid_enum_rejected", dict(reference, permission_status="probably_allowed"))
    rejected_input("string_boolean_cannot_clear_membership", dict(reference, membership_verified="True"))
    rejected_input("malformed_version_hash_rejected", dict(reference, record_version_sha256="not-a-hash"))
    rejected_input("source_text_not_accepted_as_metadata", dict(reference, description="Authored source text"))
    check("source_metadata_inputs_are_not_mutated", reference == original)
    check("metadata_classification_never_creates_actual_adoption", not ready["actual_record_approval_created"]
          and not ready["source_verification_performed"])
    return {"scenario_count": len(checks), "check_count": len(checks), "check_records": checks,
        "actual_record_approvals_created": 0, "study_source_records_read": 0,
        "source_text_read": False, "model_or_vectorizer_fits": 0}


"""Save a versioned retrieval input audit without replacing source evidence."""


def validate_step23_input_targets(project_root, payloads):
    """Bind three audit outputs to one preparation ID and preserve conflicts."""
    import hashlib
    import json
    import re
    from pathlib import Path, PurePosixPath

    stage = "payload_and_project_root"
    try:
        root = Path(project_root).resolve(strict=True)
        if not root.is_dir() or type(payloads) is not dict or len(payloads) != 3:
            raise ValueError("invalid_retrieval_input_payload_scope")
        basenames = {"source_preparation_audit.csv", "input_preparation_checks.csv",
                     "step23_input_preparation_summary.json"}
        expression = re.compile(r"results/retrieval/input_preparation/inputs_([0-9a-f]{16})/(source_preparation_audit\.csv|input_preparation_checks\.csv|step23_input_preparation_summary\.json)")
        matches = [expression.fullmatch(value) if type(value) is str else None for value in payloads]
        if (any(value is None for value in matches)
                or len({value.group(1) for value in matches}) != 1
                or {PurePosixPath(value).name for value in payloads} != basenames):
            raise ValueError("invalid_retrieval_input_version_scope")
        prefix = next(iter(payloads)).rsplit("/", 1)[0] + "/"
        names = {prefix + value for value in basenames}
        marker = prefix + "step23_input_preparation_summary.json"
        if set(payloads) != names:
            raise ValueError("invalid_retrieval_input_payload_scope")
        canonical, identical, missing, hashes = [], [], [], {}
        for relative, content in payloads.items():
            stage = "canonical_path_allowlist"
            if type(relative) is not str or type(content) is not bytes or not content:
                raise ValueError("invalid_retrieval_input_payload")
            parsed = PurePosixPath(relative)
            if (not relative or "\\" in relative or ":" in relative or parsed.is_absolute()
                    or parsed.as_posix() != relative or any(part in (".", "..") for part in parsed.parts)):
                raise ValueError("invalid_retrieval_input_path")
            target = root.joinpath(*parsed.parts)
            if target == root or target.resolve() != target or not target.is_relative_to(root):
                raise ValueError("escaped_or_symlink_retrieval_input_target")
            for ancestor in (target, *target.parents):
                if ancestor == root:
                    break
                if ancestor.is_symlink():
                    raise ValueError("symlink_retrieval_input_target")
            stage = "existing_canonical_targets"
            if target.exists():
                if not target.is_file() or target.read_bytes() != content:
                    raise ValueError("conflicting_retrieval_input_artifact_preserved")
                identical.append(relative)
            else:
                missing.append(relative)
            canonical.append(relative)
            hashes[relative] = hashlib.sha256(content).hexdigest()
        stage = "owned_version_folder_inventory"
        version_root = root / prefix
        if version_root.exists():
            if (not version_root.is_dir() or version_root.is_symlink()
                    or any(entry.name not in basenames or not entry.is_file() or entry.is_symlink()
                           for entry in version_root.iterdir())):
                raise ValueError("unrecognized_retrieval_input_version_entry_preserved")
        stage = "existing_completion_marker_requires_complete_outputs"
        if marker in identical and missing:
            raise ValueError("incomplete_existing_retrieval_input_export_preserved")
        stage = "producer_payload_hash_bindings"

        def pairs(items):
            value = {}
            for key, item in items:
                if key in value:
                    raise ValueError("duplicate_retrieval_input_json_key")
                value[key] = item
            return value

        producer = json.loads(payloads[marker].decode("utf-8"), object_pairs_hook=pairs,
            parse_constant=lambda value: (_ for _ in ()).throw(ValueError("nonfinite_producer_json")))
        if (not isinstance(producer, dict)
                or producer.get("schema_version") != "step23-retrieval-input-preparation-producer-1"
                or producer.get("output_hashes") != {
                    relative: hashes[relative] for relative in names - {marker}}):
            raise ValueError("retrieval_input_producer_hash_mismatch")
        preparation_id = producer.get("input_preparation_id")
        if (not isinstance(preparation_id, str)
                or not re.fullmatch(r"retrieval-input-preparation:[0-9a-f]{64}", preparation_id)
                or prefix != "results/retrieval/input_preparation/inputs_" + preparation_id.split(":")[1][:16] + "/"):
            raise ValueError("retrieval_input_identity_and_version_path_disagree")
        if (json.dumps(producer, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n").encode("utf-8") != payloads[marker]:
            raise ValueError("noncanonical_retrieval_input_producer")
        return {"status": "retrieval_input_targets_verified", "root": root,
            "canonical_files": canonical, "identical_existing_files": identical, "missing_files": missing,
            "artifact_hashes": hashes, "producer_relative_path": marker,
            "version_relative_path": prefix[:-1], "input_preparation_id": preparation_id}
    except Exception:
        raise RuntimeError("step23_input_target_check_failed:" + stage) from None


def commit_step23_input_payloads(project_root, payloads, verify_inputs, verify_published=None):
    """Publish the audit and checks before their producer; roll back only files we own."""
    import os
    import tempfile
    from pathlib import Path

    stage = "canonical_target_preflight"
    staged, created, created_directories = {}, [], []
    root, frozen, staging_root = None, None, None
    staging_identity = None
    published_verification = None

    def require(condition):
        if not bool(condition):
            raise ValueError("retrieval_input_preparation_commit_condition_failed")

    def ensure_parent(parent):
        pending, cursor = [], parent
        while not cursor.exists():
            pending.append(cursor)
            cursor = cursor.parent
        require(cursor.is_dir() and not cursor.is_symlink())
        for directory in reversed(pending):
            try:
                directory.mkdir()
            except FileExistsError:
                require(directory.is_dir() and not directory.is_symlink())
            else:
                created_directories.append(directory)

    def verify_callback():
        require(verify_inputs() is not False)
        require(payloads == frozen)

    def clean_staging():
        complete = True
        for temporary, identity in staged.values():
            try:
                if temporary.is_symlink():
                    complete = False
                elif temporary.exists():
                    current = temporary.stat()
                    if (current.st_dev, current.st_ino) == identity:
                        temporary.unlink()
                    else:
                        complete = False
            except OSError:
                complete = False
        if staging_root is not None:
            try:
                if staging_root.is_symlink():
                    complete = False
                elif staging_root.exists():
                    current = staging_root.stat()
                    if (current.st_dev, current.st_ino) != staging_identity:
                        complete = False
                    else:
                        staging_root.rmdir()
            except OSError:
                complete = False
        return complete

    def clean_empty_directories():
        for directory in reversed(created_directories):
            try:
                directory.rmdir()
            except OSError:
                pass

    try:
        require(callable(verify_inputs) and (verify_published is None or callable(verify_published)))
        plan = validate_step23_input_targets(project_root, payloads)
        root, frozen = plan["root"], dict(payloads)
        stage = "input_verification_before_staging"
        verify_callback()
        marker = plan["producer_relative_path"]
        order = [relative for relative in frozen if relative != marker]
        stage = "complete_temporary_payloads"
        if plan["missing_files"]:
            staging_root = Path(tempfile.mkdtemp(prefix=".step23-input-stage-", dir=root))
            info = staging_root.stat()
            staging_identity = info.st_dev, info.st_ino
        for number, relative in enumerate(plan["missing_files"]):
            descriptor, name = tempfile.mkstemp(prefix="payload-" + str(number) + "-", suffix=".tmp", dir=staging_root)
            temporary = Path(name)
            info = os.fstat(descriptor)
            staged[relative] = temporary, (info.st_dev, info.st_ino)
            with os.fdopen(descriptor, "wb") as handle:
                require(handle.write(frozen[relative]) == len(frozen[relative]))
                handle.flush()
                os.fsync(handle.fileno())
            require(temporary.read_bytes() == frozen[relative])
        stage = "target_and_input_reverification_before_publish"
        validate_step23_input_targets(root, frozen)
        verify_callback()

        def publish(relative):
            nonlocal stage
            target, content = root / relative, frozen[relative]
            ensure_parent(target.parent)
            require(target.resolve() == target and not target.is_symlink())
            if target.exists():
                require(target.is_file() and target.read_bytes() == content)
                return
            require(relative in staged)
            temporary, identity = staged[relative]
            require(temporary.read_bytes() == content)
            try:
                os.link(temporary, target)
            except FileExistsError:
                require(not target.is_symlink() and target.is_file() and target.read_bytes() == content)
            except OSError:
                stage = "atomic_exclusive_input_preparation_publication_unavailable"
                raise
            else:
                created.append((relative, identity))
            require(not target.is_symlink() and target.is_file() and target.read_bytes() == content)

        stage = "atomic_exclusive_input_preparation_publication"
        for relative in order:
            publish(relative)
        stage = "published_input_preparation_and_report_readback"
        intermediate = validate_step23_input_targets(root, frozen)
        require(set(intermediate["missing_files"]).issubset({marker}))
        stage = "published_input_preparation_verification"
        if verify_published is not None:
            published_verification = verify_published()
            require(published_verification is not False)
        stage = "input_verification_after_input_preparation_verification"
        verify_callback()
        stage = "producer_last_publication"
        publish(marker)
        stage = "complete_saved_input_preparation_readback"
        final = validate_step23_input_targets(root, frozen)
        require(not final["missing_files"])
        stage = "input_verification_after_publication"
        verify_callback()
        stage = "final_saved_input_preparation_readback"
        final = validate_step23_input_targets(root, frozen)
        require(not final["missing_files"])
        newly_created = [relative for relative, _identity in created]
        result = {"status": "retrieval_input_preparation_committed_and_verified", "root": root,
            "mode": "saved_and_verified_retrieval_input_preparation" if created else "reused_verified_retrieval_input_preparation",
            "canonical_files": list(frozen), "saved_files": len(frozen), "newly_created_files": len(created),
            "identical_files_reused": len(frozen) - len(created), "newly_created_paths": newly_created,
            "identical_reused_paths": [relative for relative in frozen if relative not in newly_created],
            "artifact_hashes": final["artifact_hashes"], "existing_files_overwritten": 0,
            "producer_published_after_payload_verification": True,
            "published_verification": published_verification,
            "publication": "atomic exclusive hard links from complete fsynced temporary payloads",
            "input_verifications": 4, "all_payloads_read_back": True, "temporary_files_removed": True}
        stage = "temporary_payload_cleanup"
        require(clean_staging())
        return result
    except BaseException as error:
        changed = []
        if root is not None and frozen is not None:
            for relative, identity in reversed(created):
                target = root / relative
                try:
                    if not target.exists() and not target.is_symlink():
                        continue
                    if target.is_symlink() or target.resolve() != target:
                        changed.append(relative)
                        continue
                    current = target.stat()
                    if ((current.st_dev, current.st_ino) == identity and target.is_file()
                            and target.read_bytes() == frozen[relative]):
                        target.unlink()
                    else:
                        changed.append(relative)
                except OSError:
                    changed.append(relative)
        staging_removed = clean_staging()
        clean_empty_directories()
        if changed:
            raise RuntimeError("step23_input_commit_failed:" + stage
                               + ":rollback_incomplete_preserved_changed_files") from None
        if not staging_removed:
            raise RuntimeError("step23_input_commit_failed:" + stage
                               + ":temporary_payload_cleanup_incomplete") from None
        message = str(error)
        if stage == "canonical_target_preflight" and message.startswith("step23_input_target_check_failed:"):
            raise RuntimeError(message) from None
        raise RuntimeError("step23_input_commit_failed:" + stage) from None



"""Save a bounded reference-preparation audit before building a retrieval corpus."""


def execute_step23_input_preparation(namespace):
    import copy
    import hashlib
    import importlib.metadata
    import io
    import json
    import platform
    from pathlib import Path
    import pandas as pd

    stage, checks = "classifier_catalog_handoff", []

    def packed(value):
        return (json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n").encode("utf-8")

    def sha(value):
        return hashlib.sha256(value).hexdigest()

    def check(name, condition, observed=True):
        nonlocal stage
        stage = name
        if not bool(condition):
            raise ValueError("retrieval_input_preparation_condition_failed")
        checks.append({"check": name, "status": "pass", "observed": str(observed)})

    try:
        print("Verifying the saved classifier/catalog handoff; no model loading or prediction...", flush=True)
        classifier = verify_step23_classifier_handoff(namespace)
        root = Path(classifier["root"])
        print("Auditing the explicitly named drill, guidance and structured-food preparation bundles...", flush=True)
        stage = "saved_reference_preparation_inventory"
        sources = prepare_step23_source_inventory(root, classifier["input_hashes"])
        check("source_preparation_audit_admits_no_records_or_approvals",
              sources["record_level_retrieval_admission_assessed"] is False
              and sources["global_retrieval_eligible_records"] is None
              and sources["corpus_records_admitted"] == sources["source_or_review_decisions_created"] == 0
              and sources["source_content_decoded_as_passages"] is False)
        stage = "artificial_reference_eligibility_checks"
        probes = run_step23_readiness_probes()
        check("artificial_eligibility_checks_do_not_create_actual_approvals",
              probes["actual_record_approvals_created"] == 0 and probes["source_text_read"] is False)
        input_hashes = dict(classifier["input_hashes"])
        for relative, digest in sources["input_hashes"].items():
            if relative in input_hashes and input_hashes[relative] != digest:
                raise ValueError("source_preparation_conflicts_with_frozen_classifier_bindings")
            input_hashes[relative] = digest
        check("all_metadata_dependencies_are_bound_without_replacing_prior_inputs",
              len(classifier["input_hashes"]) == 297 and all(input_hashes[key] == value
                  for key, value in classifier["input_hashes"].items()), len(input_hashes))

        handoff = classifier["handoff"]
        general = {"resource_family": "general_exercises", "preparation_status": "verified_development_catalog_handoff",
            "reported_prepared_records": handoff["development_population"]["catalog_records"],
            "record_unit": "development_exercise_records",
            "documented_retrieval_approved_records": 0,
            "retrieval_admission_status": "pending_separate_source_and_reference_use_review",
            "planner_eligible_in_preparation_snapshot": None, "adopted_rules_in_preparation_snapshot": None,
            "producer_path": "results/step22_classifier_packaging_summary.json",
            "handoff_path": "results/step22_step23_classifier_catalog_handoff.json"}
        resource_records = [general] + copy.deepcopy(sources["resources"])
        # Object dtype preserves unavailable counts without turning them into zeros.
        inventory = pd.DataFrame(resource_records, dtype=object)
        blocker_records = [{"resource_family": "general_exercises", "requirement": requirement,
            "status": "pending", "detail": "Development suggestions preserve source labels and do not establish retrieval or planner approval."}
            for requirement in ("independent_source_verification", "permitted_use_review",
                                "documented_reference_use_review_and_explicit_inclusion_list")]
        blocker_records += copy.deepcopy(sources["blocker_records"])
        blocker_records += [{"resource_family": "retrieval_collection", "requirement": "reviewed_record_level_inclusion",
            "status": "not_assessed_by_this_metadata_audit", "detail": "No candidate records were admitted to a corpus."},
            {"resource_family": "new_exercises", "requirement": "complete_protected_group_screening",
             "status": "pending_population_not_selected", "detail": "Unproven records remain deferred; repeated-relation digests alone do not clear membership."}]
        blockers = pd.DataFrame(blocker_records)
        check("prepared_population_counts_are_not_retrieval_approval_counts",
              general["reported_prepared_records"] == 2434
              and general["documented_retrieval_approved_records"] == 0
              and all(row["documented_retrieval_approved_records"] is None for row in sources["resources"]))

        stage = "package_metadata_inventory"
        package_roles = {"numpy": "lexical_and_semantic_array_operations", "pandas": "metadata_tables",
            "scipy": "lexical_sparse_arrays", "scikit-learn": "lexical_retrieval",
            "torch": "semantic_runtime", "transformers": "semantic_tokenizer_and_runtime",
            "sentence-transformers": "semantic_encoder", "tokenizers": "semantic_tokenization"}
        runtime_packages = {"python": platform.python_version(), "packages": {}}
        package_rows = []
        for name, role in package_roles.items():
            try:
                version, availability = importlib.metadata.version(name), "installed_metadata_found"
            except importlib.metadata.PackageNotFoundError:
                version, availability = None, "unavailable_not_installed"
            runtime_packages["packages"][name] = {"version": version, "availability": availability}
            package_rows.append({"package": name, "version": version, "availability": availability,
                                 "planned_role": role, "working_model_runtime_verified": False})
        package_table = pd.DataFrame(package_rows, dtype=object)
        check("package_metadata_is_not_a_working_encoder_or_device_check",
              all(row["working_model_runtime_verified"] is False for row in package_rows))
        shared_tokenizer = "src/champion_athletic_map/text_preprocessing.py"
        check("shared_text_preparation_source_is_frozen_for_later_retrieval_use", shared_tokenizer in input_hashes
              and sha((root / shared_tokenizer).read_bytes()) == input_hashes[shared_tokenizer])

        planned_contract = {
            "schema_version": "step23-planned-retrieval-contract-1",
            "status": "prepared_policy_not_operational_corpus_or_model_adoption",
            "classifier_release_id": handoff["release_id"], "classifier_catalog_version": handoff["catalog_version"],
            "shared_text_preparation_source": {"relative_path": shared_tokenizer, "sha256": input_hashes[shared_tokenizer]},
            "corpus": {"inclusion": "explicit_reviewed_record_list_only", "recursive_project_indexing": False,
                "source_verification_required": True, "permitted_use_review_required": True,
                "current_record_reference_use_review_required": True,
                "record_hash_and_review_decision_evidence_bindings_required": True,
                "planner_eligibility_review_is_separate": True,
                "guideline_reference_use_does_not_enable_executable_rules": True,
                "planning_rules_and_food_facts": "separate_structured_tools",
                "evidence_units_and_passages_are_distinct": True,
                "excluded_material": handoff["information_use"]["excluded_index_material"]},
            "lexical": {"status": "planned_not_created_or_fitted", "method": "tfidf_cosine",
                "separate_from_classifier_fitted_vectorizer": True, "ngram_range": [1, 2], "min_df": 1,
                "max_df": 1.0, "stop_words": None, "max_features": None,
                "smooth_idf": True, "sublinear_tf": False, "norm": "l2", "dtype": "float64",
                "fit_population": "eligible_reference_passages_only", "query_vocabulary_or_idf_fitting": False},
            "semantic": {"status": "candidate_not_adopted_or_loaded",
                "candidate_model_id": "sentence-transformers/all-MiniLM-L6-v2",
                "exact_revision": None, "license_verified": False, "local_weights_verified": False,
                "working_device": None, "model_max_seq_length_verified": False,
                "frozen_pretrained_weights": True, "dtype": "float32", "l2_normalized_embeddings": True,
                "similarity": "cosine", "task_prompts": None},
            "passages": {"status": "not_constructed", "target_embedding_tokens": [150, 200],
                "initial_max_encoded_tokens": 200, "headings_and_special_tokens_included": True,
                "must_verify_actual_loaded_model_limit": True, "silent_truncation_allowed": False,
                "required_context_and_continuation_links_preserved": True},
            "ranking": {"status": "planned_not_executed", "maximum_distinct_evidence_units": 5,
                "unit_score": "maximum_passage_score", "unit_tie_rule": "stable_evidence_unit_id",
                "passage_tie_rule": "stable_passage_id", "lexical_zero_score_fill": False,
                "semantic_similarity_establishes_answerability": False,
                "tuned_similarity_abstention_threshold_adopted": False},
            "benchmark": {"status": "planned_no_questions_or_judgments_created",
                "planned_development_questions": 30, "planned_held_out_questions": 30,
                "planned_per_partition_categories": {"drill_and_resource": 10,
                    "guideline_and_qualification": 10, "unsupported_by_identified_corpus": 10},
                "question_families_cannot_cross_partitions": True,
                "ranking_relevance_and_complete_evidence_judgments_separate": True,
                "actual_questions": 0, "actual_reviewed_judgments": 0,
                "question_text_or_answers_in_corpus": False,
                "selection_rule": ["higher_development_mean_recall_at_5",
                    "higher_development_mrr_at_5_on_exact_tie", "lexical_on_exact_double_tie"]},
            "context_integration": {"status": "pending_step24_generation_budget_and_tokenizer",
                "ranking_metrics_and_delivered_context_coverage_separate": True},
            "version_controls": {"final_experiment_freeze_step": 31,
                "held_out_classifier_evaluation_step": 32,
                "post_test_catalog_tagging_requires_separate_revision": True,
                "same_adopted_retrieval_configuration_for_planner_versions": ["V2", "V3", "V4"]}}
        check("fixed_retrieval_intentions_preserve_independent_evaluation_boundaries",
              planned_contract["benchmark"]["actual_questions"] == 0
              and planned_contract["semantic"]["exact_revision"] is None
              and planned_contract["lexical"]["separate_from_classifier_fitted_vectorizer"] is True
              and planned_contract["corpus"]["recursive_project_indexing"] is False)
        identity = {"recipe_version": "retrieval-input-preparation-0.1.0",
            "implementation_sha256": _STEP23_INPUT_IMPLEMENTATION_SHA256, "input_hashes": input_hashes,
            "classifier_handoff_id": handoff["handoff_id"],
            "source_inventory_identity": sources["source_metadata_digest"],
            "planned_contract": planned_contract, "runtime_packages": runtime_packages}
        identity_digest = sha(packed(identity))
        preparation_id = "retrieval-input-preparation:" + identity_digest
        prefix = "results/retrieval/input_preparation/inputs_" + identity_digest[:16] + "/"
        ledger = []
        for scope, values in (("classifier_catalog_handoff", classifier["checks"]),
                              ("saved_reference_preparation_metadata", sources["checks"]),
                              ("artificial_reference_eligibility_policy", probes["check_records"]),
                              ("input_preparation_accounting", checks)):
            records = values.to_dict("records") if isinstance(values, pd.DataFrame) else values
            for number, row in enumerate(records, 1):
                if row["status"] != "pass":
                    raise ValueError("nonpassing_retrieval_input_preparation_check")
                ledger.append({"scope": scope, "scope_check_number": number, "check": row["check"],
                    "status": "pass", "observed": str(row.get("observed", ""))})
        check_table = pd.DataFrame(ledger)
        audit_path, checks_path = prefix + "source_preparation_audit.csv", prefix + "input_preparation_checks.csv"
        producer_path = prefix + "step23_input_preparation_summary.json"
        payloads = {audit_path: inventory.to_csv(index=False, lineterminator="\n").encode("utf-8"),
            checks_path: check_table.to_csv(index=False, lineterminator="\n").encode("utf-8")}
        output_hashes = {relative: sha(value) for relative, value in payloads.items()}
        summary = {"schema_version": "step23-retrieval-input-preparation-producer-1", **identity,
            "input_preparation_id": preparation_id,
            "status": "saved_inputs_and_source_preparation_audit_verified_corpus_approval_pending",
            "output_hashes": output_hashes, "resource_inventory": resource_records,
            "open_requirements": blocker_records,
            "classifier_files_reverified": len(classifier["input_hashes"]),
            "additional_source_preparation_files_verified": len(set(sources["input_hashes"]) - set(classifier["input_hashes"])),
            "source_preparation_files_verified": sources["verified_metadata_files"],
            "all_bound_files_reverified": len(input_hashes), "saved_checks": len(check_table),
            "artificial_eligibility_scenarios": probes["scenario_count"],
            "artificial_eligibility_checks": len(probes["check_records"]),
            "full_upstream_source_dependency_closure_verified": False,
            "record_level_retrieval_eligibility_assessed": False,
            "global_retrieval_eligible_records": None, "candidate_counts_are_corpus_approval_counts": False,
            "corpus_records_admitted": 0, "evidence_units_created": 0, "passages_created": 0,
            "retrieval_vectorizers_fitted": 0, "embedding_models_loaded": 0, "model_downloads": 0,
            "embedding_operations": 0, "retrieval_requests_executed": 0,
            "questions_created": 0, "judgments_created": 0, "source_review_decisions_created": 0,
            "reference_or_planner_approvals_granted": 0, "classifier_models_loaded": 0,
            "classifier_predictions_produced": 0, "new_model_training_or_fits": 0,
            "source_body_decoded_as_passages": False, "source_refresh_performed": False,
            "test_text_transformed_or_predicted": False, "protected_catalog_rows_deferred": 439,
            "new_record_population_selected": False, "new_record_screening_complete": False,
            "step23_complete": False, "operational_corpus_ready": False,
            "semantic_model_revision_license_and_runtime_verified": False,
            "retrieval_benchmark_review_complete": False, "delivered_context_integration_ready": False,
            "final_experiment_freeze_complete": False,
            "next_substep": "Step 23-2 prepare source-linked record eligibility and permitted-use review before admitting passages; keep unresolved material outside the corpus."}
        payloads[producer_path] = packed(summary)
        expected_hashes = {relative: sha(value) for relative, value in payloads.items()}
        metadata_guard = sha(packed(identity))
        exposed_frames = {"inventory": inventory, "blockers": blockers,
                          "package_metadata": package_table, "checks": check_table}
        frame_guards = {key: sha(frame.to_csv(index=False, lineterminator="\n").encode("utf-8"))
                        for key, frame in exposed_frames.items()}

        def verify_inputs():
            classifier["verify_unchanged"]()
            sources["verify_unchanged"]()
            if (sha(packed(identity)) != metadata_guard
                    or expected_hashes != {relative: sha(value) for relative, value in payloads.items()}
                    or sha(packed(summary)) != expected_hashes[producer_path]
                    or any(sha(frame.to_csv(index=False, lineterminator="\n").encode("utf-8")) != frame_guards[key]
                           for key, frame in exposed_frames.items())):
                raise RuntimeError("step23_input_preparation_failed:verified_preparation_state_changed")
            return True

        def verify_saved():
            verify_inputs()
            audit_bytes, checks_bytes = (root / audit_path).read_bytes(), (root / checks_path).read_bytes()
            if sha(audit_bytes) != output_hashes[audit_path] or sha(checks_bytes) != output_hashes[checks_path]:
                raise ValueError("published_retrieval_preparation_bytes_changed")
            audit = pd.read_csv(io.BytesIO(audit_bytes), dtype=str, keep_default_na=False)
            saved_checks = pd.read_csv(io.BytesIO(checks_bytes), dtype=str, keep_default_na=False)
            if (audit.columns.tolist() != inventory.columns.tolist() or len(audit) != len(inventory)
                    or audit["resource_family"].tolist() != inventory["resource_family"].tolist()
                    or saved_checks.columns.tolist() != check_table.columns.tolist()
                    or len(saved_checks) != len(check_table) or not saved_checks["status"].eq("pass").all()):
                raise ValueError("published_retrieval_preparation_schema_or_status_changed")
            return {"audit_resource_families": len(audit), "saved_check_records": len(saved_checks),
                "all_prior_bindings_unchanged": True, "corpus_records_admitted": 0,
                "models_loaded": 0, "source_or_review_decisions_created": 0}

        print("Saving the versioned input/source audit; no corpus, index or benchmark is created...", flush=True)
        stage = "versioned_input_preparation_publication"
        saved = commit_step23_input_payloads(root, payloads, verify_inputs, verify_saved)

        def verify_complete():
            verify_inputs()
            for relative, digest in expected_hashes.items():
                if sha((root / relative).read_bytes()) != digest:
                    raise RuntimeError("step23_input_preparation_failed:saved_preparation_file_changed")
            return True

        verify_complete()
        return {"status": summary["status"], "mode": saved["mode"], "root": root,
            "classifier": classifier, "sources": sources, "summary": summary, "planned_contract": planned_contract,
            "resource_inventory": inventory, "blockers": blockers, "runtime_packages": package_table,
            "checks": check_table, "probes": probes, "input_hashes": input_hashes,
            "input_preparation_id": preparation_id, "save": saved, "saved_files": saved["canonical_files"],
            "verify_unchanged": verify_complete, "input_preparation_verified": True,
            "operational_corpus_ready": False, "step23_complete": False,
            "models_loaded": 0, "corpus_records_admitted": 0, "test_text_processed": False}
    except Exception as error:
        message = str(error)
        if message.startswith(("step23_", "step22_")):
            raise RuntimeError(message) from None
        raise RuntimeError("step23_input_preparation_failed:" + stage) from None


step23_input_preparation_ready = False

