_STEP23_SOURCE_EVIDENCE_IMPLEMENTATION_SHA256 = '1c5629d197e55ddaed2e9fa6486e2daf8cef17f99b621f2dd25fd0188c272fa5'

"""Pure metadata gates for reference preparation, without adopting source records."""


def classify_step23_reference_state(metadata):
    """Classify supplied metadata; do not verify sources, read text or grant approval.

    A verified status here must come from a separate source/decision verifier.
    A caller scope, a prepared bundle or an accepted body-part suggestion is not
    such evidence. Missing metadata remains pending. This helper is deliberately
    independent of any existing project's source-table column names.
    """
    if not isinstance(metadata, dict):
        raise ValueError("invalid_step23_reference_metadata")
    enums = {
        "record_kind": ({"general_exercise", "basketball_drill", "guideline", "structured_rule", "food_fact", "unknown"}, "unknown"),
        "membership_status": ({"eligible_development", "verified_reference_candidate", "reviewed_reference", "protected_group", "excluded", "review_only", "unproven", "evaluation_material"}, "unproven"),
        "source_identity_status": ({"verified", "pending", "unknown", "rejected"}, "pending"),
        "source_version_status": ({"verified", "pending", "unknown", "rejected"}, "pending"),
        "locator_status": ({"verified", "pending", "unknown", "rejected"}, "pending"),
        "source_context_status": ({"preserved", "pending", "unknown", "rejected"}, "pending"),
        "permission_status": ({"permitted", "pending", "unknown", "denied"}, "pending"),
        "reference_review_status": ({"accepted", "pending", "unknown", "rejected"}, "pending"),
        "planner_review_status": ({"accepted", "pending", "unknown", "rejected"}, "pending"),
        "planner_requirements_status": ({"verified", "pending", "unknown", "rejected"}, "pending"),
        "body_part_tag_status": ({"accepted", "pending", "unknown", "rejected", "not_applicable"}, "not_applicable"),
        "executable_rule_adoption_status": ({"adopted", "pending", "unknown", "unadopted", "not_applicable"}, "not_applicable"),
    }
    flags = ("membership_verified", "reference_review_documented", "reference_review_version_matches",
             "planner_review_documented", "planner_review_version_matches", "source_preparation_verified")
    hashes = ("record_version_sha256", "reference_review_record_sha256", "planner_review_record_sha256")
    identifiers = ("reference_review_decision_id", "reference_review_evidence_id", "planner_review_decision_id", "planner_review_evidence_id")
    allowed = set(enums) | set(flags) | set(hashes) | set(identifiers) | {"input_scope"}
    if set(metadata) - allowed:
        raise ValueError("unexpected_step23_reference_metadata_fields")
    values = {}
    for key, (accepted, default) in enums.items():
        value = metadata.get(key, default)
        if not isinstance(value, str) or value not in accepted:
            raise ValueError("invalid_step23_reference_metadata_state:" + key)
        values[key] = value
    for key in flags:
        value = metadata.get(key, False)
        if type(value) is not bool:
            raise ValueError("invalid_step23_reference_metadata_flag:" + key)
        values[key] = value
    if "input_scope" in metadata and not isinstance(metadata["input_scope"], str):
        raise ValueError("invalid_step23_reference_scope")
    import re
    for key in hashes:
        value = metadata.get(key, "")
        if not isinstance(value, str) or (value and not re.fullmatch(r"[0-9a-f]{64}", value)):
            raise ValueError("invalid_step23_reference_version_binding:" + key)
        values[key] = value
    for key in identifiers:
        value = metadata.get(key, "")
        if not isinstance(value, str) or value != value.strip():
            raise ValueError("invalid_step23_reference_review_binding:" + key)
        values[key] = value

    result = {"decision_scope": "metadata_policy_only_no_actual_record_adoption",
        "record_kind": values["record_kind"], "membership_status": values["membership_status"],
        "reference_eligible": False, "planner_eligible": False,
        "source_verification_performed": False, "actual_record_approval_created": False,
        "source_text_read": False, "caller_scope_establishes_membership": False,
        "body_part_tag_acceptance_establishes_eligibility": False,
        "preparation_verification_establishes_eligibility": False,
        "executable_rule_enabled_by_reference_review": False,
        "structured_tool_eligibility_assessed": False,
        "executable_rule_adoption_status": values["executable_rule_adoption_status"],
        "disposition": "pending", "blocking_reasons": [], "pending_requirements": [],
        "planner_pending_requirements": [], "planner_blocking_reasons": []}
    membership = values["membership_status"]
    if membership in ("protected_group", "excluded", "evaluation_material"):
        result.update(disposition="excluded", blocking_reasons=[{
            "protected_group": "protected_group_excluded_before_text_access",
            "excluded": "outside_current_reference_candidate_population",
            "evaluation_material": "private_or_evaluation_material_excluded_from_corpus",
        }[membership]])
        return result
    if membership == "review_only":
        result.update(disposition="deferred", pending_requirements=["separate_review_only_record_inclusion_decision"])
        return result
    if membership == "unproven" or not values["membership_verified"]:
        result.update(disposition="deferred", pending_requirements=["verified_candidate_membership_and_complete_protected_group_exclusion"])
        return result
    if values["record_kind"] in ("structured_rule", "food_fact"):
        result.update(disposition="structured_tool_route", blocking_reasons=["structured_resource_is_not_generic_passage_material"])
        return result
    if values["record_kind"] == "unknown":
        result.update(disposition="deferred", pending_requirements=["supported_record_kind"])
        return result

    gates = (("source_identity_status", "verified", "rejected"),
             ("source_version_status", "verified", "rejected"),
             ("locator_status", "verified", "rejected"),
             ("source_context_status", "preserved", "rejected"),
             ("permission_status", "permitted", "denied"),
             ("reference_review_status", "accepted", "rejected"))
    for key, ready, rejected in gates:
        if values[key] == rejected:
            result["blocking_reasons"].append(key + ":" + rejected)
        elif values[key] != ready:
            result["pending_requirements"].append(key)
    for key in ("reference_review_documented", "reference_review_version_matches"):
        if not values[key]:
            result["pending_requirements"].append(key)
    for key in ("record_version_sha256", "reference_review_record_sha256", "reference_review_decision_id", "reference_review_evidence_id"):
        if not values[key]:
            result["pending_requirements"].append(key)
    if (values["record_version_sha256"] and values["reference_review_record_sha256"]
            and values["record_version_sha256"] != values["reference_review_record_sha256"]):
        result["pending_requirements"].append("reference_review_binding_to_current_record_version")
    if result["blocking_reasons"]:
        result["disposition"] = "rejected"
        return result
    if result["pending_requirements"]:
        result["disposition"] = "pending"
        return result

    result["reference_eligible"] = True
    result["disposition"] = "reference_eligible_by_supplied_verified_metadata"
    if values["record_kind"] == "guideline":
        result["planner_pending_requirements"] = ["guideline_is_reference_material_not_an_activity_selection"]
        return result
    for key, ready in (("planner_review_status", "accepted"), ("planner_requirements_status", "verified")):
        if values[key] == "rejected":
            result["planner_blocking_reasons"].append(key + ":rejected")
        elif values[key] != ready:
            result["planner_pending_requirements"].append(key)
    for key in ("planner_review_documented", "planner_review_version_matches"):
        if not values[key]:
            result["planner_pending_requirements"].append(key)
    for key in ("planner_review_record_sha256", "planner_review_decision_id", "planner_review_evidence_id"):
        if not values[key]:
            result["planner_pending_requirements"].append(key)
    if (values["planner_review_record_sha256"]
            and values["record_version_sha256"] != values["planner_review_record_sha256"]):
        result["planner_pending_requirements"].append("planner_review_binding_to_current_record_version")
    result["planner_eligible"] = not result["planner_blocking_reasons"] and not result["planner_pending_requirements"]
    return result


def run_step23_readiness_probes():
    """Check authored metadata cases; no real source record is read or approved."""
    import copy

    checks = []

    def check(name, condition):
        if not bool(condition):
            raise ValueError("step23_readiness_probe_failed:" + name)
        checks.append({"check": name, "status": "pass", "observed": "authored_metadata_only"})

    def rejected_input(name, metadata):
        try:
            classify_step23_reference_state(metadata)
        except ValueError:
            check(name, True)
        else:
            check(name, False)

    reference = {"record_kind": "general_exercise", "membership_status": "eligible_development",
        "membership_verified": True, "source_identity_status": "verified", "source_version_status": "verified",
        "locator_status": "verified", "source_context_status": "preserved", "permission_status": "permitted",
        "reference_review_status": "accepted", "reference_review_documented": True,
        "reference_review_version_matches": True, "record_version_sha256": "a" * 64,
        "reference_review_record_sha256": "a" * 64,
        "reference_review_decision_id": "authored-reference-decision:1",
        "reference_review_evidence_id": "authored-reference-evidence:1"}
    original = copy.deepcopy(reference)
    ready = classify_step23_reference_state(reference)
    check("documented_current_reference_can_be_eligible_metadata", ready["reference_eligible"] and not ready["planner_eligible"])
    check("reference_review_does_not_grant_planner_approval", len(ready["planner_pending_requirements"]) == 7)
    planner = dict(reference, planner_review_status="accepted", planner_requirements_status="verified",
        planner_review_documented=True, planner_review_version_matches=True,
        planner_review_record_sha256="a" * 64, planner_review_decision_id="authored-planner-decision:1",
        planner_review_evidence_id="authored-planner-evidence:1")
    check("separate_documented_planner_gates_can_pass_metadata", classify_step23_reference_state(planner)["planner_eligible"])
    for kind in ("basketball_drill", "guideline"):
        result = classify_step23_reference_state(dict(reference, record_kind=kind,
            membership_status="verified_reference_candidate"))
        check("supported_reference_kind:" + kind, result["reference_eligible"])
    guideline = classify_step23_reference_state(dict(planner, record_kind="guideline",
        executable_rule_adoption_status="unadopted"))
    check("guideline_reference_does_not_adopt_executable_rule", guideline["reference_eligible"]
          and not guideline["planner_eligible"] and not guideline["executable_rule_enabled_by_reference_review"]
          and guideline["executable_rule_adoption_status"] == "unadopted")
    for membership in ("protected_group", "excluded", "evaluation_material"):
        result = classify_step23_reference_state(dict(planner, membership_status=membership))
        check("exclusion_precedes_all_ready_flags:" + membership, not result["reference_eligible"]
              and not result["planner_eligible"] and result["disposition"] == "excluded" and not result["source_text_read"])
    for membership in ("review_only", "unproven"):
        result = classify_step23_reference_state(dict(planner, membership_status=membership))
        check("unapproved_membership_is_deferred:" + membership, result["disposition"] == "deferred"
              and not result["reference_eligible"])
    check("scope_string_is_not_membership_evidence", not classify_step23_reference_state(
        dict(reference, membership_verified=False, input_scope="development_train"))["reference_eligible"])
    check("reviewed_reference_membership_supports_public_guidelines", classify_step23_reference_state(
        dict(reference, record_kind="guideline", membership_status="reviewed_reference"))["reference_eligible"])
    check("preparation_verification_alone_is_not_approval", not classify_step23_reference_state(
        {"record_kind": "guideline", "source_preparation_verified": True})["reference_eligible"])
    check("accepted_body_part_tag_alone_is_not_approval", not classify_step23_reference_state(
        {"record_kind": "general_exercise", "body_part_tag_status": "accepted"})["reference_eligible"])
    check("missing_metadata_keeps_unknowns_pending", classify_step23_reference_state({})["disposition"] == "deferred")
    for key in ("source_identity_status", "source_version_status", "locator_status", "source_context_status", "permission_status", "reference_review_status"):
        result = classify_step23_reference_state(dict(reference, **{key: "pending"}))
        check("missing_reference_gate_stays_pending:" + key, not result["reference_eligible"]
              and result["disposition"] == "pending" and key in result["pending_requirements"])
    check("unknown_permission_is_not_denied_or_permitted", classify_step23_reference_state(
        dict(reference, permission_status="unknown"))["disposition"] == "pending")
    for key, value in (("permission_status", "denied"), ("reference_review_status", "rejected")):
        result = classify_step23_reference_state(dict(reference, **{key: value}))
        check("explicit_rejection_remains_distinct:" + key, result["disposition"] == "rejected"
              and not result["reference_eligible"] and result["blocking_reasons"])
    for key in ("reference_review_documented", "reference_review_version_matches"):
        result = classify_step23_reference_state(dict(reference, **{key: False}))
        check("review_documentation_and_version_are_required:" + key, not result["reference_eligible"])
    for key in ("record_version_sha256", "reference_review_record_sha256", "reference_review_decision_id", "reference_review_evidence_id"):
        result = classify_step23_reference_state(dict(reference, **{key: ""}))
        check("explicit_reference_binding_is_required:" + key, not result["reference_eligible"]
              and result["disposition"] == "pending")
    check("accepted_flags_cannot_hide_mismatched_record_version", not classify_step23_reference_state(
        dict(reference, reference_review_record_sha256="b" * 64))["reference_eligible"])
    check("planner_rejection_does_not_remove_reference_permission", classify_step23_reference_state(
        dict(planner, planner_review_status="rejected"))["reference_eligible"]
        and not classify_step23_reference_state(dict(planner, planner_review_status="rejected"))["planner_eligible"])
    check("planner_version_cannot_migrate_silently", not classify_step23_reference_state(
        dict(planner, planner_review_version_matches=False))["planner_eligible"])
    check("planner_hash_binding_cannot_migrate_silently", not classify_step23_reference_state(
        dict(planner, planner_review_record_sha256="b" * 64))["planner_eligible"])
    for key in ("planner_review_record_sha256", "planner_review_decision_id", "planner_review_evidence_id"):
        result = classify_step23_reference_state(dict(planner, **{key: ""}))
        check("explicit_planner_binding_is_required:" + key, result["reference_eligible"] and not result["planner_eligible"])
    for kind in ("structured_rule", "food_fact"):
        result = classify_step23_reference_state(dict(planner, record_kind=kind))
        check("structured_tools_are_separate:" + kind, result["disposition"] == "structured_tool_route"
              and not result["reference_eligible"] and not result["structured_tool_eligibility_assessed"])
    rejected_input("nonmapping_input_rejected", "guideline")
    rejected_input("invalid_enum_rejected", dict(reference, permission_status="probably_allowed"))
    rejected_input("string_boolean_cannot_clear_membership", dict(reference, membership_verified="True"))
    rejected_input("malformed_version_hash_rejected", dict(reference, record_version_sha256="not-a-hash"))
    rejected_input("source_text_not_accepted_as_metadata", dict(reference, description="Authored source text"))
    check("source_metadata_inputs_are_not_mutated", reference == original)
    check("metadata_classification_never_creates_actual_adoption", not ready["actual_record_approval_created"]
          and not ready["source_verification_performed"])
    return {"scenario_count": len(checks), "check_count": len(checks), "check_records": checks,
        "actual_record_approvals_created": 0, "study_source_records_read": 0,
        "source_text_read": False, "model_or_vectorizer_fits": 0}


