def _step232_review_json(value):
    import json
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False)


def _step232_review_no_body_fields(value):
    """Reject source bodies and private evaluation content in a metadata packet."""
    forbidden = {"instruction", "instructions", "description", "description_prepared",
        "classifier_text", "model_text", "source_text", "source_body", "source_excerpt",
        "passage_text", "passage_content", "expected_answer", "expected_answers",
        "private_expectations", "evaluation_expectations", "athlete_profile"}
    if isinstance(value, dict):
        for key, item in value.items():
            if not isinstance(key, str) or key.casefold() in forbidden:
                raise ValueError("source_body_or_private_content_field_in_review_packet")
            _step232_review_no_body_fields(item)
    elif isinstance(value, (list, tuple)):
        for item in value:
            _step232_review_no_body_fields(item)


def _step232_validate_review_targets(target_records):
    import re

    if not isinstance(target_records, list):
        raise ValueError("invalid_reference_review_target_collection")
    required = ("review_target_id", "resource_family", "candidate_id", "candidate_unit", "record_version_sha256")
    seen_ids, seen_candidates = set(), set()
    for target in target_records:
        if not isinstance(target, dict) or any(not isinstance(target.get(key), str)
                or not target[key] or target[key] != target[key].strip() for key in required):
            raise ValueError("invalid_reference_review_target_identity")
        if not re.fullmatch(r"[0-9a-f]{64}", target["record_version_sha256"]):
            raise ValueError("invalid_reference_review_record_hash")
        candidate = (target["resource_family"], target["candidate_id"])
        if target["review_target_id"] in seen_ids or candidate in seen_candidates:
            raise ValueError("duplicate_reference_review_target")
        seen_ids.add(target["review_target_id"])
        seen_candidates.add(candidate)
        _step232_review_no_body_fields(target)
        policy = target.get("policy_metadata")
        if not isinstance(policy, dict) or policy.get("record_version_sha256") != target["record_version_sha256"]:
            raise ValueError("review_target_and_policy_versions_do_not_match")
        # The policy evaluates supplied states; it does not independently verify them.
        result = classify_step23_reference_state(policy)
        if policy.get("membership_status") in ("protected_group", "excluded", "evaluation_material"):
            raise ValueError("protected_or_excluded_record_in_review_packet")
        if result["record_kind"] in ("structured_rule", "food_fact"):
            raise ValueError("structured_resource_in_reference_review_packet")
        for field in ("actual_record_approval_created", "actual_review_decision_created", "planner_eligibility_granted"):
            if target.get(field, False) is not False:
                raise ValueError("review_packet_cannot_create_an_approval")
    return True


def prepare_step23_review_worklist(target_records):
    """Prepare an empty-decision worklist from supplied, version-bound metadata."""
    _step232_validate_review_targets(target_records)
    rows, dispositions, families = [], {}, {}
    reference_ready, planner_ready = 0, 0
    for target in target_records:
        metadata_result = classify_step23_reference_state(target["policy_metadata"])
        disposition = metadata_result["disposition"]
        if disposition == "pending":
            queue = "pending_reference_review"
        elif disposition == "rejected":
            queue = "blocked_reference_review"
        elif disposition == "deferred":
            queue = "deferred_membership_or_scope_review"
        else:
            queue = "supplied_metadata_ready_requires_document_verification"
        row = {key: "" for key in STEP23_REVIEW_WORKLIST_COLUMNS}
        row.update({key: target[key] for key in ("review_target_id", "resource_family", "candidate_id",
                                                "candidate_unit", "record_version_sha256")})
        row.update(reference_disposition=disposition,
            reference_eligible_by_metadata=bool(metadata_result["reference_eligible"]),
            planner_eligible_by_metadata=bool(metadata_result["planner_eligible"]),
            pending_requirements_json=_step232_review_json(metadata_result["pending_requirements"]),
            blocking_reasons_json=_step232_review_json(metadata_result["blocking_reasons"]),
            planner_pending_requirements_json=_step232_review_json(metadata_result["planner_pending_requirements"]),
            planner_blocking_reasons_json=_step232_review_json(metadata_result["planner_blocking_reasons"]),
            planner_assessment_status=("not_assessed_before_reference_eligibility" if not metadata_result["reference_eligible"]
                else "guideline_reference_only" if metadata_result["record_kind"] == "guideline"
                else "supplied_metadata_only_separate_document_verification_required"),
            queue_status=queue)
        rows.append(row)
        dispositions[disposition] = dispositions.get(disposition, 0) + 1
        families[target["resource_family"]] = families.get(target["resource_family"], 0) + 1
        reference_ready += int(metadata_result["reference_eligible"])
        planner_ready += int(metadata_result["planner_eligible"])
    return {"worklist_records": rows, "worklist_columns": list(STEP23_REVIEW_WORKLIST_COLUMNS),
        "status_counts": {"review_targets": len(rows), "by_resource_family": families,
            "reference_disposition_counts": dispositions,
            "reference_eligible_by_supplied_metadata": reference_ready,
            "planner_eligible_by_supplied_metadata": planner_ready,
            "actual_review_decisions_created": 0, "actual_record_approvals_created": 0},
        "actual_review_decisions_created": 0, "actual_record_approvals_created": 0,
        "source_text_read": False, "source_verification_performed": False}


def validate_step23_review_packet(target_records, source_evidence_records, worklist_records):
    """Resolve metadata links and worklist rows without adopting review decisions."""
    import re
    from pathlib import PurePosixPath

    _step232_validate_review_targets(target_records)
    if not isinstance(source_evidence_records, list) or not isinstance(worklist_records, list):
        raise ValueError("invalid_reference_review_packet_tables")
    targets = {row["review_target_id"]: row for row in target_records}
    source_counts, seen_evidence, artifact_hashes = {key: 0 for key in targets}, set(), {}
    for row in source_evidence_records:
        if not isinstance(row, dict) or row.get("review_target_id") not in targets:
            raise ValueError("orphan_reference_review_source_link")
        _step232_review_no_body_fields(row)
        relative, digest = row.get("local_artifact_path"), row.get("local_artifact_sha256")
        if (not isinstance(relative, str) or not relative or "\\" in relative or ":" in relative
                or not isinstance(digest, str) or not re.fullmatch(r"[0-9a-f]{64}", digest)):
            raise ValueError("unbound_reference_review_source_artifact")
        parsed = PurePosixPath(relative)
        if (parsed.is_absolute() or parsed.as_posix() != relative
                or any(part in (".", "..") for part in parsed.parts)):
            raise ValueError("unsafe_reference_review_source_artifact_path")
        if not any(isinstance(row.get(key), str) and row[key].strip()
                   for key in ("local_record_locator", "source_record_locator", "package_record_locator")):
            raise ValueError("missing_reference_review_source_record_locator")
        if relative in artifact_hashes and artifact_hashes[relative] != digest:
            raise ValueError("conflicting_reference_review_artifact_hashes")
        artifact_hashes[relative] = digest
        row_identity = _step232_review_json(row)
        if row_identity in seen_evidence:
            raise ValueError("duplicate_reference_review_source_link")
        seen_evidence.add(row_identity)
        source_counts[row["review_target_id"]] += 1
    if any(count < 1 for count in source_counts.values()):
        raise ValueError("reference_review_target_has_no_source_link")
    expected = prepare_step23_review_worklist(target_records)
    expected_rows = expected["worklist_records"]
    if len(worklist_records) != len(expected_rows):
        raise ValueError("reference_review_worklist_population_changed")
    for saved, wanted in zip(worklist_records, expected_rows):
        if not isinstance(saved, dict) or set(saved) != set(STEP23_REVIEW_WORKLIST_COLUMNS):
            raise ValueError("invalid_reference_review_worklist_schema")
        for key, value in wanted.items():
            actual = saved[key]
            # Canonical CSV readback represents these two Boolean columns as strings.
            if type(value) is bool:
                if type(actual) is bool:
                    equal = actual is value
                else:
                    equal = isinstance(actual, str) and actual == ("True" if value else "False")
            else:
                equal = type(actual) is type(value) and actual == value
            if not equal:
                raise ValueError("review_worklist_changed_or_claims_actual_decision")
    return {"review_targets": len(target_records), "source_links": len(source_evidence_records),
        "worklist_rows": len(worklist_records), "unique_source_artifact_bindings": len(artifact_hashes),
        "every_target_has_source_links": True, "all_worklist_rows_match_policy_metadata": True,
        "actual_review_decisions_created": 0, "actual_record_approvals_created": 0,
        "source_bodies_copied_to_packet": False, "corpus_records_admitted": 0,
        "status_counts": expected["status_counts"]}


def step23_review_packet_instructions():
    """Describe a later, separate decision-intake workflow; do not execute it."""
    return {"packet_status": "pending_source_and_reference_use_review_not_corpus_admission",
        "canonical_packet_is_immutable": True,
        "decision_template_columns": list(STEP23_REFERENCE_DECISION_COLUMNS),
        "review_scopes": list(STEP23_REFERENCE_REVIEW_SCOPES),
        "decision_values": ["accepted", "rejected", "unresolved"],
        "decision_template_contains_actual_decisions": False,
        "decision_intake_or_adoption_executed": False,
        "steps": ["Preserve the canonical packet, worklist and prior review evidence.",
            "Copy the empty decision template to a separately named review-decision file before entering decisions.",
            "Review each named source artifact and record locator against the current source version; preserve required context.",
            "Record one documented scope-specific decision with reviewer, timezone-aware date, reason and traceable evidence.",
            "Bind each decision to review_target_id and the exact record_version_sha256. Permission decisions must identify their basis and permitted-use scope.",
            "Keep source/reference review and planner-use review separate; unresolved or rejected requirements do not become approvals.",
            "Submit the separately saved decisions to a later verifier. A filled template alone does not admit records or alter the frozen packet."]}


def run_step23_record_review_probes():
    """Exercise authored packet metadata without reading any project record."""
    import copy

    checks = []

    def check(name, condition):
        if not bool(condition):
            raise ValueError("step23_record_review_probe_failed:" + name)
        checks.append({"check": name, "status": "pass", "observed": "authored_review_metadata_only"})

    def rejection(name, function):
        try:
            function()
        except ValueError:
            check(name, True)
        else:
            check(name, False)

    target = {"review_target_id": "authored-review-target:one", "resource_family": "basketball_drills",
        "candidate_id": "authored-drill:one", "candidate_unit": "drill_or_warmup_candidate",
        "record_version_sha256": "a" * 64, "local_traceability_status": "verified_saved_artifact",
        "policy_metadata": {"record_kind": "basketball_drill", "membership_status": "verified_reference_candidate",
            "membership_verified": True, "record_version_sha256": "a" * 64, "source_preparation_verified": True,
            "source_identity_status": "pending", "source_version_status": "pending", "locator_status": "pending",
            "source_context_status": "pending", "permission_status": "pending", "reference_review_status": "pending",
            "reference_review_documented": False, "reference_review_version_matches": False}}
    source = {"review_target_id": target["review_target_id"], "local_artifact_path": "results/authored/metadata.csv",
        "local_artifact_sha256": "b" * 64, "local_record_locator": "candidate_id=authored-drill:one",
        "relationship_role": "authored_source_pointer", "source_url": "https://example.invalid/authored"}
    original = copy.deepcopy(target)
    work = prepare_step23_review_worklist([target])
    rows = work["worklist_records"]
    result = validate_step23_review_packet([target], [source], rows)
    check("one_pending_target_and_source_link_resolve", result["review_targets"] == result["source_links"] == 1)
    check("pending_worklist_creates_no_decision", work["actual_review_decisions_created"] == 0
          and rows[0]["actual_review_decision_id"] == rows[0]["reviewer"] == "")
    check("preparation_and_local_traceability_do_not_approve_reference", rows[0]["reference_eligible_by_metadata"] is False
          and rows[0]["queue_status"] == "pending_reference_review")
    check("pending_reference_does_not_approve_planner", rows[0]["planner_eligible_by_metadata"] is False
          and rows[0]["planner_assessment_status"] == "not_assessed_before_reference_eligibility")
    csv_rows = [{key: ("True" if value else "False") if type(value) is bool else value for key, value in row.items()}
                for row in rows]
    check("canonical_csv_boolean_readback_is_supported", validate_step23_review_packet([target], [source], csv_rows)["worklist_rows"] == 1)
    rejection("duplicate_target_id_rejected", lambda: prepare_step23_review_worklist([target, copy.deepcopy(target)]))
    other = copy.deepcopy(target)
    other["review_target_id"] = "authored-review-target:two"
    rejection("duplicate_candidate_different_target_id_rejected", lambda: prepare_step23_review_worklist([target, other]))
    rejection("missing_record_version_rejected", lambda: prepare_step23_review_worklist([dict(target, record_version_sha256="")]))
    changed = copy.deepcopy(target)
    changed["policy_metadata"]["record_version_sha256"] = "c" * 64
    rejection("policy_and_target_hash_mismatch_rejected", lambda: prepare_step23_review_worklist([changed]))
    for membership in ("protected_group", "excluded", "evaluation_material"):
        changed = copy.deepcopy(target)
        changed["policy_metadata"]["membership_status"] = membership
        rejection("protected_or_excluded_target_not_exported:" + membership,
                  lambda item=changed: prepare_step23_review_worklist([item]))
    for kind in ("structured_rule", "food_fact"):
        changed = copy.deepcopy(target)
        changed["policy_metadata"]["record_kind"] = kind
        rejection("structured_route_not_a_passage_review_target:" + kind,
                  lambda item=changed: prepare_step23_review_worklist([item]))
    rejection("orphan_source_link_rejected", lambda: validate_step23_review_packet([target], [dict(source, review_target_id="absent")], rows))
    rejection("source_less_target_rejected", lambda: validate_step23_review_packet([target], [], rows))
    rejection("duplicate_source_link_rejected", lambda: validate_step23_review_packet([target], [source, copy.deepcopy(source)], rows))
    rejection("unbound_source_hash_rejected", lambda: validate_step23_review_packet([target], [dict(source, local_artifact_sha256="")], rows))
    rejection("source_locator_required", lambda: validate_step23_review_packet([target], [dict(source, local_record_locator="")], rows))
    rejection("escaping_artifact_path_rejected", lambda: validate_step23_review_packet([target], [dict(source, local_artifact_path="../private.csv")], rows))
    source_two = dict(source, local_artifact_sha256="d" * 64, relationship_role="other")
    rejection("conflicting_source_artifact_hashes_rejected", lambda: validate_step23_review_packet([target], [source, source_two], rows))
    rejection("source_body_field_not_copied_to_target", lambda: prepare_step23_review_worklist([dict(target, instructions="Authored body")]))
    rejection("source_body_field_not_copied_to_links", lambda: validate_step23_review_packet([target], [dict(source, source_text="Authored body")], rows))
    rejection("pending_worklist_cannot_claim_a_reviewer", lambda: validate_step23_review_packet([target], [source], [dict(rows[0], reviewer="Invented review")]))
    rejection("pending_worklist_cannot_claim_a_decision", lambda: validate_step23_review_packet([target], [source], [dict(rows[0], actual_review_decision_id="invented")]))
    rejection("pending_worklist_cannot_flip_eligibility", lambda: validate_step23_review_packet([target], [source], [dict(rows[0], reference_eligible_by_metadata=True)]))
    rejection("noncanonical_boolean_does_not_clear_gate", lambda: validate_step23_review_packet([target], [source], [dict(csv_rows[0], reference_eligible_by_metadata="1")]))
    rejection("missing_worklist_rows_rejected", lambda: validate_step23_review_packet([target], [source], []))
    rejection("unexpected_worklist_columns_rejected", lambda: validate_step23_review_packet([target], [source], [dict(rows[0], acceptance="yes")]))
    rejection("target_cannot_create_actual_approval", lambda: prepare_step23_review_worklist([dict(target, actual_record_approval_created=True)]))
    ready = copy.deepcopy(target)
    ready["policy_metadata"].update(source_identity_status="verified", source_version_status="verified",
        locator_status="verified", source_context_status="preserved", permission_status="permitted",
        reference_review_status="accepted", reference_review_documented=True, reference_review_version_matches=True,
        reference_review_record_sha256="a" * 64, reference_review_decision_id="authored-decision:one",
        reference_review_evidence_id="authored-evidence:one")
    ready_work = prepare_step23_review_worklist([ready])
    check("supplied_ready_metadata_is_not_an_actual_adoption", ready_work["worklist_records"][0]["reference_eligible_by_metadata"] is True
          and ready_work["actual_record_approvals_created"] == 0
          and ready_work["worklist_records"][0]["actual_review_decision_id"] == "")
    rejected = copy.deepcopy(target)
    rejected["policy_metadata"]["permission_status"] = "denied"
    check("permission_denial_remains_blocked", prepare_step23_review_worklist([rejected])["worklist_records"][0]["queue_status"] == "blocked_reference_review")
    unproven = copy.deepcopy(target)
    unproven["policy_metadata"]["membership_verified"] = False
    check("unproven_membership_remains_deferred", prepare_step23_review_worklist([unproven])["worklist_records"][0]["queue_status"] == "deferred_membership_or_scope_review")
    instructions = step23_review_packet_instructions()
    check("template_does_not_contain_decisions_or_execute_intake", not instructions["decision_template_contains_actual_decisions"]
          and not instructions["decision_intake_or_adoption_executed"]
          and "record_version_sha256" in STEP23_REFERENCE_DECISION_COLUMNS)
    check("source_reference_and_planner_review_scopes_are_separate", "permitted_use" in STEP23_REFERENCE_REVIEW_SCOPES
          and "reference_use" in STEP23_REFERENCE_REVIEW_SCOPES and "planner_use" in STEP23_REFERENCE_REVIEW_SCOPES)
    check("targets_and_evidence_are_not_mutated", target == original and source["local_artifact_sha256"] == "b" * 64)
    return {"scenario_count": len(checks), "check_count": len(checks), "check_records": checks,
        "actual_record_approvals_created": 0, "actual_review_decisions_created": 0,
        "source_records_read": 0, "source_bodies_copied_to_packet": False,
        "corpus_records_admitted": 0, "model_or_vectorizer_operations": 0}


"""Bind publisher-evidence work to the saved, still-pending reference packet."""


def verify_step23_source_evidence_inputs(namespace):
    """Verify all saved packet dependencies without network, inference or adoption."""
    import hashlib
    import io
    import json
    import re
    from pathlib import Path, PurePosixPath
    import pandas as pd

    stage, checks = "completed_reference_review_packet", []

    def packed(value):
        return (json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n").encode("utf-8")

    def sha(value):
        return hashlib.sha256(value).hexdigest()

    def jsonl(value):
        return ("".join(json.dumps(row, ensure_ascii=False, sort_keys=True,
            separators=(",", ":"), allow_nan=False) + "\n" for row in value)).encode("utf-8")

    def check(name, condition, observed=True):
        nonlocal stage
        stage = name
        if not bool(condition):
            raise ValueError("source_evidence_preflight_condition_failed")
        checks.append({"check": name, "status": "pass", "observed": str(observed)})

    def json_object(content):
        def unique(items):
            value = {}
            for key, item in items:
                if key in value:
                    raise ValueError("duplicate_saved_source_evidence_json_key")
                value[key] = item
            return value
        value = json.loads(content, object_pairs_hook=unique,
            parse_constant=lambda _value: (_ for _ in ()).throw(ValueError("nonfinite_source_evidence_json")))
        if not isinstance(value, dict) or packed(value) != content:
            raise ValueError("noncanonical_saved_source_evidence_json")
        return value

    try:
        check("verified_record_review_packet_is_available", isinstance(namespace, dict)
              and namespace.get("step23_record_review_preparation_ready") is True
              and isinstance(namespace.get("step23_record_review_preparation"), dict))
        receipt = namespace["step23_record_review_preparation"]
        check("packet_preparation_has_not_become_review_or_corpus_approval", receipt.get("status")
              == "source_linked_reference_review_packets_saved_no_approvals_or_corpus_admission"
              and receipt.get("review_packet_preparation_complete") is True
              and receipt.get("actual_review_decisions_created") == receipt.get("corpus_records_admitted") == 0
              and receipt.get("operational_corpus_ready") is receipt.get("step23_complete") is False
              and callable(receipt.get("verify_unchanged")))
        receipt["verify_unchanged"]()
        root = Path(receipt["root"]).resolve(strict=True)
        upstream = receipt["preflight"]
        classifier = upstream["classifier"]
        sources = upstream["sources"]
        check("source_and_classifier_metadata_share_the_bound_project", root.is_dir()
              and root == Path(upstream["root"]).resolve(strict=True)
              == Path(classifier["root"]).resolve(strict=True) == Path(sources["root"]).resolve(strict=True)
              and callable(upstream.get("verify_unchanged")))

        def safe_path(relative):
            if not isinstance(relative, str) or not relative or "\\" in relative or ":" in relative:
                raise ValueError("unsafe_source_evidence_dependency")
            parsed, target = PurePosixPath(relative), root / relative
            if (parsed.is_absolute() or parsed.as_posix() != relative
                    or any(part in (".", "..") for part in parsed.parts)
                    or target.resolve() != target or not target.is_relative_to(root)
                    or target.is_symlink() or not target.is_file()):
                raise ValueError("unsafe_source_evidence_dependency")
            return target

        preparation_id = receipt["record_review_preparation_id"]
        match = re.fullmatch(r"retrieval-record-review:([0-9a-f]{64})", str(preparation_id))
        check("record_review_preparation_identifier_is_explicit", match is not None)
        prefix = "results/retrieval/record_review/review_" + match.group(1)[:16] + "/"
        filenames = {"reference_review_targets.jsonl", "reference_source_links.csv", "reference_review_worklist.csv",
                     "reference_review_decision_template.csv", "non_passage_routes.csv", "record_review_checks.csv"}
        producer_path = prefix + "step23_record_review_summary.json"
        producer_bytes = safe_path(producer_path).read_bytes()
        summary = json_object(producer_bytes)
        identity_keys = ("recipe_version", "implementation_sha256", "input_hashes", "input_preparation_id",
            "target_metadata_sha256", "source_relationships_sha256", "decision_template_columns", "review_instructions")
        identity = {key: summary[key] for key in identity_keys}
        check("saved_record_review_producer_matches_the_completed_receipt", summary == receipt["summary"]
              and summary["schema_version"] == "step23-record-review-preparation-producer-1"
              and summary["status"] == receipt["status"]
              and summary["recipe_version"] == "source-linked-record-review-preparation-0.1.0"
              and summary["record_review_preparation_id"] == preparation_id
              == "retrieval-record-review:" + sha(packed(identity)))
        check("all_six_packet_payloads_are_bound_by_the_final_producer",
              set(summary["output_hashes"]) == {prefix + name for name in filenames}
              and set(summary["output_hashes"]).isdisjoint(summary["input_hashes"])
              and producer_path not in summary["input_hashes"])
        saved_hashes = {**summary["output_hashes"], producer_path: sha(producer_bytes)}
        check("completed_packet_hashes_include_exactly_seven_outputs", saved_hashes == receipt["save"]["artifact_hashes"]
              and set(saved_hashes) == set(receipt["saved_files"]) and len(saved_hashes) == 7)
        prior_hashes = dict(summary["input_hashes"])
        check("all_prior_preparation_bindings_are_preserved", prior_hashes == receipt["input_hashes"]
              and len(prior_hashes) == summary["bound_inputs_reverified"] == 351
              and all(prior_hashes[key] == value for key, value in upstream["input_hashes"].items()))
        hashes = {**prior_hashes, **saved_hashes}
        check("all_358_saved_source_and_review_packet_files_are_unchanged", len(hashes) == 358
              and all(isinstance(digest, str) and re.fullmatch(r"[0-9a-f]{64}", digest)
                      and sha(safe_path(relative).read_bytes()) == digest for relative, digest in hashes.items()), len(hashes))
        def verify_packet_inventory():
            folder = safe_path(producer_path).parent
            return ({path.name for path in folder.iterdir()} == filenames | {"step23_record_review_summary.json"}
                    and all(path.is_file() and not path.is_symlink() for path in folder.iterdir()))
        check("packet_directory_contains_exactly_its_seven_canonical_files", verify_packet_inventory())

        target_path = prefix + "reference_review_targets.jsonl"
        target_bytes = safe_path(target_path).read_bytes()
        targets = [json.loads(line) for line in target_bytes.decode("utf-8").splitlines()]
        check("saved_target_rows_keep_their_exact_versions_and_canonical_jsonl", len(targets) == 2600
              and target_bytes == jsonl(targets)
              and sha(target_bytes) == summary["target_metadata_sha256"]
              and targets == receipt["target_records"])
        target_by_id = {row["review_target_id"]: row for row in targets}
        target_by_candidate = {row["candidate_id"]: row for row in targets}
        check("target_and_candidate_identifiers_are_unique", len(target_by_id) == len(target_by_candidate) == 2600)
        frames = {}
        for name in filenames - {"reference_review_targets.jsonl"}:
            frame = pd.read_csv(io.BytesIO(safe_path(prefix + name).read_bytes()), dtype=str,
                                keep_default_na=False, encoding="utf-8-sig")
            if not frame.columns.is_unique:
                raise ValueError("duplicate_saved_packet_columns")
            frames[name] = frame
        links = frames["reference_source_links.csv"]
        source_rows = links.to_dict("records")
        worklist = frames["reference_review_worklist.csv"]
        template = frames["reference_review_decision_template.csv"]
        non_passage = frames["non_passage_routes.csv"]
        saved_checks = frames["record_review_checks.csv"]
        validation = validate_step23_review_packet(targets, source_rows, worklist.to_dict("records"))
        check("saved_source_relationship_graph_and_worklist_still_resolve", validation["review_targets"] == 2600
              and validation["source_links"] == len(links) == summary["source_relationships"] == 2634
              and validation["worklist_rows"] == len(worklist) == summary["worklist_rows"] == 2600
              and validation["every_target_has_source_links"] is True
              and validation["actual_review_decisions_created"] == validation["corpus_records_admitted"] == 0)
        check("all_local_source_links_are_bound_to_saved_artifact_versions", all(
            row["local_artifact_path"] in prior_hashes
            and row["local_artifact_sha256"] == prior_hashes[row["local_artifact_path"]]
            for row in source_rows))
        check("saved_original_relationship_identity_is_preserved", summary["source_relationships_sha256"]
              == sha(packed(receipt["source_evidence_records"])))
        check("no_human_review_or_permission_adoption_is_in_the_pending_packet", len(template) == summary["decision_template_rows"] == 0
              and template.columns.tolist() == summary["decision_template_columns"]
              and validation["status_counts"] == summary["metadata_status_counts"]
              and summary["metadata_status_counts"]["reference_disposition_counts"] == {"pending": 2588, "deferred": 12}
              and summary["metadata_status_counts"]["reference_eligible_by_supplied_metadata"]
              == summary["metadata_status_counts"]["planner_eligible_by_supplied_metadata"] == 0
              and worklist["actual_review_decision_id"].eq("").all()
              and worklist["reviewer"].eq("").all() and worklist["reviewed_at"].eq("").all())
        check("source_review_packet_checks_and_non_passage_routes_are_preserved", len(saved_checks)
              == summary["saved_checks"] == 83 and saved_checks["status"].eq("pass").all()
              and len(non_passage) == 13
              and summary["artificial_packet_scenarios"] == summary["artificial_packet_checks"] == 36
              and summary["project_policy_and_user_constraint_templates_routed_separately"] == 12)
        zero_fields = ("actual_source_verification_decisions", "actual_permission_decisions", "actual_reference_use_reviews",
            "actual_planner_reviews", "actual_review_decisions_created", "corpus_records_admitted", "model_loads",
            "classifier_predictions", "vectorizer_fits", "embedding_operations", "model_downloads", "new_model_training",
            "passages_created", "evidence_units_created", "retrieval_requests", "questions_created", "judgments_created")
        check("prepared_metadata_has_not_become_admission_or_execution", all(summary[key] == 0 for key in zero_fields)
              and summary["source_bodies_or_classifier_scores_copied_to_packets"] is False
              and summary["source_refresh_or_network_access_performed"] is False
              and summary["decision_intake_or_adoption_executed"] is summary["operational_corpus_ready"] is summary["step23_complete"] is False
              and summary["global_retrieval_eligible_records"] is None)
        private = upstream["private_boundary"]
        check("protected_and_excluded_classifier_records_remain_outside_review_targets",
              len(private["protected_catalog_ids"]) == 439 and len(private["protected_group_ids"]) == 385
              and len(private["other_excluded_catalog_ids"]) == 36
              and all(row["candidate_id"] not in private["protected_catalog_ids"]
                      and row["candidate_id"] not in private["other_excluded_catalog_ids"] for row in targets)
              and summary["protected_classifier_text_transformed_or_predicted"] is False)

        metadata = {"summary": summary, "input_hashes": hashes, "targets": targets,
                    "target_by_id": target_by_id, "target_by_candidate": target_by_candidate,
                    "saved_source_link_records": source_rows,
                    "source_relationships": receipt["source_evidence_records"]}
        metadata_digest = sha(packed(metadata))
        frame_digests = {key: sha(value.to_csv(index=False, lineterminator="\n").encode("utf-8")) for key, value in frames.items()}
        def private_snapshot():
            return {key: list(value) if isinstance(value, tuple) else sorted(value) for key, value in private.items()}
        private_digest = sha(packed(private_snapshot()))

        def verify_unchanged():
            receipt["verify_unchanged"]()
            if (sha(packed(metadata)) != metadata_digest or sha(packed(private_snapshot())) != private_digest
                    or any(sha(safe_path(relative).read_bytes()) != digest for relative, digest in hashes.items())
                    or any(sha(frame.to_csv(index=False, lineterminator="\n").encode("utf-8")) != frame_digests[key]
                           for key, frame in frames.items()) or not verify_packet_inventory()):
                raise RuntimeError("step23_source_evidence_preflight_failed:verified_packet_or_source_bindings_changed")
            return True

        check("source_evidence_preflight_is_read_only_and_stable", verify_unchanged())
        return {"status": "verified_pending_record_review_packet_for_source_evidence_work", "root": root,
            "summary": summary, "record_review_preparation_id": preparation_id,
            "prior_receipt": receipt, "preflight": upstream,
            "input_preparation": upstream["input_preparation"], "input_preparation_summary": upstream["summary"],
            "planned_contract": upstream["planned_contract"], "classifier": classifier,
            "sources": sources, "source_inventory": sources, "source_receipts": sources["source_receipts"],
            "input_hashes": hashes, "targets": targets, "target_records": targets,
            "target_by_id": target_by_id, "target_by_candidate": target_by_candidate,
            "source_links": links, "source_evidence_records": source_rows,
            "worklist": worklist, "decision_template": template, "non_passage_routes": non_passage,
            "saved_packet_checks": saved_checks, "frames": frames,
            "private_boundary": private, "population_boundary": upstream["population_boundary"],
            "checks": pd.DataFrame(checks), "check_records": checks, "verify_unchanged": verify_unchanged,
            "models_loaded": 0, "new_predictions": 0, "network_requests": 0,
            "source_or_review_decisions_created": 0, "corpus_records_admitted": 0,
            "test_text_processed": False, "files_changed": False}
    except Exception as error:
        message = str(error)
        if message.startswith(("step23_", "step22_")):
            raise RuntimeError(message) from None
        raise RuntimeError("step23_source_evidence_preflight_failed:" + stage) from None


"""Capture three official CDC pages as scoped evidence, never as an approval."""

STEP23_CDC_SOURCE_URLS = {
    "cdc_sleep_about": "https://www.cdc.gov/sleep/about/",
    "cdc_agency_materials": "https://www.cdc.gov/other/agencymaterials.html",
    "cdc_generative_ai": "https://www.cdc.gov/other/generative-ai.html",
}

# These identities describe the critical source/context and policy text reviewed
# while this recipe was authored. A changed projection requires another review.
STEP23_CDC_REVIEWED_PROJECTION_SHA256 = {
    "cdc_sleep_about": "0ae454350bafffa1f7ceea2860171c3caf1fded9ca01ae64a62ee45acb5453cb",
    "cdc_agency_materials": "8aa8bc5a45dc6cb946cb2cfb2ffeef1e05a61d42ecafe29c3488a151db749e6e",
    "cdc_generative_ai": "d199c7c99eb5e059cadb4250703289a598503a91725517e623e0f9cfe987c33b",
}

STEP23_CDC_CAPTURE_PATHS = {
    "cdc_sleep_about": ("captures/cdc_sleep.html", "representations/cdc_sleep_scoped.txt"),
    "cdc_agency_materials": ("captures/cdc_material_use_policy.html", "representations/cdc_material_use_policy_scoped.txt"),
    "cdc_generative_ai": ("captures/cdc_generative_ai.html", "representations/cdc_generative_ai_scoped.txt"),
}


def _step233_cdc_packed(value):
    import json
    return (json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2,
                       allow_nan=False) + "\n").encode("utf-8")


def _step233_cdc_sha(value):
    import hashlib
    return hashlib.sha256(value).hexdigest()


def _step233_cdc_normalize(value):
    import re
    return re.sub(r"\s+", " ", value).strip()


def _step233_cdc_parse_html(content):
    """Build a small HTML tree with standard-library parsing only."""
    from html.parser import HTMLParser

    class Parser(HTMLParser):
        void = {"area", "base", "br", "col", "embed", "hr", "img", "input",
                "link", "meta", "param", "source", "track", "wbr"}

        def __init__(self):
            super().__init__(convert_charrefs=True)
            self.root = {"tag": "document", "attrs": {}, "children": []}
            self.stack = [self.root]

        def handle_starttag(self, tag, attrs):
            node = {"tag": tag, "attrs": dict(attrs), "children": []}
            self.stack[-1]["children"].append(node)
            if tag not in self.void:
                self.stack.append(node)

        def handle_startendtag(self, tag, attrs):
            self.handle_starttag(tag, attrs)
            if tag not in self.void:
                self.handle_endtag(tag)

        def handle_endtag(self, tag):
            for index in range(len(self.stack) - 1, 0, -1):
                if self.stack[index]["tag"] == tag:
                    del self.stack[index:]
                    break

        def handle_data(self, data):
            self.stack[-1]["children"].append(data)

    if type(content) is not bytes or not content or len(content) > 2_000_000:
        raise ValueError("invalid_cdc_html_payload")
    parser = Parser()
    parser.feed(content.decode("utf-8-sig", errors="strict"))
    parser.close()
    return parser.root


def _step233_cdc_nodes(node, predicate):
    found = []
    if isinstance(node, dict):
        if predicate(node):
            found.append(node)
        for child in node["children"]:
            found.extend(_step233_cdc_nodes(child, predicate))
    return found


def _step233_cdc_text(node, exclude=()):
    if isinstance(node, str):
        return node
    if node["tag"] in set(exclude) | {"script", "style", "svg"}:
        return ""
    return " ".join(_step233_cdc_text(child, exclude) for child in node["children"])


def _step233_cdc_single(values, stage):
    if len(values) != 1:
        raise ValueError("cdc_capture_ambiguous_or_missing:" + stage)
    return values[0]


def _step233_cdc_extract_sleep(tree):
    main = _step233_cdc_single(_step233_cdc_nodes(tree,
        lambda node: node["tag"] == "main"), "sleep_main")
    title = _step233_cdc_single(_step233_cdc_nodes(main,
        lambda node: node["tag"] == "h1"), "sleep_title")
    if _step233_cdc_normalize(_step233_cdc_text(title)) != "About Sleep":
        raise ValueError("cdc_sleep_title_changed")
    sections = _step233_cdc_nodes(main, lambda node: node["tag"] == "div"
        and "dfe-section" in node["attrs"].get("class", "").split())

    def section(heading):
        return _step233_cdc_single([node for node in sections if any(
            _step233_cdc_normalize(_step233_cdc_text(h)) == heading
            for h in _step233_cdc_nodes(node, lambda n: n["tag"] == "h2"))], heading)

    enough, quality, management = section("Getting enough sleep"), section("Sleep quality"), section("Management")
    introduction = _step233_cdc_single([_step233_cdc_normalize(_step233_cdc_text(node))
        for node in _step233_cdc_nodes(enough, lambda n: n["tag"] == "p")
        if _step233_cdc_normalize(_step233_cdc_text(node)).startswith("The daily recommended hours")],
        "sleep_daily_introduction")
    tables = _step233_cdc_nodes(enough, lambda node: node["attrs"].get("role") == "table")
    table = _step233_cdc_single(tables, "sleep_age_table")
    rows = _step233_cdc_nodes(table, lambda node: node["attrs"].get("role") == "row")
    cells = [[_step233_cdc_normalize(_step233_cdc_text(cell, exclude=("sup",)))
              for cell in _step233_cdc_nodes(row, lambda node: node["attrs"].get("role") == "cell")]
             for row in rows]
    if not cells or cells[0] != ["Age Group", "Age", "Sleep Recommended Daily"]:
        raise ValueError("cdc_sleep_table_headers_changed")
    teen = _step233_cdc_single([row for row in cells[1:] if row and row[0] == "Teen"], "teen_row")
    if teen != ["Teen", "13–17 years", "8–10 hours"]:
        raise ValueError("cdc_sleep_teen_recommendation_changed")
    teen_node = _step233_cdc_single([node for node, row in zip(rows, cells) if row == teen], "teen_node")
    footnotes = _step233_cdc_nodes(teen_node, lambda node: node["tag"] == "a"
        and node["attrs"].get("href", "").endswith("#cdcreference_2"))
    if len(footnotes) != 1:
        raise ValueError("cdc_sleep_teen_source_footnote_changed")
    quality_text = _step233_cdc_normalize(_step233_cdc_text(_step233_cdc_single(
        [node for node in _step233_cdc_nodes(quality, lambda n: n["tag"] == "p")
         if _step233_cdc_normalize(_step233_cdc_text(node)).startswith("Quality sleep means")], "quality_context")))
    provider_text = _step233_cdc_normalize(_step233_cdc_text(_step233_cdc_single(
        [node for node in _step233_cdc_nodes(management, lambda n: n["tag"] == "p")
         if _step233_cdc_normalize(_step233_cdc_text(node)).startswith("Talk to your healthcare provider")], "provider_context")))
    references = _step233_cdc_single(_step233_cdc_nodes(main,
        lambda node: node["tag"] == "ul" and node["attrs"].get("id") == "page_sources"), "source_references")
    pediatric = _step233_cdc_single([_step233_cdc_normalize(_step233_cdc_text(node))
        for node in _step233_cdc_nodes(references, lambda n: n["tag"] == "li")
        if _step233_cdc_normalize(_step233_cdc_text(node)).startswith("Paruthi S,")], "pediatric_citation")
    if "American Academy of Sleep Medicine" not in pediatric or "2016;12(6):785–786." not in pediatric:
        raise ValueError("cdc_sleep_pediatric_citation_changed")
    meta = _step233_cdc_nodes(tree, lambda node: node["tag"] == "meta"
        and node["attrs"].get("property") == "cdc:last_updated")
    updated = _step233_cdc_single(meta, "sleep_updated_metadata")["attrs"].get("content", "")
    if updated != "May 15, 2024":
        raise ValueError("cdc_sleep_update_date_requires_review")
    content_source = _step233_cdc_single([_step233_cdc_normalize(_step233_cdc_text(node))
        for node in _step233_cdc_nodes(main, lambda n: n["tag"] == "a")
        if node["attrs"].get("href") == "/nccdphp/index.html"], "cdc_content_source")
    projection = {"title": "About Sleep", "displayed_updated": updated,
        "daily_table_heading": cells[0], "daily_introduction": introduction, "teen_row": teen,
        "quality_context": quality_text, "provider_context": provider_text,
        "pediatric_source_citation": pediatric, "content_source": content_source,
        "complete_sleep_age_table": cells,
        "main_article_sections": [_step233_cdc_normalize(_step233_cdc_text(node)) for node in sections]}
    representation = ("About Sleep — CDC\nDisplayed update: " + updated
        + "\nGetting enough sleep\n" + introduction + "\n"
        + " | ".join(cells[0]) + "\n" + " | ".join(teen)
        + "\nSleep quality\n" + quality_text + "\nManagement\n" + provider_text
        + "\nSource footnote 2: Paruthi et al., AASM pediatric consensus, 2016.\n")
    if len(representation.split()) > 120:
        raise ValueError("cdc_sleep_scoped_representation_too_long")
    scoped_lower = representation.casefold()
    if any(marker in scoped_lower for marker in ("copyright", "all rights reserved", "permission required",
                                                 "reproduction prohibited", "do not reproduce")):
        raise ValueError("cdc_sleep_scoped_rights_statement_requires_review")
    observation = {"publisher": "Centers for Disease Control and Prevention",
        "content_source": content_source, "page_title": "About Sleep", "displayed_updated": updated,
        "section_locator": "Getting enough sleep > Sleep Recommended Daily > Teen",
        "age_min_years": 13, "age_max_years": 17, "hours_min": 8, "hours_max": 10,
        "time_basis": "daily", "sleep_quality_qualification_preserved": True,
        "persistent_sleep_problem_provider_context_preserved": True,
        "underlying_citation": pediatric, "underlying_article_itself_captured": False,
        "scope_is_general_reference_not_individual_prescription": True,
        "observed_no_rights_statement_in_scoped_text": True,
        "scoped_text_contains_no_images_logos_or_third_party_article_body": True,
        "rights_observation_is_not_a_blanket_page_public_domain_finding": True,
        "full_publisher_page_context_in_raw_capture": True}
    return projection, representation.encode("utf-8"), observation


def _step233_cdc_extract_policy(tree):
    import re
    main = _step233_cdc_single(_step233_cdc_nodes(tree,
        lambda node: node["tag"] == "main"), "policy_main")
    titles = _step233_cdc_nodes(main, lambda node: node["tag"] == "h1")
    title = _step233_cdc_normalize(_step233_cdc_text(_step233_cdc_single(titles, "policy_title")))
    if title != "Use of Agency Materials":
        raise ValueError("cdc_agency_materials_title_changed")
    paragraphs = [_step233_cdc_normalize(_step233_cdc_text(node))
                  for node in _step233_cdc_nodes(main, lambda n: n["tag"] == "p")]

    def starting(prefix):
        return _step233_cdc_single([value for value in paragraphs if value.startswith(prefix)], prefix)

    public_domain = starting("Most of the information on the CDC and ATSDR websites")
    exceptions = starting("There are, however, a few exceptions.")
    numbered = [value for value in paragraphs if re.match(r"^[1-9][0-9]*\)", value)]
    if len(numbered) != 4 or [row[:2] for row in numbered] != ["1)", "2)", "3)", "4)"]:
        raise ValueError("cdc_policy_numbered_conditions_changed")
    required = (("Attribution to the agency",), ("does not imply endorsement", "prominently and unambiguously displayed"),
                ("may not change the substantive content",), ("agency website for no charge",))
    for paragraph, phrases in zip(numbered, required):
        if not all(phrase in paragraph for phrase in phrases):
            raise ValueError("cdc_policy_required_condition_changed")
    if not all(phrase in exceptions for phrase in (
            "licensed by a third party", "works of state and local governments", "copyright laws also differ internationally")):
        raise ValueError("cdc_policy_exception_context_changed")
    logos = starting("The CDC and/or ATSDR logo")
    if "may not be used without express written permission" not in logos:
        raise ValueError("cdc_policy_logo_condition_changed")
    revisions = starting("Note: Many of CDC’s on-line publications")
    linking = starting("Linking to CDC, ATSDR or HHS content")
    if not all(phrase in linking for phrase in ("new browser window", "should not appear within the original window")):
        raise ValueError("cdc_policy_linking_context_changed")
    projection = {"title": title, "public_domain_statement": public_domain,
        "exceptions": exceptions, "numbered_conditions": numbered, "logo_condition": logos,
        "revision_and_link_preference": revisions, "linking_condition": linking,
        "complete_main_policy_paragraphs": paragraphs}
    # Selected source sentences are bounded excerpts; the complete clauses and
    # exceptions remain present in the separately retained raw source capture.
    short_one = numbered[0].split(" Such attribution", 1)[0]
    short_two = numbered[1].split(" (e.g.,", 1)[0]
    representation = (title + " — selected public-domain-content requirements\n"
        + short_one + "\n" + short_two + "\n" + numbered[2] + "\n" + numbered[3] + "\n")
    if len(representation.split()) > 140:
        raise ValueError("cdc_policy_scoped_representation_too_long")
    observation = {"publisher": "Centers for Disease Control and Prevention", "page_title": title,
        "section_locator": "Public-domain content requirements, exceptions, links and CDC logo restrictions",
        "public_domain_statement_is_qualified_not_blanket": True,
        "required_conditions": ["credit_CDC", "prominent_unambiguous_nonendorsement_disclaimer",
            "do_not_change_substantive_content", "state_free_availability_on_CDC_website"],
        "exceptions": ["third_party_or_licensed_content", "contractor_or_grantee_content",
            "state_or_local_government_works", "international_rights_not_resolved"],
        "logos_and_images_excluded_from_proposed_scope": True,
        "third_party_article_text_excluded_from_proposed_scope": True,
        "links_open_new_window_without_framing": True,
        "direct_link_and_revision_check_context_preserved": True,
        "permission_decision_created": False, "legal_clearance_claimed": False}
    return projection, representation.encode("utf-8"), observation


def _step233_cdc_extract_ai(tree):
    main = _step233_cdc_single(_step233_cdc_nodes(tree,
        lambda node: node["tag"] == "main"), "ai_addendum_main")
    title = _step233_cdc_normalize(_step233_cdc_text(_step233_cdc_single(
        _step233_cdc_nodes(main, lambda node: node["tag"] == "h1"), "ai_addendum_title")))
    if title != "CDC.gov & Generative Super Intelligence":
        raise ValueError("cdc_ai_addendum_title_changed")
    paragraph = _step233_cdc_single([_step233_cdc_normalize(_step233_cdc_text(node))
        for node in _step233_cdc_nodes(main, lambda n: n["tag"] == "p")
        if _step233_cdc_normalize(_step233_cdc_text(node)).startswith("CDC sometimes uses GenSI")],
        "ai_addendum_content")
    if not all(phrase in paragraph for phrase in ("our experts review our communication materials",
            "before use", "separate agency review process prior to release")):
        raise ValueError("cdc_ai_addendum_review_context_changed")
    projection = {"title": title, "agency_content_process_paragraph": paragraph,
        "complete_main_addendum_paragraphs": [_step233_cdc_normalize(_step233_cdc_text(node))
            for node in _step233_cdc_nodes(main, lambda n: n["tag"] == "p")]}
    expert_review = paragraph[paragraph.index("In every case,"):]
    representation = title + "\nAgency content process — selected source sentences\n" + expert_review + "\n"
    if len(representation.split()) > 80:
        raise ValueError("cdc_ai_addendum_scoped_representation_too_long")
    observation = {"publisher": "Centers for Disease Control and Prevention", "page_title": title,
        "section_locator": "Agency GenSI-assisted public communication and review process",
        "agency_reports_assisted_content_creation": True,
        "agency_reports_expert_communication_review_before_use": True,
        "research_data_recommendations_have_separate_agency_review": True,
        "page_is_not_a_third_party_reuse_license": True,
        "third_party_reuse_grant_inferred": False, "permission_decision_created": False,
        "no_change_to_agency_materials_conditions_inferred": True}
    return projection, representation.encode("utf-8"), observation


def fetch_step23_cdc_documents():
    """GET only the three named public CDC pages; send no study identifiers."""
    from datetime import datetime, timezone
    from urllib.parse import urlsplit
    import urllib.request

    def allowed(url):
        parts = urlsplit(url)
        return (parts.scheme == "https" and parts.hostname in {"www.cdc.gov", "cdc.gov"}
                and parts.port in (None, 443) and parts.username is None and parts.password is None)

    class OfficialRedirect(urllib.request.HTTPRedirectHandler):
        def redirect_request(self, request, fp, code, msg, headers, newurl):
            if not allowed(newurl):
                raise ValueError("cdc_capture_redirect_left_official_https_host")
            return super().redirect_request(request, fp, code, msg, headers, newurl)

    opener = urllib.request.build_opener(OfficialRedirect())
    documents = []
    for key, url in STEP23_CDC_SOURCE_URLS.items():
        print("Capturing official CDC source: " + key, flush=True)
        request = urllib.request.Request(url, headers={"User-Agent": "Champion-Athletic-MAP-Source-Verification/1.0"})
        with opener.open(request, timeout=15) as response:
            resolved = response.geturl()
            content_type = response.headers.get("Content-Type", "")
            if response.status != 200 or not allowed(resolved) or not content_type.lower().startswith("text/html"):
                raise ValueError("cdc_capture_unexpected_official_response")
            length = response.headers.get("Content-Length")
            if length is not None and int(length) > 2_000_000:
                raise ValueError("cdc_capture_response_too_large")
            payload = response.read(2_000_001)
            if not payload or len(payload) > 2_000_000:
                raise ValueError("cdc_capture_response_too_large_or_empty")
            headers = {name: response.headers.get(name) for name in ("Content-Type", "Last-Modified", "ETag")
                       if response.headers.get(name) is not None}
        documents.append({"document_key": key, "requested_url": url, "resolved_url": resolved,
            "http_status": 200, "content_type": content_type,
            "observed_at": datetime.now(timezone.utc).isoformat(), "response_headers": headers,
            "raw_html": payload})
    return documents


def verify_step23_cdc_capture(raw_documents):
    """Verify scoped representations against this recipe's reviewed projection."""
    import copy
    from datetime import datetime
    from urllib.parse import urlsplit

    if not isinstance(raw_documents, list) or len(raw_documents) != 3:
        raise ValueError("cdc_capture_requires_three_documents")
    by_key = {}
    for document in raw_documents:
        if not isinstance(document, dict) or document.get("document_key") in by_key:
            raise ValueError("duplicate_or_invalid_cdc_capture")
        key = document.get("document_key")
        if key not in STEP23_CDC_SOURCE_URLS or document.get("requested_url") != STEP23_CDC_SOURCE_URLS[key]:
            raise ValueError("cdc_capture_unexpected_requested_url")
        resolved = urlsplit(document.get("resolved_url", ""))
        if (resolved.scheme != "https" or resolved.hostname not in {"www.cdc.gov", "cdc.gov"}
                or resolved.port not in (None, 443) or resolved.username or resolved.password
                or document.get("http_status") != 200
                or not str(document.get("content_type", "")).lower().startswith("text/html")):
            raise ValueError("cdc_capture_response_identity_invalid")
        instant = datetime.fromisoformat(str(document.get("observed_at", "")).replace("Z", "+00:00"))
        if instant.tzinfo is None or instant.utcoffset() is None:
            raise ValueError("cdc_capture_observation_date_requires_timezone")
        by_key[key] = document
    if set(by_key) != set(STEP23_CDC_SOURCE_URLS):
        raise ValueError("cdc_capture_documents_missing")
    captures, raw_payloads, text_payloads, checks = [], {}, {}, []
