"""Bind a pending basketball source review to saved development-only metadata."""


def _step237_packed(value):
    import json
    return (json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n").encode("utf-8")


def _step237_sha(content):
    import hashlib
    return hashlib.sha256(content).hexdigest()


def verify_step237_basketball_inputs(namespace):
    import copy
    import csv
    import io
    import json
    import re
    from pathlib import Path, PurePosixPath
    checks = []

    def check(name, condition, observed=True):
        if not bool(condition):
            raise RuntimeError("step23_basketball_review_preflight_failed:" + name)
        checks.append({"check": name, "status": "pass", "observed": str(observed)})

    def decode(content):
        def unique(pairs):
            row = {}
            for key, value in pairs:
                if key in row:
                    raise ValueError("duplicate_basketball_input_json_key")
                row[key] = value
            return row
        return json.loads(content.decode("utf-8"), object_pairs_hook=unique,
            parse_constant=lambda value: (_ for _ in ()).throw(ValueError("nonfinite_input_json")))

    check("completed_passage_receipt_is_available", namespace.get("step23_reference_passages_ready") is True
          and isinstance(namespace.get("step23_reference_passages"), dict))
    receipt = namespace["step23_reference_passages"]
    check("passage_receipt_is_verified_without_operational_readiness", receipt.get("passage_preparation_verified") is True
          and receipt.get("step23_complete") is receipt.get("operational_retrieval_ready") is False
          and receipt.get("passages_prepared") == 1 and callable(receipt.get("verify_unchanged")))
    receipt["verify_unchanged"]()
    root = Path(receipt["root"]).resolve(strict=True)

    def safe_path(relative):
        if not isinstance(relative, str) or not relative or "\\" in relative or ":" in relative:
            raise RuntimeError("step23_basketball_review_preflight_failed:unsafe_dependency_path")
        parsed, path = PurePosixPath(relative), root / relative
        if (parsed.is_absolute() or parsed.as_posix() != relative or any(p in (".", "..") for p in parsed.parts)
                or path.resolve() != path or not path.is_file() or path.is_symlink()):
            raise RuntimeError("step23_basketball_review_preflight_failed:unsafe_dependency_path")
        return path

    summary = copy.deepcopy(receipt["summary"])
    preparation_id = summary["passage_preparation_id"]
    match = re.fullmatch(r"passage-preparation:([0-9a-f]{64})", preparation_id)
    check("passage_preparation_identifier_has_the_saved_shape", match is not None
          and receipt["passage_preparation_id"] == preparation_id)
    prefix = "artifacts/retrieval/passages/passages_" + match.group(1)[:16] + "/"
    marker = prefix + "step23_passage_preparation_summary.json"
    producer_bytes = safe_path(marker).read_bytes()
    check("saved_passage_producer_is_canonical_and_matches_this_kernel", decode(producer_bytes) == summary
          and _step237_packed(summary) == producer_bytes
          and summary["schema_version"] == "step23-passage-preparation-producer-1"
          and summary["recipe_version"] == "intact-reviewed-reference-passage-sizing-0.1.0")
    identity_keys = ("recipe_version", "implementation_sha256", "input_hashes", "semantic_runtime_adoption_id",
        "evidence_unit_preparation_id", "reference_unit_id", "source_unit_record_sha256",
        "source_delivery_bundle_record_sha256", "tokenizer_worker_sha256",
        "encoded_core_cap_including_heading_and_special_tokens", "nominal_passage_target",
        "intact_short_source_exception_allowed", "required_delivery_policy", "generation_context_token_budget_assessed",
        "embedding_or_index_creation_executed")
    identity = {key: summary[key] for key in identity_keys}
    check("passage_identity_reproduces_the_saved_recipe", preparation_id
          == "passage-preparation:" + _step237_sha(_step237_packed(identity)))
    members = {"retrieval_passages.jsonl", "source_aliases.csv", "required_delivery_bundles.jsonl",
        "tokenizer_measurements.json", "tokenizer_worker.py", "passage_checks.csv", "passage_manifest.json"}
    check("passage_producer_binds_exactly_seven_payloads", set(summary["output_hashes"])
          == {prefix + name for name in members} and set(summary["input_hashes"]).isdisjoint(summary["output_hashes"]))
    passage_hashes = {**summary["output_hashes"], marker: _step237_sha(producer_bytes)}
    check("all_eight_passage_outputs_match_the_completed_receipt", passage_hashes == receipt["save"]["artifact_hashes"]
          and set(passage_hashes) == set(receipt["saved_files"]))
    hashes = {**summary["input_hashes"], **passage_hashes}
    check("all_396_prior_files_remain_byte_unchanged", len(summary["input_hashes"]) == 388
          and summary["input_hashes"] == receipt["input_hashes"] and len(hashes) == 396
          and all(isinstance(digest, str) and re.fullmatch(r"[0-9a-f]{64}", digest)
              and _step237_sha(safe_path(relative).read_bytes()) == digest for relative, digest in hashes.items()), len(hashes))
    check("passage_directory_has_no_unbound_extras", {p.name for p in (root / prefix).iterdir()}
          == members | {"step23_passage_preparation_summary.json"})
    check("existing_sleep_only_coverage_and_budgets_remain_separate", summary["passages_prepared"] == 1
          and summary["underlying_source_units"] == 1 and summary["source_alias_rows"] == 2
          and summary["reference_core_encoded_tokens_including_specials"] == 87
          and summary["complete_delivery_minilm_tokens_including_specials"] == 241
          and summary["encoded_core_cap_including_heading_and_special_tokens"] == 200
          and summary["generation_context_token_budget_assessed"] is False
          and summary["generation_context_budget_remains_step24_work"] is True)
    check("no_existing_retrieval_or_final_evaluation_is_inferred", summary["corpus_embeddings_created"]
          == summary["retrieval_indexes_created"] == summary["retrieval_requests"]
          == summary["questions_or_judgments_created"] == summary["human_reviews_created"] == 0
          and summary["protected_classifier_text_transformed_or_predicted"] is False
          and summary["operational_retrieval_ready"] is summary["step23_complete"] is False)
    packets = [p for p in hashes if re.fullmatch(r"results/retrieval/record_review/review_[0-9a-f]{16}/step23_record_review_summary.json", p)]
    check("one_exact_saved_reference_packet_is_bound", len(packets) == 1)
    packet_summary = decode(safe_path(packets[0]).read_bytes())
    packet_prefix = str(PurePosixPath(packets[0]).parent) + "/"
    check("packet_payload_hashes_are_already_bound_by_the_passage_chain", packet_summary["schema_version"]
          == "step23-record-review-preparation-producer-1" and all(hashes.get(p) == h for p, h in packet_summary["output_hashes"].items()))
    targets = [decode(line) for line in safe_path(packet_prefix + "reference_review_targets.jsonl").read_bytes().splitlines()]
    links = list(csv.DictReader(io.StringIO(safe_path(packet_prefix + "reference_source_links.csv").read_text(encoding="utf-8"))))
    basketball = [row for row in targets if row["resource_family"] == "basketball_drills"]
    check("packet_population_units_remain_distinct", len(targets) == 2600 and len(links) == 2634
          and len(basketball) == 144 and sum(row["resource_family"] == "basketball_drills" for row in links) == 156)
    check("warmup_membership_deferrals_remain_in_place", sum(row["policy_metadata"]["membership_verified"] is True
          for row in basketball) == 132 and sum(row["policy_metadata"]["membership_status"] == "unproven" for row in basketball) == 12)
    candidates = {row["candidate_id"]: row for row in basketball}
    chosen = list(_STEP237_SELECTED_CANDIDATES)
    check("the_fixed_twenty_target_subset_is_present_without_substitution", len(chosen) == len(set(chosen)) == 20
          and set(chosen) <= set(candidates))
    selected = [copy.deepcopy(candidates[key]) for key in chosen]
    selected_ids = {row["review_target_id"] for row in selected}
    relationships = [copy.deepcopy(row) for row in links if row["review_target_id"] in selected_ids]
    for row in selected:
        validate_step237_review_target(row)
    check("only_verified_public_basketball_metadata_is_selected", len(relationships) == 21
          and all(row["policy_metadata"]["membership_verified"] is True for row in selected)
          and not any(row["candidate_unit"] == "general_warmup_candidate" for row in selected))
    check("each_source_relationship_matches_its_exact_parent_version", all(
        row["resource_family"] == "basketball_drills" and row["candidate_id"]
            == candidates[row["candidate_id"]]["candidate_id"]
        and row["review_target_id"] == candidates[row["candidate_id"]]["review_target_id"]
        and hashes.get(row["local_artifact_path"]) == row["local_artifact_sha256"] for row in relationships))
    allowed_urls = {"https://jr.nba.com/basketball-practice-plans/starter/",
        "https://jr.nba.com/basketball-practice-plans/starter/page/2/",
        "https://jr.nba.com/basketball-practice-plans/starter/page/3/"}
    check("all_selected_locators_are_the_three_recorded_plan_pages", {r["source_url"] for r in relationships} == allowed_urls)
    snapshot = {"summary": summary, "hashes": hashes, "selected": selected, "relationships": relationships,
        "packet_summary": packet_summary}
    frozen = _step237_sha(_step237_packed(snapshot))

    def verify_unchanged():
        if (_step237_sha(_step237_packed(snapshot)) != frozen
                or any(_step237_sha(safe_path(p).read_bytes()) != h for p, h in hashes.items())):
            raise RuntimeError("step23_basketball_review_preflight_failed:earlier_files_or_prepared_metadata_changed")
        return True

    verify_unchanged()
    return {"root": root, "input_hashes": hashes, "passage_preparation_id": preparation_id,
        "record_review_preparation_id": packet_summary["record_review_preparation_id"],
        "selected_targets": selected, "source_relationships": relationships,
        "checks": checks, "verify_unchanged": verify_unchanged}


def validate_step237_review_target(target):
    import re
    if not isinstance(target, dict):
        raise ValueError("basketball_target_not_a_record")
    policy = target.get("policy_metadata", {})
    if (target.get("resource_family") != "basketball_drills"
            or target.get("candidate_unit") != "basketball_drill_candidate"
            or target.get("local_candidate_membership_verified") is not True
            or target.get("protected_group_screening_status") != "record_type_is_public_basketball_or_guideline_reference_candidate"
            or policy.get("membership_verified") is not True
            or policy.get("membership_status") != "verified_reference_candidate"
            or policy.get("record_kind") != "basketball_drill"
            or policy.get("record_version_sha256") != target.get("record_version_sha256")
            or re.fullmatch(r"[0-9a-f]{64}", str(target.get("record_version_sha256"))) is None
            or re.fullmatch(r"retrieval-review-target:[0-9a-f]{64}", str(target.get("review_target_id"))) is None):
        raise ValueError("basketball_target_outside_verified_metadata_scope")
    for key in ("permission_status", "source_identity_status", "source_version_status", "source_context_status", "reference_review_status", "planner_requirements_status"):
        if policy.get(key) != "pending":
            raise ValueError("basketball_target_prior_status_changed")
    if any(key in target for key in ("instructions", "description", "classifier_text", "model_text", "probabilities", "raw_scores", "retrieval_text")):
        raise ValueError("basketball_target_contains_out_of_scope_body_fields")
    return True


def build_step237_pending_disposition(target, assessment):
    validate_step237_review_target(target)
    if (assessment.get("scope") != "shared_retrieval_corpus_and_delivered_instructional_text"
            or assessment.get("permission_accepted") is not False
            or assessment.get("status") != "pending_no_express_grant_for_project_corpus_scope"
            or assessment.get("reviewer_role") != "assistant_documentary_reviewer"
            or not assessment.get("official_source_observation_record_sha256")):
        raise ValueError("basketball_assessment_cannot_be_reinterpreted_as_permission")
    return {"schema_version": "step23-basketball-pending-disposition-1",
        "review_target_id": target["review_target_id"], "candidate_id": target["candidate_id"],
        "record_version_sha256": target["record_version_sha256"],
        "review_target_record_sha256": _step237_sha(_step237_packed(target)),
        "permission_assessment_id": assessment["assessment_id"],
        "permission_assessment_record_sha256": _step237_sha(_step237_packed(assessment)),
        "disposition": "pending", "reason_code": "R1", "corpus_admission": False,
        "instruction_body_compared_to_publisher": False, "source_context_review_completed": False,
        "source_version_review_completed": False, "reference_inclusion_decision_created": False,
        "human_review_created": False, "planner_eligibility_granted": False,
        "decision_origin": "assistant_documentary_pending_disposition",
        "effective_source_label_changed": False, "prior_worklist_overwritten": False}


def run_step237_review_probes():
    import copy
    target = {"resource_family": "basketball_drills", "candidate_unit": "basketball_drill_candidate",
        "local_candidate_membership_verified": True,
        "protected_group_screening_status": "record_type_is_public_basketball_or_guideline_reference_candidate",
        "record_version_sha256": "a" * 64, "review_target_id": "retrieval-review-target:" + "b" * 64,
        "candidate_id": "AUTHORED-BASKETBALL-ONLY",
        "policy_metadata": {"membership_verified": True, "membership_status": "verified_reference_candidate",
            "record_kind": "basketball_drill", "record_version_sha256": "a" * 64,
            **{key: "pending" for key in ("permission_status", "source_identity_status", "source_version_status",
                "source_context_status", "reference_review_status", "planner_requirements_status")}}}
    assessment = {"scope": "shared_retrieval_corpus_and_delivered_instructional_text", "permission_accepted": False,
        "status": "pending_no_express_grant_for_project_corpus_scope", "reviewer_role": "assistant_documentary_reviewer",
        "official_source_observation_record_sha256": "c" * 64, "assessment_id": "authored-assessment"}
    checks = []
    def check(name, condition):
        if not condition:
            raise RuntimeError("step23_basketball_review_probe_failed:" + name)
        checks.append({"check": name, "status": "pass", "observed": "authored_only"})
    result = build_step237_pending_disposition(target, assessment)
    check("pending_assessment_does_not_admit_the_target", result["disposition"] == "pending" and result["corpus_admission"] is False)
    check("pending_is_not_a_categorical_denial", result["reason_code"] == "R1" and "denied" not in result.values())
    check("exact_target_and_assessment_records_are_bound", result["review_target_record_sha256"] == _step237_sha(_step237_packed(target))
          and result["permission_assessment_record_sha256"] == _step237_sha(_step237_packed(assessment)))
    check("assistant_events_do_not_create_human_reviews_or_planner_approvals", result["human_review_created"]
          is result["planner_eligibility_granted"] is result["reference_inclusion_decision_created"] is False)
    check("pending_dispositions_preserve_original_catalog_and_worklist", result["effective_source_label_changed"] is result["prior_worklist_overwritten"] is False)
    mutations = [("family", lambda t: t.update(resource_family="general_exercises")),
        ("candidate_unit", lambda t: t.update(candidate_unit="general_warmup_candidate")),
        ("local_membership", lambda t: t.update(local_candidate_membership_verified=False)),
        ("protected_scope", lambda t: t.update(protected_group_screening_status="scope_string_only")),
        ("policy_membership", lambda t: t["policy_metadata"].update(membership_verified=False)),
        ("membership_status", lambda t: t["policy_metadata"].update(membership_status="unproven")),
        ("record_kind", lambda t: t["policy_metadata"].update(record_kind="exercise")),
        ("version_mismatch", lambda t: t["policy_metadata"].update(record_version_sha256="d" * 64)),
        ("malformed_version", lambda t: t.update(record_version_sha256="not-a-hash")),
        ("malformed_id", lambda t: t.update(review_target_id="user-supplied"))]
    mutations += [(key, lambda t, key=key: t["policy_metadata"].update({key: "accepted"})) for key in
        ("permission_status", "source_identity_status", "source_version_status", "source_context_status", "reference_review_status", "planner_requirements_status")]
    mutations += [("body_" + key, lambda t, key=key: t.update({key: "authored artificial value"})) for key in
        ("instructions", "description", "classifier_text", "model_text", "probabilities", "raw_scores", "retrieval_text")]
    for name, mutate in mutations:
        altered = copy.deepcopy(target); mutate(altered)
        try:
            build_step237_pending_disposition(altered, assessment)
        except ValueError:
            check("reject_" + name, True)
        else:
            check("reject_" + name, False)
    for key, value in (("scope", "personal_reading"), ("permission_accepted", True), ("status", "accepted"),
                       ("reviewer_role", "human"), ("official_source_observation_record_sha256", "")):
        altered = copy.deepcopy(assessment); altered[key] = value
        try:
            build_step237_pending_disposition(target, altered)
        except ValueError:
            check("reject_assessment_" + key, True)
        else:
            check("reject_assessment_" + key, False)
    check("artificial_subject_is_not_a_study_or_source_record", target["candidate_id"].startswith("AUTHORED-"))
    return {"scenario_count": len(checks), "check_records": checks}


"""Publish a scoped basketball-source review with immutable, producer-last outputs.

This module handles bytes and documentary records only. It never loads a source,
creates an approval, or admits content to a retrieval corpus.
"""


def validate_step237_basketball_review_targets(project_root, payloads, *, _allow_transaction_partial=False):
    """Bind eight immutable review outputs to one ID; reject existing partial versions."""
    import hashlib
    import json
    import re
    from pathlib import Path, PurePosixPath

    stage = "payload_and_project_root"
    try:
        root = Path(project_root).resolve(strict=True)
        if not root.is_dir() or type(payloads) is not dict or len(payloads) != 8:
            raise ValueError("invalid_basketball_review_payload_scope")
        basenames = {"scoped_review_targets.jsonl", "source_relationships.csv",
            "official_source_observations.json", "permission_scope_assessment.json",
            "record_dispositions.jsonl", "basketball_review_checks.csv", "basketball_review_manifest.json", "step23_basketball_review_summary.json"}
        expression = re.compile(r"results/retrieval/basketball_review/review_([0-9a-f]{16})/(scoped_review_targets\.jsonl|source_relationships\.csv|official_source_observations\.json|permission_scope_assessment\.json|record_dispositions\.jsonl|basketball_review_checks\.csv|basketball_review_manifest\.json|step23_basketball_review_summary\.json)")
        matches = [expression.fullmatch(value) if type(value) is str else None for value in payloads]
        if (any(value is None for value in matches)
                or len({value.group(1) for value in matches}) != 1
                or {PurePosixPath(value).name for value in payloads} != basenames):
            raise ValueError("invalid_basketball_review_version_scope")
        prefix = next(iter(payloads)).rsplit("/", 1)[0] + "/"
        names = {prefix + value for value in basenames}
        marker = prefix + "step23_basketball_review_summary.json"
        if set(payloads) != names:
            raise ValueError("invalid_basketball_review_payload_scope")
        canonical, identical, missing, hashes = [], [], [], {}
        for relative, content in payloads.items():
            stage = "canonical_path_allowlist"
            if type(relative) is not str or type(content) is not bytes or not content:
                raise ValueError("invalid_basketball_review_payload")
            parsed = PurePosixPath(relative)
            if (not relative or "\\" in relative or ":" in relative or parsed.is_absolute()
                    or parsed.as_posix() != relative or any(part in (".", "..") for part in parsed.parts)):
                raise ValueError("invalid_basketball_review_path")
            target = root.joinpath(*parsed.parts)
            if target == root or target.resolve() != target or not target.is_relative_to(root):
                raise ValueError("escaped_or_symlink_basketball_review_target")
            for ancestor in (target, *target.parents):
                if ancestor == root:
                    break
                if ancestor.is_symlink():
                    raise ValueError("symlink_basketball_review_target")
            stage = "existing_canonical_targets"
            if target.exists():
                if not target.is_file() or target.read_bytes() != content:
                    if parsed.name in ("official_source_observations.json", "permission_scope_assessment.json"):
                        stage = "existing_review_history_conflict_preserved"
                    raise ValueError("conflicting_basketball_review_artifact_preserved")
                identical.append(relative)
            else:
                missing.append(relative)
            canonical.append(relative)
            hashes[relative] = hashlib.sha256(content).hexdigest()
        stage = "owned_version_folder_inventory"
        version_root = root / prefix
        if version_root.exists():
            if (not version_root.is_dir() or version_root.is_symlink()
                    or any(entry.name not in basenames or not entry.is_file() or entry.is_symlink()
                           for entry in version_root.iterdir())):
                raise ValueError("unrecognized_basketball_review_version_entry_preserved")
        stage = "existing_partial_version_preserved"
        if identical and missing and not _allow_transaction_partial:
            raise ValueError("incomplete_existing_basketball_review_export_preserved")
        stage = "existing_completion_marker_requires_complete_outputs"
        if marker in identical and missing:
            raise ValueError("incomplete_existing_basketball_review_export_preserved")
        stage = "producer_payload_hash_bindings"

        def pairs(items):
            value = {}
            for key, item in items:
                if key in value:
                    raise ValueError("duplicate_basketball_review_json_key")
                value[key] = item
            return value

        producer = json.loads(payloads[marker].decode("utf-8"), object_pairs_hook=pairs,
            parse_constant=lambda value: (_ for _ in ()).throw(ValueError("nonfinite_producer_json")))
        if (not isinstance(producer, dict)
                or producer.get("schema_version") != "step23-basketball-review-producer-1"
                or producer.get("output_hashes") != {
                    relative: hashes[relative] for relative in names - {marker}}):
            raise ValueError("basketball_review_producer_hash_mismatch")
        preparation_id = producer.get("basketball_review_id")
        if (not isinstance(preparation_id, str)
                or not re.fullmatch(r"basketball-source-review:[0-9a-f]{64}", preparation_id)
                or prefix != "results/retrieval/basketball_review/review_" + preparation_id.split(":")[1][:16] + "/"):
            raise ValueError("basketball_review_identity_and_version_path_disagree")
        if (json.dumps(producer, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n").encode("utf-8") != payloads[marker]:
            raise ValueError("noncanonical_basketball_review_producer")
        return {"status": "basketball_review_targets_verified", "root": root,
            "canonical_files": canonical, "identical_existing_files": identical, "missing_files": missing,
            "artifact_hashes": hashes, "producer_relative_path": marker,
            "version_relative_path": prefix[:-1], "basketball_review_id": preparation_id}
    except Exception:
        raise RuntimeError("step237_basketball_review_target_check_failed:" + stage) from None


def commit_step237_basketball_review_payloads(project_root, payloads, verify_inputs, verify_published=None):
    """Publish seven payloads before their producer; roll back only owned, unchanged files."""
    import os
    import tempfile
    from pathlib import Path

    stage = "canonical_target_preflight"
    staged, created, created_directories = {}, [], []
    root, frozen, staging_root = None, None, None
    staging_identity = None
    published_verification = None

    def require(condition):
        if not bool(condition):
            raise ValueError("basketball_review_preparation_commit_condition_failed")

    def ensure_parent(parent):
        pending, cursor = [], parent
        while not cursor.exists():
            pending.append(cursor)
            cursor = cursor.parent
        require(cursor.is_dir() and not cursor.is_symlink())
        for directory in reversed(pending):
            try:
                directory.mkdir()
            except FileExistsError:
                require(directory.is_dir() and not directory.is_symlink())
            else:
                created_directories.append(directory)

    def verify_callback():
        require(verify_inputs() is not False)
        require(payloads == frozen)

    def clean_staging():
        complete = True
        for temporary, identity in staged.values():
            try:
                if temporary.is_symlink():
                    complete = False
                elif temporary.exists():
                    current = temporary.stat()
                    if (current.st_dev, current.st_ino) == identity:
                        temporary.unlink()
                    else:
                        complete = False
            except OSError:
                complete = False
        if staging_root is not None:
            try:
                if staging_root.is_symlink():
                    complete = False
                elif staging_root.exists():
                    current = staging_root.stat()
                    if (current.st_dev, current.st_ino) != staging_identity:
                        complete = False
                    else:
                        staging_root.rmdir()
            except OSError:
                complete = False
        return complete

    def clean_empty_directories():
        for directory in reversed(created_directories):
            try:
                directory.rmdir()
            except OSError:
                pass

    try:
        require(callable(verify_inputs) and (verify_published is None or callable(verify_published)))
        plan = validate_step237_basketball_review_targets(project_root, payloads)
        root, frozen = plan["root"], dict(payloads)
        stage = "input_verification_before_staging"
        verify_callback()
        marker = plan["producer_relative_path"]
        order = [relative for relative in frozen if relative != marker]
        stage = "complete_temporary_payloads"
        if plan["missing_files"]:
            staging_root = Path(tempfile.mkdtemp(prefix=".step237-basketball-review-stage-", dir=root))
            info = staging_root.stat()
            staging_identity = info.st_dev, info.st_ino
        for number, relative in enumerate(plan["missing_files"]):
            descriptor, name = tempfile.mkstemp(prefix="payload-" + str(number) + "-", suffix=".tmp", dir=staging_root)
            temporary = Path(name)
            info = os.fstat(descriptor)
            staged[relative] = temporary, (info.st_dev, info.st_ino)
            with os.fdopen(descriptor, "wb") as handle:
                require(handle.write(frozen[relative]) == len(frozen[relative]))
                handle.flush()
                os.fsync(handle.fileno())
            require(temporary.read_bytes() == frozen[relative])
        stage = "target_and_input_reverification_before_publish"
        validate_step237_basketball_review_targets(root, frozen)
        verify_callback()

        def publish(relative):
            nonlocal stage
            target, content = root / relative, frozen[relative]
            ensure_parent(target.parent)
            require(target.resolve() == target and not target.is_symlink())
            if target.exists():
                require(target.is_file() and target.read_bytes() == content)
                return
            require(relative in staged)
            temporary, identity = staged[relative]
            require(temporary.read_bytes() == content)
            try:
                os.link(temporary, target)
            except FileExistsError:
                require(not target.is_symlink() and target.is_file() and target.read_bytes() == content)
            except OSError:
                stage = "atomic_exclusive_basketball_review_publication_unavailable"
                raise
            else:
                created.append((relative, identity))
            require(not target.is_symlink() and target.is_file() and target.read_bytes() == content)

        stage = "atomic_exclusive_basketball_review_publication"
        for relative in order:
            publish(relative)
        stage = "published_basketball_review_and_report_readback"
        intermediate = validate_step237_basketball_review_targets(root, frozen, _allow_transaction_partial=True)
        require(set(intermediate["missing_files"]).issubset({marker}))
        stage = "published_basketball_review_verification"
        if verify_published is not None:
            published_verification = verify_published()
            require(published_verification is not False)
        stage = "input_verification_after_basketball_review_verification"
        verify_callback()
        stage = "producer_last_publication"
        publish(marker)
        stage = "complete_saved_basketball_review_readback"
        final = validate_step237_basketball_review_targets(root, frozen)
        require(not final["missing_files"])
        stage = "input_verification_after_publication"
        verify_callback()
        stage = "final_saved_basketball_review_readback"
        final = validate_step237_basketball_review_targets(root, frozen)
        require(not final["missing_files"])
        newly_created = [relative for relative, _identity in created]
        result = {"status": "basketball_review_preparation_committed_and_verified", "root": root,
            "mode": "saved_and_verified_basketball_source_review" if created else "reused_verified_basketball_source_review",
            "basketball_review_id": final["basketball_review_id"],
            "version_relative_path": final["version_relative_path"],
            "producer_relative_path": marker,
            "canonical_files": list(frozen), "saved_files": len(frozen), "newly_created_files": len(created),
            "identical_files_reused": len(frozen) - len(created), "newly_created_paths": newly_created,
            "identical_reused_paths": [relative for relative in frozen if relative not in newly_created],
            "artifact_hashes": final["artifact_hashes"], "existing_files_overwritten": 0,
            "producer_published_after_payload_verification": True,
            "published_verification": published_verification,
            "publication": "atomic exclusive hard links from complete fsynced temporary payloads",
            "input_verifications": 4, "all_payloads_read_back": True, "temporary_files_removed": True}
        stage = "temporary_payload_cleanup"
        require(clean_staging())
        return result
    except BaseException as error:
        changed = []
        if root is not None and frozen is not None:
            for relative, identity in reversed(created):
                target = root / relative
                try:
                    if not target.exists() and not target.is_symlink():
                        continue
                    if target.is_symlink() or target.resolve() != target:
                        changed.append(relative)
                        continue
                    current = target.stat()
                    if ((current.st_dev, current.st_ino) == identity and target.is_file()
                            and target.read_bytes() == frozen[relative]):
                        target.unlink()
                    else:
                        changed.append(relative)
                except OSError:
                    changed.append(relative)
        staging_removed = clean_staging()
        clean_empty_directories()
        if changed:
            raise RuntimeError("step237_basketball_review_commit_failed:" + stage
                               + ":rollback_incomplete_preserved_changed_files") from None
        if not staging_removed:
            raise RuntimeError("step237_basketball_review_commit_failed:" + stage
                               + ":temporary_payload_cleanup_incomplete") from None
        message = str(error)
        if stage == "canonical_target_preflight" and message.startswith("step237_basketball_review_target_check_failed:"):
            raise RuntimeError(message) from None
        raise RuntimeError("step237_basketball_review_commit_failed:" + stage) from None



"""Save a permission-unresolved basketball review without changing source records."""


def execute_step237_basketball_review(namespace):
    import copy
    import csv
    import io
    import json
    import re
    import pandas as pd
    print("Reverifying the saved passage and 396 earlier files; no model loading or publisher requests...", flush=True)
    preflight = verify_step237_basketball_inputs(namespace)
    root = preflight["root"]
    observations = copy.deepcopy(_STEP237_OFFICIAL_OBSERVATIONS)
    alternative = copy.deepcopy(_STEP237_OPEN_SOURCE_LEAD)
    observation_hash = _step237_sha(_step237_packed(observations))
    check_records = list(preflight["checks"])

    def check(name, condition, observed=True):
        if not bool(condition):
            raise RuntimeError("step23_basketball_review_failed:" + name)
        check_records.append({"check": name, "status": "pass", "observed": str(observed)})

    source_rows = observations["observations"]
    source_map = {row["observation_id"]: row for row in source_rows}
    check("five_imported_assistant_observations_have_distinct_official_urls", len(source_rows) == len(source_map) == 5
          and {row["url"] for row in source_rows} == {
              "https://jr.nba.com/jr-nba-instructional-curriculum/",
              "https://jr.nba.com/basketball-practice-plans/starter/",
              "https://jr.nba.com/basketball-practice-plans/starter/page/2/",
              "https://jr.nba.com/basketball-practice-plans/starter/page/3/", "https://www.nba.com/termsofuse"})
    check("observation_receipts_record_origin_and_no_local_freshness_claim", all(
        row["capture_origin"] == "assistant_environment_official_https_observation"
        and row["http_status"] == 200 and row["url"] == row["final_url"]
        and row["raw_response_in_deliverable"] is False
        and row["independent_publisher_reauthentication_on_user_machine"] is False
        and re.fullmatch(r"[0-9a-f]{64}", row["raw_response_sha256"])
        and row["raw_response_bytes"] > 0 for row in source_rows))
    check("policy_link_is_observed_on_the_actual_curriculum_site", source_map["jr_nba_curriculum"]["footer_terms_link_observed"] is True)
    check("practice_plan_observations_do_not_claim_individual_instruction_checks", all(
        source_map[key]["practice_plan_heading_observed"] is True
        and source_map[key]["drill_body_comparison_performed"] is False
        for key in ("starter_plan_1", "starter_plan_2", "starter_plan_3")))
    check("policy_body_and_drill_instructions_are_not_imported", source_map["nba_terms"]["policy_text_reproduced"] is False
          and observations["captured_source_bodies_included"] is False
          and observations["raw_response_hashes_are_observation_receipts_not_locally_replayable_captures"] is True)
    check("the_alternative_is_an_unadopted_research_lead", alternative["artifact_type"] == "unadopted_source_research_lead"
          and alternative["review_status"] == "unadopted_requires_separate_source_version_license_and_context_review"
          and alternative["instructional_text_included"] is alternative["protected_classifier_text_processed"] is False
          and len(alternative["chapters"]) == 6)
    assessment_basis = {"schema_version": "step23-basketball-permission-scope-assessment-1",
        "official_source_observation_record_sha256": observation_hash,
        "reviewer_role": "assistant_documentary_reviewer", "human_review": False,
        "review_event_basis": "authored_review_of_bound_assistant_url_observations",
        "review_event_date_utc": "2026-11-12",
        "scope": "shared_retrieval_corpus_and_delivered_instructional_text",
        "status": "pending_no_express_grant_for_project_corpus_scope", "permission_accepted": False,
        "reason_dictionary": {"R1": "Project corpus permission remains unestablished."},
        "policy_url": "https://www.nba.com/termsofuse", "policy_section_locators": ["1", "6", "7"],
        "policy_finding_is_project_scope_documentation_not_legal_advice": True,
        "statutory_exception_assessed": False, "categorical_rights_denial": False,
        "ai_specific_prohibition_asserted": False, "source_body_accuracy_assessment_completed": False,
        "fresh_publisher_verification_on_this_machine": False,
        "publisher_response_bytes_available_for_local_replay": False,
        "unsigned_imported_observations_are_not_independent_source_authentication": True,
        "reviewed_source_material_copied_into_corpus": False,
        "permission_may_be_reassessed_with_new_documented_scope_evidence": True,
        "prior_approvals_or_worklists_overwritten": False,
        "separate_unadopted_alternative": alternative}
    assessment = {**assessment_basis,
        "assessment_id": "basketball-permission-assessment:" + _step237_sha(_step237_packed(assessment_basis))}
    print("Binding the documented permission scope to twenty public basketball review targets...", flush=True)
    targets = preflight["selected_targets"]
    dispositions = [build_step237_pending_disposition(row, assessment) for row in targets]
    relations = copy.deepcopy(preflight["source_relationships"])
    check("twenty_pending_dispositions_bind_twenty_exact_target_versions", len(dispositions) == 20
          and len({r["review_target_id"] for r in dispositions}) == 20
          and all(row["review_target_record_sha256"] == _step237_sha(_step237_packed(target))
                  and row["record_version_sha256"] == target["record_version_sha256"]
              for row, target in zip(dispositions, targets)))
    check("all_twenty_targets_remain_unadmitted_without_human_or_planner_decisions", all(
        row["disposition"] == "pending" and row["reason_code"] == "R1"
        and row["corpus_admission"] is row["human_review_created"]
            is row["planner_eligibility_granted"] is row["reference_inclusion_decision_created"] is False for row in dispositions))
    check("one_shared_assessment_does_not_become_twenty_independent_sources", len(relations) == 21
          and len({row["source_url"] for row in relations}) == 3
          and len({row["permission_assessment_id"] for row in dispositions}) == 1)
    check("recorded_locators_remain_unverified_metadata", all(row["instruction_body_compared_to_publisher"]
          is row["source_context_review_completed"] is row["source_version_review_completed"] is False for row in dispositions))
    probes = run_step237_review_probes()
    for row in probes["check_records"]:
        check_records.append({**row, "scope": "artificial_pending_review_contract"})
    for row in check_records:
        row.setdefault("scope", "saved_inputs_and_documentary_review")
    checks = pd.DataFrame(check_records, columns=["scope", "check", "status", "observed"])
    identity = {"recipe_version": "basketball-permission-unresolved-review-0.1.0",
        "implementation_sha256": _STEP237_IMPLEMENTATION_SHA256, "input_hashes": preflight["input_hashes"],
        "passage_preparation_id": preflight["passage_preparation_id"],
        "record_review_preparation_id": preflight["record_review_preparation_id"],
        "selected_candidate_ids": list(_STEP237_SELECTED_CANDIDATES),
        "official_source_observations_sha256": observation_hash,
        "permission_assessment_sha256": _step237_sha(_step237_packed(assessment)),
        "admission_policy": "pending_dispositions_only_no_source_instruction_ingestion",
        "models_or_publisher_requests_executed": False}
    review_id = "basketball-source-review:" + _step237_sha(_step237_packed(identity))
    prefix = "results/retrieval/basketball_review/review_" + review_id.split(":")[1][:16] + "/"

    def jsonl(rows):
        return ("".join(json.dumps(row, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False)
            + "\n" for row in rows)).encode("utf-8")

    payloads = {prefix + "scoped_review_targets.jsonl": jsonl(targets),
        prefix + "source_relationships.csv": pd.DataFrame(relations).to_csv(index=False, lineterminator="\n").encode("utf-8"),
        prefix + "official_source_observations.json": _step237_packed(observations),
        prefix + "permission_scope_assessment.json": _step237_packed(assessment),
        prefix + "record_dispositions.jsonl": jsonl(dispositions),
        prefix + "basketball_review_checks.csv": checks.to_csv(index=False, lineterminator="\n").encode("utf-8")}
    manifest = {"schema_version": "step23-basketball-review-manifest-1", "basketball_review_id": review_id,
        "permission_assessment_id": assessment["assessment_id"],
        "payload_hashes": {name: _step237_sha(content) for name, content in payloads.items()},
        "review_target_record_hashes": {row["review_target_id"]: _step237_sha(_step237_packed(row)) for row in targets},
        "source_record_version_hashes": {row["review_target_id"]: row["record_version_sha256"] for row in targets},
        "record_disposition_hashes": {row["review_target_id"]: _step237_sha(_step237_packed(row)) for row in dispositions},
        "relationships": 21, "recorded_plan_urls": 3, "shared_permission_assessments": 1,
        "reference_units_admitted": 0, "passages_created": 0,
        "imported_observations_have_no_publisher_signature": True,
        "source_instruction_bodies_stored_in_this_release": False,
        "existing_sleep_passage_and_delivery_bundle_unchanged": True,
        "open_source_alternative_adopted": False, "operational_retrieval_ready": False}
    payloads[prefix + "basketball_review_manifest.json"] = _step237_packed(manifest)
    summary = {"schema_version": "step23-basketball-review-producer-1", **identity,
        "basketball_review_id": review_id, "status": "basketball_subset_permission_review_recorded_admission_pending",
        "output_hashes": {name: _step237_sha(content) for name, content in payloads.items()},
        "prior_files_reverified": len(preflight["input_hashes"]), "saved_checks": len(checks),
        "artificial_scenarios": probes["scenario_count"], "artificial_checks": len(probes["check_records"]),
        "scoped_basketball_targets": 20, "source_relationships": 21, "recorded_plan_urls": 3,
        "imported_assistant_url_observations": 5, "shared_permission_assessments": 1,
        "pending_dispositions": 20, "accepted_permission_decisions": 0,
        "current_drill_body_or_dosage_verifications": 0, "new_reference_inclusion_decisions": 0,
        "new_reference_units_admitted": 0, "new_passages_created": 0,
        "model_or_tokenizer_loads": 0, "corpus_embeddings_created": 0, "vectorizer_fits": 0,
        "retrieval_indexes_created": 0, "retrieval_requests": 0, "questions_or_judgments_created": 0,
        "human_reviews_created": 0, "planner_approvals_created": 0,
        "network_requests_this_execution": 0, "publisher_contacts": 0,
        "source_labels_or_prior_reviews_changed": False, "protected_classifier_text_processed": False,
        "existing_sleep_reference_units": 1, "existing_sleep_passages": 1,
        "warmup_targets_still_deferred": 12, "remaining_review_targets_not_assessed_by_this_stage": 2580,
        "open_source_alternative_status": "unadopted_requires_separate_review",
        "basketball_coverage_expanded": False, "planned_basketball_retrieval_benchmark_supported": False,
        "operational_retrieval_ready": False, "step23_complete": False,
        "next_substep": "Review the separately identified Open UGA text, exact source version, chapter exceptions, attribution and reference context before an explicit inclusion decision. Keep the NBA subset pending unless sufficient new scope evidence is documented."}
    marker = prefix + "step23_basketball_review_summary.json"
    payloads[marker] = _step237_packed(summary)
    hashes = {name: _step237_sha(content) for name, content in payloads.items()}
    frozen = _step237_sha(_step237_packed({"identity": identity, "summary": summary, "manifest": manifest,
        "targets": targets, "relations": relations, "dispositions": dispositions, "observations": observations,
        "assessment": assessment}))

    def verify_inputs():
        preflight["verify_unchanged"]()
        if (_step237_sha(_step237_packed({"identity": identity, "summary": summary, "manifest": manifest,
                "targets": targets, "relations": relations, "dispositions": dispositions, "observations": observations,
                "assessment": assessment})) != frozen
                or hashes != {name: _step237_sha(content) for name, content in payloads.items()}):
            raise RuntimeError("step23_basketball_review_failed:prepared_review_state_changed")
        return True

    def verify_saved():
        verify_inputs()
        if any((root / name).read_bytes() != content for name, content in payloads.items() if name != marker):
            raise RuntimeError("step23_basketball_review_failed:saved_payload_changed")
        read_rows = lambda name: [json.loads(line) for line in (root / (prefix + name)).read_text(encoding="utf-8").splitlines()]
        if (read_rows("scoped_review_targets.jsonl") != targets or read_rows("record_dispositions.jsonl") != dispositions
                or json.loads((root / (prefix + "permission_scope_assessment.json")).read_bytes()) != assessment
                or json.loads((root / (prefix + "official_source_observations.json")).read_bytes()) != observations):
            raise RuntimeError("step23_basketball_review_failed:record_readback_changed")
        with (root / (prefix + "source_relationships.csv")).open(encoding="utf-8", newline="") as handle:
            if list(csv.DictReader(handle)) != relations:
                raise RuntimeError("step23_basketball_review_failed:relationship_readback_changed")
        return {"payloads_read_back_before_producer": 7, "pending_dispositions": 20,
            "corpus_admissions": 0, "prior_sources_and_worklists_unchanged": True}

    print("Saving the versioned pending review and source observations; no new corpus admissions...", flush=True)
    saved = commit_step237_basketball_review_payloads(root, payloads, verify_inputs, verify_saved)

    def verify_complete():
        verify_inputs()
        if any(_step237_sha((root / name).read_bytes()) != digest for name, digest in hashes.items()):
            raise RuntimeError("step23_basketball_review_failed:saved_review_changed")
        return True

    verify_complete()
    return {"root": root, "mode": saved["mode"], "status": summary["status"], "summary": summary,
        "manifest": manifest, "preflight": preflight, "assessment": assessment, "dispositions": dispositions,
        "official_observations": observations, "checks": checks, "probes": probes,
        "input_hashes": preflight["input_hashes"], "save": saved, "saved_files": saved["canonical_files"],
        "basketball_review_id": review_id, "verify_unchanged": verify_complete,
        "basketball_source_review_verified": True, "basketball_pending_documentary_review_verified": True,
        "basketball_admission_ready": False, "basketball_coverage_expanded": False,
        "operational_retrieval_ready": False, "step23_complete": False}


_STEP237_IMPLEMENTATION_SHA256 = 'e499cb877dc373792250afa877b1ef01571e31694f1288335c1eac755ab5ca21'

