def check_step2311_question_families(rows):
    """Authored design validator; this call never creates or scores questions."""
    if type(rows) is not list:
        raise ValueError("question_design_requires_a_list")
    identities, family_splits = {}, {}
    required = {"question_id", "question_family_id", "split", "category", "related_question_ids", "source_family_ids"}
    for row in rows:
        if (type(row) is not dict or set(row) != required
                or any(type(row[k]) is not str or not row[k].strip() for k in ("question_id", "question_family_id"))
                or type(row["split"]) is not str or type(row["category"]) is not str
                or row["split"] not in ("development", "held_out") or row["category"] not in _STEP2311_CATEGORIES
                or type(row["related_question_ids"]) is not list or type(row["source_family_ids"]) is not list
                or any(type(x) is not str or not x.strip() for k in ("related_question_ids", "source_family_ids") for x in row[k])
                or len(set(row["related_question_ids"])) != len(row["related_question_ids"])
                or len(set(row["source_family_ids"])) != len(row["source_family_ids"])
                or row["question_id"] in identities):
            raise ValueError("question_design_row_invalid")
        identities[row["question_id"]] = row
        family_splits.setdefault(row["question_family_id"], set()).add(row["split"])
    if any(len(parts) != 1 for parts in family_splits.values()):
        raise ValueError("question_family_crosses_partitions")
    for row in rows:
        for related in row["related_question_ids"]:
            if (related not in identities or related == row["question_id"]
                    or identities[related]["question_family_id"] != row["question_family_id"]):
                raise ValueError("related_information_need_requires_one_question_family")
    return {"questions": len(rows), "question_families": len(family_splits),
        "development_questions": sum(r["split"] == "development" for r in rows),
        "held_out_questions": sum(r["split"] == "held_out" for r in rows),
        "source_disjointness_required": False}


def run_step2311_design_probes():
    def row(q="authored-q1", family="authored-f1", split="development", category="drill_and_resource"):
        return {"question_id": q, "question_family_id": family, "split": split, "category": category,
            "related_question_ids": [], "source_family_ids": ["authored-shared-publisher"]}
    checks = []
    def probe(name, rows, valid):
        try:
            value = check_step2311_question_families(rows)
        except ValueError:
            if valid: raise
        else:
            if not valid: raise AssertionError("authored_design_rejection_did_not_occur")
        checks.append({"scope": "artificial_question_design", "check": name, "status": "pass",
            "observed": "authored_fixture_only;no_benchmark_question_or_judgment"})
    probe("empty_design_does_not_imply_capacity_or_readiness", [], True)
    probe("one_assigned_authored_family_is_valid", [row()], True)
    probe("distinct_families_may_share_a_publisher_across_partitions",
        [row(), row("authored-q2", "authored-f2", "held_out")], True)
    probe("paraphrases_can_share_one_family_within_a_partition", [row(), row("authored-q2")], True)
    probe("same_family_cannot_cross_partitions", [row(), row("authored-q2", split="held_out")], False)
    for key, value in (("question_id", ""), ("question_family_id", " "), ("split", "test"),
                       ("category", "new_category"), ("related_question_ids", None), ("source_family_ids", [True])):
        item = row(); item[key] = value; probe("reject_invalid_" + key, [item], False)
    probe("duplicate_question_ids_are_rejected", [row(), row()], False)
    a, b = row(), row("authored-q2", "authored-f2"); a["related_question_ids"] = [b["question_id"]]
    probe("linked_equivalent_information_needs_cannot_split_families", [a, b], False)
    a, b = row(), row("authored-q2"); a["related_question_ids"] = [b["question_id"]]
    probe("linked_equivalent_needs_can_share_one_family", [a, b], True)
    a = row(); a["related_question_ids"] = ["authored-missing"]
    probe("dangling_related_question_is_rejected", [a], False)
    a = row(); a["related_question_ids"] = [a["question_id"]]
    probe("self_relation_is_rejected", [a], False)
    probe("unsupported_is_a_planned_category_without_a_fabricated_gold_set",
        [row(category="unsupported_by_identified_corpus")], True)
    a = row(); a["extra_scope_flag"] = True
    probe("scope_flag_cannot_replace_the_design_contract", [a], False)
    probe("non_list_design_is_rejected", {}, False)
    return checks


