_STEP2311_OUTPUTS = ("passage_coverage.csv", "category_coverage.csv", "benchmark_design_contract.json",
    "coverage_gaps.json", "coverage_checks.csv", "coverage_manifest.json", "step23_benchmark_coverage_summary.json")


def _step2311_csv(rows):
    import csv
    import io
    if not rows: raise ValueError("empty_audit_table")
    buffer = io.StringIO(newline="")
    writer = csv.DictWriter(buffer, fieldnames=list(rows[0]), lineterminator="\n")
    writer.writeheader(); writer.writerows(rows)
    return buffer.getvalue().encode("utf-8")


def _step2311_commit(root, prefix, payloads, guard):
    import os
    import tempfile
    from pathlib import Path
    folder, marker = root / prefix, "step23_benchmark_coverage_summary.json"
    if set(payloads) != set(_STEP2311_OUTPUTS) or any(type(v) is not bytes or not v for v in payloads.values()):
        raise RuntimeError("step2311_save_failed:fixed_payload_inventory")
    frozen = dict(payloads)
    created, made = [], []
    def verify_targets(allow_partial=False):
        if payloads != frozen: raise RuntimeError("step2311_save_failed:prepared_bytes_changed")
        for path in (folder, *folder.parents):
            if path.is_symlink(): raise RuntimeError("step2311_save_failed:symlink_target_preserved")
            if path == root: break
        if folder.exists():
            if not folder.is_dir() or any(p.name not in payloads or not p.is_file() or p.is_symlink() for p in folder.iterdir()):
                raise RuntimeError("step2311_save_failed:unbound_target_entry_preserved")
        existing = [name for name in payloads if (folder / name).exists()]
        if existing and len(existing) != len(payloads) and not allow_partial:
            raise RuntimeError("step2311_save_failed:partial_audit_preserved")
        for name in existing:
            if (folder / name).read_bytes() != payloads[name]:
                raise RuntimeError("step2311_save_failed:conflicting_audit_preserved")
        return existing
    existing = verify_targets(); guard()
    if existing:
        return {"mode": "reused_verified_benchmark_coverage_audit", "newly_created_files": 0,
            "identical_files_reused": len(existing), "artifact_hashes": {prefix + n: _step2311_sha(b) for n, b in payloads.items()}}
    pending, cursor = [], folder
    while not cursor.exists(): pending.append(cursor); cursor = cursor.parent
    if not cursor.is_dir(): raise RuntimeError("step2311_save_failed:parent_not_directory")
    try:
        for directory in reversed(pending):
            directory.mkdir(); made.append(directory)
        # All canonical files are linked exclusively from same-filesystem temporary files.
        # The producer is linked last after exact readback of the other six files.
        with tempfile.TemporaryDirectory(prefix=".step2311-audit-", dir=root) as temporary:
            stage = Path(temporary)
            for name, content in payloads.items():
                with (stage / name).open("xb") as handle:
                    handle.write(content); handle.flush(); os.fsync(handle.fileno())
            guard(); verify_targets()
            order = [n for n in payloads if n != marker] + [marker]
            for name in order:
                guard(); verify_targets(allow_partial=True)
                if name == marker:
                    if any((folder / n).read_bytes() != payloads[n] for n in order[:-1]):
                        raise RuntimeError("step2311_save_failed:payload_readback")
                owned = (stage / name).stat()
                os.link(stage / name, folder / name)
                created.append((name, owned.st_dev, owned.st_ino))
            verify_targets(); guard()
        return {"mode": "saved_and_verified_benchmark_coverage_audit", "newly_created_files": len(created),
            "identical_files_reused": 0, "artifact_hashes": {prefix + n: _step2311_sha(b) for n, b in payloads.items()}}
    except BaseException:
        for name, device, inode in reversed(created):
            p = folder / name
            try:
                if (not p.is_symlink() and p.is_file() and (p.stat().st_dev, p.stat().st_ino) == (device, inode)
                        and p.read_bytes() == frozen[name]): p.unlink()
            except OSError: pass
        for directory in reversed(made):
            try: directory.rmdir()
            except OSError: pass
        raise


