            for n,r in expected.items():
                parsed=PurePosixPath(n)
                if (type(n) is not str or not n or "\\" in n or ":" in n or parsed.is_absolute() or parsed.as_posix()!=n
                        or any(p in (".","..") for p in parsed.parts) or type(r["bytes"]) is not int or r["bytes"]<=0
                        or re.fullmatch(r"[0-9a-f]{64}",str(r["sha256"])) is None):return False
            entries=list(cache.rglob("*"))
            return (not any(p.is_symlink() or (not p.is_file() and not p.is_dir()) for p in entries)
                and {p.relative_to(cache).as_posix() for p in entries if p.is_file()}==set(expected)
                and {p.relative_to(cache).as_posix() for p in entries if p.is_dir()}=={"1_Pooling"}
                and all((cache/n).resolve()==cache/n and (cache/n).stat().st_size==r["bytes"] and sha((cache/n).read_bytes())==r["sha256"] for n,r in expected.items()))
