"""Read-only bindings for benchmark authoring; no new index, tokenizer or model load."""


def _step2316_input_pack(value):
    import json
    return (json.dumps(value,ensure_ascii=False,sort_keys=True,indent=2,allow_nan=False)+"\n").encode("utf-8")


def _step2316_input_sha(value):
    import hashlib
    return hashlib.sha256(value).hexdigest()


def _step2316_input_decode(value):
    import json
    def unique(pairs):
        result={}
        for key,item in pairs:
            if key in result:raise ValueError("duplicate_benchmark_input_json_key")
            result[key]=item
        return result
    def finite(value):raise ValueError("nonfinite_benchmark_input_json")
    return json.loads(value.decode("utf-8"),object_pairs_hook=unique,parse_constant=finite)


def verify_step2316_inputs(namespace):
    """Reverify 512 opaque file bindings and the explicit public corpus/policy metadata.

    The required existing receipt guard may fingerprint already-loaded arrays.
    This verifier itself imports only the standard library and neither loads a
    fitted object nor executes retrieval, tokenization or embedding code.
    """
    import copy
    import csv
    import io
    import re
    from pathlib import Path,PurePosixPath
    pack,sha,decode=_step2316_input_pack,_step2316_input_sha,_step2316_input_decode
    checks=[];stage="completed_query_preparation_receipt"
    def check(name,condition,observed=True):
        nonlocal stage
