"""Read-only benchmark bindings with development-only question/gold exports."""


def _step2317_input_pack(value):
    import json
    return (json.dumps(value,ensure_ascii=False,sort_keys=True,indent=2,allow_nan=False)+"\n").encode("utf-8")


def _step2317_input_sha(value):
    import hashlib
    return hashlib.sha256(value).hexdigest()


def _step2317_input_decode(content):
    import json
    def pairs(rows):
        result={}
        for key,value in rows:
            if key in result:raise ValueError("duplicate_development_input_json_key")
            result[key]=value
        return result
    return json.loads(content.decode("utf-8"),object_pairs_hook=pairs,
        parse_constant=lambda value:(_ for _ in ()).throw(ValueError("nonfinite_development_input_json")))


