def _step2318_input_pack(value):
    import json
    return (json.dumps(value,ensure_ascii=False,sort_keys=True,indent=2,allow_nan=False)+"\n").encode("utf-8")


def _step2318_input_sha(content):
    import hashlib
    return hashlib.sha256(content).hexdigest()


def _step2318_input_decode(content):
    import json
    def pairs(rows):
        value={}
        for key,item in rows:
            if key in value:raise ValueError("duplicate_heldout_input_json_key")
            value[key]=item
        return value
    return json.loads(content.decode("utf-8"),object_pairs_hook=pairs,
        parse_constant=lambda value:(_ for _ in ()).throw(ValueError("nonfinite_heldout_input_json")))


