            scored=[r for r in rows if r["relevant_unit_count"]>0];sufficient=[r for r in rows if r["complete_evidence_set_covered_at_5"] is not None]
            means=(math.fsum(r["recall_at_5"] for r in scored)/len(scored),math.fsum(r["reciprocal_rank_at_5"] for r in scored)/len(scored))
