"""Publish immutable held-out evaluation payloads with producer-last completion.

This module publishes prepared bytes only. Corpus and retrieval semantics remain
with the caller; it performs no network request, model load, or source interpretation.
"""


# Root composes this tuple from the fixed authored recipe before its code hash is frozen.
STEP2318_OUTPUT_NAMES = ('heldout_queries.jsonl', 'heldout_query_embeddings.npy', 'heldout_query_verification.json', 'heldout_rankings.jsonl', 'heldout_per_query_metrics.jsonl', 'heldout_route_metrics.csv', 'heldout_category_metrics.csv', 'heldout_error_audit.jsonl', 'frozen_method_evaluation.json', 'retrieval_handoff.json', 'retrieval_findings.md', 'heldout_checks.csv', 'heldout_evaluation_config.json', 'heldout_diagnostics.json', 'heldout_replay_worker.py', 'heldout_manifest.json', 'step23_retrieval_evaluation_summary.json')


def validate_step2318_targets(project_root, payloads, *, _allow_transaction_partial=False):
    """Bind exactly the configured immutable outputs to one ID; reject partial versions."""
    import hashlib
    import json
    import re
    from pathlib import Path, PurePosixPath

    stage = "payload_and_project_root"
    try:
        supplied_root = Path(project_root)
        if any(ancestor.is_symlink() for ancestor in (supplied_root, *supplied_root.parents)):
            raise ValueError("symlink_heldout_evaluation_project_root")
        root = supplied_root.resolve(strict=True)
        if (not root.is_dir() or type(payloads) is not dict or not isinstance(STEP2318_OUTPUT_NAMES, tuple)
                or len(STEP2318_OUTPUT_NAMES) < 2 or len(payloads) != len(STEP2318_OUTPUT_NAMES)):
            raise ValueError("invalid_heldout_evaluation_payload_scope")
        basenames = set(STEP2318_OUTPUT_NAMES)
        if (len(basenames) != len(STEP2318_OUTPUT_NAMES)
                or "step23_retrieval_evaluation_summary.json" not in basenames
                or any(type(value) is not str or not value or "/" in value or "\\" in value
                       or ":" in value or value in (".", "..") for value in basenames)):
            raise ValueError("invalid_heldout_evaluation_output_name_configuration")
        expression = re.compile(r"artifacts/retrieval/evaluation/evaluation_([0-9a-f]{16})/(" +
            "|".join(re.escape(value) for value in sorted(basenames)) + r")")
        matches = [expression.fullmatch(value) if type(value) is str else None for value in payloads]
        if (any(value is None for value in matches)
                or len({value.group(1) for value in matches}) != 1
                or {PurePosixPath(value).name for value in payloads} != basenames):
            raise ValueError("invalid_heldout_evaluation_version_scope")
        prefix = next(iter(payloads)).rsplit("/", 1)[0] + "/"
        names = {prefix + value for value in basenames}
        marker = prefix + "step23_retrieval_evaluation_summary.json"
        if set(payloads) != names:
            raise ValueError("invalid_heldout_evaluation_payload_scope")
        canonical, identical, missing, hashes = [], [], [], {}
        for relative, content in payloads.items():
            stage = "canonical_path_allowlist"
            if type(relative) is not str or type(content) is not bytes or (not content and relative.rsplit("/", 1)[-1] != "heldout_error_audit.jsonl"):
                raise ValueError("invalid_heldout_evaluation_payload")
            parsed = PurePosixPath(relative)
            if (not relative or "\\" in relative or ":" in relative or parsed.is_absolute()
                    or parsed.as_posix() != relative or any(part in (".", "..") for part in parsed.parts)):
                raise ValueError("invalid_heldout_evaluation_path")
            target = root.joinpath(*parsed.parts)
            if target == root or target.resolve() != target or not target.is_relative_to(root):
                raise ValueError("escaped_or_symlink_heldout_evaluation_target")
            for ancestor in (target, *target.parents):
                if ancestor == root:
                    break
                if ancestor.is_symlink():
                    raise ValueError("symlink_heldout_evaluation_target")
            stage = "existing_canonical_targets"
            if target.exists():
                if not target.is_file() or target.read_bytes() != content:
                    if parsed.name in ("heldout_queries.jsonl", "heldout_rankings.jsonl", "frozen_method_evaluation.json"):
                        stage = "existing_review_history_conflict_preserved"
                    raise ValueError("conflicting_heldout_evaluation_artifact_preserved")
                identical.append(relative)
            else:
                missing.append(relative)
            canonical.append(relative)
            hashes[relative] = hashlib.sha256(content).hexdigest()
        stage = "owned_version_folder_inventory"
        version_root = root / prefix
        if version_root.exists():
            if (not version_root.is_dir() or version_root.is_symlink()
                    or any(entry.name not in basenames or not entry.is_file() or entry.is_symlink()
                           for entry in version_root.iterdir())):
                raise ValueError("unrecognized_heldout_evaluation_version_entry_preserved")
        stage = "existing_partial_version_preserved"
        if identical and missing and not _allow_transaction_partial:
            raise ValueError("incomplete_existing_heldout_evaluation_export_preserved")
        stage = "existing_completion_marker_requires_complete_outputs"
        if marker in identical and missing:
            raise ValueError("incomplete_existing_heldout_evaluation_export_preserved")
        stage = "producer_payload_hash_bindings"

        def pairs(items):
            value = {}
            for key, item in items:
                if key in value:
                    raise ValueError("duplicate_heldout_evaluation_json_key")
                value[key] = item
            return value

        producer = json.loads(payloads[marker].decode("utf-8"), object_pairs_hook=pairs,
            parse_constant=lambda value: (_ for _ in ()).throw(ValueError("nonfinite_producer_json")))
        if (not isinstance(producer, dict)
                or producer.get("schema_version") != "step23-heldout-evaluation-producer-1"
                or producer.get("output_hashes") != {
                    relative: hashes[relative] for relative in names - {marker}}):
            raise ValueError("heldout_evaluation_producer_hash_mismatch")
        stage = "producer_input_output_scope_separation"
        if (type(producer.get("input_hashes")) is not dict
                or not set(producer["input_hashes"]).isdisjoint(names)):
            raise ValueError("heldout_evaluation_input_and_output_scope_overlap")
        stage = "producer_payload_hash_bindings"
        preparation_id = producer.get("heldout_evaluation_id")
        if (not isinstance(preparation_id, str)
                or not re.fullmatch(r"retrieval-heldout-evaluation:[0-9a-f]{64}", preparation_id)
                or prefix != "artifacts/retrieval/evaluation/evaluation_" + preparation_id.split(":")[1][:16] + "/"):
            raise ValueError("heldout_evaluation_identity_and_version_path_disagree")
        if (json.dumps(producer, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n").encode("utf-8") != payloads[marker]:
            raise ValueError("noncanonical_heldout_evaluation_producer")
        return {"status": "heldout_evaluation_targets_verified", "root": root,
            "canonical_files": canonical, "identical_existing_files": identical, "missing_files": missing,
            "artifact_hashes": hashes, "producer_relative_path": marker,
            "version_relative_path": prefix[:-1], "heldout_evaluation_id": preparation_id}
    except Exception:
        raise RuntimeError("step2318_heldout_evaluation_target_check_failed:" + stage) from None


def commit_step2318_payloads(project_root, payloads, verify_inputs, verify_published=None):
    """Publish payloads before their producer; roll back only owned, unchanged files."""
    import os
    import tempfile
    from pathlib import Path

    stage = "canonical_target_preflight"
    staged, created, created_directories = {}, [], []
    root, frozen, staging_root = None, None, None
    staging_identity = None
    published_verification = None
    output_name_configuration = STEP2318_OUTPUT_NAMES

    def require(condition):
        if not bool(condition):
            raise ValueError("heldout_evaluation_commit_condition_failed")

    def ensure_parent(parent):
        pending, cursor = [], parent
        while not cursor.exists():
            pending.append(cursor)
            cursor = cursor.parent
        require(cursor.is_dir() and not cursor.is_symlink())
        for directory in reversed(pending):
            try:
                directory.mkdir()
            except FileExistsError:
                require(directory.is_dir() and not directory.is_symlink())
            else:
                created_directories.append(directory)

    def verify_callback():
        require(verify_inputs() is not False)
        require(payloads == frozen)
        require(STEP2318_OUTPUT_NAMES == output_name_configuration)

    def clean_staging():
        complete = True
        for temporary, identity in staged.values():
            try:
                if temporary.is_symlink():
                    complete = False
                elif temporary.exists():
                    current = temporary.stat()
                    if (current.st_dev, current.st_ino) == identity:
                        temporary.unlink()
                    else:
                        complete = False
            except OSError:
                complete = False
        if staging_root is not None:
            try:
                if staging_root.is_symlink():
                    complete = False
                elif staging_root.exists():
                    current = staging_root.stat()
                    if (current.st_dev, current.st_ino) != staging_identity:
                        complete = False
                    else:
                        staging_root.rmdir()
            except OSError:
                complete = False
        return complete

    def clean_empty_directories():
        for directory in reversed(created_directories):
            try:
                directory.rmdir()
            except OSError:
                pass

    try:
        require(callable(verify_inputs) and (verify_published is None or callable(verify_published)))
        plan = validate_step2318_targets(project_root, payloads)
        root, frozen = plan["root"], dict(payloads)
        stage = "input_verification_before_staging"
        verify_callback()
        marker = plan["producer_relative_path"]
        order = [relative for relative in frozen if relative != marker]
        stage = "complete_temporary_payloads"
        if plan["missing_files"]:
            staging_root = Path(tempfile.mkdtemp(prefix=".step2318-heldout-stage-", dir=root))
            info = staging_root.stat()
            staging_identity = info.st_dev, info.st_ino
        for number, relative in enumerate(plan["missing_files"]):
            descriptor, name = tempfile.mkstemp(prefix="payload-" + str(number) + "-", suffix=".tmp", dir=staging_root)
            temporary = Path(name)
            info = os.fstat(descriptor)
            staged[relative] = temporary, (info.st_dev, info.st_ino)
            with os.fdopen(descriptor, "wb") as handle:
                require(handle.write(frozen[relative]) == len(frozen[relative]))
                handle.flush()
                os.fsync(handle.fileno())
            require(temporary.read_bytes() == frozen[relative])
        stage = "target_and_input_reverification_before_publish"
        validate_step2318_targets(root, frozen)
        verify_callback()

        def publish(relative):
            nonlocal stage
            target, content = root / relative, frozen[relative]
            ensure_parent(target.parent)
            require(target.resolve() == target and not target.is_symlink())
            if target.exists():
                require(target.is_file() and target.read_bytes() == content)
                return
            require(relative in staged)
            temporary, identity = staged[relative]
            require(temporary.read_bytes() == content)
            # Claim the staged inode before the link: cancellation can arrive
            # after the syscall creates the target but before Python returns.
            # Rollback still removes only this inode with unchanged bytes.
            created.append((relative, identity))
            try:
                os.link(temporary, target)
            except FileExistsError:
                created.pop()  # A concurrent publisher owns this existing path.
                require(not target.is_symlink() and target.is_file() and target.read_bytes() == content)
            except OSError:
                stage = "atomic_exclusive_heldout_evaluation_publication_unavailable"
                raise
            require(not target.is_symlink() and target.is_file() and target.read_bytes() == content)

        stage = "atomic_exclusive_heldout_evaluation_publication"
        for relative in order:
            publish(relative)
        stage = "published_heldout_evaluation_and_report_readback"
        intermediate = validate_step2318_targets(root, frozen, _allow_transaction_partial=True)
        require(set(intermediate["missing_files"]).issubset({marker}))
        stage = "published_heldout_evaluation_verification"
        if verify_published is not None:
            published_verification = verify_published()
            require(published_verification is not False)
        stage = "input_verification_after_heldout_evaluation_verification"
        verify_callback()
        stage = "producer_last_publication"
        publish(marker)
        stage = "complete_saved_heldout_evaluation_readback"
        final = validate_step2318_targets(root, frozen)
        require(not final["missing_files"])
        stage = "input_verification_after_publication"
        verify_callback()
        stage = "final_saved_heldout_evaluation_readback"
        final = validate_step2318_targets(root, frozen)
        require(not final["missing_files"])
        newly_created = [relative for relative, _identity in created]
        result = {"status": "heldout_evaluation_committed_and_verified", "root": root,
            "mode": "saved_and_verified_heldout_evaluation" if created else "reused_verified_heldout_evaluation",
            "heldout_evaluation_id": final["heldout_evaluation_id"],
            "version_relative_path": final["version_relative_path"],
            "producer_relative_path": marker,
            "canonical_files": list(frozen), "saved_files": len(frozen), "newly_created_files": len(created),
            "identical_files_reused": len(frozen) - len(created), "newly_created_paths": newly_created,
            "identical_reused_paths": [relative for relative in frozen if relative not in newly_created],
            "artifact_hashes": final["artifact_hashes"], "existing_files_overwritten": 0,
            "producer_published_after_payload_verification": True,
            "published_verification": published_verification,
            "publication": "atomic exclusive hard links from complete fsynced temporary payloads",
            "input_verifications": 4, "all_payloads_read_back": True, "temporary_files_removed": True}
        stage = "temporary_payload_cleanup"
        require(clean_staging())
        return result
    except BaseException as error:
        changed = []
        if root is not None and frozen is not None:
            for relative, identity in reversed(created):
                target = root / relative
                try:
                    if not target.exists() and not target.is_symlink():
                        continue
                    if target.is_symlink() or target.resolve() != target:
                        changed.append(relative)
                        continue
                    current = target.stat()
                    if ((current.st_dev, current.st_ino) == identity and target.is_file()
                            and target.read_bytes() == frozen[relative]):
                        target.unlink()
                    else:
                        changed.append(relative)
                except OSError:
                    changed.append(relative)
        staging_removed = clean_staging()
        clean_empty_directories()
        if changed:
            raise RuntimeError("step2318_heldout_evaluation_commit_failed:" + stage
                               + ":rollback_incomplete_preserved_changed_files") from None
        if not staging_removed:
            raise RuntimeError("step2318_heldout_evaluation_commit_failed:" + stage
                               + ":temporary_payload_cleanup_incomplete") from None
        message = str(error)
