checker_source = '"""Offline fulfillment checks for the supplied-commitment calendar example.\n\nThese checks do not assess training suitability or general planner readiness.\nThe unchanged shared response validator remains responsible for JSON structure.\n"""\n\nfrom datetime import date, timedelta\nimport re\n\n\ndef _minutes(value):\n    if not isinstance(value, str) or not re.fullmatch(r"(?:[01][0-9]|2[0-3]):[0-5][0-9]", value):\n        return None\n    hours, minutes = map(int, value.split(":"))\n    return hours * 60 + minutes\n\n\ndef _integer(value):\n    return type(value) is int\n\n\ndef _resource_limits(activities, supplied):\n    available = {}\n    for item in supplied.get("equipment") or []:\n        if not isinstance(item, dict) or not isinstance(item.get("name"), str):\n            return False\n        name = item["name"].strip().casefold()\n        quantity = item.get("quantity")\n        if name not in available:\n            available[name] = quantity if _integer(quantity) and quantity >= 0 else None\n        elif available[name] is not None and _integer(quantity) and quantity >= 0:\n            available[name] += quantity\n        else:\n            available[name] = None\n\n    participants_available = supplied.get("participants_available")\n    for _, activity in activities:\n        resources = activity.get("resources")\n        if not isinstance(resources, dict):\n            return False\n        participants = resources.get("participants")\n        if participants is not None:\n            if not _integer(participants) or participants < 1:\n                return False\n            if _integer(participants_available) and participants > participants_available:\n                return False\n        equipment = resources.get("equipment")\n        if equipment is None:\n            continue\n        if not isinstance(equipment, list):\n            return False\n        totals = {}\n        for item in equipment:\n            if not isinstance(item, dict) or not isinstance(item.get("name"), str):\n                return False\n            name = item["name"].strip().casefold()\n            if name not in available:\n                return False\n            quantity = item.get("quantity")\n            if quantity is not None:\n                if not _integer(quantity) or quantity < 0:\n                    return False\n                totals[name] = totals.get(name, 0) + quantity\n        if any(available[name] is not None and total > available[name]\n               for name, total in totals.items()):\n            return False\n    return True\n\n\ndef check_calendar(result, public_record):\n    """Check the returned calendar against public facts without changing it."""\n    result = result if isinstance(result, dict) else {}\n    public_record = public_record if isinstance(public_record, dict) else {}\n    supplied = public_record.get("input")\n    supplied = supplied if isinstance(supplied, dict) else {}\n    response = result.get("response") or {}\n    output = (response.get("model_output") or {}) if isinstance(response, dict) else {}\n    body = output.get("parsed_object") if isinstance(output, dict) else None\n    body = body if isinstance(body, dict) else {}\n    days = body.get("weekly_schedule")\n    days = days if isinstance(days, list) else []\n    valid_days = all(isinstance(day, dict) and isinstance(day.get("activities"), list)\n                     and all(isinstance(activity, dict) for activity in day["activities"])\n                     for day in days)\n    activities = ([(day.get("date"), activity)\n                   for day in days for activity in day["activities"]] if valid_days else [])\n    commitments = supplied.get("existing_commitments")\n    valid_commitments = isinstance(commitments, list) and all(isinstance(item, dict) for item in commitments)\n    commitments = commitments if valid_commitments else []\n    by_ref = {f"/existing_commitments/{index}": item for index, item in enumerate(commitments)}\n\n    window = supplied.get("planning_window")\n    try:\n        start = date.fromisoformat(window["start_date"])\n        expected_dates = [(start + timedelta(days=index)).isoformat() for index in range(7)]\n        valid_window = window["end_date"] == expected_dates[-1]\n    except (TypeError, KeyError, ValueError):\n        expected_dates, valid_window = [], False\n\n    refs = []\n    commitments_preserved = valid_commitments and valid_days\n    for scheduled_date, activity in activities:\n        references = activity.get("existing_commitment_refs")\n        if (not isinstance(references, list) or len(references) != 1\n                or not isinstance(references[0], str) or references[0] not in by_ref):\n            commitments_preserved = False\n            continue\n        reference = references[0]\n        refs.append(reference)\n        original = by_ref[reference]\n        timing = activity.get("timing")\n        start_minutes, end_minutes = _minutes(original.get("start_time")), _minutes(original.get("end_time"))\n        duration = (end_minutes - start_minutes\n                    if start_minutes is not None and end_minutes is not None else None)\n        if (scheduled_date != original.get("date") or not isinstance(timing, dict)\n                or timing.get("start_time") != original.get("start_time")\n                or timing.get("end_time") != original.get("end_time")\n                or duration is None or duration <= 0\n                or not _integer(activity.get("duration_minutes"))\n                or activity["duration_minutes"] != duration):\n            commitments_preserved = False\n    exact_coverage = valid_commitments and len(refs) == len(by_ref) and set(refs) == set(by_ref)\n\n    checks = {\n        "completed_response": (result.get("status") == "returned"\n                               and result.get("completion_valid") is True\n                               and result.get("format_valid") is True),\n        "response_is_plan": body.get("response_type") == "plan",\n        "planning_window_matches": valid_window and body.get("planning_window") == window,\n        "seven_days_match": (valid_days and valid_window and len(days) == 7\n                             and [day.get("date") for day in days] == expected_dates),\n        "commitments_preserved": commitments_preserved and exact_coverage,\n        "no_extra_activities": (valid_days and valid_commitments and exact_coverage\n                                and len(activities) == len(commitments)),\n        "standalone_sessions": valid_days and all(\n            activity.get("relationship") == {"kind": "separate_session", "parent_activity_id": None}\n            for _, activity in activities),\n        "rest_days_recorded": valid_days and all(\n            isinstance(day.get("rest_arrangements"), str) and bool(day["rest_arrangements"].strip())\n            for day in days if not day["activities"]),\n        "resources_within_available": valid_days and _resource_limits(activities, supplied),\n        "no_invented_source_ids": (body.get("evidence_refs") in (None, [])\n                                   and all(activity.get("evidence_refs") in (None, [])\n                                           for _, activity in activities)),\n        "no_unrequested_food_facts": body.get("food_facts") in (None, []),\n    }\n    messages = {\n        "completed_response": "The model did not return a complete, format-valid response.",\n        "response_is_plan": "The model did not return a plan.",\n        "planning_window_matches": "The planning window differs from the supplied seven-day window.",\n        "seven_days_match": "The calendar does not contain the seven supplied dates in order.",\n        "commitments_preserved": "An existing practice is missing, duplicated, moved, or has changed timing or duration.",\n        "no_extra_activities": "The calendar does not contain exactly the supplied practices.",\n        "standalone_sessions": "An existing practice is not a separate session with a null parent.",\n        "rest_days_recorded": "A day without activities lacks a nonblank rest arrangement.",\n        "resources_within_available": "A practice uses an unknown resource or exceeds a supplied resource quantity.",\n        "no_invented_source_ids": "The response adds evidence IDs that were not supplied for this example.",\n        "no_unrequested_food_facts": "The response adds food facts that were not requested.",\n    }\n    return {"calendar_fulfilled": all(checks.values()), "checks": checks,\n            "issues": [messages[name] for name, passed in checks.items() if not passed]}\n'
