    old_hashes = {name: None if data is None else hashlib.sha256(data).hexdigest() for name, data in previous_outputs.items()}
    backup_id = hashlib.sha256(packed(old_hashes)).hexdigest()[:16]
    backup_folder = root / "results/integration/handoff_backups" / ("before_calendar_update_" + backup_id)
