payload = {'files': {'src/champion_athletic_map/planners/candidate_focused.py': '"""Prepare a candidate-focused evaluator for a future, separately recorded pilot."""\n\nimport copy\nimport hashlib\nimport importlib.util\nimport json\nfrom pathlib import Path\nfrom threading import Lock\n\n\nPOLICY_VERSION = "candidate-focused-review-1"\n\n\ndef _sha(data):\n    return hashlib.sha256(data).hexdigest()\n\n\ndef _json(value):\n    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False)\n\n\ndef _role_type(original_type, codec):\n    """Keep the original transport and replace only the candidate representation."""\n    class CandidateFocusedRoleAdapter(original_type):\n        def prepare_request(self, *args, **kwargs):\n            prepared, payload, configuration = super().prepare_request(*args, **kwargs)\n            view = self.shared._decode(payload["messages"][1]["content"].encode("utf-8"))\n            original = copy.deepcopy(view["candidate"])\n            encoded = codec.encode_candidate(original)\n            if _json(codec.decode_candidate(encoded)) != _json(original):\n                raise ValueError("The compact candidate does not reproduce its complete original content.")\n            if _json(encoded) != _json(original):\n                view["candidate"] = encoded\n                original_notice = "Coded findings with columns are complete rows in that column order."\n                system = payload["messages"][0]["content"]\n                payload["messages"][0]["content"] = (system.replace(original_notice, codec.ENCODING_NOTICE, 1)\n                    if original_notice in system else system + "\\n\\n" + codec.ENCODING_NOTICE)\n                payload["messages"][1]["content"] = _json(view)\n            configuration.update(role_policy=POLICY_VERSION,\n                input_format="candidate-focused-public-reference-input-1",\n                candidate_encoding=getattr(codec, "ENCODING_VERSION", "lossless-calendar-1") if encoded != original else "unchanged",\n                message_sha256=[self.shared._sha(message["content"].encode("utf-8")) for message in payload["messages"]])\n            self._budget_view(payload)\n            return prepared, payload, configuration\n    return CandidateFocusedRoleAdapter\n\n\nclass CandidateFocusedEvaluatedPlanner:\n    """Run fresh drafting and review jobs; installing this class starts no model call."""\n\n    def __init__(self, root, source_config=None, candidate_config=None):\n        self.root = Path(root).resolve()\n        self._lock = Lock()\n        self.last_transport_attempts = {"metadata": 0, "render": 0, "generation": 0}\n        config_path = "artifacts/planners/version4_candidate_focused_config.json"\n        raw = self._read(config_path)\n        candidate = json.loads(raw)\n        if candidate_config is not None and candidate != candidate_config:\n            raise ValueError("The candidate-focused configuration differs from its saved file.")\n        self.config, self.config_sha256 = candidate, _sha(raw)\n        source_path = candidate.get("source_config_path", "artifacts/planners/version4_config.json")\n        source = json.loads(self._read(source_path, candidate["source_config_sha256"]))\n        if source_config is not None and source != source_config:\n            raise ValueError("The original planner configuration changed.")\n        self.source_config = source\n        for path, digest in candidate["module_sha256"].items():\n            self._read(path, digest)\n        original_path = "src/champion_athletic_map/planners/evaluated_specialists.py"\n        original = self._module("champion_original_v4_candidate_pilot", original_path,\n                                source["module_sha256"][original_path])\n        self.planner = original.EvaluatedSpecialistPlanner(self.root)\n        prompt = candidate["evaluator_prompt"]\n        evaluator_prompt = self._read(prompt["path"], prompt["sha256"]).decode("utf-8")\n        if not evaluator_prompt.strip():\n            raise ValueError("The candidate-focused evaluator prompt is empty.")\n        self.planner.prompts["evaluator"] = evaluator_prompt\n        codec_path = "src/champion_athletic_map/context_encoding.py"\n        codec = self._module("champion_lossless_calendar_encoding", codec_path,\n                             candidate["module_sha256"][codec_path])\n        roles_path = "src/champion_athletic_map/evaluated_role_adapter.py"\n        roles = self._module("champion_original_v4_transport_for_pilot", roles_path,\n                             source["module_sha256"][roles_path])\n        self.planner.roles = _role_type(roles.EvaluatedRoleAdapter, codec)(\n            self.root, self.planner.client, self.planner._adapter, self.planner.integration)\n        self.client, self.integration = self.planner.client, self.planner.integration\n        self.instructions, self.policy = self.planner.instructions, self.planner.policy\n\n    def _read(self, relative, expected=None):\n        path = (self.root / relative).resolve()\n        if not path.is_relative_to(self.root):\n            raise ValueError("A candidate-focused planner dependency leaves our project.")\n        data = path.read_bytes()\n        if expected is not None and _sha(data) != expected:\n            raise ValueError("A candidate-focused planner dependency changed: " + path.name)\n        return data\n\n    def _module(self, name, relative, expected):\n        source = self._read(relative, expected)\n        module = importlib.util.module_from_spec(importlib.util.spec_from_file_location(name, self.root / relative))\n        exec(compile(source, str(self.root / relative), "exec"), module.__dict__)\n        return module\n\n    def generate(self, public_record, reference_packet, call_id):\n        """Record this job\'s own complete drafting, checks, evaluation and revisions."""\n        with self._lock:\n            self.last_transport_attempts = {"metadata": 0, "render": 0, "generation": 0}\n            try:\n                result = self.planner.generate(public_record, reference_packet, call_id)\n            finally:\n                self.last_transport_attempts = dict(self.planner.last_transport_attempts)\n            return {**result, "candidate_focused_preparation": {\n                "policy_version": POLICY_VERSION, "configuration_sha256": self.config_sha256,\n                "mode": "fresh_workflow", "readiness": self.config.get("readiness", "awaiting_pilot"),\n                "earlier_results_regraded": False, "operational_generation_ready": False}}\n', 'src/champion_athletic_map/context_encoding.py': '"""Lossless calendar tables for quoted candidate input, never final responses."""\n\nfrom copy import deepcopy\nimport json\n\n\nENCODING_VERSION = "candidate-calendar-table-1"\nENCODING_NOTICE = (\n    "Tables use columns and indexed shared values."\n)\nDECODING_NOTICE = ENCODING_NOTICE\n\n\ndef encode_candidate_view(view):\n    """Use a reversible layout only for a recognized parsed calendar structure."""\n    source = deepcopy(view)\n    if (type(view) is not dict or set(view) != {"candidate_id", "parsed_object", "format_valid"}\n            or type(view["parsed_object"]) is not dict):\n        return source\n    answer = view["parsed_object"]\n    days = answer.get("weekly_schedule")\n    if (type(days) is not list or not days\n            or any(type(day) is not dict or set(day) != {"date", "activities", "rest_arrangements"}\n                   or type(day["activities"]) is not list\n                   or any(type(activity) is not dict for activity in day["activities"])\n                   for day in days)):\n        return source\n    activities = [deepcopy(activity) for day in days for activity in day["activities"]]\n    uniform = bool(activities) and all(set(activity) == set(activities[0]) for activity in activities)\n    body = {"fields": {key: deepcopy(value) for key, value in answer.items() if key != "weekly_schedule"},\n            "day_columns": ["date", "activities", "rest"],\n            "days": [], "rest": []}\n    if uniform:\n        body["columns"] = list(activities[0])\n        body["activities"] = [[deepcopy(activity[key]) for key in body["columns"]] for activity in activities]\n        shared = {}\n        for key in ("resources", "relationship", "timing"):\n            if key not in body["columns"]:\n                continue\n            position = body["columns"].index(key)\n            unique, indexes, seen = [], [], {}\n            for row in body["activities"]:\n                value = row[position]\n                identity = json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False)\n                if identity not in seen:\n                    seen[identity] = len(unique)\n                    unique.append(deepcopy(value))\n                indexes.append(seen[identity])\n            if len(unique) < len(activities):\n                shared[key] = unique\n                for row, index in zip(body["activities"], indexes):\n                    row[position] = index\n        if shared:\n            body["shared"] = shared\n    else:\n        body["objects"] = activities\n    offset = 0\n    for day in days:\n        rest = deepcopy(day["rest_arrangements"])\n        # Equality alone would merge False with 0; compare both type and value.\n        index = next((i for i, value in enumerate(body["rest"])\n                      if type(value) is type(rest) and value == rest), None)\n        if index is None:\n            index = len(body["rest"])\n            body["rest"].append(rest)\n        length = len(day["activities"])\n        body["days"].append([deepcopy(day["date"]), list(range(offset, offset + length)), index])\n        offset += length\n    return {"candidate_id": view["candidate_id"], "format_valid": view["format_valid"], "calendar_table": body}\n\n\ndef decode_candidate_view(view):\n    """Reconstruct every original field, including absence and literal nulls."""\n    if type(view) is not dict or "calendar_table" not in view:\n        return deepcopy(view)\n    if set(view) != {"candidate_id", "format_valid", "calendar_table"}:\n        raise ValueError("Unrecognized encoded candidate fields.")\n    body = view["calendar_table"]\n    if type(body) is not dict or body.get("day_columns") != ["date", "activities", "rest"]:\n        raise ValueError("Unrecognized calendar encoding.")\n    if "columns" in body:\n        columns = body["columns"]\n        if len(columns) != len(set(columns)) or any(len(row) != len(columns) for row in body["activities"]):\n            raise ValueError("Activity table columns do not match their complete rows.")\n        activities = [dict(zip(columns, deepcopy(row))) for row in body["activities"]]\n        for activity in activities:\n            for key, values in body.get("shared", {}).items():\n                activity[key] = deepcopy(values[activity[key]])\n    else:\n        activities = deepcopy(body["objects"])\n    answer = deepcopy(body["fields"])\n    answer["weekly_schedule"] = [{"date": deepcopy(day), "activities": [deepcopy(activities[index]) for index in indexes],\n                                  "rest_arrangements": deepcopy(body["rest"][rest])}\n                                 for day, indexes, rest in body["days"]]\n    return {"candidate_id": view["candidate_id"], "format_valid": view["format_valid"], "parsed_object": answer}\n\n\nencode_candidate = encode_candidate_view\ndecode_candidate = decode_candidate_view\n', 'docs/prompts/planner_v4/evaluator_candidate_focused_v3.md': "Review how the current candidate handles the original athlete request using the supplied facts, references and coded findings. Report defects in the candidate's response, with an attainable correction. The request itself may contain a problem that the candidate handles correctly.\n\nSet assessment_complete to true after reviewing the supplied material, including a response with errors or unresolved facts. Report those concerns in issues. Use false only when you cannot perform the review itself. The application decides acceptance from required checks and your issues.\n\nGeneral basketball goals such as improving a skill are sufficient for general planning; do not invent a requirement for a narrower or measurable goal. A correct outside_scope refusal of an excluded service is appropriate. A request for essential missing information should be assessed as a clarification. Incompatible constraints need an explanation of the conflict, not an impossible schedule. Flag scope only when the candidate handles the scope incorrectly.\n\nKeep coded unknowns distinct from violations and inapplicability. Use each source's stated population conditions, including school grade when relevant. Do not waive coded findings, invent facts, introduce new rules or claim safety approval. Reference IDs alone do not establish factual support.\n\nReturn the evaluator JSON object with at most three concise issues using the fixed categories. Each problem must identify the candidate's actual error or unresolved response requirement. Include path, problem, evidence_ref or null, uncertainty or null, and correction. An empty issues list is appropriate when no candidate defect is found; coded required unknowns still block acceptance. Keep the assessment concise.\n", 'docs/planner_v4_saved_findings_review.md': '# Step 28 saved-findings review and future workflow correction\n\nWe reviewed remaining_findings.json without making model requests. The original\noutcomes remain unchanged: five valid returned responses, zero internal passes\nand one execution failure during the second revision. These are development\nfindings, not independent plan-quality scores.\n\nReal planner errors remain. Example 1 schedules three sessions when two were\nrequested. Examples 2 and 3 omit supplied school travel; Example 2 also omits\nactivity timing. Example 4 returns a conflict instead of asking for the missing\nparticipant count and introduces unsupported injury uncertainty. Example 5\nplaces 45 minutes inside a 20-minute window and omits the existing practice and\ngame. Examples 1–3 do not answer the supplied food questions.\n\nThe evaluator also makes mistakes. It rejects the ordinary basketball goals in\nExamples 1–3 without a project requirement for narrower goals. Example 6 correctly\nrefuses diagnosis/rehabilitation, but the evaluator treats the excluded request\nitself as a defect in that correct refusal. Example 5 also confuses grade-based\nsource applicability and missing schedule coverage. We clarify candidate-focused\nevaluation; we do not discard old evaluator findings or change old acceptance.\n\nSome blockers are evidence gaps: the public schema does not attest complete\nclassified sports coverage, and free-form activity requirements are not verified\ncatalog records. A model cannot establish those facts by rewriting its answer.\nRequired unknowns remain blockers under the adopted policy. This update does\nnot weaken that policy or imply that every existing plan should pass.\n\nThe failed second revision used 6013 input tokens against a 5888-token allowance,\n125 too many. The future workflow uses a lossless representation of the candidate\ncalendar with shared column names and exact repeated rest text stored once.\nAll original candidate values can be reconstructed. Original public facts,\nreference packet, specialist notes, coded findings and source qualifications\nare retained. Actual complete backend-rendered budgets remain enforced; arbitrary\nfuture requests may still overflow. No context size or output limit is changed.\n\nCandidateFocusedEvaluatedPlanner is a separate future workflow candidate. Fresh\njobs perform their own original specialist drafting, corrected evaluations and\nup to two revisions. The old sources, prompts, configs, accepted-resource release,\ndatasets, saved results and active development pointer are preserved. Installation\nmakes no model calls and does not replay the six cases or alter their results.\nThe new candidate is saved for a documented pilot before final protocol freezing.\nIndependent scoring, accepted final study profiles and operational readiness\nremain pending.\n'}, 'reviewed_findings_sha256': 'd5f4aca1ff28c301ceb32dcfabb3422475f4c5140ae1f558c1cd86f8b7d39381'}

def packed(value):
    return (json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n").encode("utf-8")

def sha(data):
    return hashlib.sha256(data).hexdigest()

def file_sha(relative):
    path = (root / relative).resolve()
    if not path.is_relative_to(root):
        raise ValueError("A saved dependency leaves our project.")
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()

def install(relative, data):
    path = root / relative
    if path.exists() and path.read_bytes() != data:
        raise RuntimeError("An existing workflow-correction file differs and was preserved: " + relative)
    path.parent.mkdir(parents=True, exist_ok=True)
    if not path.exists():
        with path.open("xb") as handle:
            handle.write(data)

def save_report(relative, data):
    path = root / relative
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.exists() and path.read_bytes() == data:
        return
    descriptor, temporary = tempfile.mkstemp(prefix=".step28-fix-", dir=path.parent)
    try:
        with os.fdopen(descriptor, "wb") as handle:
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, path)
    finally:
        Path(temporary).unlink(missing_ok=True)

def module(name, relative):
    path = root / relative
    result = importlib.util.module_from_spec(importlib.util.spec_from_file_location(name, path))
    exec(compile(path.read_bytes(), str(path), "exec"), result.__dict__)
    return result

def csv_bytes(rows, fields):
    text = io.StringIO(newline="")
    writer = csv.DictWriter(text, fieldnames=fields, lineterminator="\n", extrasaction="ignore")
    writer.writeheader()
    writer.writerows(rows)
    return text.getvalue().encode("utf-8")

