    previous_packages = {dist.metadata["Name"].lower().replace("_", "-"): dist.version for dist in metadata.distributions()
        if dist.metadata.get("Name") and re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.-]*", dist.metadata["Name"])}
    constraints = "\n".join(name + "==" + version for name, version in sorted(previous_packages.items()) if name != "streamlit") + "\n"
    constraints_path = root / "artifacts/application/install_constraints.txt"
