for relative, expected in payload["source_sha256"].items():
    path = root / relative
    if not path.is_file() or hashlib.sha256(path.read_bytes()).hexdigest() != expected:
        raise RuntimeError("A project file differs from the version prepared for these tests: " + relative)
for relative, source in payload["files"].items():
    path = root / relative
    if path.exists() and path.read_bytes() != source.encode("utf-8"):
        if hashlib.sha256(path.read_bytes()).hexdigest() != payload["previous_file_sha256"].get(relative):
            raise RuntimeError("An existing test file differs and was preserved: " + relative)
    if relative.endswith(".py"):
        compile(source, str(path), "exec")
for relative, source in payload["files"].items():
    path = root / relative
    path.parent.mkdir(parents=True, exist_ok=True)
    if not path.exists():
        with path.open("xb") as handle:
            handle.write(source.encode("utf-8"))
    elif path.read_bytes() != source.encode("utf-8"):
        previous = path.read_bytes()
        backup = root / "results/testing/previous_test_files" / hashlib.sha256(previous).hexdigest()[:16] / relative
        backup.parent.mkdir(parents=True, exist_ok=True)
        if backup.exists() and backup.read_bytes() != previous:
            raise RuntimeError("An earlier test-file backup differs and was preserved: " + relative)
        if not backup.exists():
            with backup.open("xb") as handle:
                handle.write(previous)
        temporary = path.with_name(path.name + ".step30-update")
        with temporary.open("wb") as handle:
            handle.write(source.encode("utf-8"))
        os.replace(temporary, path)

# We add the test runner only if it is missing, keeping existing packages pinned.
try:
    metadata.version("pytest")
except metadata.PackageNotFoundError:
    packages = {d.metadata["Name"].lower().replace("_", "-"): d.version for d in metadata.distributions()
        if d.metadata.get("Name") and re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.-]*", d.metadata["Name"])}
    report_dir = root / "results/testing"
    report_dir.mkdir(parents=True, exist_ok=True)
    constraint = report_dir / "install_constraints.txt"
    constraint.write_text("\n".join(name + "==" + version for name, version in sorted(packages.items())) + "\n", encoding="utf-8")
    command = [sys.executable, "-m", "pip", "install", "--disable-pip-version-check", "--constraint", str(constraint),
               "--requirement", str(root / "requirements/testing.txt")]
    installed = subprocess.run(command, cwd=root, capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=180)
    (report_dir / "dependency_install.log").write_text(installed.stdout + installed.stderr, encoding="utf-8")
    if installed.returncode:
        raise RuntimeError("The test runner could not be installed. See results/testing/dependency_install.log")
    after = {d.metadata["Name"].lower().replace("_", "-"): d.version for d in metadata.distributions() if d.metadata.get("Name")}
    if any(after.get(name) != version for name, version in packages.items()):
        raise RuntimeError("An existing package changed during test-runner installation.")

# We keep the detailed test output in the saved reports.
run = subprocess.run([sys.executable, str(root / "tests/run_step30.py")], cwd=root,
    capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=360)
if run.stdout.strip():
    print(run.stdout.strip())
if run.returncode:
    log = root / "results/testing/runner_output.log"
    log.parent.mkdir(parents=True, exist_ok=True)
    log.write_text(run.stdout + run.stderr, encoding="utf-8")
    raise RuntimeError("Some integration checks need attention. See results/testing/runner_output.log and results/testing/pytest_output.log")


