# We check the saved sources before attaching these findings to our project.
for relative_name, expected in review["source_sha256"].items():
    source = root / relative_name
    if not source.is_file() or hashlib.sha256(source.read_bytes()).hexdigest() != expected:
        raise ValueError("A reviewed source is missing or has changed: " + relative_name)
if len(review["outcome_notes"]) != 80 or review["new_model_calls"] != 0:
    raise ValueError("The saved review is incomplete.")

