root = next((p for p in (Path.cwd().resolve(), *Path.cwd().resolve().parents)
             if (p / "results/step31_saved_reply_review_summary.json").is_file()),
            Path(r"C:\Users\samta\Documents\champion-athletic-map"))

# We check our dependencies and preserve any existing local edits.
for relative, expected in payload["dependency_sha256"].items():
    path = root / relative
    if not path.is_file() or hashlib.sha256(path.read_bytes()).hexdigest() != expected:
        raise ValueError("A saved dependency is missing or has changed: " + relative)
for relative, source in payload["files"].items():
    path = root / relative
    if relative.endswith(".py"):
        compile(source, str(path), "exec")
    if path.exists() and path.read_bytes() != source.encode("utf-8"):
        raise ValueError("An existing candidate file has local edits and was preserved: " + relative)
for relative, source in payload["files"].items():
    path = root / relative
    path.parent.mkdir(parents=True, exist_ok=True)
    if not path.exists():
        with path.open("xb") as handle:
            handle.write(source.encode("utf-8"))

# Our routine tests block service calls and external workers.
report_dir = root / "results/pilot/reviewed_workflow_software_checks" / uuid4().hex[:12]
report_dir.mkdir(parents=True, exist_ok=False)
environment = dict(os.environ)
environment["CAM_TEST_REPORT_DIR"] = str(report_dir)
run = subprocess.run([sys.executable, "-m", "pytest", "tests/reviewed_workflow", "-q", "--disable-warnings"],
    cwd=root, env=environment, capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=240)
(report_dir / "pytest_output.log").write_text(run.stdout + run.stderr, encoding="utf-8")
details_path = report_dir / "execution_details.json"
if not details_path.is_file():
    raise RuntimeError("The offline tests did not finish. See " + str(report_dir.relative_to(root) / "pytest_output.log"))
details = json.loads(details_path.read_bytes())
collected = {row["test_id"] for row in details["collected"]}
phases = {test: [row for row in details["phases"] if row["test_id"] == test] for test in collected}
passed = {test for test, rows in phases.items()
          if {row["phase"] for row in rows} == {"setup", "call", "teardown"}
          and all(row["outcome"] == "passed" and not row.get("expected_failure") for row in rows)}
if run.returncode or not collected or passed != collected or details["collection_errors"] or details["deselected"]:
    raise RuntimeError("Some offline checks need attention. See " + str(report_dir.relative_to(root) / "pytest_output.log"))
evidence = {"status": "passed", "passed": len(passed), "failed": 0, "not_completed": 0,
    "files": {relative: hashlib.sha256(source.encode("utf-8")).hexdigest()
              for relative, source in payload["files"].items() if relative.startswith("tests/")},
    "execution_report": details_path.relative_to(root).as_posix(),
    "execution_report_sha256": hashlib.sha256(details_path.read_bytes()).hexdigest(),
    "new_model_calls": 0, "query_encoder_processes": 0}

# We use the saved rankings to check the new packets without another search run.
path = root / "src/champion_athletic_map/reviewed_preparation.py"
spec = importlib.util.spec_from_file_location("champion_reviewed_preparation", path)
preparation = importlib.util.module_from_spec(spec)
spec.loader.exec_module(preparation)
summary = preparation.execute(root, software_evidence=evidence)
print("Offline checks passed:", len(passed))
print("Cases with approved drill context:", str(summary["cases_with_delivered_drills"]) + "/20", "| Requested food facts available:", str(summary["food_focus_cases_available"]) + "/6")
print("New model calls: 0 | New query encodings: 0")
print("Live model checks and final scoring: pending")
print("Saved: results/step31_reviewed_workflow_preparation_summary.json")


