payload = json.loads(zlib.decompress(base64.b64decode(source_data)))
root = next((p for p in (Path.cwd().resolve(), *Path.cwd().resolve().parents)
             if (p / "results/step31_reviewed_workflow_preparation_summary.json").is_file()),
            Path(r"C:\Users\samta\Documents\champion-athletic-map"))

# We keep the recorded code and results unchanged.
for relative, expected in payload["dependency_sha256"].items():
    path = root / relative
    if not path.is_file() or hashlib.sha256(path.read_bytes()).hexdigest() != expected:
        raise ValueError("A saved dependency is missing or changed: " + relative)
for relative, source in payload["files"].items():
    path = root / relative
    compile(source, str(path), "exec")
    if path.exists() and path.read_bytes() != source.encode("utf-8"):
        raise ValueError("A candidate file has local edits and was preserved: " + relative)
for relative, source in payload["files"].items():
    path = root / relative
    path.parent.mkdir(parents=True, exist_ok=True)
    if not path.exists():
        with path.open("xb") as handle:
            handle.write(source.encode("utf-8"))

# Our software checks stay offline; the model test starts only after they pass.
report_dir = root / "results/pilot/reviewed_probe_software_checks" / uuid4().hex[:12]
report_dir.mkdir(parents=True, exist_ok=False)
environment = dict(os.environ)
environment["CAM_TEST_REPORT_DIR"] = str(report_dir)
run = subprocess.run([sys.executable, "-m", "pytest", "tests/reviewed_probe", "-q", "--disable-warnings"],
    cwd=root, env=environment, capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=240)
(report_dir / "pytest_output.log").write_text(run.stdout + run.stderr, encoding="utf-8")
details_path = report_dir / "execution_details.json"
if not details_path.is_file():
    raise RuntimeError("The software checks did not finish. See " + str(report_dir.relative_to(root) / "pytest_output.log"))
details = json.loads(details_path.read_bytes())
collected = {r["test_id"] for r in details["collected"]}
phases = {test: [r for r in details["phases"] if r["test_id"] == test] for test in collected}
passed = {test for test, rows in phases.items()
          if {r["phase"] for r in rows} == {"setup", "call", "teardown"}
          and all(r["outcome"] == "passed" and not r.get("expected_failure") for r in rows)}
if run.returncode or not collected or passed != collected or details["collection_errors"] or details["deselected"]:
    raise RuntimeError("Some software checks need attention. See " + str(report_dir.relative_to(root) / "pytest_output.log"))
evidence = {"status": "passed", "passed": len(passed), "failed": 0, "not_completed": 0,
    "files": {relative: hashlib.sha256(source.encode("utf-8")).hexdigest()
              for relative, source in payload["files"].items() if relative.startswith("tests/")},
    "execution_report": details_path.relative_to(root).as_posix(),
    "execution_report_sha256": hashlib.sha256(details_path.read_bytes()).hexdigest(),
    "new_model_calls": 0, "query_encoder_processes": 0}

# Each case uses the four planners in its original balanced order.
path = root / "src/champion_athletic_map/reviewed_probe.py"
spec = importlib.util.spec_from_file_location("champion_reviewed_probe", path)
probe = importlib.util.module_from_spec(spec)
spec.loader.exec_module(probe)
manifest = probe.prepare(root)
try:
    summary = probe.execute(root, manifest, software_evidence=evidence,
        emit=lambda message: print(message) if message.startswith("Case ") else None)
except Exception:
    if (root / "results/step31_reviewed_probe_summary.json").is_file():
        print("Saved review file: results/step31_reviewed_probe_summary.json")
    raise
reports = [r for case in summary["cases"] for r in case.get("reports", [])]
table = ["| Planner | Contract valid | Responses completed | Food value verified | Plans fully verified |",
         "|---|---:|---:|---:|---:|"]
for version in range(1, 5):
    rows = [r for r in reports if r["planner_version"] == version]
    plans = [r for r in rows if r["outcome"].get("response_type") == "plan"]
    food_met = sum(any(q["check_id"] == "food_numeric_correctness" and q["status"] == "met"
                       for q in r["assessment"]["checks"]) for r in rows)
    verified = sum(r["assessment"]["overall"] == "declared_checks_supported" for r in plans)
    plan_count = str(verified) + "/" + str(len(plans)) if plans else "—"
    table.append("| " + str(version) + " | " + str(sum(r["outcome"].get("format_valid") is True for r in rows))
        + "/4 | " + str(sum(r["outcome"].get("completion_valid") is True for r in rows))
        + "/4 | " + str(food_met) + "/1 | " + plan_count + " |")
try:
    from IPython.display import Markdown, display
    display(Markdown("\n".join(table)))
except ImportError:
    print("\n".join(table))
print("Recorded outcomes:", str(summary["recorded_jobs"]) + "/16", "| New model submissions:", summary["new_model_submissions"],
      "| Saved cases reused:", summary["saved_completed_cases_reused"])
if summary.get("stop_reason"):
    print("Stopped for review:", summary["stop_reason"])
print("Final scoring and human review: pending")
print("Saved: results/step31_reviewed_probe_summary.json")


# ### Step 31-15 — Correct complete-request size and food-answer validation offline
# 
# The small live test showed that a reference packet can fit its allowance while
# a complete revision request is still too large. Planner 4 also receives the
# current candidate, coded findings and evaluator feedback. Three of its saved
# revision requests exceeded the available input space and were stopped before
# generation. We will correct that handoff using the exact saved requests.
# 
# Our new revision input will retain every athlete fact, complete reference
# record, candidate field, supplied coded finding and evaluator issue. We will
# replace repeated revision instructions with a concise statement of the same
# task and scope rules, keeping the existing decoding notices. Intermediate
# specialist notes will stay archived in the saved configuration and draft
# records instead of being repeated in the revision prompt. The model, context
# limit, response allowance and safety reserves will remain unchanged. We will
# measure the complete rendered requests, including their message boundaries,
# rather than checking the reference packet alone.
# 
# We will also separate two food questions in our checks: whether the reply gives
# a correct numerical value anywhere, and whether its required food-facts field
# actually answers the request. In the saved example, Planner 2 correctly states
# that 250 g of raw blueberries contains 1.85 g of protein in its explanation,
# while its food-facts statement omits the amount. Recognizing that value must
# not turn the incomplete field or the whole plan into a pass. Copied questions,
# wrong values, conflicting claims and unsupported wording will remain visible.
# The validator will retain a limited, declared grammar and keep uncertainty
# explicit rather than claiming to understand every possible sentence.
# 
# This cell will install a separate candidate, run offline checks, replay all
# five saved revision requests, and save a prospective food reassessment of all
# sixteen outcomes. It will keep the original replies and assessments unchanged.
# It will not send the candidate requests, resume failed calls, or generate new
# plans. Local fit on these five saved requests is evidence for this correction,
# not a guarantee for every future request. Backend confirmation, revised model
# behavior, human ratings and final study scoring will remain pending.
# 

# In[16]:


