payload = json.loads(zlib.decompress(base64.b64decode(source_data)))
root = next((p for p in (Path.cwd().resolve(), *Path.cwd().resolve().parents)
             if (p / "results/step31_reviewed_probe_summary.json").is_file()),
            Path(r"C:\Users\samta\Documents\champion-athletic-map"))

# We preserve our recorded sources and any existing local edits.
for relative, expected in payload["dependency_sha256"].items():
    path = root / relative
    if not path.is_file() or hashlib.sha256(path.read_bytes()).hexdigest() != expected:
        raise ValueError("A saved dependency is missing or changed: " + relative)
updates = []
for relative, source in payload["files"].items():
    path = root / relative
    if relative.endswith(".py"):
        compile(source, str(path), "exec")
    if path.exists() and path.read_bytes() != source.encode("utf-8"):
        previous = payload["previous_files"].get(relative)
        if previous is None or path.read_bytes() != previous.encode("utf-8"):
            raise ValueError("A candidate file has local edits and was preserved: " + relative)
        updates.append(relative)

# We keep a copy of the originally delivered test before correcting its paths.
for relative in updates:
    previous = payload["previous_files"][relative].encode("utf-8")
    archive = root / "artifacts/pilot/software_updates" / ("step31_15_test_paths_" + hashlib.sha256(previous).hexdigest()[:16]) / relative
    if archive.exists() and archive.read_bytes() != previous:
        raise ValueError("The previous test archive differs and was preserved: " + relative)
    archive.parent.mkdir(parents=True, exist_ok=True)
    if not archive.exists():
        with archive.open("xb") as handle:
            handle.write(previous)
for relative, source in payload["files"].items():
    path = root / relative
    path.parent.mkdir(parents=True, exist_ok=True)
    if not path.exists():
        with path.open("xb") as handle:
            handle.write(source.encode("utf-8"))
    elif relative in updates:
        temporary = path.with_name(path.name + ".update_" + uuid4().hex[:12])
        with temporary.open("xb") as handle:
            handle.write(source.encode("utf-8"))
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, path)

# Our software checks block service calls and external workers.
report_dir = root / "results/pilot/offline_correction_software_checks" / uuid4().hex[:12]
report_dir.mkdir(parents=True, exist_ok=False)
environment = dict(os.environ)
environment["CAM_TEST_REPORT_DIR"] = str(report_dir)
run = subprocess.run([sys.executable, "-m", "pytest", "tests/offline_corrections", "-q", "--disable-warnings"],
    cwd=root, env=environment, capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=240)
(report_dir / "pytest_output.log").write_text(run.stdout + run.stderr, encoding="utf-8")
details_path = report_dir / "execution_details.json"
if not details_path.is_file():
    raise RuntimeError("The offline checks did not finish. See " + str(report_dir.relative_to(root) / "pytest_output.log"))
details = json.loads(details_path.read_bytes())
collected = {r["test_id"] for r in details["collected"]}
phases = {test: [r for r in details["phases"] if r["test_id"] == test] for test in collected}
passed = {test for test, rows in phases.items()
          if {r["phase"] for r in rows} == {"setup", "call", "teardown"}
          and all(r["outcome"] == "passed" and not r.get("expected_failure") for r in rows)}
if run.returncode or not collected or passed != collected or details["collection_errors"] or details["deselected"]:
    raise RuntimeError("Some offline checks need attention. See " + str(report_dir.relative_to(root) / "pytest_output.log"))
evidence = {"status": "passed", "passed": len(passed), "failed": 0, "not_completed": 0,
    "files": {relative: hashlib.sha256(source.encode("utf-8")).hexdigest()
              for relative, source in payload["files"].items() if relative.startswith("tests/")},
    "execution_report": details_path.relative_to(root).as_posix(),
    "execution_report_sha256": hashlib.sha256(details_path.read_bytes()).hexdigest(),
    "new_model_calls": 0, "query_encoder_processes": 0}

# We replay the complete saved requests locally and keep the new findings separate.
path = root / "src/champion_athletic_map/offline_corrections.py"
spec = importlib.util.spec_from_file_location("champion_offline_corrections", path)
corrections = importlib.util.module_from_spec(spec)
spec.loader.exec_module(corrections)
summary = corrections.execute(root, software_evidence=evidence)
print("Offline checks passed:", len(passed))
print("Saved revision requests fitting locally:", str(summary["candidate_revision_requests_fitting_locally"])
      + "/" + str(summary["saved_revision_requests_checked"]))
print("Food values recognized:", str(summary["food_numeric_content_met"]) + "/4",
      "| Complete required food fields:", str(summary["food_field_completeness_met"]) + "/4")
print("New model calls: 0 | Original results retained")
print("Backend confirmation and revised model responses: pending")
print("Saved: results/step31_offline_corrections_summary.json")


