# We review our saved results without generating another plan.
print("Step 31-17 — Saved results and remaining findings")
from pathlib import Path
import hashlib
import json

root = next((p for p in (Path.cwd().resolve(), *Path.cwd().resolve().parents)
             if (p / "results/step31_verified_continuation_summary.json").is_file()),
            Path(r"C:\Users\samta\Documents\champion-athletic-map"))
source_hashes = {}

def require(condition, message):
    if not condition:
        raise ValueError(message)

def canonical(value):
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False).encode("utf-8")

def digest(data):
    return hashlib.sha256(data).hexdigest()

def read(relative):
    path = (root / str(relative).replace("\\", "/")).resolve()
    require(path.is_relative_to(root) and path.is_file(), "A saved input is missing or outside the project: " + str(relative))
    raw = path.read_bytes()
    source_hashes[path.relative_to(root).as_posix()] = digest(raw)
    def unique(pairs):
        result = {}
        for key, value in pairs:
            require(key not in result, "A saved input contains duplicate JSON fields.")
            result[key] = value
        return result
    return json.loads(raw, object_pairs_hook=unique,
        parse_constant=lambda value: (_ for _ in ()).throw(ValueError("A saved input contains a nonfinite number.")))

def assessment(result, checked):
    require(checked.get("assessment_execution") == "completed" and checked.get("required_flags_verified") is True
            and checked.get("internal_evaluator_used_for_verdict") is False,
            "A completed software assessment independent of the model evaluator is required.")
    require(digest(canonical(result)) == checked["designated_outcome_sha256"], "A reply differs from its saved assessment.")
    rows = checked["checks"]
    ids = [row["check_id"] for row in rows]
    require(len(ids) == len(set(ids)) == 43 and set(ids) == set(checked["expected_check_ids"])
            and all(type(row["required"]) is bool and row["status"] in
                    {"met", "violated", "unknown", "not_applicable"} for row in rows),
            "The saved assessment has incomplete or inconsistent check coverage.")
    for field, status in (("required_violations", "violated"), ("required_unknowns", "unknown")):
        require(set(checked[field]) == {row["check_id"] for row in rows if row["required"] and row["status"] == status},
                "The saved required findings disagree with their check rows.")
    overall = ("requirements_violated" if checked["required_violations"] else
               "requirements_unverified" if checked["required_unknowns"] else "declared_checks_supported")
    require(checked["overall"] == overall, "The saved overall finding disagrees with its required checks.")
    response = result.get("response") or {}
    if response:
        require(digest(canonical(response["authoritative_public_input"])) == checked["public_input_sha256"],
                "A reply contains different athlete information.")
        raw = (response.get("model_output") or {}).get("raw_text")
        if raw is not None:
            require(digest(raw.encode("utf-8")) == checked["raw_response_sha256"], "The saved raw reply differs from its assessment.")
    return {row["check_id"]: row for row in rows}

def cohort(relative, count, expected_schema, complete_flag):
    saved = read(relative)
    require(saved.get("schema_version") == expected_schema and saved.get(complete_flag) is True
            and saved.get("recorded_jobs") == count * 4 and saved.get("completed_cases") == count
            and saved.get("stop_reason") is None and saved.get("injected_test_dependencies") is False
            and saved.get("required_unknowns_waived") is False, "The requested saved pilot is not complete.")
    cases = saved["cases"]
    require(len(cases) == count and len({c["case_index"] for c in cases}) == count
            and len({c["profile_id"] for c in cases}) == count, "The saved case roster is duplicated or incomplete.")
    rows, seen = [], set()
    for case in cases:
        require(len(case["reports"]) == 4 and {r["planner_version"] for r in case["reports"]} == {1, 2, 3, 4},
                "Each case needs one saved outcome for every planner.")
        for report in case["reports"]:
            require(report["job_id"] not in seen, "A saved job is duplicated.")
            seen.add(report["job_id"])
            result = read(report["outcome_path"])
            assessment(result, report["assessment"])
            require(all(result.get(k) == report["outcome"].get(k) for k in
                        ("completion_valid", "format_valid", "response_type")), "The report flags differ from its saved reply.")
            rows.append({"case": case["case_index"], "profile_id": case["profile_id"],
                "planner": report["planner_version"], "job_id": report["job_id"], "outcome_path": report["outcome_path"],
                "completion_valid": result.get("completion_valid") is True, "format_valid": result.get("format_valid") is True,
                "response_type": result.get("response_type"), "overall": report["assessment"]["overall"],
                "required_violations": report["assessment"]["required_violations"],
                "required_unknowns": report["assessment"]["required_unknowns"]})
    stats = []
    for version in range(1, 5):
        chosen = [r for r in rows if r["planner"] == version]
        plans = [r for r in chosen if r["response_type"] == "plan"]
        stats.append({"planner": version, "outcomes": len(chosen),
            "format_valid": sum(r["format_valid"] for r in chosen),
            "completed": sum(r["completion_valid"] for r in chosen), "plan_type_replies": len(plans),
            "plans_passing_recorded_checks": sum(r["format_valid"] and r["completion_valid"]
                and r["overall"] == "declared_checks_supported" for r in plans)})
    return saved, rows, stats

# We retain the different workflow phases as separate comparisons.
pilot, original_rows, original_stats = cohort("results/step31_development_pilot_summary.json", 20,
    "resumable-development-pilot-1", "development_pilot_completed")
