publics = {r["case"]: r["profile_id"] for r in original_rows}
require(all(publics[r["case"]] == r["profile_id"] for r in reviewed_rows), "A follow-up case no longer matches the pilot roster.")
earlier_review = read("results/step31_saved_reply_review_summary.json")
