bindings = {}

def require(condition, message):
    if not condition:
        raise ValueError(message)

def canonical(value):
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False).encode("utf-8")

def sha(data):
    return hashlib.sha256(data).hexdigest()

def project_file(relative):
    path = (root / str(relative).replace("\\", "/")).resolve()
    require(path.is_relative_to(root) and path.is_file(), "A required saved file is missing or outside the project: " + str(relative))
    return path

def bind(relative, expected=None, expected_size=None):
    path = project_file(relative)
    hasher = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            hasher.update(block)
    observed = hasher.hexdigest()
    require(expected is None or observed == expected, "A frozen file changed: " + str(relative))
    require(expected_size is None or path.stat().st_size == expected_size, "A frozen file has a different size: " + str(relative))
    bindings[path.relative_to(root).as_posix()] = observed
    return path

def read(relative, expected=None):
    path = bind(relative, expected)
    def unique(pairs):
        value = {}
        for key, item in pairs:
            require(key not in value, "A saved configuration has duplicate fields.")
            value[key] = item
        return value
    return json.loads(path.read_bytes(), object_pairs_hook=unique,
        parse_constant=lambda value: (_ for _ in ()).throw(ValueError("A saved configuration contains a nonfinite number.")))

