payload = json.loads(zlib.decompress(base64.b64decode(source_data)))
root = next((p for p in (Path.cwd().resolve(), *Path.cwd().resolve().parents)
             if (p / "results/step31_protocol_checkpoint_summary.json").is_file()),
            Path(r"C:\Users\samta\Documents\champion-athletic-map"))
checkpoint = json.loads((root / "results/step31_protocol_checkpoint_summary.json").read_bytes())
if (checkpoint.get("classifier_protocol_id") != payload["protocol_id"]
        or checkpoint.get("injected_test_dependencies") is not False
        or checkpoint.get("classifier_protocol_frozen") is not True):
    raise ValueError("The completed Step 31-18 classifier checkpoint is required.")

# We preserve local edits and update the original artificial example if needed.
for relative, expected in payload["dependency_sha256"].items():
    path = root / relative
    if not path.is_file() or hashlib.sha256(path.read_bytes()).hexdigest() != expected:
        raise ValueError("A saved software-check source changed: " + relative)
updates = {}
for relative, source in payload["files"].items():
    path = root / relative
    compile(source, str(path), "exec")
    if path.exists() and path.read_bytes() != source.encode("utf-8"):
        old = path.read_bytes()
        if hashlib.sha256(old).hexdigest() != payload["replace_sha256"].get(relative):
            raise ValueError("An evaluation file has local edits and was preserved: " + relative)
        test_folder = root / "results/classifier_test"
        if (root / "results/step32_classifier_test_summary.json").exists() or (
                test_folder.is_dir() and any(p.is_file() for p in test_folder.rglob("*"))):
            raise ValueError("Classifier test evidence already exists. Preserve it before changing evaluation software.")
        updates[relative] = old
for relative, source in payload["files"].items():
    path = root / relative
    path.parent.mkdir(parents=True, exist_ok=True)
    if not path.exists():
        with path.open("xb") as handle:
            handle.write(source.encode("utf-8"))
    elif relative in updates:
        old = updates[relative]
        backup = root / "results/classifier_software_checks/fixture_correction" / hashlib.sha256(old).hexdigest() / path.name
        backup.parent.mkdir(parents=True, exist_ok=True)
        if backup.exists() and backup.read_bytes() != old:
            raise ValueError("The original software-check backup has changed.")
        if not backup.exists():
            with backup.open("xb") as handle:
                handle.write(old)
        with tempfile.NamedTemporaryFile(dir=path.parent, prefix=".step32-", delete=False) as handle:
            handle.write(source.encode("utf-8"))
            temporary = Path(handle.name)
        os.replace(temporary, path)

# We check the evaluator with artificial examples before accessing test inputs.
report_dir = root / "results/classifier_software_checks" / uuid4().hex[:12]
report_dir.mkdir(parents=True, exist_ok=False)
environment = dict(os.environ)
environment["PYTHONPATH"] = str(root / "src")
environment["PYTEST_DISABLE_PLUGIN_AUTOLOAD"] = "1"
environment["CAM_TEST_REPORT_DIR"] = str(report_dir)
environment["CHAMPION_CLASSIFIER_TEST_ROOT"] = str(root)
environment["CHAMPION_STEP32_EVALUATOR_PATH"] = str(root / "src/champion_athletic_map/classifier_test_evaluation.py")
environment["CHAMPION_STEP32_REPORT_PATH"] = str(root / "src/champion_athletic_map/classifier_test_reports.py")
checked = subprocess.run([sys.executable, "-m", "pytest", "tests/step32", "-q", "--disable-warnings"],
    cwd=root, env=environment, capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=300)
(report_dir / "pytest_output.log").write_text(checked.stdout + checked.stderr, encoding="utf-8")
details_path = report_dir / "execution_details.json"
if not details_path.is_file():
    raise RuntimeError("The evaluator checks did not finish. See " + str(report_dir.relative_to(root) / "pytest_output.log"))
details = json.loads(details_path.read_bytes())
collected = {row["test_id"] for row in details["collected"]}
phases = {test: [row for row in details["phases"] if row["test_id"] == test] for test in collected}
passed = {test for test, rows in phases.items() if {row["phase"] for row in rows} == {"setup", "call", "teardown"}
          and all(row["outcome"] == "passed" and not row.get("expected_failure") for row in rows)}
if checked.returncode or not collected or passed != collected or details["collection_errors"] or details["deselected"]:
    raise RuntimeError("Some evaluator checks need attention. See " + str(report_dir.relative_to(root) / "pytest_output.log"))
files = {name: hashlib.sha256(source.encode("utf-8")).hexdigest() for name, source in payload["files"].items()}
files.update(payload["dependency_sha256"])
evidence = {"status": "passed", "passed": len(passed), "failed": 0, "not_completed": 0, "files": files,
            "execution_report": details_path.relative_to(root).as_posix(),
            "execution_report_sha256": hashlib.sha256(details_path.read_bytes()).hexdigest()}
evidence_path = report_dir / "software_evidence.json"
evidence_path.write_text(json.dumps(evidence, indent=2, allow_nan=False) + "\n", encoding="utf-8")

# A fresh process loads the original model code and runs the fixed comparison.
result_path = report_dir / "evaluation_result.json"
run = subprocess.run([sys.executable, "tests/step32/run_evaluation.py", str(root), str(evidence_path), str(result_path)],
    cwd=root, env=environment, capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=1200)
(report_dir / "evaluation_output.log").write_text(run.stdout + run.stderr, encoding="utf-8")
if not result_path.is_file():
    raise RuntimeError("The classifier evaluation stopped before completion. See " + str(report_dir.relative_to(root) / "evaluation_output.log"))
summary = json.loads(result_path.read_bytes())
if not summary.get("all_models_complete") or run.returncode:
    print("Evaluation: incomplete | No complete comparison reported")
    print("Issue:", summary.get("error") or "The evaluation did not finish.")
    print("Saved:", summary.get("summary_path") or str(report_dir.relative_to(root)))
else:
    print("\n| Classifier | Macro-F1 | Accuracy |")
    print("|---|---:|---:|")
    for family, name in (("majority", "Majority baseline"), ("logistic_regression", "L5 logistic regression"),
                         ("neural", "N3 neural classifier")):
        result = summary["models"][family]
        print(f"| {name} | {result['macro_f1']:.4f} | {result['accuracy']:.2%} |")
    print("\nTest records:", summary["records"], "| Exercise groups:", summary["groups"])
    print("Saved predictions reused:", "yes" if summary["saved_execution_reused"] else "no")
    print("Saved: results/step32_classifier_test_summary.json")


# ### Observation — Step 32
# 
# We evaluated our three saved exercise classifiers on the same frozen test set of 438 records in 385 exercise groups, covering 16 body-part labels. We used each model’s saved preprocessing and evaluated the models without retraining them.
# 
# | Classifier | Macro-F1 | Accuracy |
# |---|---:|---:|
# | Majority baseline | 0.0234 | 23.06% |
# | L5 logistic regression | 0.6143 | 73.29% |
# | N3 neural classifier | 0.5288 | 67.81% |
# 
# L5 logistic regression achieved the highest macro-F1 and accuracy. Both trained models performed better than the majority baseline, but the neural classifier did not improve on logistic regression in this test.
# 
# Macro-F1 gives each label equal weight, while accuracy measures the percentage of correctly classified records. We kept the full-precision scores in the saved files and rounded the displayed results.
# 
# All three models produced predictions for every test record. We saved the aligned predictions, results for each label, confusion matrices, input diagnostics and selected error examples. Confidence intervals and paired statistical comparisons remain scheduled for Step 35.
# 
# The application retains L5, which we selected earlier using validation results. These test results measure agreement with our exercise labels; they do not establish basketball-plan quality or athlete suitability. Remaining source-label issues and the full-source exploration performed before the benchmark freeze remain limitations.

# <hr style="border: none; height: 10px; background-color: #FFD700;">

# ## 33. Final Comparison of the Four Planner Versions
# 
# ### 33.1 Purpose
# 
# We will compare our four frozen planner versions using the same held-out fictional athlete profiles.
# 
# We want to find out whether adding references, specialist roles, and evaluation with bounded revision improves the responses. We will also examine the additional runtime and computation required by each workflow.
# 
# The comparison will cover:
# 
# - Completion of feasible planning requests.
# - Adherence to the documented planning requirements.
# - Handling of missing information, conflicting constraints, and requests outside our scope.
# - Retrieval performance and delivery of complete supporting evidence.
# - Execution reliability and resource usage.
# - Response quality on the sample prepared for human review.
# 
# We will preserve the original responses before application edits and apply the independent scoring protocol finalized in Step 31.
# 
# ### 33.2 Verify the Frozen Configuration and Evaluation Readiness
# 
# Before execution, we will verify the protocol manifest and check that every required artifact matches its recorded version and hash.
# 
# | Area | What we will verify |
# |---|---|
# | Language model | The pinned local Ollama artifact, model digest, template, runtime version, and execution settings |
# | Generation | Prompts, message construction, output schema, context limits, and stage-specific output limits |
# | Reference preparation | Frozen corpus, selected retriever, query templates, ranking, filtering, and context assembly |
# | Structured resources | Adopted planning rules, eligible catalog records, and the frozen USDA reference |
# | Workflow behavior | Specialist routing, revision limits, acceptance policy, timeouts, and permitted retries |
# | Independent assessment | External scoring code, required-check definitions, benchmark expectations, and metric settings |
# | Final cases | Public profile inputs, private evaluation records, family mappings, and run assignments |
# 
# Prepared review bundles will not substitute for adopted operational rules or eligible planning records.
# 
# If a required resource or scoring component remains unavailable, we will record the evaluation as blocked until the dependency is resolved.
# 
# We will also confirm that classifier test findings from Step 32 have not changed the selected application classifier, catalog tags, retrieval collection, prompts, or planner settings.
# 
# A genuine defect discovered after freezing will follow the documented amendment process. We will preserve the original configuration and identify the affected results.
# 
# ### 33.3 Confirm the Final Profiles and Scheduled Jobs
# 
# We will use the 200 final profiles established in Step 16 and frozen in Step 31.
# 
# | Scenario category | Profiles per version |
# |---|---:|
# | Feasible planning requests | 150 |
# | Missing essential information | 20 |
# | Conflicting constraints | 15 |
# | Requests outside our scope | 15 |
# | **Total** | **200** |
# 
# Each age from 13 through 17 will contribute forty profiles.
# 
# Every profile will be processed by all four versions, producing **800 scheduled profile–version jobs**.
# 
# Each job will have a stable identifier linking its profile, planner version, and protocol version. Stage identifiers and transport-attempt identifiers will remain separate.
# 
# We will keep the public inputs separate from private evaluation information. Scenario labels, expected responses, feasibility witnesses, family metadata, and scoring records will remain outside generation prompts and tool results.
# 
# All four versions will receive the same public profile information, including unresolved or conflicting values. Our input preparation will not silently repair the challenge cases.
# 
# We will distinguish terminal execution failures from unstarted or unresolved jobs. An unfinished run manifest will remain an incomplete experiment.
# 
# ### 33.4 Complete the Held-Out Retrieval Assessment
# 
# We will evaluate the retriever selected using development results in Step 23.
# 
# The thirty held-out questions will retain their frozen composition:
# 
# | Question category | Questions |
# |---|---:|
# | Answerable basketball-drill questions | 10 |
# | Answerable guideline questions | 10 |
# | Requests unsupported by the approved corpus | 10 |
# | **Total** | **30** |
# 
# We will preserve the original single-query procedure, returning up to five distinct evidence units using the frozen ranking and filtering rules.
# 
# This assessment will remain separate from the planner’s two-query reference preparation, which can merge results from both searches. We will not describe the merged planner packet as the same top-five retrieval experiment.
# 
# For the twenty answerable questions, we will calculate:
# 
# - Hit rate at ranks 1, 3, and 5.
# - Recall at ranks 1, 3, and 5.
# - Mean reciprocal rank at 5.
# - Complete-evidence coverage using the frozen accepted evidence bundles.
# 
# Ranking measures will use distinct evidence-unit identifiers. Duplicate source occurrences will not become additional relevant hits.
# 
# Complete-evidence coverage will examine the actual delivered content, including required definitions and qualifications. Finding the correct identifier alone will not establish that sufficient evidence reached the context.
# 
# Executed answerable queries that fail or return no relevant evidence will remain in the declared denominator. Unexecuted queries will remain pending.
# 
# For unsupported questions, ranking measures that require relevant evidence will be not applicable. We will report returned-candidate, no-match, and error behavior separately. Returning a candidate will not, by itself, establish that the system answered an unsupported request incorrectly.
# 
# We will save the ranked results before comparing them with private relevance judgments. Those judgments will remain outside query generation and retrieval.
# 
# Held-out findings will not change the selected retriever, corpus, thresholds, or context policy. Any additional retrieval comparison must already be specified in the frozen protocol.
# 
# ### 33.5 Execute the Four Workflows Under Matched Conditions
# 
# The versions will retain their intended differences.
# 
# | Version | Workflow | Logical model calls for a fully completed workflow |
# |---|---|---|
# | Version 1 | One response using the shared instructions and public profile | 1 |
# | Version 2 | One response supplied with the prepared reference packet | 1 |
# | Version 3 | Specialist contributions followed by coordination | 3, or 4 with the food role |
# | Version 4 | Specialist drafting, coded checks, model evaluation, and up to two revisions | 4, 6, or 8; 5, 7, or 9 with the food role |
# 
# Failures may stop a workflow before it reaches these counts.
# 
# We will use the execution orders assigned in Step 31:
# 
# | Order | Planner sequence |
# |---|---|
# | A | Version 1 → Version 2 → Version 4 → Version 3 |
# | B | Version 2 → Version 3 → Version 1 → Version 4 |
# | C | Version 3 → Version 4 → Version 2 → Version 1 |
# | D | Version 4 → Version 1 → Version 3 → Version 2 |
# 
# Within each age group, ten profiles will use each order. We will follow the saved assignments rather than choose an order after seeing responses.
# 
# Workflows will execute sequentially. Each job will start with fresh conversation and workflow state.
# 
# Model weights and verified read-only indexes may remain loaded. For the primary timing comparison, computed reference-packet and query-result reuse will remain disabled so Versions 2–4 each perform their own preparation work.
# 
# For matched profiles, we will compare the canonical packet-content hashes supplied to Versions 2–4. Volatile request identifiers and timestamps will not determine content equality.
# 
# Other versions’ generated responses will remain outside each workflow. Version 1 will have no access to project reference tools during generation.
# 
# ### 33.6 Preserve Returned Responses and Follow the Recovery Policy
# 
# We will save raw model outputs and execution metadata before parsing or scoring them.
# 
# Versions 1 and 2 will retain their single-generation responses. Version 3 will retain its coordinator response when the required preceding stages complete.
# 
# Version 4 will follow the return policy established in Step 28:
# 
# - Return the first internally accepted candidate.
# - If two revisions are completed without acceptance, return the last fully assessed candidate with its unresolved status.
# - Treat a required-stage execution error as a failed workflow.
# 
# A malformed coordinator draft may enter Version 4’s declared evaluation and revision path. Missing or invalid mandatory specialist output, checker execution failure, or incomplete evaluator output will remain workflow failures.
# 
# Earlier diagnostic drafts will not become substitute final answers after a fatal failure.
# 
# Resumption will use verified saved inputs under the same frozen configuration. Completed model stages will remain preserved, and only stages that have not started may continue through the recorded resumption procedure.
# 
# An uncertain request outcome will not automatically justify replaying the request. We will resolve its status or retain the failure according to the protocol.
# 
# Only the declared confirmed pre-acceptance transport retry will be permitted. Weak, malformed, or truncated completed generations will not receive extra attempts outside Version 4’s bounded revision process.
# 
# ### 33.7 Calculate Independent Automated Feasible-Plan Success
# 
# We will score each designated returned outcome using the external assessment procedure.
# 
# Version 4’s internal acceptance decision will remain separate from its research score. The external assessment will recompute the required findings from the returned response, frozen profile inputs, and adopted resources.
# 
# Verified calculation helpers may be shared between implementations, but internal pass flags will not replace external scoring.
# 
# The primary planner measure will remain:
# 
# **Automated feasible-plan success rate = successful feasible cases ÷ all 150 feasible profiles**
# 
# For a feasible case to succeed, it must:
# 
# - Produce a complete plan under the shared structure and completeness requirements.
# - Account for the required profile information and existing commitments.
# - Have full expected coverage of the required checks.
# - Meet every required applicable condition.
# - Include a valid reason for any required check marked not applicable.
# 
# Execution failures, missing plans, inappropriate refusals, invalid required structure, required violations, and required unknowns will prevent success.
# 
# An empty check list will not produce a pass. The expected checks will come from the profile and frozen assessment policy, rather than whichever response type or activities the model chooses to declare.
# 
# An external scoring-system error will be recorded as an assessment problem. We will resolve it through the protocol process before reporting a complete comparison.
# 
# All 150 feasible profiles will remain in each version’s primary denominator. Unstarted or unresolved jobs will keep the final assessment incomplete rather than receive invented outcomes.
# 
# ### 33.8 Report Additional Outcomes with Clear Denominators
# 
# We will retain secondary measures alongside the primary result.
# 
# | Measure | Population or interpretation |
# |---|---|
# | Plan completion | Complete plans among all 150 feasible requests |
# | Required-check outcomes | Met, violated, unknown, and not applicable, with reasons and explicit counts |
# | Check coverage | Expected checks that were actually assessed |
# | Response-type match | Agreement between the declared type and the frozen scenario category |
# | Parsing reliability | Valid and invalid outputs, with missing outputs identified separately |
# | Execution reliability | Completed and failed jobs among attempted jobs, with unstarted work shown |
# | Reference-ID validity | Supplied identifiers that resolve to the relevant frozen records |
# | Resource usage | Recorded work across completed and failed attempts |
# 
# Unparseable outputs and missing responses will retain their actual statuses. We will not invent a response type for them.
# 
# A correctly named clarification can still ask the wrong question. We will therefore distinguish response-type match from semantic appropriateness.
# 
# Similarly, a valid reference identifier will not establish that the associated claim is supported. Optional identifiers may be absent under the shared schema without causing an automatic formatting failure.
# 
# We will report missing-information, conflict, and outside-scope results separately, together with descriptive age-group results and their actual denominators.
# 
# Human judgments about usefulness and evidence accuracy will remain limited to the responses reviewed in Step 34. Automated findings will describe only what the implemented checks establish.
# 
# ### 33.9 Record Runtime, Calls, and Resource Usage
# 
# We will use the timing boundaries frozen in Step 31.
# 
# Primary request timing will begin before reference preparation and end when the designated returned response has been parsed or the workflow reaches its terminal failure state.
# 
# It will include:
# 
# - Searches, structured lookups, and context assembly.
# - Specialist and coordinator calls.
# - Version 4’s coded checks, evaluator calls, and revisions.
# - Parsing, permitted transport recovery, and failed work.
# 
# Independent research scoring, human review, and application rendering will remain outside request timing.
# 
# We will preserve client wall-clock measurements and available Ollama response fields, including prompt and generated-token counts, completion reason, loading time, and generation durations.
# 
# Backend durations will be converted using their documented units. Unavailable measurements will remain unavailable.
# 
# We will distinguish:
# 
# - Scheduled jobs.
# - Logical model calls.
# - Transport attempts.
# - Searches and other supporting computation.
# - Warm-up and setup activity.
# 
# Across all four versions, the planned logical-call total for 200 fully completed matched profiles is:
# 
# **1,800 + 2F + 2R**
# 
# Here, **F** is the number of profiles activating the food role and **R** is the total number of Version 4 revisions. With at most two revisions per profile, the maximum is **2,600 + 2F**, or at most **3,000 logical calls**.
# 
# Actual counts will reflect early failures and will be reconciled with the stage records.
# 
# We will record observable backend caching and unexpected model reloads. Their time will remain visible under the frozen timing policy.
# 
# Timing summaries will identify the included population. Completed-response latency will be reported alongside failure counts and time spent on failures.
# 
# For local execution, monetary cost will remain unavailable unless we have a documented calculation basis.
# 
# ### 33.10 Prepare the Anonymized Human-Review Package
# 
# We will use the forty-profile sample selected before final outputs were examined.
# 
# | Scenario category | Selected profiles |
# |---|---:|
# | Feasible planning requests | 25 |
# | Missing essential information | 5 |
# | Conflicting constraints | 5 |
# | Requests outside our scope | 5 |
# | **Total** | **40** |
# 
# Each age will contribute eight profiles: five feasible requests and one from each challenge category.
# 
# We will include all four outcomes for every selected profile, producing **160 response records**. Both designated teammates will independently assess every record.
# 
# Each review record will contain:
# 
# - The original public profile and request.
# - The preserved response, including its citations.
# - The frozen rubric.
# - Equal, neutral access to the approved references.
# 
# We will assign anonymous response identifiers and preserve the presentation order.
# 
# Reviewer materials will exclude version labels, private scenario categories, feasibility witnesses, family metadata, automated scores, internal evaluator findings, workflow traces, and runtime information.
# 
# The identity mapping will remain separate until the initial ratings are locked.
# 
# Failed runs will remain in the sample as missing-response records. Existing malformed text will be provided without repairs. We will preserve wording and citations rather than edit responses to make the versions appear similar.
# 
# Anonymous labels cannot guarantee complete blinding because wording or structure may reveal a workflow. We will acknowledge this limitation.
# 
# Human ratings and agreement results will remain pending until Step 34.
# 
# ### 33.11 Preserve Matched Outcomes for Step 35
# 
# We will save analysis records linking each profile to all four outcomes.
# 
# The analysis files will retain profile and family identifiers, age, scenario category, execution status, independent check results, resource usage, and artifact versions.
# 
# These private analysis fields will remain separate from generation inputs and anonymized reviewer materials.
# 
# The planned comparisons will remain:
# 
# - Version 2 minus Version 1.
# - Version 3 minus Version 2.
# - Version 4 minus Version 3.
# - Version 4 minus Version 1.
# 
# Step 35 will apply the frozen paired family-bootstrap procedure and examine differences alongside failures, human ratings, and resource usage.
# 
# The 800 scheduled jobs will provide matched outcomes for 200 fictional profiles. They will not represent 800 independent users.
# 
# Our interpretation will concern the implemented workflows. Specialist and revision versions also use additional calls and tokens, so their differences will not isolate a single mechanism.
# 
# ### 33.12 Check Completeness Before Reporting the Comparison
# 
# Before presenting final results, we will confirm that:
# 
# - All 800 scheduled jobs have accounted-for terminal outcomes.
# - Unstarted and unresolved work has been resolved or the experiment is clearly marked incomplete.
# - All versions used the frozen public inputs and operating configuration.
# - Reference-packet contents match across Versions 2–4 for each profile.
# - Generation remained separate from private expectations and external scores.
# - Returned responses follow the declared workflow policies.
# - Independent scoring has complete expected coverage.
# - Failures and required unknowns remain in the appropriate outcome counts.
# - Internal acceptance has not replaced external assessment.
# - The thirty-question retrieval assessment is accounted for.
# - All 160 selected outcomes are included in the review package.
# - Runtime records include the associated attempts and failed work.
# 
# Any confirmed defect will follow the amendment process. Earlier evidence will remain preserved, and corrected results will identify the affected configuration and prior held-out exposure.
# 
# Completion will not require a particular version to win. A simpler workflow performing better will remain a valid finding.
# 
# ### 33.13 Expected Outputs
# 
# After completing this step, we expect to save:
# 
# - `results/planner_comparison/run_manifest.csv`: the 800 scheduled jobs and their execution outcomes.
# - `results/planner_comparison/raw_runs.jsonl`: preserved responses, workflow stages, and transport attempts.
# - `results/planner_comparison/reference_packets.jsonl`: reference contents and packet hashes for applicable jobs.
# - `results/planner_comparison/packet_consistency.csv`: matched packet-content checks across Versions 2–4.
# - `results/planner_comparison/case_level_checks.csv`: independently calculated check results and reasons.
# - `results/planner_comparison/metrics.csv`: automated summaries with explicit numerators and denominators.
# - `results/planner_comparison/paired_outcomes.csv`: aligned profile-level outcomes for the four versions.
# - `results/planner_comparison/runtime_usage.csv`: timings, calls, attempts, tokens, and available resource measurements.
# - `results/planner_comparison/evaluation_checks.csv`: configuration, access, execution, and scoring-completeness checks.
# - `results/retrieval/heldout_manifest.json`: the frozen retrieval assessment inputs and configuration.
# - `results/retrieval/heldout_results.jsonl`: rankings, delivered evidence, statuses, and case-level findings.
# - `results/retrieval/heldout_metrics.csv`: retrieval summaries with their applicable populations.
# - `data/evaluation/human_review_assignments.csv`: anonymous assignments and presentation order for both reviewers.
# - `data/evaluation/human_review_identity_map.csv`: the separately held response-to-version mapping.
# - `docs/planner_comparison_findings.md`: measured findings, interpretation, and limitations.
# - `results/step33_planner_comparison_summary.json`: producer record linking protocol and artifact hashes, execution counts, retrieval status, scoring completeness, review-package completeness, and unresolved issues.
# 
# The review assignments will point to preserved, anonymized response materials. Files will identify their protocol version, and amended runs will remain separate from the original evidence.
# 
# We will add actual observations after execution. The summary will report execution, retrieval, independent scoring, and review preparation as separate completion states.
# 
# Step 34 will collect the independent human ratings and calculate reviewer agreement.
# 
# ### References
# 
