from pathlib import Path
import base64
import hashlib
import importlib.metadata
import importlib.util
import json
import os
import subprocess
import sys
import xml.etree.ElementTree as ET
import zlib

source_data = (
    ''
    ''
    ''
    ''
    ''
    ''
    ''
    ''
    ''
    ''
    ''
    ''
    ''
    ''
    ''
    ''
    ''
    ''
    ''
    ''
    ''
    ''
    ''
    ''
    ''
    ''
    ''
    '59R2an8+5Pid7/8HOO0hBA=='
)
payload = json.loads(zlib.decompress(base64.b64decode(source_data)))
root = next((p for p in (Path.cwd().resolve(), *Path.cwd().resolve().parents)
             if (p / "results/step33_final_comparison_summary.json").is_file()),
            Path(r"C:\Users\samta\Documents\champion-athletic-map"))
if not (root / "results/step33_final_comparison_summary.json").is_file():
    raise ValueError("The completed Step 33-9 final comparison is required.")
for name, digest in payload["dependency_sha256"].items():
    if hashlib.sha256((root / name).read_bytes()).hexdigest() != digest:
        raise ValueError("A saved-results dependency changed and was preserved: " + name)
for name, source in payload["files"].items():
    compile(source, name, "exec")
    path = root / name
    if path.exists() and path.read_bytes() != source.encode("utf-8"):
        raise ValueError("An export source has local changes and was preserved: " + name)
for name, source in payload["files"].items():
    path = root / name
    path.parent.mkdir(parents=True, exist_ok=True)
    if not path.exists():
        with path.open("xb") as handle:
            handle.write(source.encode("utf-8"))

report_dir = root / "results/testing" / ("final_saved_export_" + payload["delivery_id"][:16])
report_dir.mkdir(parents=True, exist_ok=True)
test_dir = root / "tests/step33_10"
environment = dict(os.environ)
environment.pop("PYTEST_ADDOPTS", None)
environment["PYTEST_DISABLE_PLUGIN_AUTOLOAD"] = "1"
environment["PYTHONPATH"] = str(root / "src") + os.pathsep + environment.get("PYTHONPATH", "")
command = [sys.executable, "-m", "pytest", "-q", "-p", "no:cacheprovider",
           "--confcutdir", str(test_dir), "--junitxml", str(report_dir / "checks.xml")]
command.extend(str(root / name) for name in payload["test_files"])
run = subprocess.run(command, cwd=root, env=environment, capture_output=True,
    text=True, encoding="utf-8", errors="replace", timeout=180)
(report_dir / "pytest_output.log").write_text(run.stdout + run.stderr, encoding="utf-8")
if run.returncode:
    raise RuntimeError("Some saved-results checks need attention. See " +
                       str(report_dir.relative_to(root) / "pytest_output.log"))
cases = list(ET.parse(report_dir / "checks.xml").getroot().iter("testcase"))
if len(cases) != payload["expected_test_cases"] or any(
        child.tag in {"failure", "error", "skipped"} for case in cases for child in case):
    raise RuntimeError("The saved-results checks did not all finish as expected. See " +
                       str(report_dir.relative_to(root) / "pytest_output.log"))
bindings = {name: hashlib.sha256(source.encode("utf-8")).hexdigest()
            for name, source in payload["files"].items()}
bindings.update(payload["dependency_sha256"])
evidence = {"status": "passed", "passed": len(cases), "failed": 0, "not_completed": 0,
    "files": bindings, "environment": {"python": sys.version,
        "pytest": importlib.metadata.version("pytest")},
    "report_directory": report_dir.relative_to(root).as_posix()}
path = root / "src/champion_athletic_map/final_saved_export.py"
spec = importlib.util.spec_from_file_location("champion_final_saved_export", path)
exporter = importlib.util.module_from_spec(spec)
spec.loader.exec_module(exporter)
print("Checking the saved outcomes and assessments…")
result = exporter.export(root, software_evidence=evidence,
                         expected_manifest_id=payload["expected_manifest_id"])
summary = result["summary"]
print("Saved outcomes checked: 800/800 | Original assessments retained")
print(result["comparison_table"])
print("Total model submissions:", summary["cumulative_model_submissions"], "| New model calls: 0")
print("Team-review replies prepared: 160 | Team ratings: pending")
print("Saved: results/step33_saved_results_comparison_summary.json")
print("Upload: results/step33_saved_results_review.zip")


